// ── Prism logo letter palette ─────────────────────────────────────────
// One canonical hex per letter of "prism", shared with prismBrand.ts and
// mirrored by public/wordmark.svg. This is strictly the logo's constituent
// spectrum — black, white, and these five letter hues — not an app
// accent palette. The app's accent (bot cards, message bubbles, shell
// --accent triad) is always driven by the active bot's color; the
// letter colors only appear inside the 5-color signature glyphs
// themselves (Hub tiles, wordmark). Kept centralized so every place
// that renders the refracted-rainbow look stays in lockstep with the
// wordmark if the palette ever changes.
type CommandCenterColorTag = keyof typeof PRISM_COLORS;

const COMMAND_CENTER_COLOR_TAGS: Array<{
  id: CommandCenterColorTag;
  letter: string;
  label: string;
  color: string;
}> = [
  { id: "p", letter: "P", label: "Rose", color: PRISM_COLORS.p },
  { id: "r", letter: "R", label: "Amber", color: PRISM_COLORS.r },
  { id: "i", letter: "I", label: "Lime", color: PRISM_COLORS.i },
  { id: "s", letter: "S", label: "Cyan", color: PRISM_COLORS.s },
  { id: "m", letter: "M", label: "Violet", color: PRISM_COLORS.m },
];

function normalizeCommandCenterColorTag(
  value: unknown,
): CommandCenterColorTag | undefined {
  return value === "p" ||
    value === "r" ||
    value === "i" ||
    value === "s" ||
    value === "m"
    ? value
    : undefined;
}

function commandCenterColorForTag(
  colorTag: CommandCenterColorTag | undefined,
): string | null {
  return colorTag ? PRISM_COLORS[colorTag] : null;
}

function commandCenterColorStyle(
  colorTag: CommandCenterColorTag | undefined,
): React.CSSProperties | undefined {
  const color = commandCenterColorForTag(colorTag);
  return color
    ? {
        ["--command-color" as string]: color,
        ["--bot-menu-color" as string]: color,
        ["--prompt-command-color" as string]: color,
      }
    : undefined;
}

