function buildDefaultCoffeePollOptionDraft(): string[] {
  return Array.from({ length: COFFEE_POLL_OPTION_COUNT_MIN }, () => "");
}

const COFFEE_STARTER_TOPIC_OPTION_COUNT = 4;

function formatCoffeePollBotVoteLabel(
  vote: CoffeePollVoteState | undefined,
  options: readonly string[],
): string {
  if (!vote) return "No vote";
  if (vote.kind === "option" && typeof vote.optionIndex === "number") {
    return options[vote.optionIndex] ?? "Voted";
  }
  const leaningIndex = vote.deliberation?.leaningOptionIndex;
  const alternateIndex = vote.deliberation?.alternateOptionIndex;
  const leaning =
    typeof leaningIndex === "number" ? options[leaningIndex] : null;
  const alternate =
    typeof alternateIndex === "number" ? options[alternateIndex] : null;
  if (vote.deliberation?.stage === "deciding" && leaning) {
    return `Deciding: ${leaning}`;
  }
  if (vote.deliberation?.stage === "teetering" && leaning && alternate) {
    return `Teetering: ${leaning} vs ${alternate}`;
  }
  if (leaning) {
    return `Leaning: ${leaning}`;
  }
  if (vote.kind === "pending") return "Thinking...";
  return "No vote";
}

function defaultCoffeeTeamAssignments(
  botIds: readonly string[],
): Record<string, CoffeeTeamId> {
  const assignments: Record<string, CoffeeTeamId> = {};
  botIds.forEach((botId, index) => {
    assignments[botId] =
      index === 0 ? "left" : index === 1 ? "right" : "undecided";
  });
  return assignments;
}

function coffeeTeamDraftCounts(
  assignments: Record<string, CoffeeTeamId>,
  botIds: readonly string[],
): Record<CoffeeTeamId, number> {
  const counts: Record<CoffeeTeamId, number> = {
    left: 0,
    undecided: 0,
    right: 0,
  };
  for (const botId of botIds) {
    const teamId = assignments[botId] ?? "undecided";
    counts[teamId] += 1;
  }
  return counts;
}

function coffeeTeamName(
  state: CoffeeTeamState | null | undefined,
  teamId: CoffeeTeamId,
): string {
  if (teamId === "left") return state?.left.name?.trim() || "Left";
  if (teamId === "right") return state?.right.name?.trim() || "Right";
  return state?.undecidedLabel?.trim() || "Undecided";
}

function coffeeTeamOutcomeText(
  state: CoffeeTeamState | null | undefined,
): string | null {
  if (!state) return null;
  if (
    state.status === "left_won" ||
    (state.status === "tie_resolved" && state.winnerTeamId === "left")
  ) {
    return `${state.left.name} wins`;
  }
  if (
    state.status === "right_won" ||
    (state.status === "tie_resolved" && state.winnerTeamId === "right")
  ) {
    return `${state.right.name} wins`;
  }
  if (state.status === "tiebreaker") return "Tie - choose the winner";
  return null;
}
