/** Prefer server `askQuestion`; if missing, re-parse assistant `content` (fenced JSON / older rows). */
function resolveAssistantAskQuestion(
  msg: Message,
): NonNullable<Message["askQuestion"]> | undefined {
  if (msg.role !== "assistant") return undefined;
  const direct = msg.askQuestion;
  if (
    direct?.name === "AskQuestion" &&
    Array.isArray(direct.options) &&
    direct.options.length >= 2 &&
    direct.options.length <= 4
  ) {
    const refined = refineAskQuestionPayloadFromDisplayClient(
      msg.content,
      direct,
    );
    return askQuestionOptionsArePromptFragments(msg.content, refined)
      ? undefined
      : refined;
  }
  const parsed = parseAssistantPrismTools(msg.content);
  if (
    parsed.askQuestion?.name === "AskQuestion" &&
    parsed.askQuestion.options.length >= 2 &&
    parsed.askQuestion.options.length <= 4
  ) {
    const refined = refineAskQuestionPayloadFromDisplayClient(
      msg.content,
      parsed.askQuestion,
    );
    return askQuestionOptionsArePromptFragments(msg.content, refined)
      ? undefined
      : refined;
  }
  return undefined;
}

