function interruptionToneForCount(interruptCount: number): InterruptionTone {
  if (interruptCount >= 3) return "firm";
  if (interruptCount >= 2) return "steady";
  return "gentle";
}

function interruptionMoodForCount(
  baseMood: MessageMoodKey,
  interruptCount: number,
): MessageMoodKey {
  void baseMood;
  void interruptCount;
  return "neutral";
}

function interruptionLengthBumpForText(text: string): number {
  const wordCount = text.match(/\S+/g)?.length ?? 0;
  if (wordCount >= INTERRUPTION_LENGTH_WORD_THRESHOLD_FIRM) return 2;
  if (wordCount >= INTERRUPTION_LENGTH_WORD_THRESHOLD_STEADY) return 1;
  return 0;
}

function interruptionLengthBandForText(text: string): InterruptionLengthBand {
  const wordCount = text.match(/\S+/g)?.length ?? 0;
  if (wordCount >= INTERRUPTION_LENGTH_WORD_THRESHOLD_FIRM) return "long";
  if (wordCount >= INTERRUPTION_LENGTH_WORD_THRESHOLD_STEADY) return "medium";
  return "short";
}

function pickRandomOption(options: readonly string[]): string {
  const idx = Math.floor(Math.random() * options.length);
  return options[Math.max(0, Math.min(options.length - 1, idx))]!;
}

function interruptionCountLead(
  effectiveInterruptCount: number,
  tone: InterruptionTone,
  lengthBump: number,
): string {
  if (effectiveInterruptCount <= 1) return "";
  if (effectiveInterruptCount === 2) {
    return tone === "gentle" ? "Another pause. " : "Pausing again. ";
  }
  if (effectiveInterruptCount === 3) {
    return lengthBump > 0 ? "Longer thread paused. " : "Another clean pause. ";
  }
  return tone === "firm" ? "Keeping the boundary. " : "Pausing once more. ";
}

function buildGeneratedInterruptionOptions(input: {
  tone: InterruptionTone;
  mood: MessageMoodKey;
  lengthBand: InterruptionLengthBand;
  effectiveInterruptCount: number;
  lengthBump: number;
  fingerprint: string;
}): string[] {
  const openers = INTERRUPTION_OPENERS[input.tone];
  const reactions = INTERRUPTION_REACTIONS[input.mood];
  const closers = INTERRUPTION_CLOSERS[input.tone][input.lengthBand];
  const lead = interruptionCountLead(
    input.effectiveInterruptCount,
    input.tone,
    input.lengthBump,
  );
  const options = new Set<string>();
  for (let i = 0; i < 8; i += 1) {
    const opener =
      openers[
        hashToUnsignedInt(
          `open:${input.fingerprint}:${input.effectiveInterruptCount}:${i}`,
        ) % openers.length
      ]!;
    const reaction =
      reactions[
        hashToUnsignedInt(
          `react:${input.fingerprint}:${input.effectiveInterruptCount}:${i}`,
        ) % reactions.length
      ]!;
    const closer =
      closers[
        hashToUnsignedInt(
          `close:${input.fingerprint}:${input.effectiveInterruptCount}:${i}`,
        ) % closers.length
      ]!;
    options.add(`${lead}${opener} ${reaction} ${closer}`);
    options.add(`${lead}${opener} ${closer}`);
    options.add(`${lead}${reaction} ${closer}`);
  }
  return [...options];
}

function interruptionFollowupLine(input: {
  baseMood: MessageMoodKey;
  interruptCount: number;
  interruptedText: string;
  previousLine?: string;
}): { line: string; mood: MessageMoodKey } {
  const lengthBump = interruptionLengthBumpForText(input.interruptedText);
  const effectiveInterruptCount = input.interruptCount + lengthBump;
  const tone = interruptionToneForCount(effectiveInterruptCount);
  const mood = interruptionMoodForCount(
    input.baseMood,
    effectiveInterruptCount,
  );
  const lengthBand = interruptionLengthBandForText(input.interruptedText);
  const fingerprint = `${input.interruptedText.length}:${hashToUnsignedInt(
    input.interruptedText.slice(0, 320),
  ).toString(36)}`;
  const generatedOptions = buildGeneratedInterruptionOptions({
    tone,
    mood,
    lengthBand,
    effectiveInterruptCount,
    lengthBump,
    fingerprint,
  });
  const options = [...INTERRUPTION_REMARKS[tone][mood], ...generatedOptions]
    .map((line) => line.trim())
    .filter(
      (line, index, list) => line.length > 0 && list.indexOf(line) === index,
    );
  const previousLine = input.previousLine?.trim() ?? "";
  let selectedLine = pickRandomOption(options);
  if (previousLine && options.length > 1 && selectedLine === previousLine) {
    const nonRepeatingOptions = options.filter((line) => line !== previousLine);
    selectedLine = pickRandomOption(nonRepeatingOptions);
  }
  return {
    line: selectedLine,
    mood,
  };
}

function interruptedMidWordSnippet(
  fullText: string,
  visibleTokenCount: number,
): string {
  const displayText = extractStageDirections(fullText)
    .mainText.replace(/\[([^\]\n]+)\]\(prism-bot:\/\/[^)\n]+\)/gi, "$1")
    .replace(/\*+/g, "")
    .replace(/\s+/g, " ")
    .trim();
  const tokens = tokenizeMessageReveal(displayText);
  const visible = tokens
    .slice(0, Math.max(1, visibleTokenCount))
    .join("")
    .trimEnd();
  if (visible.length === 0) return "—";
  const lastWordMatch = visible.match(/(\S+)$/);
  if (!lastWordMatch) return `${visible}—`;
  const fullWord = lastWordMatch[1];
  if (fullWord.length < 4) return `${visible}—`;
  const cutoffLength = Math.max(2, Math.floor(fullWord.length * 0.6));
  const prefix = visible.slice(0, visible.length - fullWord.length);
  return `${prefix}${fullWord.slice(0, cutoffLength)}—`;
}

function clampUnitInterval(value: number): number {
  if (!Number.isFinite(value)) return 0;
  return Math.max(0, Math.min(1, value));
}

function waitForBotTransferPaint(): Promise<void> {
  if (
    typeof window !== "undefined" &&
    typeof window.requestAnimationFrame === "function"
  ) {
    return new Promise((resolve) => {
      window.requestAnimationFrame(() => resolve());
    });
  }
  return new Promise((resolve) => setTimeout(resolve, 0));
}

function formatBotTransferEta(seconds: number): string {
  if (!Number.isFinite(seconds) || seconds <= 0) return "Finishing up";
  if (seconds < 2) return "Almost done";
  if (seconds < 60) return `ETA ${Math.ceil(seconds)} sec`;
  const minutes = Math.ceil(seconds / 60);
  return `ETA ${minutes} min`;
}

function estimateBotTransferEtaSeconds(
  transfer: BotTransferOverlayState,
  nowMs: number,
): number | null {
  if (!transfer.totalSteps || transfer.completedSteps <= 0) return null;
  const remainingSteps = transfer.totalSteps - transfer.completedSteps;
  if (remainingSteps <= 0) return 0;
  const elapsedSeconds = Math.max(0, (nowMs - transfer.startedAt) / 1000);
  if (elapsedSeconds < 1) return null;
  const secondsPerStep = elapsedSeconds / transfer.completedSteps;
  return remainingSteps * secondsPerStep;
}

function trimMessagesToActiveTurn(messages: Message[]): Message[] {
  for (let i = messages.length - 1; i >= 0; i -= 1) {
    if (messages[i]?.role === "user") {
      return i > 0 ? messages.slice(i) : messages;
    }
  }
  return messages;
}

function trimConversationToActiveTurn(
  conversation: ConversationDetail,
): ConversationDetail {
  const trimmed = trimMessagesToActiveTurn(conversation.messages);
  if (trimmed.length === conversation.messages.length) return conversation;
  return {
    ...conversation,
    messages: trimmed,
  };
}

function hashToUnsignedInt(text: string): number {
  let h = 2166136261;
  for (let i = 0; i < text.length; i += 1) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

function pickGeneratingLabel(displayName: string, salt: string): string {
  const idx = hashToUnsignedInt(salt) % GENERATING_PHRASE_BUILDERS.length;
  return GENERATING_PHRASE_BUILDERS[idx](displayName);
}

function opinionBandTitle(band: SessionOpinion["band"]): string {
  if (band === "trusting") return "Settled";
  if (band === "guarded") return "Careful";
  return "Warming";
}

function opinionBandDescription(band: SessionOpinion["band"]): string {
  if (band === "trusting") {
    return "The conversation feels steady, safe, and collaborative.";
  }
  if (band === "guarded") {
    return "The conversation is asking for a little more care right now.";
  }
  return "The conversation is open and still finding its rhythm.";
}

function opinionTrendLabel(trend: SessionOpinion["trend"]): string {
  if (trend === "up") return "Softening";
  if (trend === "down") return "Needs warmth";
  return "Stable";
}

function opinionTrendDescription(trend: SessionOpinion["trend"]): string {
  if (trend === "up") {
    return "The latest turn helped the exchange feel more collaborative.";
  }
  if (trend === "down") {
    return "The latest turn made the exchange feel a touch more careful.";
  }
  return "Nothing needs fixing; the tone is holding steady.";
}

function opinionScoreCaption(score: number): string {
  if (score >= 68) return "High ease";
  if (score <= 34) return "Low ease";
  return "Middle ease";
}

function botOpinionBandTitle(band: BotOpinion["band"]): string {
  if (band === "bonded") return "Bonded";
  if (band === "wounded") return "Wounded";
  if (band === "careful") return "Careful";
  return "Open";
}

function botOpinionBoundaryDescription(
  level: BotOpinion["boundaryLevel"],
): string {
  if (level === "firm") return "Firm boundary";
  if (level === "gentle") return "Gentle boundary";
  return "No boundary";
}

function botOpinionBandDescription(band: BotOpinion["band"]): string {
  if (band === "bonded")
    return "The long-term relationship reads as especially settled.";
  if (band === "wounded") return "This bot is carrying some long-term caution.";
  if (band === "careful")
    return "The relationship is open, but asking for care.";
  return "The long-term relationship is open and workable.";
}
interface ConversationDetail {
  id: string;
  title: string;
  mode?: "zen" | "chat" | "sandbox" | "coffee";
  /** Bot locked to this conversation at start. Null = PRISM Default / no custom bot. */
  botId: string | null;
  /** Coffee-only bot lineup frozen when the Coffee Session starts. */
  botGroupIds?: string[];
  /** Private chat flag — saved chats read it from storage; private sessions receive it from the ephemeral API response. */
  incognito: boolean;
  /** Bot id of the most recent assistant message; null for Default-last OR no-reply-yet. */
  lastBotId: string | null;
  /** Denormalized color of the last-spoken bot; mirrors the list-endpoint field for post-send UI consistency. */
  lastBotColor: string | null;
  /** True when the conversation has at least one assistant reply; see ConversationSummary for disambiguation semantics. */
  hasAssistantReply: boolean;
  /** Zen-only ambient wallpaper metadata; absent on older responses means off. */
  zenWallpaper?: ZenWallpaperMetadata;
  /** Unified Chat metadata: Hub rows are roots; side rows fork from a Hub. */
  hubRole?: "hub" | "side";
  hubBotId?: string | null;
  parentHubId?: string | null;
  /** Stable relationship/group ownership; independent from the last speaker. */
  history?: ConversationHistoryEntry;
  /** Normalized Prism mood state for developer diagnostics and mood-aware UX. */
  prismMood?: PrismMoodSnapshot;
  messages: Message[];
}

type ZenPrivateReturnCheckpoint = {
  selectedId: string | null;
  detail: ConversationDetail | null;
  selectedBotId: string | null;
  zenPersonaBotId: string | null;
  chatBotOverride: string | null | undefined;
  sessionOpinion: SessionOpinion | null;
  botOpinion: BotOpinion | null;
};

/** POST /api/chat success envelope — `conversationStarters` only appears after “Talk to me!”. */
interface ChatPostEnvelope {
  conversation: ConversationDetail;
  conversationStarters?: string[];
  autoRecovery?: AutoRecoveryTraceV1;
  summaryCompaction?: {
    mode: "zen" | "chat" | "sandbox";
    triggered: boolean;
    inProgress: boolean;
    reason: "milestone" | "mode_exit" | "manual";
    latestSummary?: string;
    latestSummaryAt?: string;
  };
  opinion?: SessionOpinion;
  botOpinion?: BotOpinion;
  prismMood?: PrismMoodSnapshot;
  memoryLearned?: {
    created?: MemoryEventPayload[];
    retracted?: MemoryEventPayload[];
    rejected?: MemoryRejectedEventPayload[];
    maxConfidence?: number;
  };
  /** Async in-thread image job — poll GET /api/image-jobs/:jobId until done. */
  pendingImageJob?: {
    jobId: string;
    conversationId: string | null;
  };
  /** Developer-only backend trace for the floating metrics terminal. */
  backendEvents?: ChatBackendDebugEvent[];
  /** Live-only Psychic/planning detail for the developer metrics stream. */
  psychicDebug?: {
    summary: string;
    scratchpad: string;
    effort: ReasoningEffort;
    provider: Provider;
    model?: string;
    simulated: boolean;
    passCount?: number;
    passes?: Array<{
      name: "plan" | "draft" | "audit" | "revision";
      chars: number;
      warning?: string;
    }>;
    guidanceChars?: number;
  };
  /** Present for Zen idle-autonomy checks, including silent no-message decisions. */
  zenAutonomyDecision?: ZenAutonomyDecision;
  /**
   * Per-turn tool-call diagnostics for the developer metrics stream. Empty/omitted on
   * turns where nothing tool-shaped was attempted. Used to surface what the assistant
   * tried (e.g. `sendGeneratedImage`), whether the image slot was acquired or busy,
   * and whether the parser silently dropped a tool-shaped reply.
   */
  toolCalls?: ChatToolCallEvent[];
}

type ChatPsychicDebugPayload = NonNullable<ChatPostEnvelope["psychicDebug"]>;

function psychicTextEnabledForConversation(
  _conversation: Pick<ConversationDetail, "mode"> | null | undefined,
  options: { productChatSurface?: boolean } = {},
): boolean {
  return options.productChatSurface === true;
}

function livePsychicScratchpadFromDebug(
  debug: ChatPsychicDebugPayload | undefined,
  enabled: boolean,
  createdAt: string,
): PsychicCanvasScratchpadPayload | null {
  if (!enabled || !debug) return null;
  const scratchpad = debug.scratchpad.trim();
  if (!scratchpad) return null;
  return {
    v: 1,
    scratchpad,
    effort: debug.effort,
    provider: debug.provider,
    ...(debug.model ? { model: debug.model } : {}),
    simulated: debug.simulated,
    ...(typeof debug.passCount === "number"
      ? { passCount: debug.passCount }
      : {}),
    ...(typeof debug.guidanceChars === "number"
      ? { guidanceChars: debug.guidanceChars }
      : {}),
    createdAt,
  };
}

function attachLivePsychicScratchpadToConversation(
  conversation: ConversationDetail,
  debug: ChatPsychicDebugPayload | undefined,
  enabled: boolean,
): ConversationDetail {
  if (!enabled || !debug?.scratchpad.trim()) return conversation;
  const targetIndex = (() => {
    for (let i = conversation.messages.length - 1; i >= 0; i -= 1) {
      const message = conversation.messages[i];
      if (message?.role === "user" && message.psychicThought) return i;
    }
    for (let i = conversation.messages.length - 1; i >= 0; i -= 1) {
      if (conversation.messages[i]?.role === "user") return i;
    }
    return -1;
  })();
  if (targetIndex < 0) return conversation;
  const target = conversation.messages[targetIndex];
  if (!target) return conversation;
  const scratchpad = livePsychicScratchpadFromDebug(
    debug,
    enabled,
    target.psychicThought?.createdAt ?? new Date().toISOString(),
  );
  if (!scratchpad) return conversation;
  return {
    ...conversation,
    messages: conversation.messages.map((message, index) =>
      index === targetIndex
        ? { ...message, psychicScratchpad: scratchpad }
        : message,
    ),
  };
}

