function ElevenLabsVoiceDirectionChips({
  value,
  onChange,
}: {
  value: string | null | undefined;
  onChange: (value: string | null) => void;
}): React.JSX.Element {
  const [draft, setDraft] = useState("");
  const directions = useMemo(
    () =>
      (normalizeElevenLabsVoiceDirection(value) ?? "")
        .split(",")
        .map((direction) => direction.trim())
        .filter(Boolean),
    [value],
  );
  const directionsAtLimit = directions.length >= 3;
  const updateDirections = (nextDirections: string[]): void => {
    const normalized = normalizeElevenLabsVoiceDirection(
      nextDirections.join(", "),
    );
    if (normalized === (value ?? null)) return;
    onChange(normalized);
  };
  const commitDraft = (rawDraft = draft): void => {
    const normalized = normalizeElevenLabsVoiceDirection(
      [...directions, rawDraft].join(", "),
    );
    setDraft("");
    if (normalized === (value ?? null)) return;
    onChange(normalized);
  };
  const handleDraftChange = (
    event: React.ChangeEvent<HTMLInputElement>,
  ): void => {
    const next = event.currentTarget.value;
    if (!/[,;\n]/u.test(next)) {
      setDraft(next);
      return;
    }
    const parts = next.split(/[,;\n]+/u);
    const endsWithDelimiter = /[,;\n]\s*$/u.test(next);
    const trailingDraft = endsWithDelimiter ? "" : (parts.pop() ?? "");
    const normalized = normalizeElevenLabsVoiceDirection(
      [...directions, ...parts].join(", "),
    );
    const nextDirections = (normalized ?? "")
      .split(",")
      .map((direction) => direction.trim())
      .filter(Boolean);
    setDraft(nextDirections.length >= 3 ? "" : trailingDraft);
    if (normalized !== (value ?? null)) onChange(normalized);
  };
  const handleDraftKeyDown = (
    event: React.KeyboardEvent<HTMLInputElement>,
  ): void => {
    const isCommitKey =
      event.key === "," ||
      event.key === ";" ||
      event.key === "Enter" ||
      event.key === "Tab";
    if (
      isCommitKey &&
      !event.shiftKey &&
      !event.altKey &&
      !event.ctrlKey &&
      !event.metaKey
    ) {
      if (!draft.trim() && event.key === "Tab") return;
      event.preventDefault();
      commitDraft();
      return;
    }
    if (
      (event.key === "Backspace" || event.key === "Delete") &&
      draft.length === 0 &&
      directions.length > 0 &&
      !event.shiftKey &&
      !event.altKey &&
      !event.ctrlKey &&
      !event.metaKey
    ) {
      event.preventDefault();
      updateDirections(directions.slice(0, -1));
    }
  };
  return (
    <div
      className={styles.botVoiceDirectionChipBox}
      data-voice-direction-chip-field="true"
      data-full={directionsAtLimit ? "true" : undefined}
      role="group"
      aria-label="ElevenLabs voice direction cues"
      onClick={(event) => {
        if (event.target === event.currentTarget) {
          event.currentTarget.querySelector("input")?.focus();
        }
      }}
    >
      {directions.map((direction, index) => (
        <button
          key={`${direction}-${index}`}
          type="button"
          className={styles.botVoiceDirectionChip}
          aria-label={`Remove voice direction ${direction}`}
          title="Remove cue"
          onClick={() =>
            updateDirections(
              directions.filter(
                (_, directionIndex) => directionIndex !== index,
              ),
            )
          }
        >
          <span>{direction}</span>
          <span aria-hidden="true">×</span>
        </button>
      ))}
      <input
        id="bot-elevenlabs-voice-direction"
        className={styles.botVoiceDirectionInput}
        aria-label="Add ElevenLabs voice direction cue"
        type="text"
        value={draft}
        disabled={directionsAtLimit}
        maxLength={48}
        placeholder={
          directions.length > 0 ? "Add another cue" : "warmly, hushed"
        }
        autoCapitalize="none"
        autoCorrect="off"
        spellCheck={true}
        onChange={handleDraftChange}
        onKeyDown={handleDraftKeyDown}
        onBlur={() => commitDraft()}
      />
    </div>
  );
}

