function createFavoritesBotGroup(): BotLibraryGroup {
  const now = new Date().toISOString();
  return {
    id: BOT_LIBRARY_FAVORITES_GROUP_ID,
    name: "Favorites",
    description: "Pinned bots you want to keep close.",
    botIds: [],
    deleteProtected: false,
    deleteProtectionByBotId: {},
    builtIn: true,
    createdAt: now,
    updatedAt: now,
  };
}

function createPrismStarterBotGroup(
  botIds: readonly string[],
  now = new Date().toISOString(),
): BotLibraryGroup | null {
  const uniqueBotIds = Array.from(
    new Set(
      botIds.filter(
        (botId) => typeof botId === "string" && botId.trim().length > 0,
      ),
    ),
  );
  if (uniqueBotIds.length < BOT_LIBRARY_CUSTOM_GROUP_MIN_BOTS) return null;
  return {
    id: BOT_LIBRARY_STARTER_GROUP_ID,
    name: BOT_LIBRARY_STARTER_GROUP_NAME,
    description: BOT_LIBRARY_STARTER_GROUP_DESCRIPTION,
    botIds: uniqueBotIds,
    marketplaceThemeId: BOT_MARKETPLACE_STARTER_THEME_ID,
    deleteProtected: false,
    deleteProtectionByBotId: {},
    builtIn: false,
    createdAt: now,
    updatedAt: now,
  };
}

function createFactoryResetBotLibraryGroups(
  starterBotIds: readonly string[],
): BotLibraryGroup[] {
  const now = new Date().toISOString();
  const starterGroup = createPrismStarterBotGroup(starterBotIds, now);
  return normalizeBotLibraryGroups([
    createFavoritesBotGroup(),
    ...(starterGroup ? [starterGroup] : []),
  ]);
}

function normalizeBotLibraryGroups(raw: unknown): BotLibraryGroup[] {
  const normalized = Array.isArray(raw)
    ? raw
        .map((candidate): BotLibraryGroup | null => {
          if (!candidate || typeof candidate !== "object") return null;
          const record = candidate as Partial<BotLibraryGroup>;
          if (typeof record.id !== "string" || typeof record.name !== "string")
            return null;
          const builtIn =
            record.id === BOT_LIBRARY_FAVORITES_GROUP_ID ||
            record.builtIn === true;
          const now = new Date().toISOString();
          const roomAtmosphere = normalizeBotGroupRoomAtmosphere(
            record.roomAtmosphere,
          );
          return {
            id: record.id.trim(),
            name: record.name.trim() || "Untitled group",
            description:
              typeof record.description === "string" ? record.description : "",
            botIds: Array.isArray(record.botIds)
              ? record.botIds.filter(
                  (id): id is string => typeof id === "string",
                )
              : [],
            deleteProtectionByBotId:
              record.deleteProtectionByBotId &&
              typeof record.deleteProtectionByBotId === "object"
                ? Object.fromEntries(
                    Object.entries(record.deleteProtectionByBotId).flatMap(
                      ([botId, protectedValue]) =>
                        typeof protectedValue === "boolean" ||
                        protectedValue === null
                          ? [[botId, protectedValue]]
                          : [],
                    ),
                  )
                : {},
            ...(roomAtmosphere ? { roomAtmosphere } : {}),
            marketplaceThemeId:
              typeof record.marketplaceThemeId === "string" &&
              record.marketplaceThemeId.trim().length > 0
                ? record.marketplaceThemeId.trim().toLowerCase()
                : null,
            deleteProtected: record.deleteProtected === true,
            builtIn,
            createdAt:
              typeof record.createdAt === "string" ? record.createdAt : now,
            updatedAt:
              typeof record.updatedAt === "string" ? record.updatedAt : now,
          };
        })
        .filter((candidate): candidate is BotLibraryGroup => Boolean(candidate))
    : [];
  const byId = new Map<string, BotLibraryGroup>();
  for (const group of normalized) {
    if (group.id.length === 0) continue;
    byId.set(group.id, {
      ...group,
      botIds: Array.from(new Set(group.botIds)),
    });
  }
  const favorites =
    byId.get(BOT_LIBRARY_FAVORITES_GROUP_ID) ?? createFavoritesBotGroup();
  byId.set(BOT_LIBRARY_FAVORITES_GROUP_ID, {
    ...favorites,
    builtIn: true,
    name: "Favorites",
  });
  return pruneBotLibraryGroupsWithFewBots(Array.from(byId.values())).sort(
    (a, b) => {
      if (a.id === BOT_LIBRARY_FAVORITES_GROUP_ID) return -1;
      if (b.id === BOT_LIBRARY_FAVORITES_GROUP_ID) return 1;
      return a.name.localeCompare(b.name);
    },
  );
}

function protectedBotIdsForBotLibraryGroups(
  groups: readonly BotLibraryGroup[],
  existingBotIds?: ReadonlySet<string>,
): Set<string> {
  const protectedIds = new Set<string>();
  for (const group of groups) {
    for (const botId of group.botIds) {
      const override = group.deleteProtectionByBotId?.[botId];
      const protectedByMembership =
        override === true || (override !== false && group.deleteProtected);
      if (
        protectedByMembership &&
        (!existingBotIds || existingBotIds.has(botId))
      ) {
        protectedIds.add(botId);
      }
    }
  }
  return protectedIds;
}

function applyBotDeleteProtectionProjection(
  rows: Bot[],
  protectedBotIds: ReadonlySet<string>,
): Bot[] {
  let changed = false;
  const next = rows.map((bot) => {
    const deleteProtected = protectedBotIds.has(bot.id) ? 1 : 0;
    if (bot.delete_protected === deleteProtected) return bot;
    changed = true;
    return { ...bot, delete_protected: deleteProtected };
  });
  return changed ? next : rows;
}

function createBotLibraryGroupId(): string {
  return typeof crypto !== "undefined" &&
    typeof crypto.randomUUID === "function"
    ? `group:${crypto.randomUUID()}`
    : `group:${Date.now().toString(36)}`;
}

interface MarketplaceInstalledBotReference {
  botHash: string | null;
  botId: string;
}

interface MarketplaceBundleImportResult {
  importedBotIds: string[];
  importedBotReferences: MarketplaceInstalledBotReference[];
  restoredTotal: number;
  thinkingSfxGenerated: number;
  thinkingSfxFailed: number;
  thinkingSfxFailureMessage: string | null;
}

function marketplaceThinkingSfxNotice(
  result: Pick<
    MarketplaceBundleImportResult,
    "thinkingSfxGenerated" | "thinkingSfxFailed" | "thinkingSfxFailureMessage"
  >,
): string {
  if (result.thinkingSfxFailed > 0) {
    return ` ${result.thinkingSfxFailed} thinking loop${
      result.thinkingSfxFailed === 1 ? " was" : "s were"
    } not created: ${
      result.thinkingSfxFailureMessage ?? "ElevenLabs was unavailable."
    }`;
  }
  if (result.thinkingSfxGenerated > 0) {
    return ` ${result.thinkingSfxGenerated} unique thinking loop${
      result.thinkingSfxGenerated === 1 ? " is" : "s are"
    } ready.`;
  }
  return "";
}

function botIdByMarketplaceHash(
  bots: readonly Bot[],
  extraInstalledBots: readonly MarketplaceInstalledBotReference[] = [],
): Map<string, string> {
  const byHash = new Map<string, string>();
  for (const bot of bots) {
    const hash = normalizeImportedBotHash(bot.export_hash);
    if (hash) byHash.set(hash, bot.id);
  }
  for (const bot of extraInstalledBots) {
    const hash = normalizeImportedBotHash(bot.botHash);
    if (hash && bot.botId.trim().length > 0) {
      byHash.set(hash, bot.botId);
    }
  }
  return byHash;
}

function upsertMarketplaceBotLibraryThemeGroups(
  groups: readonly BotLibraryGroup[],
  manifest: BotMarketplaceManifest,
  touchedEntries: readonly BotMarketplaceEntry[],
  installedBots: readonly Bot[],
  extraInstalledBots: readonly MarketplaceInstalledBotReference[] = [],
  branchName?: string,
): BotLibraryGroup[] {
  const touchedEntryIds = new Set(touchedEntries.map((entry) => entry.id));
  if (touchedEntryIds.size === 0) return [...groups];

  const installedBotIdByHash = botIdByMarketplaceHash(
    installedBots,
    extraInstalledBots,
  );
  let nextGroups = normalizeBotLibraryGroups(groups);
  for (const theme of marketplaceVisibleThemes(manifest, { branchName })) {
    const themeEntries = marketplaceEntriesForTheme(manifest, theme.id, {
      branchName,
    });
    if (!themeEntries.some((entry) => touchedEntryIds.has(entry.id))) continue;
    const themeBotIds = themeEntries
      .map((entry) => installedBotIdByHash.get(entry.botHash) ?? null)
      .filter((botId): botId is string => Boolean(botId));
    if (themeBotIds.length === 0) continue;
    nextGroups = upsertBotLibraryGroup(nextGroups, {
      name: theme.name,
      description: theme.description,
      botIds: themeBotIds,
      marketplaceThemeId: theme.id,
      createGroupId: createBotLibraryGroupId,
    });
  }
  return normalizeBotLibraryGroups(nextGroups);
}

