const THEME_LABEL: Record<Theme, string> = {
  light: "Light",
  dark: "Dark",
  system: "Auto",
};

function nextThemeMode(current: Theme): Theme {
  if (current === "light") return "dark";
  if (current === "dark") return "system";
  return "light";
}

function isContextMenuPointerGesture(
  event: MouseEvent | PointerEvent,
): boolean {
  const isMouseEvent =
    !("pointerType" in event) || event.pointerType === "mouse";
  return (
    isMouseEvent &&
    (event.button === 2 || (event.ctrlKey && event.button === 0))
  );
}

function isPrimaryPointerDismissal(event: MouseEvent | PointerEvent): boolean {
  // Dismiss on normal primary clicks/taps, and also on desktop context-menu
  // gestures (right-click / Ctrl+click) so users can close menus without an
  // extra left-click.
  return isContextMenuPointerGesture(event) || event.button === 0;
}

function authHeadersForFetch(): HeadersInit {
  let nativeSessionToken: string | null = null;
  let clientAccessToken: string | null = null;
  if (typeof window !== "undefined") {
    try {
      nativeSessionToken = window.localStorage.getItem(
        NATIVE_SESSION_STORAGE_KEY,
      );
      clientAccessToken = window.localStorage.getItem(
        CLIENT_ACCESS_STORAGE_KEY,
      );
    } catch {
      nativeSessionToken = null;
      clientAccessToken = null;
    }
  }
  return {
    ...(nativeSessionToken
      ? { authorization: `Bearer ${nativeSessionToken}` }
      : {}),
    ...(clientAccessToken
      ? { "x-prism-client-access": clientAccessToken }
      : {}),
  };
}

async function fetchAuthenticated(
  path: string,
  init?: RequestInit,
): Promise<Response> {
  return fetch(path, {
    credentials: "include",
    headers: {
      ...authHeadersForFetch(),
      ...(init?.headers ?? {}),
    },
    ...init,
  });
}

type BabbleSynthesisMedia =
  | {
      kind: "clip";
      clip: Awaited<ReturnType<typeof readEnglishVoiceSynthesisClip>>;
    }
  | { kind: "stream"; response: Response };

type BotcastEnglishVoiceMedia =
  | { kind: "clip"; clip: EnglishVoiceSynthesisClip }
  | {
      kind: "stream";
      response: Response;
      engineUsed: string | null;
      modelHash: string | null;
      notice: string | null;
      resolvedPronunciation?: ReplayVoiceTakeV1["resolvedPronunciation"];
      resolvedSpeechprint?: ReplayVoiceTakeV1["resolvedSpeechprint"];
    };

async function requestBabbleSynthesisClip(args: {
  source: Record<string, unknown>;
  profile: BotAudioVoiceProfileV1;
  seed: string;
  signal?: AbortSignal;
  includeAlignment?: boolean;
  streamChunks?: boolean;
  moodKey?: BotMoodKey;
}): Promise<BabbleSynthesisMedia | null> {
  const response = await fetchAuthenticated("/api/voices/synthesize", {
    method: "POST",
    signal: args.signal,
    headers: { "content-type": "application/json" },
    body: JSON.stringify({
      ...args.source,
      mode: "babble",
      engine: "builtin",
      seed: args.seed,
      includeAlignment: args.includeAlignment === true,
      streamChunks: args.streamChunks === true,
      moodKey: args.moodKey,
      profile: normalizeBottishPlaybackProfile(args.profile),
    }),
  });
  if (!response.ok) {
    const payload = (await response.json().catch(() => null)) as {
      code?: string;
      error?: string;
    } | null;
    if (payload?.code === "babble-system-unavailable") return null;
    if (isBackendUnavailablePayload(payload)) {
      const error = createBackendUnavailableErrorFromPayload(payload, {
        path: "/api/voices/synthesize",
        status: response.status,
      });
      dispatchBackendUnavailableEvent(error);
      throw error;
    }
    throw new Error(
      payload?.error ??
        payload?.code ??
        `Babble synthesis failed (${response.status}).`,
    );
  }
  dispatchBackendAvailableEvent();
  if (englishVoiceResponseSupportsChunkedStreaming(response)) {
    return { kind: "stream", response };
  }
  const clip = await readBabbleVoiceSynthesisClip(response);
  return clip ? { kind: "clip", clip } : null;
}

function enqueueBabbleClipOrFallback(args: {
  media: BabbleSynthesisMedia | null;
  sourceText: string;
  profile: BotAudioVoiceProfileV1;
  seed: string;
  effectsEnabled: boolean;
  globalVolume: number;
  lifecycle?: Parameters<typeof enqueueBottishVoice>[5];
  proceduralTiming?: Parameters<typeof enqueueBottishVoice>[6];
  roomAcoustics?: RoomAcousticsSend;
  preSpeechBreath?: PreSpeechBreathPlan | null;
  stereoPan?: number;
}): Promise<void> {
  const clip = args.media?.kind === "clip" ? args.media.clip : null;
  const lifecycle =
    clip?.alignment && args.lifecycle
      ? {
          ...args.lifecycle,
          onStart: (durationMs: number | null) =>
            args.lifecycle?.onStart?.(durationMs, clip.alignment),
        }
      : args.lifecycle;
  if (args.media?.kind === "stream") {
    return enqueueChunkedBabbleVoice(
      args.media.response,
      args.sourceText,
      args.profile,
      args.seed,
      args.effectsEnabled,
      args.globalVolume,
      lifecycle,
      args.roomAcoustics,
      args.preSpeechBreath,
      args.proceduralTiming,
      args.stereoPan,
    );
  }
  return clip
    ? enqueueBabbleVoice(
        clip.bytes,
        args.sourceText,
        args.profile,
        args.seed,
        args.effectsEnabled,
        args.globalVolume,
        lifecycle,
        args.roomAcoustics,
        args.preSpeechBreath,
        args.proceduralTiming,
        args.stereoPan,
      )
    : enqueueBottishVoice(
        args.sourceText,
        args.profile,
        args.seed,
        args.effectsEnabled,
        args.globalVolume,
        args.lifecycle,
        args.proceduralTiming,
        args.roomAcoustics,
        args.preSpeechBreath,
        args.stereoPan,
      );
}

class BabbleVoiceUnavailableError extends Error {
  constructor() {
    super("Babble voice is still loading/unavailable. Please try again.");
    this.name = "BabbleVoiceUnavailableError";
  }
}

async function prepareVoiceModePlayback(mode: VoiceMode): Promise<void> {
  if (mode === "bottish") await prepareBottishVoice();
  else if (mode === "babble") await prepareBabbleVoice();
  else if (mode === "english") await prepareEnglishVoice();
}

function primeVoiceModePlaybackFromUserGesture(mode: VoiceMode): void {
  if (mode === "mute") return;
  void prepareVoiceModePlayback(mode).catch(() => undefined);
}

function stopVoicePlaybackPreservingPreparedMode(mode: VoiceMode): void {
  stopBottishVoice({
    preservePreparedMedia: mode === "bottish" || mode === "babble",
  });
  stopEnglishVoice({ preservePreparedMedia: mode === "english" });
}

/** Retire queue ownership for a natural speaker handoff without severing a
 * completed voice graph that is still draining its final rendered phoneme. */
function handoffVoicePlaybackPreservingPreparedMode(mode: VoiceMode): void {
  stopBottishVoice({
    preservePreparedMedia: mode === "bottish" || mode === "babble",
    preserveCompletedTails: true,
  });
  stopEnglishVoice({
    preservePreparedMedia: mode === "english",
    preserveCompletedTails: true,
  });
}

function releaseVoicePlaybackPreservingPreparedMode(
  mode: VoiceMode,
  fadeOutMs: number,
): void {
  releaseBottishVoice({
    fadeOutMs,
    preservePreparedMedia: mode === "bottish" || mode === "babble",
  });
  releaseEnglishVoice({
    fadeOutMs,
    preservePreparedMedia: mode === "english",
  });
}

async function enqueueRobotVoiceMode(args: {
  mode: "bottish" | "babble";
  source: Record<string, unknown>;
  sourceText: string;
  profile: BotAudioVoiceProfileV1;
  seed: string;
  effectsEnabled: boolean;
  globalVolume: number;
  signal?: AbortSignal;
  lifecycle?: Parameters<typeof enqueueBottishVoice>[5];
  proceduralTiming?: Parameters<typeof enqueueBottishVoice>[6];
  allowBabbleFallback?: boolean;
  prepare?: boolean;
  includeAlignment?: boolean;
  streamChunks?: boolean;
  namePronunciations?: readonly BotNamePronunciationEntry[];
  speakerBotId?: string | null;
  moodKey?: BotMoodKey;
  roomAcoustics?: RoomAcousticsSend;
  preSpeechBreath?: PreSpeechBreathPlan | null;
  stereoPan?: number;
}): Promise<void> {
  if (args.prepare !== false) await prepareVoiceModePlayback(args.mode);
  const spokenSourceText = applyBotNamePronunciations(
    args.sourceText,
    args.namePronunciations ?? [],
    args.speakerBotId,
  ) as string;
  const proceduralTiming = {
    ...args.proceduralTiming,
    deliveryRate:
      (args.proceduralTiming?.deliveryRate ?? 1) *
      voiceDeliveryRateForMood(args.moodKey),
  };
  if (args.mode === "bottish") {
    return enqueueBottishVoice(
      spokenSourceText,
      args.profile,
      args.seed,
      args.effectsEnabled,
      args.globalVolume,
      args.lifecycle,
      proceduralTiming,
      args.roomAcoustics,
      args.preSpeechBreath,
      args.stereoPan,
    );
  }
  const media = await requestBabbleWithProceduralFallback({
    request: () =>
      requestBabbleSynthesisClip({
        source: {
          ...args.source,
          ...(args.speakerBotId ? { speakerBotId: args.speakerBotId } : {}),
        },
        profile: args.profile,
        seed: args.seed,
        signal: args.signal,
        includeAlignment: args.includeAlignment,
        streamChunks: args.streamChunks,
        moodKey: args.moodKey,
      }),
    allowFallback: args.allowBabbleFallback,
    isTransportFailure: (error) =>
      looksLikeDisconnectedFetchFailure(error, "/api/voices/synthesize"),
  });
  if (args.signal?.aborted) return;
  if (!media && args.allowBabbleFallback === false) {
    throw new BabbleVoiceUnavailableError();
  }
  return enqueueBabbleClipOrFallback({
    media,
    sourceText: spokenSourceText,
    // System synthesis stays neutral-tempo. Apply Signal's ephemeral cadence
    // locally during playback without baking it into the saved bot profile.
    profile: args.profile,
    seed: args.seed,
    effectsEnabled: args.effectsEnabled,
    globalVolume: args.globalVolume,
    lifecycle: args.lifecycle,
    proceduralTiming,
    roomAcoustics: args.roomAcoustics,
    preSpeechBreath: args.preSpeechBreath,
    stereoPan: args.stereoPan,
  });
}

function sanitizeForFilenameSegment(raw: string): string {
  const cleaned = raw.replace(/[^\w.-]+/g, "_").replace(/^_+|_+$/g, "");
  return cleaned.length > 0 ? cleaned.slice(0, 96) : "image";
}

async function downloadBotImageFile(
  img: ImageRecord,
  botDisplayName: string,
): Promise<void> {
  const path = img.displayUrl ?? img.url;
  const res = await fetchAuthenticated(path);
  if (!res.ok) {
    const raw = await res.text();
    let message = raw.trim() || `Download failed (${res.status})`;
    let payload: { ok?: boolean; error?: string } | null = null;
    try {
      payload = JSON.parse(raw) as { ok?: boolean; error?: string };
      if (payload.error) message = payload.error;
    } catch {
      // Keep constructed message when body is not JSON.
    }
    if (
      shouldRedirectToLoginForApiFailure({
        path,
        status: res.status,
        payload,
      })
    ) {
      dispatchAuthReauthRequiredEvent({
        path,
        status: res.status,
        reason: message,
      });
      throw new Error("Please log in again.");
    }
    throw new Error(message);
  }
  const blob = await res.blob();
  const stamp = sanitizeForFilenameSegment(
    (img.createdAt ?? img.id).replace(/[:.]/g, "-"),
  );
  const nameBase = sanitizeForFilenameSegment(botDisplayName);
  const filename = `prism-${nameBase}-image-${stamp}.png`;
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = filename;
  anchor.rel = "noopener";
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
  URL.revokeObjectURL(url);
}

function formatImageGenElapsed(seconds: number): string {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${m}:${String(s).padStart(2, "0")}`;
}

/** Transport-layer failures hide behind vague messages or bare `TypeError` on some browsers. */
function looksLikeDisconnectedFetchFailure(
  err: unknown,
  path: string,
): boolean {
  const top = err instanceof Error ? err.message : String(err ?? "");
  const cause =
    err instanceof Error &&
    typeof err === "object" &&
    err.cause !== undefined &&
    err.cause !== null &&
    err.cause instanceof Error
      ? err.cause.message
      : "";
  const lowered = `${top} ${cause}`.toLowerCase();
  const isApiPath = typeof path === "string" && path.startsWith("/api");
  if (
    lowered.includes("fetch failed") ||
    lowered.includes("failed to fetch") ||
    lowered.includes("networkerror") ||
    lowered.includes("network request failed") ||
    lowered.includes("load failed") ||
    lowered.includes("unable to fetch") ||
    lowered.includes("connection refused") ||
    lowered.includes("econnrefused") ||
    lowered.includes("econnreset")
  )
    return true;
  if (!isApiPath || !(err instanceof TypeError)) return false;
  if (!top.trim()) return true;
  return (
    lowered.includes("fetch") ||
    lowered.includes("network") ||
    lowered.includes("load") ||
    lowered.includes("failed")
  );
}

function prismApiTransportHint(path: string, rawMsg: string): Error {
  return createBackendUnavailableError("Prism is waiting for its local API.", {
    path,
    detail: rawMsg,
  });
}

function isBotNotFoundError(err: unknown): boolean {
  return (
    err instanceof Error && err.message.toLowerCase().includes("bot not found")
  );
}

function apiErrorWithDiagnostic(
  error: unknown,
  path: string,
  options?: RequestInit,
  status?: number,
): unknown {
  return attachWebRequestDiagnostic(error, {
    method: options?.method ?? "GET",
    path,
    ...(typeof status === "number" ? { status } : {}),
  });
}

async function api<T>(path: string, options?: RequestInit): Promise<T> {
  const headers: HeadersInit = {
    "content-type": "application/json",
    ...authHeadersForFetch(),
    ...(options?.headers ?? {}),
  };
  const requestUrl =
    typeof window !== "undefined" &&
    typeof path === "string" &&
    path.startsWith("/") &&
    !path.startsWith("//")
      ? new URL(path, window.location.origin).href
      : path;
  let res: Response;
  try {
    res = await fetch(requestUrl, {
      credentials: "include",
      headers,
      ...options,
    });
  } catch (err) {
    if (isAbortLikeError(err)) throw err;
    const rawMsg =
      err instanceof Error
        ? `${err.message || err.name}`.trim()
        : String(err ?? "");
    if (looksLikeDisconnectedFetchFailure(err, path)) {
      const backendError = prismApiTransportHint(path, rawMsg || "network");
      if (isPrismBackendUnavailableError(backendError)) {
        dispatchBackendUnavailableEvent(backendError);
      }
      throw apiErrorWithDiagnostic(backendError, path, options);
    }
    throw apiErrorWithDiagnostic(
      err instanceof Error ? err : new Error(rawMsg),
      path,
      options,
    );
  }
  // Next rewrite failures can come back as plain text, so parse the body
  // defensively and surface the actual message instead of a JSON parse error.
  let raw: string;
  try {
    raw = await res.text();
  } catch (err) {
    if (isAbortLikeError(err)) throw err;
    const rawMsg =
      err instanceof Error
        ? `${err.message || err.name}`.trim()
        : String(err ?? "");
    if (looksLikeDisconnectedFetchFailure(err, path)) {
      const backendError = prismApiTransportHint(
        path,
        rawMsg || "response body interrupted",
      );
      if (isPrismBackendUnavailableError(backendError)) {
        dispatchBackendUnavailableEvent(backendError);
      }
      throw apiErrorWithDiagnostic(backendError, path, options, res.status);
    }
    throw apiErrorWithDiagnostic(
      err instanceof Error ? err : new Error(rawMsg),
      path,
      options,
      res.status,
    );
  }
  let payload: (T & { ok?: boolean; error?: string }) | null = null;
  if (raw.trim().length > 0) {
    try {
      payload = JSON.parse(raw) as T & { ok?: boolean; error?: string };
    } catch {
      payload = null;
    }
  }
  if (!res.ok || payload?.ok === false) {
    if (isBackendUnavailablePayload(payload)) {
      const backendError = createBackendUnavailableErrorFromPayload(payload, {
        path,
        status: res.status,
      });
      dispatchBackendUnavailableEvent(backendError);
      throw apiErrorWithDiagnostic(backendError, path, options, res.status);
    }
    const fallbackMessage = raw.trim() || `Request failed (${res.status})`;
    if (
      shouldRedirectToLoginForApiFailure({
        path,
        status: res.status,
        payload,
      })
    ) {
      dispatchAuthReauthRequiredEvent({
        path,
        status: res.status,
        reason: payload?.error ?? fallbackMessage,
      });
      throw apiErrorWithDiagnostic(
        new Error("Please log in again."),
        path,
        options,
        res.status,
      );
    }
    throw apiErrorWithDiagnostic(
      new Error(payload?.error ?? fallbackMessage),
      path,
      options,
      res.status,
    );
  }
  if (
    typeof path === "string" &&
    path.startsWith("/api") &&
    path !== "/api/dev/restart"
  ) {
    dispatchBackendAvailableEvent();
  }
  return (payload ?? {}) as T;
}

async function apiZenProgressiveChat<T>(args: {
  body: Record<string, unknown>;
  signal: AbortSignal;
  onSegment: (event: ZenProgressiveSegmentEvent) => void;
  onEnd?: (event: ZenProgressiveEndEvent) => void;
  onPsychic?: (event: PsychicProgressEvent) => void;
}): Promise<T> {
  const path = "/api/chat";
  const options: RequestInit = {
    method: "POST",
    signal: args.signal,
    body: JSON.stringify(args.body),
  };
  let response: Response;
  try {
    response = await fetch(new URL(path, window.location.origin), {
      credentials: "include",
      headers: {
        "content-type": "application/json",
        ...authHeadersForFetch(),
      },
      ...options,
    });
  } catch (error) {
    if (isAbortLikeError(error)) throw error;
    const rawMessage =
      error instanceof Error ? error.message : String(error ?? "");
    if (looksLikeDisconnectedFetchFailure(error, path)) {
      const backendError = prismApiTransportHint(path, rawMessage || "network");
      if (isPrismBackendUnavailableError(backendError)) {
        dispatchBackendUnavailableEvent(backendError);
      }
      throw apiErrorWithDiagnostic(backendError, path, options);
    }
    throw apiErrorWithDiagnostic(error, path, options);
  }

  if (!response.ok) {
    const raw = await response.text();
    let payload: { ok?: boolean; error?: string } | null = null;
    try {
      payload = JSON.parse(raw) as { ok?: boolean; error?: string };
    } catch {
      payload = null;
    }
    if (isBackendUnavailablePayload(payload)) {
      const backendError = createBackendUnavailableErrorFromPayload(payload, {
        path,
        status: response.status,
      });
      dispatchBackendUnavailableEvent(backendError);
      throw apiErrorWithDiagnostic(
        backendError,
        path,
        options,
        response.status,
      );
    }
    throw apiErrorWithDiagnostic(
      new Error(
        payload?.error ?? (raw.trim() || `Request failed (${response.status})`),
      ),
      path,
      options,
      response.status,
    );
  }

  const contentType = response.headers.get("content-type")?.toLowerCase() ?? "";
  if (!contentType.includes("application/x-ndjson")) {
    const payload = (await response.json()) as T;
    dispatchBackendAvailableEvent();
    return payload;
  }
  const result = await readZenProgressiveChatStream<T>({
    response,
    onSegment: args.onSegment,
    onEnd: args.onEnd,
    onPsychic: args.onPsychic,
  });
  dispatchBackendAvailableEvent();
  return result;
}

async function writeClipboardText(text: string): Promise<void> {
  if (navigator.clipboard && window.isSecureContext) {
    try {
      await navigator.clipboard.writeText(text);
      return;
    } catch {
      // Fall through to the legacy path below; LAN dev over plain HTTP is not
      // always treated as a secure context even when the user explicitly clicks.
    }
  }

  const textarea = document.createElement("textarea");
  textarea.value = text;
  textarea.setAttribute("readonly", "true");
  textarea.style.position = "fixed";
  textarea.style.left = "-9999px";
  textarea.style.top = "0";
  document.body.appendChild(textarea);
  textarea.focus();
  textarea.select();

  try {
    const copied = document.execCommand("copy");
    if (!copied) {
      throw new Error("Clipboard copy command failed.");
    }
  } finally {
    textarea.remove();
  }
}

function clearNativeSessionToken(): void {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.removeItem(NATIVE_SESSION_STORAGE_KEY);
  } catch {
    // Non-fatal: cookie-backed browser auth can still continue normally.
  }
}

