function randomBotName(): string {
  return randomArrayItem(RANDOM_BOT_NAMES);
}

function sampleBotNames(count: number): string[] {
  const pool = [...RANDOM_BOT_NAMES];
  for (let i = pool.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  const names: string[] = pool.slice(0, Math.min(count, pool.length));
  while (names.length < count) {
    names.push(randomArrayItem(RANDOM_BOT_NAMES));
  }
  return names;
}

interface BotGlyphProps {
  name: string | null | undefined;
  size?: number;
  strokeWidth?: number;
  className?: string;
}

const BOT_GLYPH_STANDARD_SIZE = 28;
const BOT_GLYPH_STANDARD_STROKE_WIDTH = 1.45;
const BOT_GLYPH_STROKE_MIN_SIZE = 14;
const BOT_GLYPH_STROKE_MAX_SIZE = 56;
const BOT_GLYPH_STROKE_HEAVY = 2.25;
const BOT_GLYPH_STROKE_THIN = 1.1;

function botGlyphStrokeForSize(size: number): number {
  if (size === BOT_GLYPH_STANDARD_SIZE) return BOT_GLYPH_STANDARD_STROKE_WIDTH;

  const clampedSize = Math.max(
    BOT_GLYPH_STROKE_MIN_SIZE,
    Math.min(BOT_GLYPH_STROKE_MAX_SIZE, size),
  );
  const t =
    (clampedSize - BOT_GLYPH_STROKE_MIN_SIZE) /
    (BOT_GLYPH_STROKE_MAX_SIZE - BOT_GLYPH_STROKE_MIN_SIZE);
  const stroke =
    BOT_GLYPH_STROKE_HEAVY +
    (BOT_GLYPH_STROKE_THIN - BOT_GLYPH_STROKE_HEAVY) * t;

  return Number(stroke.toFixed(2));
}

function BotGlyph({
  name,
  size = BOT_GLYPH_STANDARD_SIZE,
  strokeWidth,
  className,
}: BotGlyphProps): React.JSX.Element {
  const key: BotGlyphName = isBotGlyphName(name) ? name : DEFAULT_BOT_GLYPH;
  const definition = BOT_GLYPHS[key];
  const resolvedStrokeWidth = strokeWidth ?? botGlyphStrokeForSize(size);

  if (definition.icon) {
    const Icon = definition.icon;
    return (
      <Icon
        className={className}
        size={size}
        strokeWidth={resolvedStrokeWidth}
        aria-hidden={true}
      />
    );
  }

  return (
    <svg
      className={className}
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={resolvedStrokeWidth}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
    >
      {definition.paths}
    </svg>
  );
}

function EmptyStateBotGlyph({
  bot,
  resolvedTheme,
  privateMode = false,
}: {
  bot: Bot;
  resolvedTheme: "light" | "dark";
  privateMode?: boolean;
}): React.JSX.Element {
  const style = botAccentStyle(bot.color, resolvedTheme);

  return (
    <span
      className={`${styles.emptyStateBotGlyph} ${
        privateMode ? styles.emptyStatePrivateBotGlyph : ""
      }`}
      data-private-mode={privateMode ? "true" : "false"}
      aria-hidden="true"
      style={style}
    >
      <span
        className={`${styles.emptyStateBotGlyphLayer} ${styles.emptyStateBotGlyphLayerPublic}`}
      >
        <BotGlyph name={bot.glyph} />
      </span>
      <span
        className={`${styles.emptyStateBotGlyphLayer} ${styles.emptyStateBotGlyphLayerPrivate}`}
      >
        <BotGlyph name={bot.glyph} />
      </span>
    </span>
  );
}

// ── Empty-state icon ──────────────────────────────────────────────────
// Rendered at the top of the "new conversation" placeholder in Chat and
// Sandbox. Three rendering modes, chosen by preview/commit state:
//
//   1. No bot state → the same Prism mark used by the auth screen:
//      dark mode gets the boxed static triangle with animated RGB halos;
//      light mode gets the hue-rotating rainbow triangle with its static
//      drop-shadow.
//
//   2. `privateHero` set → private styling. Default/Prism keeps the
//      hub-style silver tile with grayscale glow; selected bots keep their
//      glyph/color but render through a more restrained inverted private tile.
//
//   3. `previewBot` set → Prism triangle, but tinted to the hovered bot's
//      normalized color. This keeps hover feeling like Prism is focusing
//      through the bot rather than replacing the hero with the bot profile.
//
//   4. `bot` set → scaled-up sibling of the .botCardGlyph tile in the
//      bot's full color. Same visual language (tinted bg + border,
//      bot-color stroke) as every other place a bot is represented. The
//      stored color is normalized so legacy bots whose picked hex drifted
//      outside the current safe range still render readably. Used once the
//      user commits the bot selection.
//
// All modes paint at the same 56×56 footprint so the layout never
// jumps when the user scans across tiles.
interface EmptyStateIconProps {
  bot: Bot | null;
  previewBot?: Bot | null;
  previewAsBotGlyph?: boolean;
  /**
   * Private chats borrow the hub/profile avatar treatment for Default, while
   * selected bots render as a subdued inverted bot glyph.
   */
  privateHero?: boolean;
  /**
   * Force the bare Prism-triangle preview regardless of bot/previewBot.
   * Used by the empty-state surface during an active hue-lens drag so the
   * hero collapses to a single tintable triangle while the slider is
   * being engaged — the triangle's stroke inherits `--accent`, so any
   * shell-level lens tint flows through automatically.
   */
  forceTrianglePreview?: boolean;
  /**
   * Active theme, resolved upstream. The bot's stored color runs through
   * `normalizeAccentForTheme(_, resolvedTheme)` so deep hues lift in dark
   * mode and bright warm hues dim in light mode before painting glyphs.
   */
  resolvedTheme: "light" | "dark";
}

function EmptyStateIcon({
  bot,
  previewBot = null,
  previewAsBotGlyph = false,
  privateHero = false,
  forceTrianglePreview = false,
  resolvedTheme,
}: EmptyStateIconProps): React.JSX.Element {
  if (privateHero && bot) {
    return (
      <EmptyStateBotGlyph bot={bot} resolvedTheme={resolvedTheme} privateMode />
    );
  }

  if (privateHero) {
    return (
      <div
        className={`${styles.brandIconShell} ${styles.userHeroAvatar} ${styles.emptyStatePrivateHero}`}
        aria-hidden="true"
      >
        {/* Decorative shell art; keeping native img avoids layout shifts in this icon stack. */}
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img
          src="/icon.jpg"
          alt=""
          aria-hidden="true"
          className={styles.brandIcon}
        />
        <PrismTriangleMark className={styles.brandIconLight} />
      </div>
    );
  }

  if (forceTrianglePreview) {
    return (
      <div
        className={`${styles.emptyStateBrand} ${styles.emptyStateBrandPreview}`}
        aria-hidden="true"
      >
        <PrismTriangleMark className={styles.emptyStateBrandTriangle} />
      </div>
    );
  }

  if (!bot && previewBot) {
    if (previewAsBotGlyph) {
      return (
        <EmptyStateBotGlyph bot={previewBot} resolvedTheme={resolvedTheme} />
      );
    }

    return (
      <div
        className={`${styles.emptyStateBrand} ${styles.emptyStateBrandPreview}`}
        aria-hidden="true"
      >
        <PrismTriangleMark className={styles.emptyStateBrandTriangle} />
      </div>
    );
  }

  if (bot) {
    return <EmptyStateBotGlyph bot={bot} resolvedTheme={resolvedTheme} />;
  }
  return (
    <div className={styles.brandIconShell} aria-hidden="true">
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src="/icon.jpg"
        alt=""
        aria-hidden="true"
        className={styles.brandIcon}
      />
      <PrismTriangleMark className={styles.brandIconLight} />
    </div>
  );
}

interface BotGlyphPickerProps {
  value: string | null | undefined;
  onChange: (next: BotGlyphName) => void;
}

const BOT_GLYPH_PICKER_GLYPH_SIZE = 56;
const BOT_GLYPH_PICKER_STROKE_WIDTH = 0.85;

function BotGlyphPicker({
  value,
  onChange,
}: BotGlyphPickerProps): React.JSX.Element {
  const selected: BotGlyphName = isBotGlyphName(value)
    ? value
    : DEFAULT_BOT_GLYPH;
  return (
    <div
      className={styles.glyphPicker}
      role="radiogroup"
      aria-label="Bot glyph"
    >
      {CUSTOM_BOT_GLYPH_ORDER.map((key) => {
        const definition = BOT_GLYPHS[key];
        if (!definition) return null;
        const isSelected = key === selected;
        return (
          <button
            key={key}
            type="button"
            role="radio"
            aria-checked={isSelected}
            className={`${styles.glyphOption} ${isSelected ? styles.glyphOptionSelected : ""}`}
            onClick={() => onChange(key)}
            data-glyph-tooltip={definition.label}
            aria-label={definition.label}
          >
            <BotGlyph
              name={key}
              size={BOT_GLYPH_PICKER_GLYPH_SIZE}
              strokeWidth={BOT_GLYPH_PICKER_STROKE_WIDTH}
              className={styles.glyphOptionIcon}
            />
          </button>
        );
      })}
    </div>
  );
}

const COMPOSE_MENU_VIEWPORT_PAD_PX = 12;
const COMPOSE_MENU_MAX_WIDTH_PX = 360;
/** Minimum popover width when the trigger is very narrow (matches CSS floors). */
const COMPOSE_MENU_BOT_MIN_WIDTH_PX = 260;
const COMPOSE_MENU_MODEL_MIN_WIDTH_PX = 300;
const BOT_LIBRARY_GROUP_MENU_MIN_WIDTH_PX = 240;
const COMPOSE_COMMAND_MENU_MIN_WIDTH_PX = 320;
const COMPOSE_MENU_PORTAL_Z_INDEX_BOT = 2500;
/** Slightly above bot menu so both open pickers stack predictably over the rail. */
const COMPOSE_MENU_PORTAL_Z_INDEX_MODEL = 2600;
type ComposeMenuPlacement = "up" | "down" | "right";
const COMPOSE_MENU_SIDE_MAX_WIDTH_PX = 330;
const COMPOSE_MENU_SIDE_HEIGHT_TARGET_PX = 380;
/** Matches `.composeBotMenu { max-height: min(420px, …) }` for caret popovers. */
const COMPOSE_CARET_MENU_MAX_HEIGHT_CAP_PX = 420;
/** Minimum space below the caret before the caret popover prefers opening downward. */
const COMPOSE_CARET_MENU_MIN_OPEN_BELOW_PX = 160;
const COMPOSE_MENU_PORTAL_THEME_VARS = [
  "--bg",
  "--bg-surface",
  "--bg-deep",
  "--bg-hover",
  "--bg-active",
  "--fg",
  "--fg-muted",
  "--fg-subtle",
  "--line",
  "--line-strong",
  "--accent",
  "--accent-ink",
  "--accent-text",
  "--accent-soft",
  "--accent-glow",
  "--shadow-sm",
] as const;

/**
 * Fixed coordinates for portaled compose popovers. Menus are
 * portaled to `document.body` so they are not clipped by
 * `.composeTools { overflow-y: hidden }` (horizontal scroll rail).
 */
function computeComposeMenuFixedStyle(
  trigger: HTMLButtonElement,
  floorMinWidth: number,
  portalZIndex: number,
  placement: ComposeMenuPlacement = "up",
): React.CSSProperties {
  const rect = trigger.getBoundingClientRect();
  const vw = globalThis.window.innerWidth;
  const vh = globalThis.window.innerHeight;
  const pad = COMPOSE_MENU_VIEWPORT_PAD_PX;
  const gap = 6;
  const viewportMaxWidth = Math.min(COMPOSE_MENU_MAX_WIDTH_PX, vw - pad * 2);
  const preferredSideLeft = rect.right + gap;
  const sideLeft = Math.max(
    pad,
    Math.min(preferredSideLeft, vw - floorMinWidth - pad),
  );
  const sideMaxWidth = Math.max(0, vw - sideLeft - pad);
  const maxW =
    placement === "right"
      ? Math.min(COMPOSE_MENU_SIDE_MAX_WIDTH_PX, sideMaxWidth)
      : viewportMaxWidth;
  const minWidth = Math.min(Math.max(rect.width, floorMinWidth), maxW);
  // Anchor using `maxW`, not `minWidth`: the menu may expand up to max-width while
  // clamping only for min-width would leave the right edge past the viewport when the
  // trigger sits near the right side (Images panel model picker).
  const left =
    placement === "right"
      ? sideLeft
      : Math.max(pad, Math.min(rect.left, vw - maxW - pad));
  const sideTop = Math.max(
    pad,
    Math.min(rect.top - 6, vh - pad - COMPOSE_MENU_SIDE_HEIGHT_TARGET_PX),
  );
  const headerRect =
    placement === "down"
      ? trigger.closest("header")?.getBoundingClientRect()
      : null;
  const downTop =
    headerRect && headerRect.bottom > rect.bottom
      ? headerRect.bottom + gap
      : rect.bottom + gap;
  const verticalPosition =
    placement === "right"
      ? { top: sideTop, bottom: "auto" }
      : placement === "down"
        ? { top: downTop, bottom: "auto" }
        : { top: "auto", bottom: vh - rect.top + gap };
  const availableHeight =
    placement === "right"
      ? vh - pad - sideTop
      : placement === "down"
        ? vh - pad - downTop
        : rect.top - pad - gap;
  const themeVars: Record<string, string> = {};
  const computedStyle = globalThis.window.getComputedStyle(trigger);
  for (const varName of COMPOSE_MENU_PORTAL_THEME_VARS) {
    const value = computedStyle.getPropertyValue(varName).trim();
    if (value) {
      themeVars[varName] = value;
    }
  }
  return {
    position: "fixed",
    left,
    ...verticalPosition,
    minWidth,
    maxWidth: maxW,
    zIndex: portalZIndex,
    ["--compose-menu-available-height" as string]: `${Math.max(0, availableHeight)}px`,
    ...themeVars,
  } as React.CSSProperties;
}

function useComposeMenuPortalStyle(
  menuOpen: boolean,
  triggerRef: React.RefObject<HTMLButtonElement | null>,
  floorMinWidth: number,
  portalZIndex: number = COMPOSE_MENU_PORTAL_Z_INDEX_BOT,
  placement: ComposeMenuPlacement = "up",
): React.CSSProperties | undefined {
  const [fixedStyle, setFixedStyle] = useState<React.CSSProperties | undefined>(
    undefined,
  );

  useLayoutEffect(() => {
    if (!menuOpen || !triggerRef.current) {
      return;
    }
    const update = (): void => {
      const el = triggerRef.current;
      if (!el) return;
      setFixedStyle(
        computeComposeMenuFixedStyle(
          el,
          floorMinWidth,
          portalZIndex,
          placement,
        ),
      );
    };
    update();
    const w = globalThis.window;
    w.addEventListener("resize", update);
    w.addEventListener("scroll", update, true);
    return () => {
      w.removeEventListener("resize", update);
      w.removeEventListener("scroll", update, true);
    };
  }, [menuOpen, floorMinWidth, placement, portalZIndex, triggerRef]);

  return menuOpen ? fixedStyle : undefined;
}

interface BotLibraryGroupPickerOption {
  id: string;
  name: string;
  menuName?: string;
  menuCountLabel?: string;
  count: number;
  cap?: number;
  bots: readonly Bot[];
}

interface BotLibraryGroupPickerProps {
  value: string;
  options: readonly BotLibraryGroupPickerOption[];
  onChange: (nextValue: string) => void;
  onCreateGroup?: () => void;
  resolvedTheme: "light" | "dark";
  showCounts?: boolean;
  disabled?: boolean;
  dismissPopoversSignal?: number;
}

function botLibraryBotCountLabel(count: number): string {
  return count === 1 ? "1 bot" : `${count} bots`;
}

function botLibrarySelectedCountLabel(count: number): string {
  return count === 1 ? "1 selected" : `${count} selected`;
}

function botLibrarySlotCountLabel(count: number): string {
  return count === 1 ? "1 slot" : `${count} slots`;
}

function botLibraryEmptySlotCountLabel(count: number): string {
  return count === 1 ? "1 empty slot" : `${count} empty slots`;
}

function botLibraryGroupCapacityLabel(count: number, cap: number): string {
  const emptySlots = Math.max(0, cap - count);
  if (count > cap) {
    return `${botLibrarySelectedCountLabel(count)}, over the ${botLibrarySlotCountLabel(cap)} limit`;
  }
  if (emptySlots === 0) {
    return `${botLibrarySelectedCountLabel(count)}, full`;
  }
  return `${botLibrarySelectedCountLabel(count)}, ${botLibraryEmptySlotCountLabel(emptySlots)}`;
}

function botLibraryGroupPickerCountLabel(
  option: BotLibraryGroupPickerOption,
): string {
  if (option.id === BOT_LIBRARY_GROUP_FILTER_ALL) {
    return String(option.count);
  }
  if (option.cap !== undefined) {
    return botLibrarySelectedCountLabel(option.count);
  }
  return botLibraryBotCountLabel(option.count);
}

function botLibraryGroupDashboardEyebrowLabel(
  count: number,
  cap: number | undefined,
  protectedCount: number,
): string {
  const labels =
    cap === undefined
      ? [botLibraryBotCountLabel(count)]
      : [
          botLibrarySelectedCountLabel(count),
          count > cap
            ? `over the ${botLibrarySlotCountLabel(cap)} limit`
            : count === cap
              ? "full"
              : botLibraryEmptySlotCountLabel(Math.max(0, cap - count)),
        ];
  if (protectedCount > 0) {
    labels.push(`${protectedCount} protected`);
  }
  return labels.join(" · ");
}

function botLibraryGroupSizeError(count: number): string | null {
  if (count < BOT_LIBRARY_CUSTOM_GROUP_MIN_BOTS) {
    return `Custom bot groups need at least ${BOT_LIBRARY_CUSTOM_GROUP_MIN_BOTS} bots.`;
  }
  return count > BOT_LIBRARY_GROUP_BOT_CAP
    ? `Custom bot groups can include up to ${BOT_LIBRARY_GROUP_BOT_CAP} bots.`
    : null;
}

function BotLibraryGroupPicker({
  value,
  options,
  onChange,
  onCreateGroup,
  resolvedTheme,
  showCounts = true,
  disabled = false,
  dismissPopoversSignal,
}: BotLibraryGroupPickerProps): React.JSX.Element | null {
  const [open, setOpen] = useState(false);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);
  const optionRefs = useRef<Map<string, HTMLButtonElement>>(new Map());
  const selectedOption =
    options.find((option) => option.id === value) ?? options[0] ?? null;
  const selectedIsDefault = selectedOption?.id === BOT_LIBRARY_GROUP_FILTER_ALL;
  const selectedStyle = selectedOption
    ? botLibraryGroupVisualStyle(
        { id: selectedOption.id },
        selectedOption.bots,
        resolvedTheme,
      )
    : undefined;
  const menuOptions =
    selectedOption?.id === BOT_LIBRARY_GROUP_FILTER_ALL
      ? options.filter((option) => option.id !== BOT_LIBRARY_GROUP_FILTER_ALL)
      : options;
  const menuOpen =
    open && !disabled && menuOptions.length > 0 && selectedOption !== null;
  const focusedOptionId =
    menuOptions.find((option) => option.id === selectedOption?.id)?.id ??
    menuOptions[0]?.id ??
    null;
  const menuPortalStyle = useComposeMenuPortalStyle(
    menuOpen,
    triggerRef,
    BOT_LIBRARY_GROUP_MENU_MIN_WIDTH_PX,
    COMPOSE_MENU_PORTAL_Z_INDEX_BOT,
    "down",
  );

  useEffect(() => {
    if (!menuOpen) return;
    const handler = (event: MouseEvent) => {
      if (!isPrimaryPointerDismissal(event)) return;
      const target = event.target as Node;
      if (triggerRef.current?.contains(target)) return;
      if (menuRef.current?.contains(target)) return;
      setOpen(false);
    };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, [menuOpen]);

  useEffect(() => {
    if (!menuOpen || !menuPortalStyle || !focusedOptionId) return;
    queueMicrotask(() => optionRefs.current.get(focusedOptionId)?.focus());
  }, [focusedOptionId, menuOpen, menuPortalStyle]);

  useEffect(() => {
    if (!menuOpen) return;
    const handler = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        event.stopPropagation();
        setOpen(false);
        triggerRef.current?.focus();
      }
    };
    document.addEventListener("keydown", handler);
    return () => document.removeEventListener("keydown", handler);
  }, [menuOpen]);

  useEffect(() => {
    if (dismissPopoversSignal === undefined) return;
    setOpen(false);
  }, [dismissPopoversSignal]);

  if (!selectedOption) return null;

  const pick = (nextValue: string): void => {
    onChange(nextValue);
    setOpen(false);
    triggerRef.current?.focus();
  };

  const focusMenuOption = (index: number): void => {
    if (menuOptions.length === 0) return;
    const normalizedIndex = (index + menuOptions.length) % menuOptions.length;
    optionRefs.current.get(menuOptions[normalizedIndex]!.id)?.focus();
  };

  const handleMenuKeyDown = (
    event: React.KeyboardEvent<HTMLDivElement>,
  ): void => {
    const currentIndex = menuOptions.findIndex(
      (option) => optionRefs.current.get(option.id) === document.activeElement,
    );
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      event.stopPropagation();
      focusMenuOption(
        currentIndex < 0
          ? event.key === "ArrowDown"
            ? 0
            : menuOptions.length - 1
          : currentIndex + (event.key === "ArrowDown" ? 1 : -1),
      );
      return;
    }
    if (event.key === "Home" || event.key === "End") {
      event.preventDefault();
      event.stopPropagation();
      focusMenuOption(event.key === "Home" ? 0 : menuOptions.length - 1);
    }
  };

  return (
    <div
      className={styles.botLibraryGroupControl}
      data-open={menuOpen ? "true" : undefined}
      data-filter-active={
        selectedOption.id !== BOT_LIBRARY_GROUP_FILTER_ALL ? "true" : undefined
      }
      data-default-option={selectedIsDefault ? "true" : undefined}
      data-disabled={disabled ? "true" : undefined}
      style={selectedStyle}
    >
      <button
        ref={triggerRef}
        type="button"
        className={styles.botLibraryGroupTrigger}
        onClick={() => setOpen((current) => !current)}
        onKeyDown={(event) => {
          if (
            event.key === "ArrowDown" ||
            event.key === "ArrowUp" ||
            event.key === "Home" ||
            event.key === "End"
          ) {
            event.preventDefault();
            setOpen(true);
          }
        }}
        disabled={disabled || menuOptions.length === 0}
        aria-haspopup="listbox"
        aria-expanded={menuOpen}
        aria-controls={menuOpen ? "bot-library-group-listbox" : undefined}
        aria-label={`Bot group filter: ${selectedOption.name}`}
        title={`Bot group filter: ${selectedOption.name}`}
      >
        <span
          className={styles.botLibraryGroupTriggerSwatch}
          aria-hidden="true"
        />
        <span className={styles.botLibraryGroupTriggerName}>
          {selectedOption.name}
        </span>
        {showCounts ? (
          <span
            className={styles.botLibraryGroupTriggerCount}
            aria-hidden="true"
          >
            {botLibraryGroupPickerCountLabel(selectedOption)}
          </span>
        ) : null}
        <span className={styles.composeBotTriggerChevron} aria-hidden="true">
          <svg
            width="10"
            height="10"
            viewBox="0 0 10 10"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.6"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <path d="M2 3.5 L5 6.5 L8 3.5" />
          </svg>
        </span>
      </button>
      {onCreateGroup ? (
        <button
          type="button"
          className={styles.botLibraryGroupCreate}
          onClick={onCreateGroup}
          aria-label="Create a new bot group"
          title="New group"
          data-tutorial-target="chat-new-group"
        >
          <Plus size={14} strokeWidth={2.2} aria-hidden="true" />
        </button>
      ) : null}
      {menuOpen &&
        menuPortalStyle &&
        typeof document !== "undefined" &&
        createPortal(
          <div
            ref={menuRef}
            className={`${styles.composeBotMenu} ${styles.botLibraryGroupMenu}`}
            style={menuPortalStyle}
          >
            <div
              id="bot-library-group-listbox"
              className={styles.composeBotListbox}
              role="listbox"
              aria-label="Bot group filter"
              onKeyDown={handleMenuKeyDown}
            >
              {menuOptions.map((option) => {
                const optionStyle = botLibraryGroupVisualStyle(
                  { id: option.id },
                  option.bots,
                  resolvedTheme,
                );
                const isSelected = option.id === selectedOption.id;
                const optionName = option.menuName ?? option.name;
                const optionCountLabel = showCounts
                  ? (option.menuCountLabel ??
                    botLibraryGroupPickerCountLabel(option))
                  : null;
                return (
                  <button
                    key={option.id}
                    ref={(node) => {
                      if (node) optionRefs.current.set(option.id, node);
                      else optionRefs.current.delete(option.id);
                    }}
                    type="button"
                    className={styles.botLibraryGroupOption}
                    role="option"
                    aria-selected={isSelected}
                    tabIndex={option.id === focusedOptionId ? 0 : -1}
                    data-default-option={
                      option.id === BOT_LIBRARY_GROUP_FILTER_ALL
                        ? "true"
                        : undefined
                    }
                    style={optionStyle}
                    onClick={() => pick(option.id)}
                  >
                    <span
                      className={styles.botLibraryGroupOptionSwatch}
                      aria-hidden="true"
                    />
                    <span className={styles.botLibraryGroupOptionCopy}>
                      <span className={styles.botLibraryGroupOptionName}>
                        {optionName}
                      </span>
                      {optionCountLabel ? (
                        <span className={styles.botLibraryGroupOptionCount}>
                          {optionCountLabel}
                        </span>
                      ) : null}
                    </span>
                  </button>
                );
              })}
            </div>
          </div>,
          document.body,
        )}
    </div>
  );
}

function computeMentionMenuFixedStyle(
  caretRect: DOMRect,
  themeSource: Element | null,
  floorMinWidth: number,
): React.CSSProperties {
  const vw = globalThis.window.innerWidth;
  const vh = globalThis.window.innerHeight;
  const pad = COMPOSE_MENU_VIEWPORT_PAD_PX;
  const gap = 6;
  const maxW = Math.min(COMPOSE_MENU_MAX_WIDTH_PX, vw - pad * 2);
  const minWidth = Math.min(
    Math.max(caretRect.width || 0, floorMinWidth),
    maxW,
  );
  const left = Math.max(pad, Math.min(caretRect.left, vw - maxW - pad));
  const maxHeightCap = Math.min(
    COMPOSE_CARET_MENU_MAX_HEIGHT_CAP_PX,
    Math.max(0, vh - 2 * pad),
  );
  const topIfBelow = caretRect.bottom + gap;
  const spaceBelow = vh - pad - topIfBelow;
  const spaceAbove = caretRect.top - pad - gap;

  let top: number;
  let maxHeight: number;

  if (
    spaceBelow >= COMPOSE_CARET_MENU_MIN_OPEN_BELOW_PX ||
    spaceBelow >= spaceAbove
  ) {
    top = topIfBelow;
    maxHeight = Math.min(maxHeightCap, Math.max(80, spaceBelow));
  } else {
    maxHeight = Math.min(maxHeightCap, Math.max(80, spaceAbove));
    top = Math.max(pad, caretRect.top - gap - maxHeight);
  }

  if (top + maxHeight + pad > vh) {
    maxHeight = Math.max(80, vh - pad - top);
  }
  if (top < pad) {
    top = pad;
    maxHeight = Math.min(maxHeightCap, Math.max(80, vh - pad - top));
  }

  const themeVars: Record<string, string> = {};
  if (themeSource) {
    const computedStyle = globalThis.window.getComputedStyle(themeSource);
    for (const varName of COMPOSE_MENU_PORTAL_THEME_VARS) {
      const value = computedStyle.getPropertyValue(varName).trim();
      if (value) {
        themeVars[varName] = value;
      }
    }
  }
  return {
    position: "fixed",
    left,
    top,
    bottom: "auto",
    minWidth,
    maxWidth: maxW,
    maxHeight,
    overflow: "hidden",
    zIndex: COMPOSE_MENU_PORTAL_Z_INDEX_BOT,
    ...themeVars,
  } as React.CSSProperties;
}

function computeCommandMenuFixedStyle(
  anchorRect: DOMRect,
  themeSource: Element | null,
): React.CSSProperties {
  const vw = globalThis.window.innerWidth;
  const vh = globalThis.window.innerHeight;
  const pad = COMPOSE_MENU_VIEWPORT_PAD_PX;
  const gap = 8;
  const availableWidth = Math.max(0, vw - pad * 2);
  const floorWidth = Math.min(
    COMPOSE_COMMAND_MENU_MIN_WIDTH_PX,
    availableWidth,
  );
  const width = Math.min(
    Math.max(anchorRect.width || 0, floorWidth),
    availableWidth,
  );
  const left = Math.max(pad, Math.min(anchorRect.left, vw - width - pad));
  const desiredBottom = vh - anchorRect.top + gap;
  const availableAbove = Math.max(0, anchorRect.top - pad - gap);
  const maxHeight = Math.min(
    COMPOSE_CARET_MENU_MAX_HEIGHT_CAP_PX,
    Math.max(80, availableAbove),
  );
  const bottom = Math.max(
    pad,
    Math.min(desiredBottom, Math.max(pad, vh - pad - maxHeight)),
  );

  const themeVars: Record<string, string> = {};
  if (themeSource) {
    const computedStyle = globalThis.window.getComputedStyle(themeSource);
    for (const varName of COMPOSE_MENU_PORTAL_THEME_VARS) {
      const value = computedStyle.getPropertyValue(varName).trim();
      if (value) {
        themeVars[varName] = value;
      }
    }
  }

  return {
    position: "fixed",
    left,
    top: "auto",
    bottom,
    width,
    minWidth: width,
    maxWidth: width,
    maxHeight,
    overflow: "hidden",
    zIndex: COMPOSE_MENU_PORTAL_Z_INDEX_BOT,
    ...themeVars,
  } as React.CSSProperties;
}

function getComposerCommandMenuAnchorRect(
  anchor: Element | null,
  fallbackRect: DOMRect,
): DOMRect {
  const rect = anchor?.getBoundingClientRect();
  if (rect && rect.width > 0 && rect.height > 0) {
    return new DOMRect(rect.left, rect.top, rect.width, rect.height);
  }
  return fallbackRect;
}

// ── Composer bot picker (custom dropdown) ────────────────────────────
// Replaces the native <select> in the composer rail so each option can
// render with its bot's glyph + tinted background. The native <select>
// can't show per-option glyphs or color tints on any OS — the options
// are always plain text rendered by the system popup — so we build a
// small CSS+React popover instead.
//
// Trigger states:
//   - Default selected (value === ""): shows the "BOT" mono-caps label
//     only. Communicates "no bot picked = Default" without repeating
//     the word "Default" in the trigger, which would be redundant with
//     the ever-present label.
//   - Bot selected: shows the bot's glyph + name, both tinted in the
//     bot's color. The surrounding pill also picks up a soft tint via
//     `data-bot-selected` so the control reads as "this bot is active".
//
// Popover is portaled to document.body with fixed coordinates above the
// trigger so it clears `.composeTools { overflow-y: hidden }` (the rail
// scrolls horizontally). Closes on outside click, on Escape, on selection,
// and automatically if the trigger becomes disabled mid-open.
//
// Accessibility:
//   - Trigger: role=combobox via aria-haspopup=listbox + aria-expanded.
//   - Menu: role=listbox, each option role=option + aria-selected.
//   - Full keyboard nav is left to browser defaults (Tab between
//     options) for this pass — arrow-key nav can come later if needed.
interface ComposerBotPickerProps {
  /** Currently-selected bot id, or empty string for Default. */
  value: string;
  onChange: (nextValue: string) => void;
  bots: Bot[];
  resolvedTheme: "light" | "dark";
  disabled?: boolean;
  /** Native title tooltip — used to explain disabled states. */
  title?: string;
  /** Visible-label equivalent for screen readers. */
  ariaLabel: string;
  /**
   * Whether the trigger should render the selected bot's NAME next to
   * its glyph. Defaults to true (Sandbox behavior). Chat-mode sets this
   * false until the conversation has at least one message so the
   * pre-send trigger reads as a compact "glyph + color" preview and
   * doesn't duplicate the name already shown on the hero title.
   */
  showName?: boolean;
  /**
   * Once a thread has actual messages, the picker becomes the main way
   * to browse a large bot library mid-chat. These controls let that
   * popout narrow by both name and color without moving the user into a
   * separate management panel.
   */
  enableFilters?: boolean;
  hueFilterCenter?: number | null;
  onHueChange?: (next: number | null) => void;
  hueLensAvailable?: boolean;
  hueLensTrackGradient?: string;
  hueLensTrackSegments?: readonly HueLensTrackSegment[];
  /** Dropdown direction. Fresh Zen can use "right" to avoid bottom clipping. */
  placement?: ComposeMenuPlacement;
  /** Increment to close floating picker menus from the parent shell. */
  dismissPopoversSignal?: number;
  /** Optional compact controls shown below the option list. */
  menuFooter?: React.ReactNode;
  /** Extra class for portaled menu contexts such as the fresh Zen hero picker. */
  menuClassName?: string;
  /** Portaled menus need their own private-tone marker; app-shell selectors cannot reach document.body children. */
  privateTone?: boolean;
}

function ComposerBotPicker({
  value,
  onChange,
  bots,
  resolvedTheme,
  disabled,
  title,
  ariaLabel,
  showName = true,
  enableFilters = false,
  hueFilterCenter = null,
  onHueChange,
  hueLensAvailable = false,
  hueLensTrackGradient = "",
  hueLensTrackSegments = EMPTY_HUE_LENS_TRACK_SEGMENTS,
  placement = "up",
  dismissPopoversSignal,
  menuFooter,
  menuClassName,
  privateTone = false,
}: ComposerBotPickerProps): React.JSX.Element {
  const [open, setOpen] = useState(false);
  const [botNameFilter, setBotNameFilter] = useState("");
  const [hueSortEngaged, setHueSortEngaged] = useState(false);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);
  const optionRefs = useRef<Map<string, HTMLButtonElement>>(new Map());

  const selectedBot = value ? (bots.find((b) => b.id === value) ?? null) : null;
  const selectedAccent = selectedBot?.color
    ? displayAccentForMode(selectedBot.color, resolvedTheme, privateTone)
    : null;
  const controlStyle: React.CSSProperties | undefined = selectedAccent
    ? ({ "--bot-color": selectedAccent } as React.CSSProperties)
    : undefined;
  const filtersEnabled = enableFilters && !disabled;
  const orderedBots = useMemo(
    () =>
      sortBotPickerItems(
        bots,
        filtersEnabled && hueSortEngaged && hueFilterCenter !== null,
        (a, b) => compareBotsByColor(a, b, resolvedTheme, false),
      ),
    [bots, filtersEnabled, hueFilterCenter, hueSortEngaged, resolvedTheme],
  );
  const normalizedBotNameFilter = botNameFilter.trim().toLocaleLowerCase();
  const visibleBots = useMemo(() => {
    if (!filtersEnabled || normalizedBotNameFilter.length === 0) {
      return orderedBots;
    }
    return orderedBots.filter((bot) =>
      bot.name.toLocaleLowerCase().includes(normalizedBotNameFilter),
    );
  }, [filtersEnabled, normalizedBotNameFilter, orderedBots]);
  const showFilterControls = filtersEnabled && bots.length > 0;
  const showHueLensInMenu =
    showFilterControls && !!onHueChange && hueLensAvailable;
  const filterSummaryVisible =
    showFilterControls && normalizedBotNameFilter.length > 0;
  const hueFocusBotId = useMemo(() => {
    if (!filtersEnabled || !hueSortEngaged || hueFilterCenter === null) {
      return null;
    }
    let bestBotId: string | null = null;
    let bestDistance = Infinity;
    for (const bot of visibleBots) {
      if (!botHasFilterableColor(bot)) continue;
      const { h } = hexToHsl(bot.color!.trim());
      const distance = Math.abs(hueLensPositionForHue(h) - hueFilterCenter);
      if (distance < bestDistance) {
        bestDistance = distance;
        bestBotId = bot.id;
      }
    }
    return bestBotId;
  }, [filtersEnabled, hueFilterCenter, hueSortEngaged, visibleBots]);
  const menuOpen = open && !disabled;
  const menuPortalStyle = useComposeMenuPortalStyle(
    menuOpen,
    triggerRef,
    COMPOSE_MENU_BOT_MIN_WIDTH_PX,
    COMPOSE_MENU_PORTAL_Z_INDEX_BOT,
    placement,
  );

  const closeMenu = useCallback((): void => {
    setOpen(false);
    setHueSortEngaged(false);
  }, []);

  const toggleMenu = (): void => {
    if (menuOpen) {
      closeMenu();
      return;
    }
    // A parent hue value may outlive this popover. Each opening still starts
    // alphabetically until the user moves this menu's hue slider again.
    setHueSortEngaged(false);
    setOpen(true);
  };

  const handleMenuHueChange = useCallback(
    (next: number | null): void => {
      setHueSortEngaged(next !== null);
      onHueChange?.(next);
    },
    [onHueChange],
  );

  // Outside-click closes. Using mousedown (not click) so a click that
  // lands on a menu option isn't intercepted by this handler.
  useEffect(() => {
    if (!menuOpen) return;
    const handler = (event: MouseEvent) => {
      if (!isPrimaryPointerDismissal(event)) return;
      const target = event.target as Node;
      if (triggerRef.current?.contains(target)) return;
      if (menuRef.current?.contains(target)) return;
      closeMenu();
    };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, [closeMenu, menuOpen]);

  // Escape closes and returns focus to the trigger so keyboard users
  // stay oriented in the compose rail instead of dropping focus to
  // the document body.
  useEffect(() => {
    if (!menuOpen) return;
    const handler = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        event.stopPropagation();
        closeMenu();
        triggerRef.current?.focus();
      }
    };
    document.addEventListener("keydown", handler);
    return () => document.removeEventListener("keydown", handler);
  }, [closeMenu, menuOpen]);

  // If the control becomes disabled while the menu is open (e.g.,
  // send-in-flight disables mid-thread bot switching), close it so a
  // stale floating popover isn't left stranded on screen.
  useEffect(() => {
    if (!disabled || !open) return;
    const timeout = window.setTimeout(closeMenu, 0);
    return () => window.clearTimeout(timeout);
  }, [closeMenu, disabled, open]);

  useEffect(() => {
    if (dismissPopoversSignal === undefined) return;
    closeMenu();
    setBotNameFilter("");
  }, [closeMenu, dismissPopoversSignal]);

  useEffect(() => {
    if (!menuOpen || !hueFocusBotId) return;
    const timeout = window.setTimeout(() => {
      optionRefs.current.get(hueFocusBotId)?.scrollIntoView({
        block: "center",
      });
    }, 0);
    return () => window.clearTimeout(timeout);
  }, [hueFocusBotId, menuOpen]);

  const pick = (nextValue: string): void => {
    onChange(nextValue);
    setBotNameFilter("");
    closeMenu();
    triggerRef.current?.focus();
  };

  return (
    <div
      className={styles.composeBotControl}
      data-bot-selected={selectedBot ? "true" : undefined}
      data-disabled={disabled ? "true" : undefined}
      data-open={menuOpen ? "true" : undefined}
      data-menu-placement={placement}
      style={controlStyle}
    >
      <button
        ref={triggerRef}
        type="button"
        className={styles.composeBotTrigger}
        onClick={toggleMenu}
        disabled={disabled}
        data-glyph-tooltip={menuOpen ? undefined : title}
        aria-haspopup="listbox"
        aria-expanded={menuOpen}
        aria-label={ariaLabel}
      >
        {selectedBot ? (
          <>
            <span className={styles.composeBotTriggerGlyph} aria-hidden="true">
              <BotGlyph name={selectedBot.glyph} size={14} strokeWidth={2.25} />
            </span>
            {showName && (
              <span className={styles.composeBotTriggerName}>
                {selectedBot.name}
              </span>
            )}
            <BotPowerNameplateIndicator powers={selectedBot.powers} />
          </>
        ) : (
          <>
            <span className={styles.composeBotTriggerGlyph} aria-hidden="true">
              <BotGlyph name="triangle" size={14} strokeWidth={2.25} />
            </span>
            {showName && (
              <span className={styles.composeBotTriggerName}>Default</span>
            )}
          </>
        )}
        <span className={styles.composeBotTriggerChevron} aria-hidden="true">
          <svg
            width="10"
            height="10"
            viewBox="0 0 10 10"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.6"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <path d="M2 3.5 L5 6.5 L8 3.5" />
          </svg>
        </span>
      </button>
      {menuOpen &&
        menuPortalStyle &&
        typeof document !== "undefined" &&
        createPortal(
          <div
            ref={menuRef}
            className={`${styles.composeBotMenu}${
              menuClassName ? ` ${menuClassName}` : ""
            }`}
            data-private-tone={privateTone ? "true" : undefined}
            style={menuPortalStyle}
          >
            {showFilterControls && (
              <div className={styles.composeBotFilters}>
                <div className={styles.composeBotSearchRow}>
                  <input
                    type="search"
                    value={botNameFilter}
                    onChange={(event) =>
                      setBotNameFilter(event.currentTarget.value)
                    }
                    onKeyDown={(event) => {
                      if (event.key === "Enter") {
                        event.preventDefault();
                      }
                    }}
                    className={styles.composeBotSearch}
                    placeholder="Filter bots..."
                    aria-label="Filter bots by name"
                  />
                  {filterSummaryVisible && (
                    <span
                      className={styles.composeBotFilterCount}
                      aria-live="polite"
                    >
                      {visibleBots.length}/{bots.length}
                    </span>
                  )}
                </div>
                {showHueLensInMenu && (
                  <HueLensControl
                    bots={bots}
                    filteredBots={visibleBots}
                    hueFilterCenter={hueFilterCenter}
                    onHueChange={handleMenuHueChange}
                    hueLensAvailable={hueLensAvailable}
                    trackGradient={hueLensTrackGradient}
                    trackSegments={hueLensTrackSegments}
                    resolvedTheme={resolvedTheme}
                    compact
                    showCount={false}
                    allowClear={false}
                  />
                )}
              </div>
            )}
            <div
              className={styles.composeBotListbox}
              role="listbox"
              aria-label={ariaLabel}
            >
              <button
                type="button"
                className={`${styles.composeBotOption} ${styles.composeBotOptionDefault}`}
                role="option"
                aria-selected={value === ""}
                onClick={() => pick("")}
              >
                <span
                  className={styles.composeBotOptionGlyph}
                  aria-hidden="true"
                >
                  <BotGlyph name="triangle" size={14} strokeWidth={2.25} />
                </span>
                <span className={styles.composeBotOptionName}>Default</span>
              </button>
              {visibleBots.length === 0 && (
                <div
                  className={styles.composeBotNoMatches}
                  role="option"
                  aria-selected="false"
                  aria-disabled="true"
                >
                  No bots match.
                </div>
              )}
              {visibleBots.map((b) => {
                const isSelected = value === b.id;
                const accent = b.color
                  ? displayAccentForMode(b.color, resolvedTheme, privateTone)
                  : null;
                const optionStyle: React.CSSProperties | undefined = accent
                  ? ({
                      "--bot-color": accent,
                      "--bot-menu-color":
                        resolvedTheme === "light"
                          ? ensureContrast(
                              accent,
                              THEME_SURFACE_BG.light,
                              COMPOSE_BOT_LIGHT_INK_CONTRAST_RATIO,
                            )
                          : accent,
                    } as React.CSSProperties)
                  : undefined;
                return (
                  <button
                    key={b.id}
                    ref={(node) => {
                      if (node) {
                        optionRefs.current.set(b.id, node);
                      } else {
                        optionRefs.current.delete(b.id);
                      }
                    }}
                    type="button"
                    className={styles.composeBotOption}
                    role="option"
                    aria-selected={isSelected}
                    style={optionStyle}
                    onClick={() => pick(b.id)}
                  >
                    <span
                      className={styles.composeBotOptionGlyph}
                      aria-hidden="true"
                    >
                      <BotGlyph name={b.glyph} size={14} strokeWidth={2.25} />
                    </span>
                    <span className={styles.composeBotOptionName}>
                      {b.name}
                    </span>
                  </button>
                );
              })}
            </div>
            {menuFooter ? (
              <div className={styles.composeBotMenuFooter}>{menuFooter}</div>
            ) : null}
          </div>,
          document.body,
        )}
    </div>
  );
}

/**
 * Collapses the "bots with saved images" directory into a trigger + popover
 * (same visual language as ComposerBotPicker) so the Images panel stays compact.
 */
interface ImageBotDirectoryDropdownProps {
  entries: ReadonlyArray<{ botId: string; count: number; name: string }>;
  bots: Bot[];
  resolvedTheme: "light" | "dark";
  /** Every saved image, shown by the aggregate PRISM choice. */
  allImagesCount: number;
  /** Whether the flat, aggregate PRISM gallery is selected. */
  prismSelected: boolean;
  /** When set, the trigger reflects this bot (gallery filtered to one bot). */
  selectedBotId: string | null;
  onPickPrism: () => void;
  onPick: (botId: string) => void;
  /** Increment to close the floating menu from the parent shell. */
  dismissPopoversSignal?: number;
  privateTone?: boolean;
}

function ImageBotDirectoryDropdown({
  entries,
  bots,
  resolvedTheme,
  allImagesCount,
  prismSelected,
  selectedBotId,
  onPickPrism,
  onPick,
  dismissPopoversSignal,
  privateTone = false,
}: ImageBotDirectoryDropdownProps): React.JSX.Element | null {
  const [open, setOpen] = useState(false);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);
  const hasOptions = allImagesCount > 0 || entries.length > 0;
  const menuOpen = open && hasOptions;
  const menuPortalStyle = useComposeMenuPortalStyle(
    menuOpen,
    triggerRef,
    COMPOSE_MENU_BOT_MIN_WIDTH_PX,
    COMPOSE_MENU_PORTAL_Z_INDEX_BOT,
    "down",
  );

  useEffect(() => {
    if (!menuOpen) return;
    const handler = (event: MouseEvent) => {
      if (!isPrimaryPointerDismissal(event)) return;
      const target = event.target as Node;
      if (triggerRef.current?.contains(target)) return;
      if (menuRef.current?.contains(target)) return;
      setOpen(false);
    };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, [menuOpen]);

  useEffect(() => {
    if (!menuOpen) return;
    const handler = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        event.stopPropagation();
        setOpen(false);
        triggerRef.current?.focus();
      }
    };
    document.addEventListener("keydown", handler);
    return () => document.removeEventListener("keydown", handler);
  }, [menuOpen]);

  useEffect(() => {
    if (dismissPopoversSignal === undefined) return;
    setOpen(false);
  }, [dismissPopoversSignal]);

  const toggleMenu = (): void => {
    setOpen((prev) => !prev);
  };

  const pick = (botId: string): void => {
    onPick(botId);
    setOpen(false);
    triggerRef.current?.focus();
  };

  const pickPrism = (): void => {
    onPickPrism();
    setOpen(false);
    triggerRef.current?.focus();
  };

  if (!hasOptions) {
    return null;
  }

  const botTallyLabel =
    entries.length === 1
      ? "1 bot with images"
      : `${entries.length} bots with images`;

  const selectedEntry =
    selectedBotId != null
      ? (entries.find((e) => e.botId === selectedBotId) ?? null)
      : null;
  const selectedBot =
    selectedBotId != null
      ? (bots.find((b) => b.id === selectedBotId) ?? null)
      : null;
  const showSelectedOnTrigger = selectedBotId != null && selectedEntry !== null;
  const selectedTriggerName = selectedBot?.name ?? selectedEntry?.name ?? "Bot";
  const triggerAccent = selectedBot?.color
    ? displayAccentForMode(selectedBot.color, resolvedTheme, privateTone)
    : null;
  const controlStyle: React.CSSProperties | undefined = triggerAccent
    ? ({ "--bot-color": triggerAccent } as React.CSSProperties)
    : undefined;

  const ariaLabel = prismSelected
    ? `PRISM image gallery, ${allImagesCount} saved images. Open to switch collections.`
    : showSelectedOnTrigger && selectedEntry
      ? `Bot image gallery: ${selectedTriggerName}, ${selectedEntry.count} saved images. ${botTallyLabel}. Open to switch bots.`
      : `Browse image collections. ${botTallyLabel}.`;

  return (
    <div
      className={styles.imageBotDirectoryControl}
      data-open={menuOpen ? "true" : undefined}
      data-bot-selected={showSelectedOnTrigger ? "true" : undefined}
      data-prism-selected={prismSelected ? "true" : undefined}
      style={controlStyle}
    >
      <button
        ref={triggerRef}
        type="button"
        className={styles.imageBotDirectoryTrigger}
        onClick={toggleMenu}
        aria-haspopup="listbox"
        aria-expanded={menuOpen}
        aria-label={ariaLabel}
      >
        {prismSelected ? (
          <>
            <span className={styles.composeBotTriggerGlyph} aria-hidden="true">
              <BotGlyph name="triangle" size={14} strokeWidth={2.25} />
            </span>
            <span className={styles.composeBotTriggerName}>PRISM</span>
            <span className={styles.imageBotDirectoryTriggerMeta}>
              {allImagesCount}
            </span>
          </>
        ) : showSelectedOnTrigger ? (
          <>
            <span className={styles.composeBotTriggerGlyph} aria-hidden="true">
              {selectedBot ? (
                <BotGlyph
                  name={selectedBot.glyph}
                  size={14}
                  strokeWidth={2.25}
                />
              ) : null}
            </span>
            <span className={styles.composeBotTriggerName}>
              {selectedTriggerName}
            </span>
            <span className={styles.imageBotDirectoryTriggerMeta}>
              {selectedEntry.count}
            </span>
          </>
        ) : (
          <>
            <span className={styles.imageBotDirectoryTriggerLabel}>
              Browse images
            </span>
            <span className={styles.imageBotDirectoryTriggerMeta}>
              {entries.length + 1}
            </span>
          </>
        )}
        <span className={styles.composeBotTriggerChevron} aria-hidden="true">
          <svg
            width="10"
            height="10"
            viewBox="0 0 10 10"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.6"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <path d="M2 3.5 L5 6.5 L8 3.5" />
          </svg>
        </span>
      </button>
      {menuOpen &&
        menuPortalStyle &&
        typeof document !== "undefined" &&
        createPortal(
          <div
            ref={menuRef}
            className={styles.composeBotMenu}
            style={menuPortalStyle}
          >
            <div
              className={styles.composeBotListbox}
              role="listbox"
              aria-label="Image collections"
            >
              <button
                type="button"
                className={styles.composeBotOption}
                role="option"
                aria-selected={prismSelected}
                onClick={pickPrism}
              >
                <span
                  className={styles.composeBotOptionGlyph}
                  aria-hidden="true"
                >
                  <BotGlyph name="triangle" size={14} strokeWidth={2.25} />
                </span>
                <span className={styles.composeBotOptionName}>PRISM</span>
                <span className={styles.imageBotDirectoryOptionCount}>
                  {allImagesCount}
                </span>
              </button>
              {entries.map((row) => {
                const bot = bots.find((b) => b.id === row.botId) ?? null;
                const accent = bot?.color
                  ? displayAccentForMode(bot.color, resolvedTheme, privateTone)
                  : null;
                const optionStyle: React.CSSProperties | undefined = accent
                  ? ({
                      "--bot-color": accent,
                      "--bot-menu-color":
                        resolvedTheme === "light"
                          ? ensureContrast(
                              accent,
                              THEME_SURFACE_BG.light,
                              COMPOSE_BOT_LIGHT_INK_CONTRAST_RATIO,
                            )
                          : accent,
                    } as React.CSSProperties)
                  : undefined;
                return (
                  <button
                    key={row.botId}
                    type="button"
                    className={styles.composeBotOption}
                    role="option"
                    aria-selected={row.botId === selectedBotId}
                    style={optionStyle}
                    onClick={() => pick(row.botId)}
                  >
                    <span
                      className={styles.composeBotOptionGlyph}
                      aria-hidden="true"
                    >
                      {bot ? (
                        <BotGlyph
                          name={bot.glyph}
                          size={14}
                          strokeWidth={2.25}
                        />
                      ) : null}
                    </span>
                    <span className={styles.composeBotOptionName}>
                      {row.name}
                    </span>
                    <span className={styles.imageBotDirectoryOptionCount}>
                      {row.count}
                    </span>
                  </button>
                );
              })}
            </div>
          </div>,
          document.body,
        )}
    </div>
  );
}

type ComposerModelPickerProvider = Provider | "online" | "all";

interface ComposerModelPickerEffortControl {
  targetKey: string;
  value: ReasoningEffort;
  capability: ModelReasoningEffortCapabilityV1;
  rowValueForModel: (model: ModelCatalogEntry) => ReasoningEffort | undefined;
  onChange: (nextValue: ReasoningEffort) => void;
  onActivate?: () => void;
  disabled?: boolean;
  disabledReason?: string;
}

interface ActiveModelEffortTarget {
  provider: Provider;
  modelId: string;
  modelLabel: string;
  capability: ModelReasoningEffortCapabilityV1;
}

interface ComposerModelPickerStatusMessage {
  title: string;
  detail?: string;
}

interface ComposerModelPickerProps {
  value: string;
  onChange: (nextValue: string) => void;
  options: ModelCatalogEntry[];
  provider: ComposerModelPickerProvider;
  /** Provider of the currently displayed model, used for provider tinting. */
  selectedProvider?: Provider;
  disabled?: boolean;
  loading?: boolean;
  /** True only while the selected model is actively generating a reply. */
  generating?: boolean;
  title?: string;
  ariaLabel: string;
  formName?: string;
  placement?: ComposeMenuPlacement;
  minMenuWidthPx?: number;
  menuClassName?: string;
  /** When false, hides the Auto row (used by image model picker). Defaults to true. */
  showAutoOption?: boolean;
  /** Value emitted by the synthetic Auto row. Defaults to `auto`. */
  autoOptionValue?: string;
  /** Visible label for the contextual Auto row. */
  autoOptionLabel?: string;
  /** Replaces the default Auto subtitle when a surface needs context-specific copy. */
  autoOptionMetaOverride?: string;
  /** Synthetic value used by batch edit when selected bots disagree. */
  mixedOptionValue?: string;
  /** Visible label for the synthetic mixed state. */
  mixedOptionLabel?: string;
  effortControl?: ComposerModelPickerEffortControl;
  statusMessage?: ComposerModelPickerStatusMessage;
  /** Increment to close floating picker menus from the parent shell. */
  dismissPopoversSignal?: number;
}

const MODEL_PICKER_QUICK_OPEN_EVENT = "prism:model-picker-quick-open";

type ComposerModelPickerSurface = "model" | "effort";
type ComposerModelPickerInteractionMode = "pointer" | "keyboard";

interface ComposerModelPickerOpenState {
  surface: ComposerModelPickerSurface | null;
  interactionMode: ComposerModelPickerInteractionMode;
}

const CLOSED_COMPOSER_MODEL_PICKER_STATE: ComposerModelPickerOpenState = {
  surface: null,
  interactionMode: "pointer",
};

function focusVisibleComposer(): void {
  const candidates = Array.from(
    document.querySelectorAll<HTMLElement>(
      [
        '[data-starter-compose-surface="true"] textarea:not(:disabled)',
        '[data-starter-compose-surface="true"] input:not(:disabled)',
        '[data-starter-compose-surface="true"] [contenteditable="true"]',
        '[data-tutorial-target="composer"] textarea:not(:disabled)',
        '[data-tutorial-target="composer"] input:not(:disabled)',
        '[data-tutorial-target="composer"] [contenteditable="true"]',
      ].join(","),
    ),
  ).filter((candidate) => {
    const rect = candidate.getBoundingClientRect();
    if (rect.width <= 0 || rect.height <= 0) return false;
    const style = window.getComputedStyle(candidate);
    return style.display !== "none" && style.visibility !== "hidden";
  });
  candidates
    .sort(
      (left, right) =>
        right.getBoundingClientRect().bottom -
        left.getBoundingClientRect().bottom,
    )[0]
    ?.focus();
}

function ComposerModelPicker({
  value,
  onChange,
  options,
  provider,
  selectedProvider,
  disabled,
  loading = false,
  generating = false,
  title,
  ariaLabel,
  formName,
  placement = "up",
  minMenuWidthPx = COMPOSE_MENU_MODEL_MIN_WIDTH_PX,
  menuClassName,
  showAutoOption = true,
  autoOptionValue = AUTO_MODEL_CHOICE,
  autoOptionLabel: _autoOptionLabel = "Auto",
  autoOptionMetaOverride,
  mixedOptionValue,
  mixedOptionLabel = BOT_BATCH_MIXED_LABEL,
  effortControl,
  statusMessage,
  dismissPopoversSignal,
}: ComposerModelPickerProps): React.JSX.Element {
  const [pickerOpenState, setPickerOpenState] =
    useState<ComposerModelPickerOpenState>(CLOSED_COMPOSER_MODEL_PICKER_STATE);
  const open = pickerOpenState.surface === "model";
  const effortOpen = pickerOpenState.surface === "effort";
  const [highlightedModelValue, setHighlightedModelValue] = useState<
    string | null
  >(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);
  const effortTriggerRef = useRef<HTMLButtonElement>(null);
  const effortMenuRef = useRef<HTMLDivElement>(null);
  const effortWheelLockedRef = useRef(false);
  const formValueRef = useRef<HTMLInputElement>(null);
  const autoMetaShown = autoOptionMetaOverride ?? AUTO_MODEL_SETTINGS_SUBTEXT;
  const autoLabelShown = "Auto";
  const normalizedValue = isDisabledModelChoice(value)
    ? autoOptionValue
    : value;
  const autoSelected = normalizedValue === autoOptionValue;
  const mixedSelected =
    mixedOptionValue !== undefined && normalizedValue === mixedOptionValue;
  const selectedModel =
    (autoSelected || mixedSelected
      ? null
      : options.find((model) => model.id === normalizedValue)) ??
    options.find((model) => model.isDefault) ??
    options[0] ??
    null;
  const selectedLabel = loading
    ? "Loading models…"
    : mixedSelected
      ? mixedOptionLabel
      : autoSelected
        ? autoLabelShown
        : (selectedModel?.label ?? normalizedValue);
  const visualProvider =
    selectedProvider ?? selectedModel?.provider ?? provider;
  const interactionDisabled = disabled || loading;
  const menuOpen = open && !interactionDisabled;
  const menuPortalStyle = useComposeMenuPortalStyle(
    menuOpen,
    triggerRef,
    minMenuWidthPx,
    COMPOSE_MENU_PORTAL_Z_INDEX_MODEL,
    placement,
  );
  const effortInteractionDisabled =
    loading ||
    autoSelected ||
    !effortControl ||
    effortControl.disabled === true ||
    effortControl.capability.mode === "unavailable";
  const effortDisabledReason = effortInteractionDisabled
    ? autoSelected
      ? "Effort is chosen automatically for each request."
      : (effortControl?.disabledReason ??
      effortControl?.capability.disabledReason ??
      (loading ? "Models are still loading." : "Effort is unavailable."))
    : undefined;
  const effortMenuOpen = effortOpen && !effortInteractionDisabled;
  const effortMenuPortalStyle = useComposeMenuPortalStyle(
    effortMenuOpen,
    effortTriggerRef,
    264,
    COMPOSE_MENU_PORTAL_Z_INDEX_MODEL,
    placement,
  );
  const effortLabel = autoSelected
    ? "Chosen automatically"
    : !effortControl || effortControl.capability.mode === "unavailable"
      ? "Not adjustable"
      : REASONING_EFFORT_LABELS[effortControl.value];
  const effortLevels = effortControl
    ? modelEffortSliderLevels(effortControl.capability)
    : [];
  const effortSliderIndex = effortControl
    ? modelEffortSliderIndex(effortLevels, effortControl.value)
    : 0;
  const effortSliderProgress = effortControl
    ? modelEffortSliderProgress(effortLevels, effortControl.value)
    : 0;
  const selectableModelValues = useMemo(
    () => [
      ...(showAutoOption ? [autoOptionValue] : []),
      ...options.flatMap((model) => (model.disabledReason ? [] : [model.id])),
    ],
    [autoOptionValue, options, showAutoOption],
  );
  const activeHighlightedModelValue = selectableModelValues.includes(
    highlightedModelValue ?? "",
  )
    ? highlightedModelValue
    : selectableModelValues.includes(normalizedValue)
      ? normalizedValue
      : (selectableModelValues[0] ?? null);

  const moveModelHighlight = useCallback(
    (direction: -1 | 1): void => {
      setHighlightedModelValue((current) =>
        modelPickerStepValue(
          selectableModelValues,
          selectableModelValues.includes(current ?? "")
            ? current
            : activeHighlightedModelValue,
          direction,
        ),
      );
    },
    [activeHighlightedModelValue, selectableModelValues],
  );

  const setEffortValue = useCallback(
    (nextValue: ReasoningEffort): void => {
      if (!effortControl || effortInteractionDisabled) return;
      effortControl.onActivate?.();
      if (nextValue !== effortControl.value) {
        effortControl.onChange(nextValue);
      }
    },
    [effortControl, effortInteractionDisabled],
  );

  const handleEffortWheel = (event: React.WheelEvent<HTMLElement>): void => {
    if (
      pickerOpenState.interactionMode !== "pointer" ||
      !effortMenuOpen ||
      !effortControl ||
      effortInteractionDisabled ||
      effortLevels.length <= 1 ||
      event.ctrlKey ||
      Math.max(Math.abs(event.deltaX), Math.abs(event.deltaY)) < 2
    ) {
      return;
    }
    const direction = modelEffortWheelDirection(event.deltaX, event.deltaY);
    if (direction === 0) return;
    event.preventDefault();
    event.stopPropagation();
    if (effortWheelLockedRef.current) return;
    const nextValue = modelEffortStep(
      effortLevels,
      effortControl.value,
      direction,
    );
    if (nextValue === effortControl.value) return;
    effortWheelLockedRef.current = true;
    window.setTimeout(() => {
      effortWheelLockedRef.current = false;
    }, 90);
    setEffortValue(nextValue);
  };

  const dismissPickersToComposer = useCallback((): void => {
    setPickerOpenState(CLOSED_COMPOSER_MODEL_PICKER_STATE);
    window.requestAnimationFrame(focusVisibleComposer);
  }, []);

  useEffect(() => {
    const trigger = triggerRef.current;
    if (!trigger) return;
    const openQuickPicker = (): void => {
      setHighlightedModelValue(
        selectableModelValues.includes(normalizedValue)
          ? normalizedValue
          : (selectableModelValues[0] ?? null),
      );
      setPickerOpenState({
        surface: "model",
        interactionMode: "keyboard",
      });
      window.requestAnimationFrame(() => trigger.focus());
    };
    trigger.addEventListener(MODEL_PICKER_QUICK_OPEN_EVENT, openQuickPicker);
    return () =>
      trigger.removeEventListener(
        MODEL_PICKER_QUICK_OPEN_EVENT,
        openQuickPicker,
      );
  }, [normalizedValue, selectableModelValues]);

  useEffect(() => {
    if (
      pickerOpenState.interactionMode !== "keyboard" ||
      (!menuOpen && !effortMenuOpen)
    ) {
      return;
    }
    const returnToPointerBrowsing = (): void => {
      setPickerOpenState((current) =>
        current.surface ? { ...current, interactionMode: "pointer" } : current,
      );
    };
    window.addEventListener("mousemove", returnToPointerBrowsing, {
      capture: true,
      once: true,
    });
    return () =>
      window.removeEventListener("mousemove", returnToPointerBrowsing, true);
  }, [effortMenuOpen, menuOpen, pickerOpenState.interactionMode]);

  useEffect(() => {
    if (
      pickerOpenState.interactionMode !== "keyboard" ||
      (!menuOpen && !effortMenuOpen)
    ) {
      return;
    }
    const handleQuickWheel = (event: WheelEvent): void => {
      // Model always keeps native wheel scrolling. Only Effort owns wheel
      // selection, including cursor-independent keyboard quick-select mode.
      if (menuOpen) return;
      if (
        event.ctrlKey ||
        Math.max(Math.abs(event.deltaX), Math.abs(event.deltaY)) < 2
      ) {
        return;
      }
      const direction = modelEffortWheelDirection(event.deltaX, event.deltaY);
      if (direction === 0) return;
      event.preventDefault();
      event.stopPropagation();
      if (
        !effortControl ||
        effortInteractionDisabled ||
        effortLevels.length <= 1 ||
        effortWheelLockedRef.current
      ) {
        return;
      }
      const nextValue = modelEffortStep(
        effortLevels,
        effortControl.value,
        direction,
      );
      if (nextValue === effortControl.value) return;
      effortWheelLockedRef.current = true;
      window.setTimeout(() => {
        effortWheelLockedRef.current = false;
      }, 90);
      setEffortValue(nextValue);
    };
    const handleQuickArrows = (event: KeyboardEvent): void => {
      if (
        event.key !== "ArrowDown" &&
        event.key !== "ArrowRight" &&
        event.key !== "ArrowUp" &&
        event.key !== "ArrowLeft"
      ) {
        return;
      }
      event.preventDefault();
      event.stopPropagation();
      if (menuOpen) {
        moveModelHighlight(
          event.key === "ArrowDown" || event.key === "ArrowRight" ? 1 : -1,
        );
        return;
      }
      if (!effortControl || effortInteractionDisabled) return;
      setEffortValue(
        modelEffortStep(
          effortLevels,
          effortControl.value,
          event.key === "ArrowUp" || event.key === "ArrowRight" ? 1 : -1,
        ),
      );
    };
    document.addEventListener("wheel", handleQuickWheel, {
      capture: true,
      passive: false,
    });
    document.addEventListener("keydown", handleQuickArrows, true);
    return () => {
      document.removeEventListener("wheel", handleQuickWheel, true);
      document.removeEventListener("keydown", handleQuickArrows, true);
    };
  }, [
    effortControl,
    effortInteractionDisabled,
    effortLevels,
    effortMenuOpen,
    menuOpen,
    moveModelHighlight,
    pickerOpenState.interactionMode,
    setEffortValue,
  ]);

  useEffect(() => {
    if (!menuOpen) return;
    setHighlightedModelValue(
      selectableModelValues.includes(normalizedValue)
        ? normalizedValue
        : (selectableModelValues[0] ?? null),
    );
  }, [menuOpen, normalizedValue, selectableModelValues]);

  useEffect(() => {
    if (
      !menuOpen ||
      pickerOpenState.interactionMode !== "keyboard" ||
      !activeHighlightedModelValue
    ) {
      return;
    }
    const frame = window.requestAnimationFrame(() => {
      const option = Array.from(
        menuRef.current?.querySelectorAll<HTMLElement>("[data-model-value]") ??
          [],
      ).find(
        (candidate) =>
          candidate.dataset.modelValue === activeHighlightedModelValue,
      );
      option?.scrollIntoView({ block: "nearest" });
    });
    return () => window.cancelAnimationFrame(frame);
  }, [activeHighlightedModelValue, menuOpen, pickerOpenState.interactionMode]);

  useEffect(() => {
    if (!menuOpen && !effortMenuOpen) return;
    const handler = (event: PointerEvent) => {
      if (!isPrimaryPointerDismissal(event)) return;
      const target = event.target as Node;
      if (triggerRef.current?.contains(target)) return;
      if (effortTriggerRef.current?.contains(target)) return;
      if (menuRef.current?.contains(target)) return;
      if (effortMenuRef.current?.contains(target)) return;
      setPickerOpenState(CLOSED_COMPOSER_MODEL_PICKER_STATE);
    };
    document.addEventListener("pointerdown", handler, true);
    return () => document.removeEventListener("pointerdown", handler, true);
  }, [effortMenuOpen, menuOpen]);

  useEffect(() => {
    if (!menuOpen) return;
    const handler = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        event.preventDefault();
        event.stopPropagation();
        dismissPickersToComposer();
      }
    };
    document.addEventListener("keydown", handler);
    return () => document.removeEventListener("keydown", handler);
  }, [dismissPickersToComposer, menuOpen]);

  useEffect(() => {
    if (!effortMenuOpen) return;
    const handler = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        event.preventDefault();
        event.stopPropagation();
        dismissPickersToComposer();
      }
    };
    document.addEventListener("keydown", handler);
    return () => document.removeEventListener("keydown", handler);
  }, [dismissPickersToComposer, effortMenuOpen]);

  useEffect(() => {
    if (!interactionDisabled || !open) return;
    const timeout = window.setTimeout(
      () => setPickerOpenState(CLOSED_COMPOSER_MODEL_PICKER_STATE),
      0,
    );
    return () => window.clearTimeout(timeout);
  }, [interactionDisabled, open]);

  useEffect(() => {
    if (!effortInteractionDisabled || !effortOpen) return;
    const timeout = window.setTimeout(
      () => setPickerOpenState(CLOSED_COMPOSER_MODEL_PICKER_STATE),
      0,
    );
    return () => window.clearTimeout(timeout);
  }, [effortInteractionDisabled, effortOpen]);

  useEffect(() => {
    if (dismissPopoversSignal === undefined) return;
    setPickerOpenState(CLOSED_COMPOSER_MODEL_PICKER_STATE);
  }, [dismissPopoversSignal]);

  useEffect(() => {
    effortControl?.onActivate?.();
  }, [effortControl?.targetKey, effortControl?.capability.mode]);

  const pick = (nextValue: string): void => {
    if (isDisabledModelChoice(nextValue)) return;
    if (formValueRef.current) {
      formValueRef.current.value = nextValue;
    }
    onChange(nextValue);
    setPickerOpenState(CLOSED_COMPOSER_MODEL_PICKER_STATE);
    triggerRef.current?.focus();
  };

  const commitHighlightedModelToEffort = (): void => {
    const nextValue = activeHighlightedModelValue;
    if (!nextValue) return;
    if (formValueRef.current) {
      formValueRef.current.value = nextValue;
    }
    if (nextValue !== normalizedValue) onChange(nextValue);
    if (!effortInteractionDisabled) {
      setPickerOpenState({
        surface: "effort",
        interactionMode: "keyboard",
      });
      window.requestAnimationFrame(() => effortTriggerRef.current?.focus());
      return;
    }
    setPickerOpenState(CLOSED_COMPOSER_MODEL_PICKER_STATE);
    triggerRef.current?.focus();
  };

  const handleModelKeyDown = (
    event: React.KeyboardEvent<HTMLElement>,
  ): void => {
    if (!menuOpen) return;
    if (event.code === "Space") {
      event.preventDefault();
      event.stopPropagation();
      dismissPickersToComposer();
      return;
    }
    if (
      event.key === "Enter" &&
      pickerOpenState.interactionMode === "keyboard"
    ) {
      event.preventDefault();
      event.stopPropagation();
      pick(activeHighlightedModelValue ?? normalizedValue);
      return;
    }
    if (event.key === "Tab" && !effortInteractionDisabled) {
      event.preventDefault();
      event.stopPropagation();
      setPickerOpenState({
        surface: "model",
        interactionMode: "keyboard",
      });
      commitHighlightedModelToEffort();
    }
  };

  const handleEffortKeyDown = (
    event: React.KeyboardEvent<HTMLElement>,
  ): void => {
    if (effortMenuOpen && event.code === "Space") {
      event.preventDefault();
      event.stopPropagation();
      dismissPickersToComposer();
      return;
    }
    if (event.key !== "Tab" || !effortMenuOpen) return;
    event.preventDefault();
    event.stopPropagation();
    setHighlightedModelValue(
      selectableModelValues.includes(normalizedValue)
        ? normalizedValue
        : (selectableModelValues[0] ?? null),
    );
    setPickerOpenState({
      surface: "model",
      interactionMode: "keyboard",
    });
    window.requestAnimationFrame(() => triggerRef.current?.focus());
  };

  useEffect(() => {
    if (formValueRef.current) {
      formValueRef.current.value = normalizedValue;
    }
  }, [normalizedValue]);

  return (
    <div
      className={styles.composeModelControl}
      data-disabled={interactionDisabled ? "true" : undefined}
      data-loading={loading ? "true" : undefined}
      data-open={menuOpen ? "true" : undefined}
      data-picker-surface={pickerOpenState.surface ?? undefined}
      data-picker-interaction-mode={
        pickerOpenState.surface ? pickerOpenState.interactionMode : undefined
      }
      data-has-effort={effortControl ? "true" : undefined}
      data-provider={visualProvider}
      data-routing-provider={provider}
    >
      {formName ? (
        <input
          ref={formValueRef}
          type="hidden"
          name={formName}
          defaultValue={normalizedValue}
        />
      ) : null}
      <button
        ref={triggerRef}
        type="button"
        className={styles.composeModelTrigger}
        data-prism-model-picker-trigger="true"
        onClick={(event) => {
          event.currentTarget.focus();
          setPickerOpenState((current) =>
            current.surface === "model"
              ? CLOSED_COMPOSER_MODEL_PICKER_STATE
              : { surface: "model", interactionMode: "pointer" },
          );
        }}
        onKeyDown={handleModelKeyDown}
        disabled={interactionDisabled}
        data-glyph-tooltip={loading ? "Models are still loading." : title}
        aria-haspopup="listbox"
        aria-expanded={menuOpen}
        aria-label={
          loading ? `${ariaLabel}. Models are still loading.` : ariaLabel
        }
        aria-busy={loading ? "true" : undefined}
      >
        <span className={styles.composeControlLabel}>Model</span>
        <span className={styles.composeModelTriggerName}>{selectedLabel}</span>
        <span className={styles.composeModelTriggerChevron} aria-hidden="true">
          <svg
            width="10"
            height="10"
            viewBox="0 0 10 10"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.6"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <path d="M2 3.5 L5 6.5 L8 3.5" />
          </svg>
        </span>
      </button>
      {effortControl ? (
        <span
          className={styles.composeModelEffortTriggerWrap}
          data-glyph-tooltip={effortDisabledReason}
          tabIndex={effortInteractionDisabled ? 0 : undefined}
          aria-label={
            effortDisabledReason
              ? `Effort unavailable. ${effortDisabledReason}`
              : undefined
          }
          aria-disabled={effortInteractionDisabled ? "true" : undefined}
        >
          <button
            ref={effortTriggerRef}
            type="button"
            className={styles.composeModelEffortTrigger}
            data-tutorial-target="model-effort"
            data-adjustable={
              !autoSelected && effortControl.capability.mode !== "unavailable"
                ? "true"
                : "false"
            }
            data-effort-level={effortControl.value}
            data-generating={generating ? "true" : undefined}
            onClick={(event) => {
              event.currentTarget.focus();
              effortControl.onActivate?.();
              setPickerOpenState((current) =>
                current.surface === "effort"
                  ? CLOSED_COMPOSER_MODEL_PICKER_STATE
                  : { surface: "effort", interactionMode: "pointer" },
              );
            }}
            onKeyDown={handleEffortKeyDown}
            onWheel={handleEffortWheel}
            disabled={effortInteractionDisabled}
            aria-haspopup="dialog"
            aria-expanded={effortMenuOpen}
            aria-label={
              autoSelected
                ? "Effort chosen automatically"
                : `Effort: ${effortLabel}`
            }
            aria-busy={generating ? "true" : undefined}
          >
            {autoSelected ? (
              <HollowTriangleEffortIcon />
            ) : (
            <ModelEffortIcon level={effortControl.value} />
            )}
            <span className={styles.srOnly}>{effortLabel}</span>
            {!autoSelected &&
            effortControl.capability.mode !== "unavailable" ? (
              <span
                className={styles.composeModelEffortTriggerChevron}
                aria-hidden="true"
              >
                ⌄
              </span>
            ) : null}
          </button>
        </span>
      ) : null}
      {loading ? (
        <span className={styles.srOnly} role="status" aria-live="polite">
          Models are still loading.
        </span>
      ) : null}
      {menuOpen &&
        menuPortalStyle &&
        typeof document !== "undefined" &&
        createPortal(
          <div
            ref={menuRef}
            className={`${styles.composeBotMenu} ${styles.composeModelMenu}${
              menuClassName ? ` ${menuClassName}` : ""
            }`}
            style={menuPortalStyle}
            onKeyDown={handleModelKeyDown}
          >
            {statusMessage ? (
              <div className={styles.composeModelStatusRow} role="status">
                <span>{statusMessage.title}</span>
                {statusMessage.detail ? (
                  <small>{statusMessage.detail}</small>
                ) : null}
              </div>
            ) : null}
            <div
              className={styles.composeBotListbox}
              role="listbox"
              aria-label={ariaLabel}
            >
              {mixedSelected && mixedOptionValue ? (
                <button
                  key={mixedOptionValue}
                  type="button"
                  className={`${styles.composeBotOption} ${styles.composeModelOption} ${styles.composeModelOptionDisabled}`}
                  role="option"
                  aria-selected="true"
                  aria-disabled="true"
                  disabled
                >
                  <span className={styles.composeModelOptionMain}>
                    <span className={styles.composeModelOptionName}>
                      {mixedOptionLabel}
                    </span>
                    <span className={styles.composeModelOptionMeta}>
                      Choose a value to update every selected bot
                    </span>
                  </span>
                </button>
              ) : null}
              {showAutoOption && (
                <button
                  key={autoOptionValue}
                  type="button"
                  className={`${styles.composeBotOption} ${styles.composeModelOption}`}
                  role="option"
                  data-model-value={autoOptionValue}
                  data-highlighted={
                    pickerOpenState.interactionMode === "keyboard" &&
                    activeHighlightedModelValue === autoOptionValue
                      ? "true"
                      : undefined
                  }
                  aria-selected={normalizedValue === autoOptionValue}
                  onClick={() => pick(autoOptionValue)}
                >
                  <span className={styles.composeModelOptionMain}>
                    <span className={styles.composeModelOptionName}>
                      {autoLabelShown}
                    </span>
                    <span className={styles.composeModelOptionMeta}>
                      {autoMetaShown}
                    </span>
                  </span>
                </button>
              )}
              {options.map((model) => {
                const isSelected = normalizedValue === model.id;
                const isUnavailable = Boolean(model.disabledReason);
                const rowEffort = effortControl?.rowValueForModel(model);
                const showCatalogDefaultBadge = Boolean(model.isDefault);
                return (
                  <button
                    key={`${model.provider}:${model.id}`}
                    type="button"
                    className={`${styles.composeBotOption} ${styles.composeModelOption} ${
                      isUnavailable ? styles.composeModelOptionDisabled : ""
                    }`}
                    role="option"
                    data-model-provider={model.provider}
                    data-model-value={model.id}
                    data-highlighted={
                      pickerOpenState.interactionMode === "keyboard" &&
                      activeHighlightedModelValue === model.id
                        ? "true"
                        : undefined
                    }
                    aria-selected={isSelected}
                    aria-disabled={isUnavailable ? "true" : undefined}
                    disabled={isUnavailable}
                    title={model.disabledReason}
                    onClick={() => {
                      if (!isUnavailable) pick(model.id);
                    }}
                  >
                    <span className={styles.composeModelOptionMain}>
                      <span className={styles.composeModelOptionName}>
                        {model.label}
                      </span>
                      {(model.hostLabel || model.disabledReason) && (
                        <span className={styles.composeModelOptionMeta}>
                          {model.disabledReason ?? model.hostLabel}
                        </span>
                      )}
                    </span>
                    <span className={styles.composeModelOptionStatus}>
                      {!isUnavailable && showCatalogDefaultBadge && (
                          <span className={styles.composeModelDefaultBadge}>
                            Default
                          </span>
                        )}
                      {rowEffort ? (
                        <span
                          className={styles.composeModelRowEffort}
                          role="img"
                          aria-label={`Saved effort: ${REASONING_EFFORT_LABELS[rowEffort]}`}
                          title={`Saved effort: ${REASONING_EFFORT_LABELS[rowEffort]}`}
                        >
                          <ModelEffortIcon
                            level={rowEffort}
                            className={
                              isSelected
                                ? undefined
                                : styles.composeModelRowEffortIconMonochrome
                            }
                          />
                        </span>
                      ) : null}
                    </span>
                  </button>
                );
              })}
            </div>
          </div>,
          document.body,
        )}
      {effortControl &&
        effortMenuOpen &&
        effortMenuPortalStyle &&
        typeof document !== "undefined" &&
        createPortal(
          <div
            ref={effortMenuRef}
            className={`${styles.composeBotMenu} ${styles.composeModelEffortMenu}`}
            style={effortMenuPortalStyle}
            role="dialog"
            aria-label="Model effort"
            onKeyDown={handleEffortKeyDown}
            onWheel={handleEffortWheel}
          >
            <div className={styles.composeModelEffortMenuHeader}>
              <div>
                <span>Effort</span>
                <small>
                  {effortControl.capability.mode === "simulated"
                    ? "Experimental · multi-call simulation"
                    : "Saved for this model"}
                </small>
              </div>
              <strong>
                <ModelEffortIcon level={effortControl.value} />
                {effortLabel}
              </strong>
            </div>
            <div
              className={styles.composeModelEffortVerticalLayout}
              style={
                {
                  "--model-effort-progress": `${effortSliderProgress}%`,
                  "--model-effort-stop-count": effortLevels.length,
                } as CSSProperties
              }
            >
              <div className={styles.composeModelEffortSlider}>
                <div className={styles.composeModelEffortSliderRail}>
                  <span
                    className={styles.composeModelEffortSliderFill}
                    data-effort-level={effortControl.value}
                    aria-hidden="true"
                  />
                  {effortLevels.map((level, index) => (
                    <span
                      key={level}
                      className={styles.composeModelEffortSliderTick}
                      data-active={
                        index <= effortSliderIndex ? "true" : undefined
                      }
                      style={
                        {
                          top: `${
                            effortLevels.length <= 1
                              ? 0
                              : (index / (effortLevels.length - 1)) * 100
                          }%`,
                        } as CSSProperties
                      }
                      aria-hidden="true"
                    />
                  ))}
                  <ModelEffortIcon
                    level={effortControl.value}
                    className={styles.composeModelEffortSliderThumb}
                  />
                </div>
                <input
                  type="range"
                  min={0}
                  max={Math.max(0, effortLevels.length - 1)}
                  step={1}
                  value={effortSliderIndex}
                  aria-label="Model effort"
                  aria-valuetext={effortLabel}
                  onPointerDown={() => effortControl.onActivate?.()}
                  onChange={(event) => {
                    const nextValue =
                      effortLevels[Number(event.currentTarget.value)];
                    if (nextValue) setEffortValue(nextValue);
                  }}
                />
              </div>
              <div className={styles.composeModelEffortStops}>
                {effortLevels.map((level) => (
                  <button
                    key={level}
                    type="button"
                    className={styles.composeModelEffortOption}
                    data-active={
                      effortControl.value === level ? "true" : undefined
                    }
                    aria-pressed={effortControl.value === level}
                    onClick={() => {
                      setEffortValue(level);
                    }}
                  >
                    <ModelEffortIcon level={level} />
                    <span>{REASONING_EFFORT_LABELS[level]}</span>
                  </button>
                ))}
              </div>
            </div>
          </div>,
          document.body,
        )}
    </div>
  );
}

// ── Hue lens (color filter) ──────────────────────────────────────────
// Color-band filter for bot-heavy picking surfaces. Pre-chat it sits
// above the compose tools so it can reshape the big starter grid; once a
// chat has messages it embeds inside the bot popout alongside name
// search. Moving the slider activates the filter at that hue; "All"
// clears it. Active state exposes the visible-bot count so the user
// knows exactly what slice of their library is showing.
//
// Renders only when at least two color families are available — otherwise
// the lens has no meaningful choice to offer and would just be visual noise.
interface HueLensControlProps {
  /** Total bot library — drives the "of N" count. */
  bots: Bot[];
  /** Visible bots to count beside the slider when counts are enabled. */
  filteredBots: Bot[];
  /** Active PRISM lens position in the slider's 0..359 range, or null when inactive. */
  hueFilterCenter: number | null;
  /** Setter; receives a PRISM lens position to activate, or null to clear. */
  onHueChange: (next: number | null) => void;
  /** True when at least two populated color families are worth filtering. */
  hueLensAvailable: boolean;
  /** Pre-computed CSS `linear-gradient(...)` string for populated PRISM bars. */
  trackGradient: string;
  /** Populated PRISM families, ordered as they appear on the compacted track. */
  trackSegments: readonly HueLensTrackSegment[];
  /** Compact layout for embedding inside the bot popout. */
  compact?: boolean;
  /** Active app theme for rail/thumb contrast tuning. */
  resolvedTheme: "light" | "dark";
  /** Whether to render the active visible/total count next to the slider. */
  showCount?: boolean;
  /** Whether the active state can be cleared back to "All". */
  allowClear?: boolean;
  /** Optional tooltip id; when provided the visible label gets a control-level info marker. */
  infoId?: string;
  /**
   * Notifies the parent shell when the user is actively pressing/touching
   * the slider thumb. The empty-state surface uses this to drive a
   * "drag-only preview" mode (hero collapses to a Prism triangle, shell
   * accent tints to the lens hue) while keeping the control's filter
   * commit semantics unchanged. Optional — embedders that don't care
   * about drag state (e.g. the popout) can omit it.
   */
  onInteractionChange?: (active: boolean) => void;
}

function HueLensControl({
  bots,
  filteredBots,
  hueFilterCenter,
  onHueChange,
  hueLensAvailable,
  trackGradient,
  trackSegments,
  compact = false,
  resolvedTheme,
  showCount = true,
  allowClear = true,
  infoId,
  onInteractionChange,
}: HueLensControlProps): React.JSX.Element | null {
  const hueChangeFrameRef = useRef<number | null>(null);
  const pendingHueChangeRef = useRef<number | null>(null);
  const latestOnHueChangeRef = useRef(onHueChange);

  useEffect(() => {
    latestOnHueChangeRef.current = onHueChange;
  }, [onHueChange]);

  useEffect(() => {
    return () => {
      if (hueChangeFrameRef.current !== null) {
        cancelAnimationFrame(hueChangeFrameRef.current);
      }
    };
  }, []);

  const scheduleHueChange = useCallback((next: number | null) => {
    if (next === null) {
      if (hueChangeFrameRef.current !== null) {
        cancelAnimationFrame(hueChangeFrameRef.current);
        hueChangeFrameRef.current = null;
      }
      pendingHueChangeRef.current = null;
      latestOnHueChangeRef.current(null);
      return;
    }

    pendingHueChangeRef.current = next;
    if (hueChangeFrameRef.current !== null) return;

    hueChangeFrameRef.current = requestAnimationFrame(() => {
      hueChangeFrameRef.current = null;
      latestOnHueChangeRef.current(pendingHueChangeRef.current);
    });
  }, []);

  const handleSliderChange = useCallback(
    (event: React.ChangeEvent<HTMLInputElement>) => {
      scheduleHueChange(
        hueLensFilterCenterForSliderValue(
          Number(event.currentTarget.value),
          trackSegments,
        ),
      );
    },
    [scheduleHueChange, trackSegments],
  );
  // Pointer + touch start/end fire the drag-state callback so the shell
  // can flip preview UI on for the duration of an active drag without
  // the lens itself owning any of that surrounding state. Pointer events
  // cover both mouse and stylus on modern browsers; touch handlers stay
  // as a fallback for legacy mobile webviews that gate pointer events.
  const handleInteractionStart = useCallback(
    () => onInteractionChange?.(true),
    [onInteractionChange],
  );
  const handleInteractionEnd = useCallback(
    () => onInteractionChange?.(false),
    [onInteractionChange],
  );
  if (!hueLensAvailable) return null;
  const active = hueFilterCenter !== null;
  // Inactive state still parks the slider thumb at a neutral resting
  // position so the control reads as "ready to use" rather than empty.
  // The value is a presentation-only fallback; activation depends on
  // `active`/`hueFilterCenter`, not on the slider's reported value.
  const sliderValue = active
    ? hueLensSliderValueForFilterCenter(hueFilterCenter, trackSegments)
    : 180;
  const isDarkTheme = resolvedTheme === "dark";
  const lensStyle = {
    "--lens-track-gradient": trackGradient,
    "--hue-lens-rail-bg": isDarkTheme
      ? HUE_LENS_RAIL_BG_DARK
      : HUE_LENS_RAIL_BG_LIGHT,
    "--hue-lens-thumb-fill": isDarkTheme
      ? HUE_LENS_THUMB_FILL_DARK
      : HUE_LENS_THUMB_FILL_LIGHT,
    "--hue-lens-thumb-shadow": isDarkTheme
      ? HUE_LENS_THUMB_SHADOW_DARK
      : HUE_LENS_THUMB_SHADOW_LIGHT,
    "--hue-lens-focus-ring": isDarkTheme
      ? HUE_LENS_FOCUS_RING_DARK
      : HUE_LENS_FOCUS_RING_LIGHT,
  } as React.CSSProperties;
  return (
    <div
      className={`${styles.hueLensRow} ${compact ? styles.hueLensRowCompact : ""}`}
      data-active={active ? "true" : undefined}
      style={lensStyle}
    >
      <span className={`${styles.hueLensLabel} ${styles.controlLabelWithInfo}`}>
        <span>Color filter</span>
        {infoId ? (
          <PanelSectionInfo
            id={infoId}
            label="About color filter"
            variant="control"
          >
            Filters the visible bot list by the color family on each bot's
            Prism.
          </PanelSectionInfo>
        ) : null}
      </span>
      <input
        type="range"
        min={0}
        max={359}
        step={1}
        value={sliderValue}
        onChange={handleSliderChange}
        onPointerDown={handleInteractionStart}
        onPointerUp={handleInteractionEnd}
        onPointerCancel={handleInteractionEnd}
        onTouchStart={handleInteractionStart}
        onTouchEnd={handleInteractionEnd}
        onTouchCancel={handleInteractionEnd}
        aria-label="Color filter - filter bots by hue"
        title="Filter bots by hue"
        className={styles.hueLensSlider}
      />
      {active && (
        <>
          {showCount && (
            <span className={styles.hueLensCount} aria-live="polite">
              {filteredBots.length}/{bots.length}
            </span>
          )}
          {allowClear && (
            <button
              type="button"
              className={styles.hueLensClear}
              onClick={() => scheduleHueChange(null)}
              aria-label="Show all bots — clear color filter"
              data-glyph-tooltip="Show all bots"
            >
              All
            </button>
          )}
        </>
      )}
    </div>
  );
}

// ── Touch preview balloon ────────────────────────────────────────────
// Mobile keyboard-style "lifted key" preview that floats above the
// user's finger when they touch the bot picker at high-density stages.
// At those stages the tile under the finger is too small (or has lost
// its glyph) to identify by sight, so we lift the visual feedback off
// the touch point — the same trick iOS/Android keyboards use to show
// the pressed key above the thumb.
//
// The balloon mirrors the resting visual identity of `.chatBotTile`
// (rounded card, soft shadow, bot-color fill, glyph centered) but at a
// readable size, plus the bot's name underneath. On the top edge of
// the picker it auto-flips below the finger so it stays in view.
//
// Position is `fixed` so the balloon escapes any clipping / transform
// container — the picker itself uses `transform: translate3d` and
// `position: absolute`, both of which would otherwise cap or warp a
// child. Coordinates come from the captured `clientX`/`clientY` so the
// balloon tracks the finger directly without a re-layout.
interface TouchPreviewBalloonProps {
  bot: Bot | null;
  x: number;
  y: number;
  resolvedTheme: "light" | "dark";
}

const TOUCH_PREVIEW_BALLOON_HEIGHT = 112;
const TOUCH_PREVIEW_BALLOON_OFFSET = 24;

function TouchPreviewBalloon({
  bot,
  x,
  y,
  resolvedTheme,
}: TouchPreviewBalloonProps): React.JSX.Element | null {
  if (!bot) return null;
  // Auto-flip below the finger when the touch sits near the top of the
  // viewport — without this, a user dragging across the top row would
  // see the balloon escape upward and either clip or hide off-screen.
  const flipBelow =
    y < TOUCH_PREVIEW_BALLOON_HEIGHT + TOUCH_PREVIEW_BALLOON_OFFSET + 12;
  const top = flipBelow
    ? y + TOUCH_PREVIEW_BALLOON_OFFSET
    : y - TOUCH_PREVIEW_BALLOON_HEIGHT - TOUCH_PREVIEW_BALLOON_OFFSET;
  const accent = bot.color?.trim()
    ? normalizeAccentForTheme(bot.color.trim(), resolvedTheme)
    : null;
  const balloonStyle: React.CSSProperties = {
    left: `${x}px`,
    top: `${top}px`,
  };
  if (accent) {
    (balloonStyle as React.CSSProperties & Record<string, string>)[
      "--bot-color"
    ] = accent;
  }
  const glyphName: BotGlyphName = isBotGlyphName(bot.glyph)
    ? bot.glyph
    : DEFAULT_BOT_GLYPH;
  return (
    <div
      className={styles.touchPreviewBalloon}
      data-flip-below={flipBelow ? "true" : undefined}
      style={balloonStyle}
      aria-hidden="true"
    >
      <span className={styles.touchPreviewBalloonGlyph}>
        <BotGlyph name={glyphName} size={56} strokeWidth={1.45} />
      </span>
      <span className={styles.touchPreviewBalloonName}>{bot.name}</span>
    </div>
  );
}

// ── Combined color + glyph picker ────────────────────────────────────
// Single swatch button that doubles as a glyph preview: the button paints
// as a solid bot-color tile, and the glyph inside inherits a readable text
// color so the mark stays legible on any accent. Click opens a popover
// containing BOTH the color wheel AND the full glyph grid so the two
// parts of "bot identity" (hue + mark) live in one affordance. Right-
// clicking the swatch or the popover re-rolls BOTH color + glyph — a
// single tap to resample a whole new identity.
interface ColorGlyphPickerProps {
  color: string;
  glyph: BotGlyphName;
  onColorChange: (next: string) => void;
  onGlyphChange: (next: BotGlyphName) => void;
  open: boolean;
  onToggle: () => void;
  /** Render the color and glyph surfaces inline instead of behind a swatch popover. */
  inline?: boolean;
  /** Optional label override for accessibility (defaults are fine for both forms). */
  ariaLabel?: string;
  /**
   * Active visual theme, resolved upstream so we never have to peek at the
   * DOM. The color is normalized against this theme before it paints the
   * solid preview tile and glyph-grid selection states.
   */
  resolvedTheme: "light" | "dark";
}

// ── Unified "virtual camera" for the glyph shoebox ────────────────────
// One (nx, ny) camera position drives every cue in the stack: the radial
// vignette (darker on the far wall), the rim-light (brighter on the near
// rim — see ::before in the stylesheet), and a subtle intensity ramp on
// the vignette. The button grid itself intentionally stays untransformed
// so pointer hit targets remain aligned with the visible glyph boxes.
function updateGlyphCamera(
  shell: HTMLElement,
  inner: HTMLElement | null,
  nx: number,
  ny: number,
): void {
  const x = Math.max(0, Math.min(1, nx));
  const y = Math.max(0, Math.min(1, ny));
  shell.style.setProperty("--vignette-x", `${(x * 100).toFixed(1)}%`);
  shell.style.setProperty("--vignette-y", `${(y * 100).toFixed(1)}%`);
  // Intensity ramp 1.0 → 1.35 with camera distance from center. Baseline
  // is 1.0 (matching the original static vignette strength) so "at rest"
  // doesn't look suddenly dimmer than it did before — the ramp only
  // ADDS depth when the camera pulls toward a corner, never subtracts.
  const cx = (x - 0.5) * 2;
  const cy = (y - 0.5) * 2;
  const dist = Math.min(1, Math.hypot(cx, cy));
  shell.style.setProperty("--vignette-intensity", (1 + dist * 0.35).toFixed(3));
  if (inner) {
    // Keep glyph hit targets exactly aligned with their visible boxes.
    // The shell still gets the camera-driven vignette/rim light; tilting
    // the scrollable button grid itself can create fixed dead zones in
    // browser hit-testing.
    inner.style.transform = "none";
  }
}

function ColorGlyphPicker({
  color,
  glyph,
  onColorChange,
  onGlyphChange,
  open,
  onToggle,
  inline = false,
  ariaLabel = "Bot color and glyph. Click to open the picker, right-click for random.",
  resolvedTheme,
}: ColorGlyphPickerProps): React.JSX.Element {
  const [mobilePickerActive, setMobilePickerActive] = useState(false);
  const [draftColor, setDraftColor] = useState(color);
  const [draftGlyph, setDraftGlyph] = useState<BotGlyphName>(glyph);
  const mobileDraftActive = mobilePickerActive && open && !inline;
  const pickerColor = mobileDraftActive ? draftColor : color;
  const pickerGlyph = mobileDraftActive ? draftGlyph : glyph;
  // Everything the swatch paints keys off the band-clamped color, not the
  // raw hex. The editor preview intentionally uses a solid selected-tile
  // treatment; the empty-state hero gets its own softer ambient styling.
  const displayColor = normalizeAccentForTheme(pickerColor, resolvedTheme);
  const readable = pickReadableText(displayColor);
  // Indicator position on the square tracks the current color so users
  // see where they are without a sliders UI. X → hue, Y → lightness
  // (inverted: top = lighter). The Y axis is bounded to the safe
  // accent band for the active theme — top row = band.max, bottom row =
  // band.min — which matches what the click handler emits and the CSS
  // overlays paint.
  const { min: bandMin, max: bandMax } = accentLightnessBand(resolvedTheme);
  const { h: currentHue, l: currentLightness } = hexToHsl(displayColor);
  const lightnessRange = bandMax - bandMin;
  const indicatorLeft = (currentHue / 360) * 100;
  const indicatorTop = ((bandMax - currentLightness) / lightnessRange) * 100;

  useEffect(() => {
    if (typeof window === "undefined") return;
    const media = window.matchMedia("(max-width: 799px)");
    const update = () => setMobilePickerActive(media.matches);
    update();
    media.addEventListener?.("change", update);
    media.addListener?.(update);
    return () => {
      media.removeEventListener?.("change", update);
      media.removeListener?.(update);
    };
  }, []);

  const togglePicker = useCallback(() => {
    if (!open) {
      setDraftColor(color);
      setDraftGlyph(glyph);
    }
    onToggle();
  }, [color, glyph, onToggle, open]);

  const commitColorPick = useCallback(
    (next: string) => {
      if (mobilePickerActive && !inline) {
        setDraftColor(next);
        return;
      }
      onColorChange(next);
    },
    [inline, mobilePickerActive, onColorChange],
  );

  const commitGlyphPick = useCallback(
    (next: BotGlyphName) => {
      if (mobilePickerActive && !inline) {
        setDraftGlyph(next);
        return;
      }
      onGlyphChange(next);
    },
    [inline, mobilePickerActive, onGlyphChange],
  );

  const applyMobileDraft = useCallback(() => {
    onColorChange(draftColor);
    onGlyphChange(draftGlyph);
    onToggle();
  }, [draftColor, draftGlyph, onColorChange, onGlyphChange, onToggle]);

  // Refs for the two glyph-grid layers. shell = outermost clip + camera
  // target for the vignette/rim light; parallaxRef points at the scroll
  // content but is kept untransformed so the visible glyph boxes and hit
  // targets remain perfectly aligned.
  const parallaxRef = useRef<HTMLDivElement>(null);
  const shellRef = useRef<HTMLDivElement>(null);
  // The .colorPickerWrapper itself. Its viewport rect is the anchor
  // for the floating popover — we read it on open (and on resize)
  // and feed an inline `top`/`left` (already projected into the
  // dimmed area to the LEFT of the panel) so the popover can render
  // with `position: fixed` and escape the panel's overflow clip,
  // mirroring the parameter-help tooltip pattern. Without this, the
  // popover would fall back to `position: absolute` inside the panel
  // (where it overlaps the system-prompt textarea + parameter card
  // and intercepts clicks).
  const wrapperRef = useRef<HTMLDivElement>(null);
  // Final viewport coords for the popover's top-left corner (NOT the
  // raw swatch rect — the leftward shift is folded in here so the
  // inline style is self-sufficient and doesn't depend on a CSS
  // `transform`). `null` while the popover is closed OR while the
  // viewport is narrow enough that the popover should fall back to
  // the centered-modal mobile layout (the `@media (max-width: 799px)`
  // override in the stylesheet ignores inline top/left only when we
  // skip setting them, hence the explicit null on mobile).
  const [popoverAnchor, setPopoverAnchor] = useState<{
    top: number;
    left: number;
  } | null>(null);
  // Below this width, the popover renders as a centered modal
  // (the existing mobile fallback). Mirrors the @media breakpoint
  // in page.module.css so JS and CSS agree on when the side-anchored
  // layout is active.
  const POPOVER_WIDE_BREAKPOINT_PX = 800;
  // Popover footprint: width (matches the CSS `width: 320px`) and the
  // gap between the popover's right edge and the swatch's left edge
  // when projecting the anchor leftward. Hoisting these as constants
  // keeps the JS-side projection in lockstep with the CSS — change
  // both together if the popover's footprint ever moves.
  const POPOVER_WIDTH_PX = 320;
  const POPOVER_GAP_FROM_SWATCH_PX = 32;
  const POPOVER_VIEWPORT_MARGIN_PX = 20;
  // Matches `.colorGlyphPopover { max-height: calc(100dvh - 96px); }`.
  const POPOVER_VERTICAL_RESERVE_PX = 96;

  // ── Drag state for the color square ───────────────────────────────
  // Pointer drag wiring (mouse / touch / stylus, unified via the
  // Pointer Events API). A single pointerdown grabs `setPointerCapture`
  // so the drag continues even if the cursor leaves the square, and a
  // short rAF loop coalesces the ~120Hz pointermove firehose into one
  // commit per painted frame — the swatch, indicator, and (through
  // `shellStyle` upstream) the whole app shell repaint at display
  // refresh rate instead of re-rendering for intermediate positions
  // the user would never see.
  //
  // draggingRef:     is a pointer currently captured?
  // dragRectRef:     the square's bounding rect, cached at pointerdown
  //                  so we skip a layout-flushing getBoundingClientRect
  //                  on every move. The popover is position: fixed /
  //                  mounted-while-open, so the rect is stable for the
  //                  lifetime of a drag.
  // pendingPointRef: latest pointer position awaiting commit. The rAF
  //                  tick reads and clears it.
  // dragFrameRef:    handle of the scheduled rAF, so we can coalesce
  //                  and cancel.
  const draggingRef = useRef(false);
  const dragRectRef = useRef<DOMRect | null>(null);
  const pendingPointRef = useRef<{ clientX: number; clientY: number } | null>(
    null,
  );
  const dragFrameRef = useRef<number | null>(null);

  // Map a pointer position inside `rect` to an HSL-picked hex using the
  // same axis convention as the visible gradient overlay: X → hue
  // 0..360, Y → lightness band.max..band.min (top row brightest
  // allowed, bottom row darkest allowed), where `band` tightens in
  // dark mode via `accentLightnessBand`. Clamping both axes to [0, 1]
  // lets captured pointers that wander past the square's edge still
  // resolve to the nearest in-bounds color rather than overshooting.
  const computePickedColor = useCallback(
    (clientX: number, clientY: number, rect: DOMRect): string => {
      const nx = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
      const ny = Math.max(0, Math.min(1, (clientY - rect.top) / rect.height));
      const hue = nx * 360;
      const { min, max } = accentLightnessBand(resolvedTheme);
      const lightness = max - ny * (max - min);
      return hslToHex(hue, 100, lightness);
    },
    [resolvedTheme],
  );

  // rAF callback: commit the freshest pending pointer position, if
  // any. Written as a ref-reading function (not a useState-reading
  // closure) so we never capture a stale onColorChange — the ref
  // values are always current at flush time.
  const flushPendingPick = useCallback(() => {
    dragFrameRef.current = null;
    const pending = pendingPointRef.current;
    const rect = dragRectRef.current;
    if (!pending || !rect) return;
    pendingPointRef.current = null;
    commitColorPick(computePickedColor(pending.clientX, pending.clientY, rect));
  }, [commitColorPick, computePickedColor]);

  const schedulePickFlush = useCallback(() => {
    if (dragFrameRef.current != null) return;
    dragFrameRef.current = requestAnimationFrame(flushPendingPick);
  }, [flushPendingPick]);

  const handleSquarePointerDown = useCallback(
    (event: React.PointerEvent<HTMLDivElement>) => {
      // Preempt the browser's native text-selection + drag-ghost
      // behavior so a press-and-drag on the square doesn't highlight
      // nearby UI or start a phantom "drag image".
      event.preventDefault();
      const target = event.currentTarget;
      // Capture the pointer so subsequent move events land on this
      // element even when the cursor leaves it — the user shouldn't
      // have to stay inside the square to finish a pick.
      target.setPointerCapture(event.pointerId);
      draggingRef.current = true;
      dragRectRef.current = target.getBoundingClientRect();
      // Commit the landing position synchronously so a tap (no drag)
      // feels instant; subsequent moves are rAF-coalesced.
      commitColorPick(
        computePickedColor(event.clientX, event.clientY, dragRectRef.current),
      );
    },
    [commitColorPick, computePickedColor],
  );

  const handleSquarePointerMove = useCallback(
    (event: React.PointerEvent<HTMLDivElement>) => {
      if (!draggingRef.current) return;
      pendingPointRef.current = {
        clientX: event.clientX,
        clientY: event.clientY,
      };
      schedulePickFlush();
    },
    [schedulePickFlush],
  );

  const handleSquarePointerUp = useCallback(
    (event: React.PointerEvent<HTMLDivElement>) => {
      if (!draggingRef.current) return;
      draggingRef.current = false;
      // Flush any queued rAF synchronously so the final release
      // position is committed immediately — without this, releasing
      // between two animation frames would drop the last movement
      // and leave the swatch on the previous frame's color.
      if (dragFrameRef.current != null) {
        cancelAnimationFrame(dragFrameRef.current);
        dragFrameRef.current = null;
      }
      const pending = pendingPointRef.current;
      const rect = dragRectRef.current;
      if (pending && rect) {
        commitColorPick(
          computePickedColor(pending.clientX, pending.clientY, rect),
        );
      }
      pendingPointRef.current = null;
      dragRectRef.current = null;
      try {
        event.currentTarget.releasePointerCapture(event.pointerId);
      } catch {
        // Capture may have already been released by the browser
        // (e.g. on some touch-end paths); releasing twice throws.
      }
    },
    [commitColorPick, computePickedColor],
  );

  // Mirror of Up for interrupted drags (OS alerts, touch cancellation,
  // context menus, viewport changes). Drops any pending state without
  // committing a partial pick — the last successfully-moved frame
  // stays as the current color.
  const handleSquarePointerCancel = useCallback(
    (event: React.PointerEvent<HTMLDivElement>) => {
      draggingRef.current = false;
      pendingPointRef.current = null;
      dragRectRef.current = null;
      if (dragFrameRef.current != null) {
        cancelAnimationFrame(dragFrameRef.current);
        dragFrameRef.current = null;
      }
      try {
        event.currentTarget.releasePointerCapture(event.pointerId);
      } catch {
        // See handleSquarePointerUp — capture may be gone already.
      }
    },
    [],
  );

  // Drop any in-flight drag state when the popover closes. Without
  // this, a scheduled rAF could fire after the square is unmounted,
  // call onColorChange with a stale rect, and quietly overwrite the
  // user's picked color.
  useEffect(() => {
    if (open || inline) return;
    draggingRef.current = false;
    pendingPointRef.current = null;
    dragRectRef.current = null;
    if (dragFrameRef.current != null) {
      cancelAnimationFrame(dragFrameRef.current);
      dragFrameRef.current = null;
    }
  }, [inline, open]);

  // Position driver — the baseline camera. Maps the shell's viewport
  // position to the camera coords so the vignette + rim light pool on
  // the side facing the nearest viewport edge. Popover floating near
  // the top-right of the screen → camera at (1, 0) → rim-light on the
  // top-right edges, shadow on the bottom-left. Popover centered → even
  // ring. Simulates light bouncing off the edges of a physical 3D box
  // being pushed against a wall.
  const positionCamera = useCallback(() => {
    const shell = shellRef.current;
    if (!shell) return;
    const rect = shell.getBoundingClientRect();
    // Shell's center as a [0, 1] coordinate inside the viewport. Clamp
    // defensively — if the popover ever ends up partially off-screen,
    // the vignette stays on the visible side instead of going out of
    // range and producing a flat background.
    const nx = Math.max(
      0,
      Math.min(1, (rect.left + rect.width / 2) / window.innerWidth),
    );
    const ny = Math.max(
      0,
      Math.min(1, (rect.top + rect.height / 2) / window.innerHeight),
    );
    updateGlyphCamera(shell, parallaxRef.current, nx, ny);
  }, []);

  // Floating-popover anchor driver. Captures the swatch wrapper's
  // viewport rect synchronously before paint (useLayoutEffect) and
  // projects it leftward by (popover width + gap) so the popover's
  // right edge lands a clean POPOVER_GAP_FROM_SWATCH_PX from the
  // swatch — placing it cleanly outside the panel chrome in the
  // dimmed area. The projection happens here in JS rather than via
  // a CSS `transform` so the inline style is fully self-sufficient
  // (immune to CSS HMR oddities and ancestor stacking-context
  // surprises). Re-measures on resize so the popover stays glued
  // to the swatch when the viewport changes. On narrow viewports
  // (< POPOVER_WIDE_BREAKPOINT_PX) we leave anchor `null` so the
  // `@media (max-width: 799px)` centered-modal fallback in
  // page.module.css can take over.
  useLayoutEffect(() => {
    if (inline) {
      return;
    }
    if (!open) {
      // Resetting the anchor when the popover closes is the intended
      // synchronization between component-state and the projected
      // viewport-rect cache; the cascading-render concern the lint rule
      // raises doesn't apply here because `popoverAnchor` is not in the
      // effect's dep array, so this never re-fires the effect.
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setPopoverAnchor(null);
      return;
    }
    function measure() {
      if (typeof window === "undefined") return;
      if (window.innerWidth < POPOVER_WIDE_BREAKPOINT_PX) {
        setPopoverAnchor(null);
        return;
      }
      const wrapper = wrapperRef.current;
      if (!wrapper) return;
      const rect = wrapper.getBoundingClientRect();
      const maxPopoverHeight = Math.max(
        0,
        window.innerHeight - POPOVER_VERTICAL_RESERVE_PX,
      );
      const maxTop = Math.max(
        POPOVER_VIEWPORT_MARGIN_PX,
        window.innerHeight - maxPopoverHeight - POPOVER_VIEWPORT_MARGIN_PX,
      );
      setPopoverAnchor({
        top: Math.min(Math.max(rect.top, POPOVER_VIEWPORT_MARGIN_PX), maxTop),
        left: rect.left - POPOVER_WIDTH_PX - POPOVER_GAP_FROM_SWATCH_PX,
      });
    }
    measure();
    window.addEventListener("resize", measure);
    return () => window.removeEventListener("resize", measure);
  }, [inline, open]);

  // Wire the position driver only while the popover is open (the DOM
  // doesn't exist until then, and leaving listeners attached to window
  // after unmount leaks). Window scroll + resize both move the shell
  // within the viewport, so both trigger a re-compute.
  useEffect(() => {
    if (!open && !inline) return;
    const shell = shellRef.current;
    if (!shell) return;
    window.addEventListener("scroll", positionCamera, { passive: true });
    window.addEventListener("resize", positionCamera);
    // Initial pass once the popover has mounted — gives the opening
    // animation a baseline to ease into instead of a 50%/50% flash.
    positionCamera();
    return () => {
      window.removeEventListener("scroll", positionCamera);
      window.removeEventListener("resize", positionCamera);
    };
  }, [inline, open, positionCamera]);

  // Cursor driver — hover-capable override. While the cursor is over
  // the shell, its position becomes the vignette/rim camera directly.
  const handleGridMouseMove = useCallback(
    (event: React.MouseEvent<HTMLDivElement>) => {
      const shell = event.currentTarget;
      const rect = shell.getBoundingClientRect();
      const nx = (event.clientX - rect.left) / rect.width;
      const ny = (event.clientY - rect.top) / rect.height;
      updateGlyphCamera(shell, parallaxRef.current, nx, ny);
    },
    [],
  );

  // On leave, re-invoke the position driver so the camera eases back
  // to match the shell's current viewport placement (NOT a hard 50%/50%
  // reset). Cursor effect softly hands off to the ambient "where on the
  // screen the box is" cue.
  const handleGridMouseLeave = useCallback(() => {
    positionCamera();
  }, [positionCamera]);

  return (
    <div
      ref={wrapperRef}
      className={styles.colorPickerWrapper}
      data-color-affordance="true"
    >
      {!inline ? (
        <button
          type="button"
          className={styles.colorSwatchButton}
          style={
            {
              ["--bot-color" as string]: displayColor,
              ["--bot-tile-ink" as string]: readable,
            } as React.CSSProperties
          }
          onClick={togglePicker}
          aria-label={ariaLabel}
          aria-haspopup="dialog"
          aria-expanded={open}
          data-glyph-tooltip="Pick color and glyph"
        >
          <BotGlyph name={pickerGlyph} />
        </button>
      ) : null}
      {(inline || open) && (
        // Popover is a pure picking surface — no reroll affordance lives
        // here. Randomization is exclusively the swatch's right-click,
        // keeping the popover's two jobs (pick color, pick glyph)
        // unambiguous.
        //
        // Inline `position`/`top`/`left` only fire on wide viewports —
        // `popoverAnchor` already encodes the leftward shift into the
        // dimmed area beside the panel (see useLayoutEffect above).
        // We force `position: fixed` inline because (a) the popover
        // MUST escape the panel's overflow clip to render in the
        // dimmed area, and (b) inlining the position keeps us robust
        // against any CSS HMR / cascade weirdness in dev. On narrow
        // viewports we leave the style off entirely so the
        // `@media (max-width: 799px)` rule in page.module.css wins
        // and the popover recenters as a modal.
        <div
          className={
            inline ? styles.colorGlyphInline : styles.colorGlyphPopover
          }
          style={
            !inline && popoverAnchor
              ? {
                  position: "fixed",
                  top: `${popoverAnchor.top}px`,
                  left: `${popoverAnchor.left}px`,
                  transform: "none",
                }
              : undefined
          }
          role={inline ? "group" : "dialog"}
          aria-label="Bot color and glyph picker"
        >
          <div
            className={styles.colorSquare}
            onPointerDown={handleSquarePointerDown}
            onPointerMove={handleSquarePointerMove}
            onPointerUp={handleSquarePointerUp}
            onPointerCancel={handleSquarePointerCancel}
            role="group"
            aria-label="Bot color. Horizontal axis: hue; vertical axis: lightness."
          >
            <div
              className={styles.colorPickerIndicator}
              style={{ left: `${indicatorLeft}%`, top: `${indicatorTop}%` }}
              aria-hidden="true"
            />
          </div>
          {!inline ? (
            <div className={styles.popoverDivider} aria-hidden="true" />
          ) : null}
          {/* glyph picker lives in a three-layer stack:
              · shell (shellRef): clips, hosts the dynamic vignette +
                rim light (both read --vignette-x/y; rim is a masked
                radial on the ::before). Anchors the perspective frame
                and is the target of the viewport-position camera so
                where the popover SITS on the user's screen biases
                where the bright point of the vignette pools.
              · scroll: native overflow container. Scrollbar hidden;
                scrolling the grid doesn't shift the vignette, only
                the glyphs move.
              · inner (parallaxRef): scroll content, intentionally kept
                untransformed so glyph hit targets stay reliable.
              Cursor hover overrides the position baseline; mouseleave
              eases back to the viewport-placement baseline. */}
          <div
            ref={shellRef}
            className={styles.glyphGridShell}
            // Keep the picked color available to future picker affordances.
            // The glyph buttons themselves are deliberately theme-polarity
            // black/white so their click targets stay visually stable.
            style={
              {
                ["--picker-color" as string]: displayColor,
                ["--picker-ink" as string]: readable,
              } as React.CSSProperties
            }
            onMouseMove={handleGridMouseMove}
            onMouseLeave={handleGridMouseLeave}
          >
            <div className={styles.glyphGridScroll}>
              <div ref={parallaxRef} className={styles.glyphGridInner}>
                <BotGlyphPicker
                  value={pickerGlyph}
                  onChange={commitGlyphPick}
                />
              </div>
            </div>
          </div>
          {!inline ? (
            <div className={styles.colorGlyphApplyBar}>
              <div
                className={styles.colorGlyphApplyPreview}
                style={
                  {
                    ["--bot-color" as string]: displayColor,
                    ["--bot-tile-ink" as string]: readable,
                  } as React.CSSProperties
                }
                aria-hidden="true"
              >
                <BotGlyph name={pickerGlyph} />
              </div>
              <button
                type="button"
                className={styles.colorGlyphApplyButton}
                onClick={applyMobileDraft}
              >
                Apply
              </button>
            </div>
          ) : null}
        </div>
      )}
    </div>
  );
}

// ── Hub glyphs ────────────────────────────────────────────────────────
// Each Hub tile carries a large 5-color glyph echoing the wordmark's
// per-letter palette (P / R / I / S / M). Drawn as inline SVG with one
// coloured element per prism letter so the icons read as miniature
// wordmark refractions — no single-color fill, no gradient shortcut.

interface GlyphProps {
  size?: number;
}

function GlyphChat({ size = 88 }: GlyphProps): React.JSX.Element {
  // Speech bubble whose perimeter is split into four 90° arcs (P / R / I
  // / S) plus a small tail (M). Each arc is its own <path> so the colour
  // transitions happen at the cardinal points, giving the bubble a
  // refracted-rainbow look without needing gradients.
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 48 48"
      fill="none"
      strokeWidth={3}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
    >
      {/* Arc 1 (P): top -> right */}
      <path d="M24 6 A 16 16 0 0 1 40 22" stroke={PRISM_COLORS.p} />
      {/* Arc 2 (R): right -> bottom */}
      <path d="M40 22 A 16 16 0 0 1 24 38" stroke={PRISM_COLORS.r} />
      {/* Arc 3 (I): bottom -> left */}
      <path d="M24 38 A 16 16 0 0 1 8 22" stroke={PRISM_COLORS.i} />
      {/* Arc 4 (S): left -> top */}
      <path d="M8 22 A 16 16 0 0 1 24 6" stroke={PRISM_COLORS.s} />
      {/* Tail (M): small chevron hanging off the bottom-left of the bubble */}
      <path d="M18 36 L10 44 L22 38" stroke={PRISM_COLORS.m} />
    </svg>
  );
}

