function applyWildcardSlotChipBoundaryDelete(
  editor: Editor,
  direction: "backward" | "forward",
  wildcardSlotNames: readonly string[],
  excludedBangNames: readonly string[],
): boolean {
  const ranges = findWildcardSlotTokenRanges(
    editor.state.doc,
    wildcardSlotNames,
    excludedBangNames,
  );
  if (ranges.length === 0) return false;
  const sel = editor.state.selection;

  for (const range of ranges) {
    const chipFrom = range.from;
    const chipTo = range.to;
    let from = chipFrom;
    let to = chipTo;

    if (!sel.empty) {
      if (sel.from >= chipTo || sel.to <= chipFrom) continue;
      from = Math.min(sel.from, chipFrom);
      to = Math.max(sel.to, chipTo);
    } else if (direction === "backward") {
      if (sel.from <= chipFrom || sel.from > chipTo) continue;
    } else if (sel.from < chipFrom || sel.from >= chipTo) {
      continue;
    }

    editor.chain().focus().deleteRange({ from, to }).run();
    return true;
  }

  return false;
}

function applyWildcardSlotReferenceCycle(
  editor: Editor,
  direction: "up" | "down",
  wildcardSlotNames: readonly string[],
  excludedBangNames: readonly string[],
): boolean {
  const sel = editor.state.selection;
  if (sel.empty) return false;
  const ranges = findWildcardSlotTokenRanges(
    editor.state.doc,
    wildcardSlotNames,
    excludedBangNames,
  );
  if (ranges.length === 0) return false;

  for (const range of ranges) {
    if (sel.from !== range.from || sel.to !== range.to) continue;
    const token = editor.state.doc.textBetween(
      range.from,
      range.to,
      "\n",
      "\n",
    );
    const replacement = rewriteWildcardSlotTokenReference(token, direction);
    if (!replacement || replacement === token) return false;
    editor
      .chain()
      .focus()
      .insertContentAt({ from: range.from, to: range.to }, replacement)
      .setTextSelection({
        from: range.from,
        to: range.from + replacement.length,
      })
      .run();
    return true;
  }

  return false;
}

type ComposerShortcutChipKind =
  "command" | "tool" | "prompt" | "wildcard" | "wildcard-slot";

interface EditorComposerShortcutChipRange {
  kind: ComposerShortcutChipKind;
  from: number;
  to: number;
}

function editorChipTokenRange(range: { from: number; to: number }): {
  from: number;
  to: number;
} {
  return {
    from: range.from,
    to: range.to,
  };
}

function findEditorComposerShortcutChipRanges(
  editor: Editor,
  commandNames: readonly string[],
  toolNames: readonly string[],
  promptNames: readonly string[],
  wildcardNames: readonly string[],
  wildcardSlotNames: readonly string[],
): EditorComposerShortcutChipRange[] {
  const ranges: EditorComposerShortcutChipRange[] = [];
  const commandRange = findLeadingDevCommandTokenRange(
    editor.state.doc,
    commandNames,
  );
  if (commandRange) {
    ranges.push({
      kind: "command",
      ...editorChipTokenRange(commandRange),
    });
  }
  const toolRange = findLeadingToolShortcutTokenRange(
    editor.state.doc,
    toolNames,
  );
  if (toolRange) {
    ranges.push({
      kind: "tool",
      ...editorChipTokenRange(toolRange),
    });
  }
  for (const promptRange of findPromptShortcutTokenRanges(
    editor.state.doc,
    promptNames,
  )) {
    ranges.push({
      kind: "prompt",
      ...editorChipTokenRange(promptRange),
    });
  }
  for (const wildcardRange of findWildcardDeckTokenRanges(
    editor.state.doc,
    wildcardNames,
  )) {
    ranges.push({
      kind: "wildcard",
      ...editorChipTokenRange(wildcardRange),
    });
  }
  for (const wildcardSlotRange of findWildcardSlotTokenRanges(
    editor.state.doc,
    wildcardSlotNames,
    wildcardNames,
  )) {
    ranges.push({
      kind: "wildcard-slot",
      ...editorChipTokenRange(wildcardSlotRange),
    });
  }
  return ranges.sort((a, b) => a.from - b.from);
}

function composerShortcutChipKindFromClick(
  event: MouseEvent,
): ComposerShortcutChipKind | null {
  const target = event.target;
  const element =
    target instanceof Element
      ? target
      : target instanceof Node
        ? target.parentElement
        : null;
  const chip = element?.closest(
    ".tiptapPrismDevCommandToken, .tiptapPrismToolToken, .tiptapPrismPromptShortcutToken, .tiptapPrismWildcardDeckToken, .tiptapPrismWildcardSlotToken",
  );
  if (!chip) return null;
  if (chip.classList.contains("tiptapPrismDevCommandToken")) return "command";
  if (chip.classList.contains("tiptapPrismToolToken")) return "tool";
  if (chip.classList.contains("tiptapPrismWildcardDeckToken"))
    return "wildcard";
  if (chip.classList.contains("tiptapPrismWildcardSlotToken"))
    return "wildcard-slot";
  return "prompt";
}

function findEditorComposerShortcutChipRangeAt(
  editor: Editor,
  pos: number,
  kind: ComposerShortcutChipKind,
  commandNames: readonly string[],
  toolNames: readonly string[],
  promptNames: readonly string[],
  wildcardNames: readonly string[],
  wildcardSlotNames: readonly string[],
): EditorComposerShortcutChipRange | null {
  return (
    findEditorComposerShortcutChipRanges(
      editor,
      commandNames,
      toolNames,
      promptNames,
      wildcardNames,
      wildcardSlotNames,
    ).find((candidate) => {
      return (
        candidate.kind === kind && pos >= candidate.from && pos <= candidate.to
      );
    }) ?? null
  );
}

function editorComposerChipActivationTarget(
  editor: Editor,
  range: EditorComposerShortcutChipRange,
): ComposerChipActivationTarget | null {
  const text = editor.state.doc.textBetween(range.from, range.to, "\n", "\n");
  if (!text) return null;
  return {
    surface: "editor",
    kind: range.kind,
    start: range.from,
    end: range.to,
    text,
  };
}

function replaceComposerChipRangeInEditor(
  editor: Editor,
  target: ComposerChipActivationTarget,
  replacement: string,
): boolean {
  if (target.surface !== "editor") return false;
  if (
    editor.state.doc.textBetween(target.start, target.end, "\n", "\n") !==
    target.text
  ) {
    return false;
  }
  editor
    .chain()
    .focus()
    .deleteRange({ from: target.start, to: target.end })
    .insertContentAt(target.start, replacement)
    .run();
  return true;
}

function deleteComposerChipRangeInEditor(
  editor: Editor,
  target: ComposerChipActivationTarget,
): boolean {
  if (target.surface !== "editor") return false;
  if (
    editor.state.doc.textBetween(target.start, target.end, "\n", "\n") !==
    target.text
  ) {
    return false;
  }
  editor
    .chain()
    .focus()
    .deleteRange({ from: target.start, to: target.end })
    .run();
  return true;
}

function insertPendingWildcardSlotChipInEditor(
  editor: Editor,
  target: ComposerChipActivationTarget,
  key: BuiltInPromptWildcardSlotKey,
  fallback: string,
  id: string,
): PendingComposerWildcardSlot | null {
  if (target.surface !== "editor" || target.kind !== "wildcard-slot")
    return null;
  if (
    editor.state.doc.textBetween(target.start, target.end, "\n", "\n") !==
    target.text
  ) {
    return null;
  }
  const pendingText = PENDING_COMPOSER_WILDCARD_SLOT_TEXT;
  editor
    .chain()
    .focus()
    .deleteRange({ from: target.start, to: target.end })
    .insertContentAt(target.start, pendingText)
    .run();
  return {
    id,
    key,
    fallback,
    pendingText,
    from: target.start,
    to: target.start + pendingText.length,
  };
}

function findComposerTextareaChipRangeAt(
  ranges: readonly ComposerTextareaChipRange[],
  caret: number,
): ComposerTextareaChipRange | null {
  return (
    ranges.find(
      (range) => !range.pending && caret >= range.start && caret <= range.end,
    ) ?? null
  );
}

function findComposerTextareaChipRangeAtPoint(
  ranges: readonly ComposerTextareaChipRange[],
  overlay: HTMLElement | null,
  clientX: number,
  clientY: number,
): ComposerTextareaChipRange | null {
  if (!overlay) return null;
  const slots = overlay.querySelectorAll<HTMLElement>(
    "[data-composer-chip-slot='true']",
  );
  for (const slot of slots) {
    const rect = slot.getBoundingClientRect();
    if (
      clientX < rect.left ||
      clientX > rect.right ||
      clientY < rect.top ||
      clientY > rect.bottom
    ) {
      continue;
    }
    const start = Number(slot.dataset.chipStart);
    const end = Number(slot.dataset.chipEnd);
    if (!Number.isFinite(start) || !Number.isFinite(end)) continue;
    const kind = slot.dataset.kind as
      ComposerTextareaChipRange["kind"] | undefined;
    return (
      ranges.find(
        (range) =>
          !range.pending &&
          range.start === start &&
          range.end === end &&
          (!kind || range.kind === kind),
      ) ?? null
    );
  }
  return null;
}

function textareaComposerChipActivationTarget(
  value: string,
  range: ComposerTextareaChipRange,
): ComposerChipActivationTarget | null {
  const text = value.slice(range.start, range.end);
  if (!text) return null;
  return {
    surface: "textarea",
    kind: range.kind,
    start: range.start,
    end: range.end,
    text,
  };
}

function applyComposerShortcutChipArrowKey(
  editor: Editor,
  direction: "left" | "right",
  commandNames: readonly string[],
  toolNames: readonly string[],
  promptNames: readonly string[],
  wildcardNames: readonly string[],
  wildcardSlotNames: readonly string[],
): boolean {
  const sel = editor.state.selection;
  if (!sel.empty) return false;
  const caret = sel.from;
  const ranges = findEditorComposerShortcutChipRanges(
    editor,
    commandNames,
    toolNames,
    promptNames,
    wildcardNames,
    wildcardSlotNames,
  );
  for (const range of ranges) {
    const shouldJump =
      direction === "right"
        ? caret >= range.from && caret < range.to
        : caret > range.from && caret <= range.to;
    if (!shouldJump) continue;
    if (range.kind === "wildcard-slot") {
      editor
        .chain()
        .focus()
        .setTextSelection({ from: range.from, to: range.to })
        .run();
      return true;
    }
    editor
      .chain()
      .focus()
      .setTextSelection(direction === "right" ? range.to : range.from)
      .run();
    return true;
  }
  return false;
}

function isPlainTextInsertionKey(event: {
  key: string;
  altKey: boolean;
  ctrlKey: boolean;
  metaKey: boolean;
  nativeEvent?: { isComposing?: boolean };
}): boolean {
  if (event.nativeEvent?.isComposing) return false;
  if (event.altKey || event.ctrlKey || event.metaKey) return false;
  return event.key.length === 1 || event.key === "Enter";
}

function shouldAcceptComposerShortcutCompletionKey(event: {
  key: string;
  shiftKey: boolean;
  altKey: boolean;
  ctrlKey: boolean;
  metaKey: boolean;
}): boolean {
  if (event.shiftKey || event.altKey || event.ctrlKey || event.metaKey)
    return false;
  return (
    event.key === "Enter" ||
    event.key === "Tab" ||
    event.key === " " ||
    event.key === "Spacebar"
  );
}

function getMountedEditorView(
  editor: Editor | null | undefined,
): Editor["view"] | null {
  if (!editor || editor.isDestroyed) return null;
  try {
    return editor.view;
  } catch {
    return null;
  }
}

function getMountedEditorDom(
  editor: Editor | null | undefined,
): HTMLElement | null {
  return (getMountedEditorView(editor)?.dom as HTMLElement | undefined) ?? null;
}

interface ProseMirrorSelectionState {
  selection: {
    $from: {
      depth: number;
      node: (depth: number) => { type: { name: string } };
    };
  };
}

function selectionIsInsideMarkdownList(
  state: ProseMirrorSelectionState,
): boolean {
  const { $from } = state.selection;
  for (let depth = $from.depth; depth > 0; depth -= 1) {
    const nodeName = $from.node(depth).type.name;
    if (
      nodeName === "listItem" ||
      nodeName === "bulletList" ||
      nodeName === "orderedList"
    ) {
      return true;
    }
  }
  return false;
}

function domSelectionIsInsideMarkdownList(root: HTMLElement): boolean {
  const selection = root.ownerDocument.getSelection();
  const anchor = selection?.anchorNode;
  if (!anchor) return false;

  const anchorElement =
    anchor instanceof Element ? anchor : anchor.parentElement;

  return Boolean(
    anchorElement &&
    root.contains(anchorElement) &&
    anchorElement.closest("li, ol, ul"),
  );
}

function editorSelectionIsInsideMarkdownList(editor: Editor): boolean {
  return (
    editor.isActive("listItem") ||
    editor.isActive("bulletList") ||
    editor.isActive("orderedList")
  );
}

function useMobileKeyboardInset(active: boolean): number {
  const [inset, setInset] = useState(0);

  useEffect(() => {
    if (!active || typeof window === "undefined" || !window.visualViewport) {
      return;
    }

    const viewport = window.visualViewport;
    let frame = 0;
    const updateInset = () => {
      const nextInset = Math.max(
        0,
        Math.round(window.innerHeight - viewport.height - viewport.offsetTop),
      );
      setInset(nextInset);
    };
    const scheduleUpdate = () => {
      if (frame) window.cancelAnimationFrame(frame);
      frame = window.requestAnimationFrame(updateInset);
    };

    scheduleUpdate();
    viewport.addEventListener("resize", scheduleUpdate);
    viewport.addEventListener("scroll", scheduleUpdate);
    window.addEventListener("resize", scheduleUpdate);
    return () => {
      if (frame) window.cancelAnimationFrame(frame);
      viewport.removeEventListener("resize", scheduleUpdate);
      viewport.removeEventListener("scroll", scheduleUpdate);
      window.removeEventListener("resize", scheduleUpdate);
    };
  }, [active]);

  return active ? inset : 0;
}

interface ComposerCommandPopoverProps {
  open: boolean;
  anchorRect: DOMRect | null;
  themeSource: Element | null;
  scope: ComposerShortcutScope;
  commands: readonly CommandCenterCommand[];
  highlightIndex: number;
  onHighlightIndexChange: (next: number) => void;
  onPickCommand: (command: CommandCenterCommand) => void;
  excludeInteractionRef?: RefObject<Element | null>;
  onDismiss?: () => void;
}

function commandPickDescription(command: CommandCenterCommand): string {
  if (isComposerToolPick(command)) {
    return command.command.trim();
  }
  if (isComposerTrueWildcardSlotPick(command)) {
    return command.title.trim() || "Filled by the selected model on send.";
  }
  if (isComposerWildcardDeckPick(command)) {
    return (
      command.title.trim() ||
      command.command.trim().replace(/\s+/g, " ").slice(0, 96)
    );
  }
  const aliasText =
    command.aliases.length > 0
      ? `Aliases: ${command.aliases.map((alias) => `/${alias}`).join(", ")}`
      : "";
  const title = command.title.trim();
  if (title && title.toLowerCase() !== command.name.toLowerCase()) {
    return aliasText ? `${aliasText} · ${title}` : title;
  }
  if (aliasText) return aliasText;
  return command.command.trim().replace(/\s+/g, " ").slice(0, 96);
}

function ComposerCommandPopover({
  open,
  anchorRect,
  themeSource,
  scope,
  commands,
  highlightIndex,
  onHighlightIndexChange,
  onPickCommand,
  excludeInteractionRef,
  onDismiss,
}: ComposerCommandPopoverProps): React.JSX.Element | null {
  const menuRef = useRef<HTMLDivElement>(null);
  const portalStyle = useMemo(() => {
    if (!open || !anchorRect) return null;
    return computeCommandMenuFixedStyle(anchorRect, themeSource);
  }, [anchorRect, open, themeSource]);
  const [viewportNudge, setViewportNudge] = useState({ x: 0, y: 0 });
  const adjustedStyle = useMemo((): React.CSSProperties | null => {
    if (!portalStyle) return null;
    const left =
      typeof portalStyle.left === "number"
        ? portalStyle.left
        : Number(portalStyle.left);
    const top =
      typeof portalStyle.top === "number"
        ? portalStyle.top
        : Number(portalStyle.top);
    const bottom =
      typeof portalStyle.bottom === "number"
        ? portalStyle.bottom
        : Number(portalStyle.bottom);
    const next: React.CSSProperties = { ...portalStyle };
    if (Number.isFinite(left)) {
      next.left = left + viewportNudge.x;
    }
    if (Number.isFinite(top)) {
      next.top = top + viewportNudge.y;
    } else if (Number.isFinite(bottom)) {
      next.bottom = bottom - viewportNudge.y;
    }
    return next;
  }, [portalStyle, viewportNudge]);
  const safeHighlight = Math.max(
    0,
    Math.min(highlightIndex, Math.max(0, commands.length - 1)),
  );

  useLayoutEffect(() => {
    if (!open || !anchorRect || !portalStyle) return;
    const menu = menuRef.current;
    if (!menu) return;
    const r = menu.getBoundingClientRect();
    const pad = COMPOSE_MENU_VIEWPORT_PAD_PX;
    const vw = globalThis.window.innerWidth;
    const vh = globalThis.window.innerHeight;
    let x = 0;
    let y = 0;
    if (r.right > vw - pad) x += vw - pad - r.right;
    if (r.left + x < pad) x = pad - r.left;
    if (r.bottom > vh - pad) y += vh - pad - r.bottom;
    if (r.top + y < pad) y = pad - r.top;
    const frame = window.requestAnimationFrame(() => {
      setViewportNudge((prev) =>
        prev.x === x && prev.y === y ? prev : { x, y },
      );
    });
    return () => window.cancelAnimationFrame(frame);
  }, [open, anchorRect, portalStyle, commands.length]);

  useEffect(() => {
    if (!open || commands.length === 0) return;
    const row = menuRef.current?.querySelector<HTMLElement>(
      `[data-command-index="${safeHighlight}"]`,
    );
    row?.scrollIntoView({ block: "nearest" });
  }, [open, commands.length, safeHighlight, viewportNudge]);

  useEffect(() => {
    if (!open || !onDismiss) return;
    const handlePointerDown = (event: PointerEvent): void => {
      const target = event.target;
      if (!(target instanceof Node)) return;
      if (menuRef.current?.contains(target)) return;
      const shell = excludeInteractionRef?.current;
      if (shell?.contains(target)) return;
      onDismiss();
    };
    document.addEventListener("pointerdown", handlePointerDown, true);
    return () =>
      document.removeEventListener("pointerdown", handlePointerDown, true);
  }, [open, onDismiss, excludeInteractionRef]);

  if (!open || !adjustedStyle || typeof document === "undefined") {
    return null;
  }
  const indexedCommands = commands.map((command, index) => ({
    command,
    index,
  }));
  const wildcardRailEntries =
    scope === "wildcard-slot"
      ? indexedCommands.filter(({ command }) =>
          isComposerTrueWildcardSlotPick(command),
        )
      : [];
  const commandRailEntries =
    scope === "leading"
      ? indexedCommands.filter(({ command }) =>
          isCommandCenterOperationalCommand(command),
        )
      : [];
  const listEntries =
    scope === "wildcard-slot"
      ? indexedCommands.filter(
          ({ command }) => !isComposerTrueWildcardSlotPick(command),
        )
      : scope === "leading"
        ? indexedCommands.filter(
            ({ command }) => !isCommandCenterOperationalCommand(command),
          )
        : indexedCommands;
  const visibleKinds = new Set(
    listEntries.map(({ command }) => composerCommandPickKind(command)),
  );
  const railEntriesLength =
    wildcardRailEntries.length + commandRailEntries.length;
  const showSectionHeaders =
    scope === "wildcard-slot" || scope === "leading"
      ? railEntriesLength > 0 && listEntries.length > 0
      : visibleKinds.size > 1;

  return createPortal(
    <div
      ref={menuRef}
      className={`${styles.composeBotMenu} ${styles.composeCommandMenu}`}
      style={adjustedStyle}
      role="listbox"
      aria-label={
        scope === "wildcard-slot"
          ? "Choose a wildcard"
          : scope === "wildcard"
            ? "Choose a wildcard deck"
            : scope === "tool"
              ? "Choose a tool"
              : scope === "leading"
                ? "Choose a command or prompt"
                : "Choose a prompt"
      }
    >
      <div className={styles.composeBotListbox}>
        {commands.length === 0 && (
          <div className={styles.composeBotNoMatches} role="presentation">
            {scope === "wildcard"
              ? "No decks match."
              : scope === "wildcard-slot"
                ? "No wildcards match."
                : scope === "tool"
                  ? "No tools match."
                  : scope === "leading"
                    ? "No commands or prompts match."
                    : "No prompts match."}
          </div>
        )}
        {wildcardRailEntries.length > 0 ? (
          <div
            className={styles.composeWildcardSlotRail}
            role="group"
            aria-label="Wildcard generators"
          >
            {wildcardRailEntries.map(({ command, index }) => {
              const active = index === safeHighlight;
              const description = commandPickDescription(command);
              return (
                <button
                  key={command.id}
                  type="button"
                  data-command-index={index}
                  data-command-kind="wildcard-slot"
                  role="option"
                  aria-selected={active ? "true" : "false"}
                  className={`${styles.composeWildcardSlotButton} ${styles.composeCommandOption}`}
                  title={description}
                  onMouseEnter={() => onHighlightIndexChange(index)}
                  onMouseDown={(event) => {
                    event.preventDefault();
                    onPickCommand(command);
                  }}
                >
                  <span
                    className={styles.composeCommandSlash}
                    aria-hidden="true"
                  >
                    {"{"}
                  </span>
                  <span className={styles.composeBotOptionName}>
                    {composerCommandDisplayName(command)}
                  </span>
                  <span
                    className={styles.composeCommandSlash}
                    aria-hidden="true"
                  >
                    {"}"}
                  </span>
                </button>
              );
            })}
          </div>
        ) : null}
        {commandRailEntries.length > 0 ? (
          <div
            className={styles.composeCommandRail}
            role="group"
            aria-label="System operations"
          >
            {commandRailEntries.map(({ command, index }) => {
              const active = index === safeHighlight;
              const description = commandPickDescription(command);
              return (
                <button
                  key={command.id}
                  type="button"
                  data-command-index={index}
                  data-command-kind="command"
                  role="option"
                  aria-selected={active ? "true" : "false"}
                  className={`${styles.composeCommandRailButton} ${styles.composeCommandOption}`}
                  title={description}
                  onMouseEnter={() => onHighlightIndexChange(index)}
                  onMouseDown={(event) => {
                    event.preventDefault();
                    onPickCommand(command);
                  }}
                >
                  <span
                    className={styles.composeCommandSlash}
                    aria-hidden="true"
                  >
                    $
                  </span>
                  <span className={styles.composeBotOptionName}>
                    {command.name}
                  </span>
                </button>
              );
            })}
          </div>
        ) : null}
        {listEntries.map(({ command, index }, listIndex) => {
          const active = index === safeHighlight;
          const description = commandPickDescription(command);
          const commandKind = composerCommandPickKind(command);
          const previousCommand =
            listIndex > 0 ? listEntries[listIndex - 1]?.command : null;
          const previousKind = previousCommand
            ? composerCommandPickKind(previousCommand)
            : null;
          const sectionHeader =
            showSectionHeaders && commandKind !== previousKind
              ? commandKind === "command"
                ? "System"
                : commandKind === "tool"
                  ? "Tools"
                  : commandKind === "wildcard-slot"
                    ? "Wildcards"
                    : commandKind === "wildcard"
                      ? "Decks"
                      : "Prompts"
              : null;
          return (
            <Fragment key={command.id}>
              {sectionHeader ? (
                <div
                  className={styles.composeCommandSectionHeader}
                  data-command-kind={commandKind}
                  role="presentation"
                >
                  <span>{sectionHeader}</span>
                </div>
              ) : null}
              <button
                type="button"
                data-command-index={index}
                data-command-kind={commandKind}
                role="option"
                aria-selected={active ? "true" : "false"}
                className={`${styles.composeBotOption} ${styles.composeCommandOption}`}
                data-color-tag={command.colorTag ?? undefined}
                style={commandCenterColorStyle(command.colorTag)}
                onMouseEnter={() => onHighlightIndexChange(index)}
                onMouseDown={(event) => {
                  event.preventDefault();
                  onPickCommand(command);
                }}
              >
                {commandKind === "wildcard-slot" ? (
                  <span
                    className={styles.composeCommandSlash}
                    aria-hidden="true"
                  >
                    {"{"}
                  </span>
                ) : (
                  <span
                    className={styles.composeCommandSlash}
                    aria-hidden="true"
                  >
                    {composerShortcutInvocationPrefix(command)}
                  </span>
                )}
                <span className={styles.composeCommandText}>
                  <span className={styles.composeBotOptionName}>
                    {composerCommandDisplayName(command)}
                  </span>
                  {description ? (
                    <span className={styles.composeCommandMeta}>
                      {description}
                    </span>
                  ) : null}
                </span>
                {commandKind === "wildcard-slot" ? (
                  <span
                    className={styles.composeCommandSlash}
                    aria-hidden="true"
                  >
                    {"}"}
                  </span>
                ) : null}
              </button>
            </Fragment>
          );
        })}
      </div>
    </div>,
    document.body,
  );
}

function resolveTypedLineStartIndexes(lines: string[]): number[] {
  let cursor = 0;
  return lines.map((line) => {
    const headingInfo = parseChatModeHashHeadingLine(line);
    const displayLine = headingInfo?.text ?? line;
    const wordTokens = tokenizeMessageReveal(displayLine);
    const lineStartIndex = cursor;
    cursor += wordTokens.length;
    return lineStartIndex;
  });
}

