function optionalScaleLabel(
  value: BotProfileScaleValue | null,
  labels: readonly [string, string, string, string, string],
): string {
  if (value === null) return "Unspecified";
  return labels[value + 2] ?? "Unspecified";
}

function BotProfileScaleControl({
  label,
  infoId,
  info,
  value,
  labels,
  leftLabel,
  rightLabel,
  onChange,
  onRandomize,
}: {
  label: string;
  infoId?: string;
  info?: string;
  value: BotProfileScaleValue | null;
  labels: readonly [string, string, string, string, string];
  leftLabel: string;
  rightLabel: string;
  onChange: (value: BotProfileScaleValue | null) => void;
  onRandomize?: () => void | Promise<void>;
}): React.JSX.Element {
  return (
    <div className={styles.botProfileScaleControl}>
      <div className={styles.botProfileScaleHeader}>
        <span className={styles.controlLabelWithInfo}>
          <span>{label}</span>
          {info && infoId ? (
            <PanelSectionInfo
              id={infoId}
              label={`About ${label}`}
              variant="control"
            >
              {info}
            </PanelSectionInfo>
          ) : null}
        </span>
        <span className={styles.botAvatarAtomicFieldActions}>
          <strong>{optionalScaleLabel(value, labels)}</strong>
          {onRandomize ? (
            <BotFieldRandomizerButton label={label} onRandomize={onRandomize} />
          ) : null}
        </span>
      </div>
      <input
        type="range"
        min={-2}
        max={2}
        step={1}
        value={value ?? 0}
        data-active={value !== null ? "true" : undefined}
        onChange={(event) =>
          onChange(Number(event.currentTarget.value) as BotProfileScaleValue)
        }
        aria-label={label}
      />
      <div className={styles.botProfileScaleEnds} aria-hidden="true">
        <span>{leftLabel}</span>
        <span>{rightLabel}</span>
      </div>
      <button
        type="button"
        className={styles.botProfileClearButton}
        onClick={() => onChange(null)}
        disabled={value === null}
      >
        Leave unspecified
      </button>
    </div>
  );
}

/** Max characters for the purpose clause after "You are [Name]..." in the profile builder. */
const BOT_PROFILE_PURPOSE_STATEMENT_MAX_LENGTH = 120;

/**
 * Expand Prompt Center tokens in profile-builder textareas before save.
 * Leaves compact single-line inputs and non-text controls untouched.
 */
function BotAvatarFontOption({
  fontId,
  part,
  selected,
  onClick,
}: {
  fontId: BotFaceFontId;
  part: "eyes" | "mouth";
  selected: boolean;
  onClick: () => void;
}): React.JSX.Element {
  return (
    <button
      type="button"
      className={styles.botAvatarFontOption}
      data-selected={selected ? "true" : undefined}
      aria-pressed={selected}
      aria-label={`${BOT_FACE_FONT_LABELS[fontId]} ${part}`}
      onClick={onClick}
    >
      <span
        className={styles.botAvatarFontOptionSample}
        data-face-font={fontId}
        aria-hidden="true"
      >
        {part === "eyes" ? "••" : "━"}
      </span>
      <span>{BOT_FACE_FONT_LABELS[fontId]}</span>
    </button>
  );
}

function BotAvatarCustomGlyphCapture({
  ariaLabel,
  placeholderGlyph,
  value,
  normalize,
  onChange,
  onRandomize,
}: {
  ariaLabel: string;
  placeholderGlyph: string;
  value: string | null;
  normalize: (raw: string) => string | null;
  onChange: (character: string | null) => void;
  onRandomize: () => void;
}): React.JSX.Element {
  const [capturing, setCapturing] = useState(false);
  const inputRef = useRef<HTMLInputElement | null>(null);

  useEffect(() => {
    if (!capturing) return;
    const frame = window.requestAnimationFrame(() => inputRef.current?.focus());
    return () => window.cancelAnimationFrame(frame);
  }, [capturing]);

  const commitCapture = (raw: string) => {
    onChange(normalize(raw));
    setCapturing(false);
  };

  return (
    <BotAvatarRefractRandomizer label={ariaLabel} onRandomize={onRandomize}>
      {(binding) => (
    <div
      {...binding}
      className={styles.botAvatarCustomGlyphCapture}
      data-capturing={capturing ? "true" : undefined}
    >
      {capturing ? (
        <input
          ref={inputRef}
          className={styles.botAvatarCustomGlyphCaptureInput}
          type="text"
          aria-label={ariaLabel}
          autoCapitalize="off"
          autoCorrect="off"
          spellCheck={false}
          onBlur={() => setCapturing(false)}
          onKeyDown={(event) => {
            if (event.key === "Escape") {
              event.preventDefault();
              setCapturing(false);
            }
          }}
          onChange={(event) => {
            const next = event.currentTarget.value;
            if (!next) return;
            commitCapture(next);
            event.currentTarget.value = "";
          }}
        />
      ) : null}
      <button
        type="button"
        className={styles.botAvatarCustomGlyphCaptureButton}
        data-filled={value ? "true" : undefined}
        aria-label={ariaLabel}
        aria-pressed={capturing}
        onClick={() => setCapturing(true)}
      >
        <span aria-hidden="true">{value ?? placeholderGlyph}</span>
        <strong>
          {capturing ? "Type glyph…" : value ? "Custom" : "Set glyph"}
        </strong>
      </button>
      {value ? (
        <button
          type="button"
          className={styles.botAvatarCustomGlyphClearButton}
          aria-label={`Clear ${ariaLabel.toLowerCase()}`}
          onClick={() => onChange(null)}
        >
          <X size={12} strokeWidth={2.4} aria-hidden="true" />
        </button>
      ) : null}
    </div>
      )}
    </BotAvatarRefractRandomizer>
  );
}

function botAvatarWeightLabel(weight: number): string {
  if (weight <= 450) return "Thin";
  if (weight >= 750) return "Bold";
  return "Balanced";
}

function botAvatarEyeScaleLabel(scale: number): string {
  return `${Math.round(scale * 100)}%`;
}

function botAvatarEyeOffsetYLabel(offsetY: number): string {
  if (Math.abs(offsetY) < BOT_FACE_EYE_OFFSET_Y_STEP / 2) return "Centered";
  return `${Math.round(Math.abs(offsetY) * 100)}% ${offsetY < 0 ? "higher" : "lower"}`;
}

function botAvatarBlinkBarLabel(blinkBar: BotFaceBlinkBar): string {
  if (blinkBar === DEFAULT_BOT_FACE_BLINK_BAR) return "Default";
  return blinkBar === "none" ? "No blink" : blinkBar;
}

function botAvatarBlinkBarOptionLabel(blinkBar: BotFaceBlinkBar): string {
  if (blinkBar === "none") return "No blink";
  if (blinkBar === DEFAULT_BOT_FACE_BLINK_BAR) return "Default blink";
  return `Blink bar ${blinkBar}`;
}

function botAvatarBlinkBarInputValue(blinkBar: BotFaceBlinkBar): string {
  return blinkBar === DEFAULT_BOT_FACE_BLINK_BAR ? "" : blinkBar;
}

type BotAvatarGraphemeSegment = {
  segment: string;
};

type BotAvatarGraphemeSegmenter = {
  segment(input: string): Iterable<BotAvatarGraphemeSegment>;
};

type BotAvatarGraphemeSegmenterConstructor = new (
  locale?: string | string[],
  options?: { granularity?: "grapheme" },
) => BotAvatarGraphemeSegmenter;

function botAvatarSplitVisibleGraphemes(value: string): string[] {
  const trimmed = value.trim();
  if (!trimmed) return [];
  const segmenterConstructor = (
    Intl as unknown as { Segmenter?: BotAvatarGraphemeSegmenterConstructor }
  ).Segmenter;
  const graphemes = segmenterConstructor
    ? Array.from(
        new segmenterConstructor(undefined, {
          granularity: "grapheme",
        }).segment(trimmed),
        (part) => part.segment,
      )
    : Array.from(trimmed);
  return graphemes
    .map((grapheme) => grapheme.trim())
    .filter((grapheme) => grapheme.length > 0);
}

function botAvatarThinkingFramesFromPaste(
  value: string,
): BotFaceThinkingFrames | null {
  const graphemes = botAvatarSplitVisibleGraphemes(value);
  if (graphemes.length < 4) return null;
  return normalizeBotFaceThinkingFrames(graphemes.slice(0, 4));
}

function botAvatarThinkingFrameFromInput(value: string): string | null {
  const graphemes = botAvatarSplitVisibleGraphemes(value);
  return graphemes.at(-1) ?? null;
}

function botAvatarThinkingFramesLabel(frames: readonly string[]): string {
  return frames.join(" ");
}

function botAvatarPreviewIdentityStyle(
  rawHex: string,
  prismPersona = false,
): CSSProperties {
  if (prismPersona) return {};
  const accentStyle = botAccentStyle(rawHex, "dark") ?? {};
  return {
    ...accentStyle,
    ...botAvatarIdentityMaterialStyle(),
  } as CSSProperties;
}

