interface ZenRelationshipDepthRuntimeCheckpoint {
  controller: RelationshipDepthCheckpoint;
  transitionState: RelationshipDepthTransitionState | null;
  surface: "library" | "group-room" | "home";
  returnLabel: string;
  identityKey: string;
  botId: string | null;
  conversationId: string | null;
  library: {
    groupFilterId: string;
    panelGroup: BotLibraryFilterId;
    hueFilterCenter: number | null;
    searchOpen: boolean;
    searchQuery: string;
    selectedBotId: string | null;
    sandboxGridSelectedBotId: string | null;
    zenPersonaBotId: string | null;
    scrollTop: number;
  } | null;
  draft: string;
  scrollTop: number;
  focusElement: HTMLElement | null;
}

type ZenHomeVisitDestination =
  | { kind: "infer" }
  | { kind: "pending" }
  | { kind: "resolve" }
  | { kind: "conversation"; conversationId: string };

interface ZenHomeVisitOptions {
  sourceElement?: HTMLElement | null;
  focusElement?: HTMLElement | null;
  sourceSurface?: "library" | "home";
  destination?: ZenHomeVisitDestination;
  commitSourceVisit?: () => void;
}

type PrismViewTransitionDocument = Document & {
  startViewTransition?: (
    update: () => void | Promise<void>,
  ) => RelationshipDepthNativeViewTransition;
};

const RELATIONSHIP_DEPTH_ANCHOR_NAME = "relationship-depth-anchor";
const RELATIONSHIP_DEPTH_NATIVE_TIMEOUT_MS = 900;

function relationshipDepthIdentity(botId: string | null): string {
  return botId ? `bot:${botId}` : "prism";
}

function visibleRelationshipDepthAnchor(
  surface: "library" | "group-room" | "home",
  identityKey: string,
): HTMLElement | null {
  const candidates = document.querySelectorAll<HTMLElement>(
    "[data-relationship-depth-anchor][data-relationship-depth-identity]",
  );
  for (const candidate of candidates) {
    if (candidate.dataset.relationshipDepthAnchor !== surface) continue;
    if (candidate.dataset.relationshipDepthIdentity !== identityKey) continue;
    const rect = candidate.getBoundingClientRect();
    if (rect.width <= 0 || rect.height <= 0) continue;
    if (
      rect.right <= 0 ||
      rect.bottom <= 0 ||
      rect.left >= window.innerWidth ||
      rect.top >= window.innerHeight
    ) {
      continue;
    }
    return candidate;
  }
  return null;
}

function relationshipDepthAnchorGeometry(
  identityKey: string,
  source: HTMLElement | null,
  destination: HTMLElement | null,
): RelationshipDepthAnchorGeometry | null {
  if (!source || !destination) return null;
  const sourceRect = source.getBoundingClientRect();
  const destinationRect = destination.getBoundingClientRect();
  return {
    identityKey,
    viewport: { width: window.innerWidth, height: window.innerHeight },
    source: {
      left: sourceRect.left,
      top: sourceRect.top,
      width: sourceRect.width,
      height: sourceRect.height,
    },
    destination: {
      left: destinationRect.left,
      top: destinationRect.top,
      width: destinationRect.width,
      height: destinationRect.height,
    },
  };
}

function waitForRelationshipDepthBeat(delayMs: number): Promise<void> {
  return new Promise((resolve) => window.setTimeout(resolve, delayMs));
}

