  function scheduleApiKeyDraftValidation(
    provider: ApiKeyValidationProvider,
    value: string,
  ): () => void {
    const trimmed = value.trim();
    if (panel !== "settings" || !trimmed) {
      setApiKeyDraftValidation((previous) => {
        const current = previous[provider];
        if (
          current.value === "" &&
          current.status === "idle" &&
          current.detail === null
        ) {
          return previous;
        }
        return {
          ...previous,
          [provider]: { value: "", status: "idle", detail: null },
        };
      });
      return () => {};
    }

    setApiKeyDraftValidation((previous) => {
      const current = previous[provider];
      if (current.value === trimmed && current.status === "checking")
        return previous;
      return {
        ...previous,
        [provider]: { value: trimmed, status: "checking", detail: null },
      };
    });

    const controller = new AbortController();
    const timerId = window.setTimeout(() => {
      void api<ApiKeyStatusResponse>("/api/settings/api-key-status", {
        method: "POST",
        body: JSON.stringify({ provider, apiKey: trimmed }),
        signal: controller.signal,
      })
        .then((result) => {
          setApiKeyDraftValidation((previous) => {
            if (previous[provider].value !== trimmed) return previous;
            return {
              ...previous,
              [provider]: {
                value: trimmed,
                status: result.status.reachable ? "connected" : "error",
                detail: result.status.detail ?? null,
              },
            };
          });
        })
        .catch((err) => {
          if (isAbortLikeError(err)) return;
          setApiKeyDraftValidation((previous) => {
            if (previous[provider].value !== trimmed) return previous;
            return {
              ...previous,
              [provider]: {
                value: trimmed,
                status: "error",
                detail:
                  err instanceof Error ? err.message : "Validation failed.",
              },
            };
          });
        });
    }, 260);

    return () => {
      window.clearTimeout(timerId);
      controller.abort();
    };
  }
  useEffect(
    () => scheduleApiKeyDraftValidation("openai", openAiKey),
    [panel, openAiKey],
  );
  useEffect(
    () => scheduleApiKeyDraftValidation("anthropic", anthropicKey),
    [panel, anthropicKey],
  );
  useEffect(
    () => scheduleApiKeyDraftValidation("elevenlabs", elevenLabsKey),
    [panel, elevenLabsKey],
  );
  useEffect(
    () => scheduleApiKeyDraftValidation("brave", braveSearchKey),
    [panel, braveSearchKey],
  );
  const refreshUsageReport = useCallback(
    async (
      range: UsageRange = usageRange,
      scope: "all" | "conversation" = usageScope,
    ): Promise<void> => {
      const query = new URLSearchParams({ range });
      if (scope === "conversation" && selectedId) {
        query.set("conversationId", selectedId);
      }
      startTransition(() => {
        setUsageLoading(true);
      });
      try {
        const report = await api<UsageResponse>(
          `/api/usage?${query.toString()}`,
        );
        startTransition(() => {
          setUsageReport(report);
          setUsageLoading(false);
        });
      } catch (err) {
        startTransition(() => {
          setPanelError(
            err instanceof Error ? err.message : "Failed to load usage.",
          );
          setUsageLoading(false);
        });
      }
    },
    [selectedId, usageRange, usageScope],
  );
  useEffect(() => {
    if (panel !== "usage") return;
    void refreshUsageReport();
  }, [panel, refreshUsageReport]);
  useEffect(() => {
    if (!selectedId && usageScope === "conversation") {
      setUsageScope("all");
    }
  }, [selectedId, usageScope]);
  function exportUsageCsv(): void {
    if (!usageReport) return;
    const blob = new Blob([`\ufeff${buildUsageCsv(usageReport)}`], {
      type: "text/csv;charset=utf-8",
    });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = usageExportFileName(usageReport);
    anchor.click();
    URL.revokeObjectURL(url);
  }
  selectedIdRef.current = selectedId;
  detailIdRef.current = detail?.id ?? null;
  // Drill-in target for the high-count Prism color dashboard. Null at
