  useLayoutEffect(() => {
    if (typeof window === "undefined") return;

    let frame: number | null = null;
    const syncAppShellTopNavHeight = () => {
      const header = chatHeaderRef.current;
      const shell = header?.parentElement;
      if (!header || !shell) return;
      shell.style.setProperty(
        "--app-shell-top-nav-height",
        appShellTopNavHeightCssValue(header.getBoundingClientRect().height),
      );
    };
    const scheduleMeasure = () => {
      if (frame !== null) return;
      frame = window.requestAnimationFrame(() => {
        frame = null;
        syncAppShellTopNavHeight();
        if (viewportWidth <= PHONE_MENU_BREAKPOINT) {
          chatHeaderToolsWrapWidthRef.current = null;
          if (chatHeaderToolsWrapped) setChatHeaderToolsWrapped(false);
          return;
        }

        if (chatHeaderToolsWrapped) {
          const wrapWidth = chatHeaderToolsWrapWidthRef.current;
          if (wrapWidth !== null && viewportWidth >= wrapWidth + 32) {
            setChatHeaderToolsWrapped(false);
          }
          return;
        }

        const header = chatHeaderRef.current;
        const actions = chatHeaderInlineActionsRef.current;
        if (!header || !actions) return;

        const visibleChildren = Array.from(header.children).filter((child) => {
          const element = child as HTMLElement;
          return element.offsetParent !== null && element.offsetHeight > 0;
        }) as HTMLElement[];
        const firstRowTop = Math.min(
          ...visibleChildren.map((child) => child.offsetTop),
        );
        if (!Number.isFinite(firstRowTop)) return;

        if (actions.offsetTop > firstRowTop + 8) {
          chatHeaderToolsWrapWidthRef.current = viewportWidth;
          setChatHeaderToolsWrapped(true);
        }
      });
    };

    syncAppShellTopNavHeight();
    scheduleMeasure();
    const header = chatHeaderRef.current;
    const shell = header?.parentElement ?? null;
    const observer =
      header && typeof ResizeObserver !== "undefined"
        ? new ResizeObserver(scheduleMeasure)
        : null;
    if (header) observer?.observe(header);
    window.addEventListener("resize", scheduleMeasure);

    return () => {
      if (frame !== null) window.cancelAnimationFrame(frame);
      observer?.disconnect();
      window.removeEventListener("resize", scheduleMeasure);
      shell?.style.removeProperty("--app-shell-top-nav-height");
    };
  }, [chatHeaderToolsWrapped, sidebarOpen, view, viewportWidth]);
  useLayoutEffect(() => {
    if (
      !DEV_TOOLS_ENABLED ||
      !devToolsRuntimeActive ||
      typeof document === "undefined"
    ) {
      const defaultInsets = DEV_PANEL_SAFE_AREA_DEFAULT_INSETS;
      if (
        !devPanelSafeAreaInsetsEqual(
          devPanelSafeAreaInsetsRef.current,
          defaultInsets,
        )
      ) {
        devPanelSafeAreaInsetsRef.current = defaultInsets;
        setDevPanelSafeAreaInsets(defaultInsets);
      }
      return;
    }

    let frame: number | null = null;
    const resizeObserver =
      typeof ResizeObserver === "undefined"
        ? null
        : new ResizeObserver(() => scheduleMeasure());

    function observeSafeAreaNodes() {
      resizeObserver?.disconnect();
      document
        .querySelectorAll<HTMLElement>(`[${DEV_PANEL_SAFE_AREA_ATTRIBUTE}]`)
        .forEach((node) => resizeObserver?.observe(node));
    }

    function measure() {
      frame = null;
      const next = stableMeasuredDevPanelSafeAreaInsets(
        collectDevPanelSafeAreaInsets(viewportWidth, viewportHeight),
      );
      if (devPanelSafeAreaInsetsEqual(devPanelSafeAreaInsetsRef.current, next))
        return;
      devPanelSafeAreaInsetsRef.current = next;
      setDevPanelSafeAreaInsets(next);
    }

    function scheduleMeasure() {
      if (frame !== null) return;
      frame = window.requestAnimationFrame(measure);
    }

    observeSafeAreaNodes();
    scheduleMeasure();

    const mutationObserver =
      typeof MutationObserver === "undefined"
        ? null
        : new MutationObserver(() => {
            observeSafeAreaNodes();
            scheduleMeasure();
          });
    mutationObserver?.observe(document.body, {
      attributes: true,
      childList: true,
      subtree: true,
      attributeFilter: [
        "class",
        "style",
        DEV_PANEL_SAFE_AREA_ATTRIBUTE,
        "data-chat-sidebar-hidden",
        "data-chat-overflow-menu-open",
        "data-choice-composer-hidden",
        "data-session-active",
        "data-transcript-open",
      ],
    });
    window.addEventListener("resize", scheduleMeasure);
    window.addEventListener("transitionend", scheduleMeasure, true);

    return () => {
      if (frame !== null) window.cancelAnimationFrame(frame);
      resizeObserver?.disconnect();
      mutationObserver?.disconnect();
      window.removeEventListener("resize", scheduleMeasure);
      window.removeEventListener("transitionend", scheduleMeasure, true);
    };
  }, [devToolsRuntimeActive, viewportHeight, viewportWidth]);
