  const blockCoffeeConfigurationMutation = useCallback((): boolean => {
    if (!coffeeConfigurationLockedRef.current) return false;
    setPanelNotice(COFFEE_CONFIGURATION_LOCK_MESSAGE);
    setCoffeeError(COFFEE_CONFIGURATION_LOCK_MESSAGE);
    return true;
  }, []);
  useEffect(() => {
    const voiceSelection = voicePlaybackSelectionRef.current;
    if (!coffeeConversation) {
      const coffeeOwnedPlayback = coffeeVoiceConversationIdRef.current !== null;
      coffeeVoiceConversationIdRef.current = null;
      coffeeVoiceSeenMessageIdsRef.current = new Set();
      coffeeVoicePlaybackBusyRef.current = false;
      coffeeActiveVoiceMessageIdRef.current = null;
      if (coffeeOwnedPlayback) stopAudioForStateExit();
      return;
    }
    const assistantMessages = coffeeConversation.messages.filter(
      (message) => message.role === "assistant",
    );
    const conversationChanged =
      coffeeVoiceConversationIdRef.current !== coffeeConversation.id;
    if (conversationChanged) {
      coffeeVoiceConversationIdRef.current = coffeeConversation.id;
      const shouldSpeakLatest =
        (coffeeSessionPhase === "live" || coffeeSessionPhase === "arriving") &&
        assistantMessages.length > 0;
      coffeeVoiceSeenMessageIdsRef.current = new Set(
        (shouldSpeakLatest
          ? assistantMessages.slice(0, -1)
          : assistantMessages
        ).map((message) => message.id),
      );
    }
    // Normal live turns belong to queueCoffeeReveal, which keeps the audible
    // line, speaker, and table typewriter on one message. Same-session state
    // refreshes must not independently reclaim an older "unseen" line.
    if (!conversationChanged) return;
    const unseen = assistantMessages.filter(
      (message) => !coffeeVoiceSeenMessageIdsRef.current.has(message.id),
    );
    unseen.forEach((message) =>
      coffeeVoiceSeenMessageIdsRef.current.add(message.id),
    );
    if (unseen.length === 0 || !settings || voiceSelection.voiceMode === "mute")
      return;

    const controller = new AbortController();
    voiceSynthesisAbortRef.current?.abort();
    voiceSynthesisAbortRef.current = controller;
    coffeeVoicePlaybackBusyRef.current = true;
    coffeeActiveVoiceMessageIdRef.current = unseen[0]?.id ?? null;
    void (async () => {
      try {
        await prepareVoiceModePlayback(voiceSelection.voiceMode);
        for (const message of unseen) {
          if (controller.signal.aborted) return;
          if (prismPresentationSuspendedRef.current) return;
          const synthesisSource = coffeeBotVoiceSynthesisSource(message);
          if (!synthesisSource) continue;
          const bot = message.botId
            ? bots.find((candidate) => candidate.id === message.botId)
            : null;
          const messageIndex = coffeeConversation.messages.findIndex(
            (candidate) => candidate.id === message.id,
          );
          const identityMirrorState = bot
            ? coffeeIdentityMirrorStateBeforeMessage(
                coffeeConversation.messages,
                messageIndex,
                bot.id,
              )
            : null;
          const powerVoiceVolume =
            settings.voiceVolume *
            (bot
              ? coffeePowerPlan
                ? botPowerVoiceGainMultiplierFromEffectsV1(
                    coffeePowerPlan.bots[bot.id]?.effects,
                  )
                : botPowerVoiceGainMultiplierV1(bot.powers)
              : 1);
          const profile = bot
            ? coffeeBorrowedIdentityVoiceBeforeMessage(
                coffeeConversation.messages,
                messageIndex,
                bot.id,
                bot.authored_audio_voice_profile,
                bot.audio_voice_profile_override,
              )
            : resolveBotIdentityMirrorVoiceV1(identityMirrorState, null, null);
          if (!profile.enabled || settings.voiceVolume <= 0) continue;
          const preSpeechBreath = resolvePreSpeechBreathPlan({
            seed: message.id,
            text: synthesisSource.spokenText,
            surface: "coffee",
            mood: message.moodKey,
            enabled: settings.voiceEffectsEnabled !== false,
          });
          coffeeActiveVoiceMessageIdRef.current = message.id;
          if (
            voiceSelection.voiceMode === "bottish" ||
            voiceSelection.voiceMode === "babble"
          ) {
            await enqueueRobotVoiceMode({
              mode: voiceSelection.voiceMode,
              source: { ...synthesisSource },
              sourceText: synthesisSource.spokenText,
              profile,
              seed: message.id,
              signal: controller.signal,
              effectsEnabled: settings.voiceEffectsEnabled !== false,
              globalVolume: powerVoiceVolume,
              namePronunciations: bots,
              speakerBotId: bot?.id,
              moodKey: message.moodKey,
              prepare: false,
              preSpeechBreath,
            });
          } else {
            const response = await fetch(
              new URL("/api/voices/synthesize", window.location.origin),
              {
                method: "POST",
                credentials: "include",
                signal: controller.signal,
                headers: {
                  "content-type": "application/json",
                  ...authHeadersForFetch(),
                },
                body: JSON.stringify({
                  ...synthesisSource,
                  mode: "english",
                  engine: voiceSelection.englishVoiceEngine,
                  explicitOnlineContext: true,
                  moodKey: message.moodKey,
                  profile,
                }),
              },
            );
            if (!response.ok)
              throw new Error(`Voice playback failed (${response.status}).`);
            const engineUsed = response.headers.get("x-prism-voice-engine");
            if (engineUsed === "builtin-local-fallback") {
              setVoicePlaybackNotice("PRISM Voice Pack used for LOCAL mode.");
            } else if (engineUsed === "builtin-provider-fallback") {
              setVoicePlaybackNotice(
                "ElevenLabs was unavailable, so Prism used its local voice pack.",
              );
            }
            const clip = await readEnglishVoiceSynthesisClip(response);
            await enqueueEnglishVoice(
              clip.bytes,
              profile,
              message.id,
              settings.voiceEffectsEnabled !== false,
              powerVoiceVolume,
              undefined,
              clip.engineUsed,
              message.moodKey,
              undefined,
              preSpeechBreath,
            );
          }
        }
      } catch (err) {
        if (!isAbortLikeError(err)) {
          setVoicePlaybackNotice(
            err instanceof Error
              ? err.message
              : "Coffee voice playback failed.",
          );
        }
      } finally {
        if (voiceSynthesisAbortRef.current === controller) {
          coffeeActiveVoiceMessageIdRef.current = null;
          coffeeVoicePlaybackBusyRef.current = false;
          voiceSynthesisAbortRef.current = null;
        }
      }
    })();
    return () => {
      controller.abort();
      if (voiceSynthesisAbortRef.current === controller) {
        coffeeActiveVoiceMessageIdRef.current = null;
        coffeeVoicePlaybackBusyRef.current = false;
        voiceSynthesisAbortRef.current = null;
      }
    };
  }, [
    bots,
    coffeeConversation,
    coffeeSessionPhase,
    settings?.voiceEffectsEnabled,
    settings?.voiceVolume,
    stopAudioForStateExit,
  ]);
  /** Scenario for arrival animation — held while the user picks a starter topic. */
