  const requestBotcastEnglishClip = useCallback(
    async (
      message: BotcastMessage,
      profile: BotAudioVoiceProfileV1,
      signalOnlineVoiceEnabled: boolean,
      selectedEngine: EnglishVoiceEngine,
      signal?: AbortSignal,
      playbackSurface: "signal" | "debate" = "signal",
    ): Promise<BotcastEnglishVoiceMedia> => {
      const ephemeralSoundcheck =
        signalStageSoundcheckMessageIsEphemeral(message);
      const ephemeralInterruptionBridge =
        botcastMessageIsEphemeralInterruptionBridge(message);
      const performanceText = message.voicePerformanceText ?? message.content;
      const useLocalPerformanceStream = voicePerformancePlanFromText(
        performanceText,
      ).segments.some((segment) => segment.kind === "vocal-action");
      const premiumAlignmentRequested =
        signalOnlineVoiceEnabled &&
        selectedEngine === "elevenlabs" &&
        !useLocalPerformanceStream;
      const response = await fetch(
        new URL("/api/voices/synthesize", window.location.origin),
        {
          method: "POST",
          credentials: "include",
          signal,
          headers: {
            "content-type": "application/json",
            ...authHeadersForFetch(),
          },
          body: JSON.stringify({
            text: voiceSpokenText(message.content),
            speakerBotId: message.botId,
            ...(!ephemeralSoundcheck &&
            !ephemeralInterruptionBridge &&
            playbackSurface === "signal"
              ? { signalMessageId: message.id }
              : {}),
            ...(ephemeralInterruptionBridge
              ? {
                  signalEpisodeId: message.episodeId,
                  signalInterruptionBridge: true,
                }
              : {}),
            ...(ephemeralSoundcheck ? { explicitVoicePreview: true } : {}),
            ...(signalOnlineVoiceEnabled && message.voicePerformanceText
              ? {
                  elevenLabsText: message.voicePerformanceText,
                }
              : {}),
            performanceText,
            mode: "english",
            engine: signalOnlineVoiceEnabled ? selectedEngine : "builtin",
            explicitOnlineContext: signalOnlineVoiceEnabled,
            includeAlignment: premiumAlignmentRequested,
            // Premium keeps its exact timestamped clip when available. Every
            // local path, including Premium recovery, may instead return the
            // sentence-chunk stream so long statements cannot hit the local
            // voice model's single-clip token ceiling.
            streamChunks: true,
            moodKey: message.moodKey,
            profile,
          }),
        },
      );
      if (!response.ok) {
        throw new Error(`Signal voice playback failed (${response.status}).`);
      }
      if (englishVoiceResponseSupportsChunkedStreaming(response)) {
        const rawNotice = response.headers.get("x-prism-voice-notice");
        return {
          kind: "stream",
          response,
          engineUsed: response.headers.get("x-prism-voice-engine"),
          modelHash: response.headers.get("x-prism-voice-model-sha256"),
          notice: rawNotice ? decodeURIComponent(rawNotice) : null,
          resolvedPronunciation: readEnglishVoiceResolvedPronunciation(
            response.headers,
          ),
          resolvedSpeechprint: readEnglishVoiceResolvedSpeechprint(
            response.headers,
          ),
        };
      }
      return {
        kind: "clip",
        clip: await readEnglishVoiceSynthesisClip(response),
      };
    },
    [],
  );
