      if (chatModeSmoothScrollIsActive(conversationId)) return;

      const maxScrollTop = resolveZenReadableMaxScrollTop(scrollEl);
      const activeAssistantRow =
        latestMessageRole === "assistant" && latestAssistantMessageId
          ? findMessageRowById(scrollEl, latestAssistantMessageId)
          : null;
      const activeUserRow =
        !activeAssistantRow && latestUserMessageId
          ? findMessageRowById(scrollEl, latestUserMessageId)
          : null;
