  const appendDevChatDebugLines = useCallback(
    (
      entries: Array<{
        kind: DevChatDebugEvent["kind"];
        text: string;
      }>,
    ) => {
      if (!devChatMetricsTerminalActive || entries.length === 0) return;
      const createdAt = new Date().toISOString();
      const nextEvents = entries.map((entry, index) => ({
        id: `dev-metric-${createdAt}-${index}-${Math.random().toString(36).slice(2, 9)}`,
        createdAt,
        kind: entry.kind,
        text: entry.text,
      }));
      setDevChatDebugEvents((current) => [
        ...current.slice(-60),
        ...nextEvents,
      ]);
    },
    [devChatMetricsTerminalActive],
  );

  function collectDebugLinesFromEnvelope(
    envelope: ChatPostEnvelope,
    source: "send" | "edit",
  ): Array<{ kind: DevChatDebugEvent["kind"]; text: string }> {
    const lines: Array<{ kind: DevChatDebugEvent["kind"]; text: string }> = [];
    const prefix = source === "edit" ? "[edit]" : "[send]";
    for (const event of envelope.backendEvents ?? []) {
      lines.push({
        kind: devDebugKindForBackendEvent(event.kind),
        text: formatBackendDebugLine(prefix, event),
      });
    }
    if (envelope.summaryCompaction?.triggered) {
      const summaryPreview = envelope.summaryCompaction.latestSummary?.trim();
      lines.push({
        kind: "summary",
        text: `${prefix} summary (${envelope.summaryCompaction.mode}, ${envelope.summaryCompaction.reason}) triggered.`,
      });
      if (summaryPreview && summaryPreview.length > 0) {
        lines.push({
          kind: "summary",
          text: `${prefix} summary text: ${summaryPreview}`,
        });
      }
    }
    const createdMemories = envelope.memoryLearned?.created ?? [];
    const retractedMemories = envelope.memoryLearned?.retracted ?? [];
    const rejectedMemories = envelope.memoryLearned?.rejected ?? [];
    if (createdMemories.length > 0) {
      lines.push({
        kind: "memory",
        text: `${prefix} memories created (${createdMemories.length}): ${createdMemories
          .map((memory) => memory.text)
          .join(" | ")}`,
      });
    }
    if (retractedMemories.length > 0) {
      lines.push({
        kind: "memory",
        text: `${prefix} memories retracted (${retractedMemories.length}): ${retractedMemories
          .map((memory) => memory.text)
          .join(" | ")}`,
      });
    }
    if (rejectedMemories.length > 0) {
      lines.push({
        kind: "memory",
        text: `${prefix} memories rejected (${rejectedMemories.length}).`,
      });
    }
    if (envelope.opinion) {
      lines.push({
        kind: "opinion",
        text: `${prefix} session opinion: ${envelope.opinion.band} ${envelope.opinion.score}% (${envelope.opinion.trend})`,
      });
    }
    if (envelope.botOpinion) {
      lines.push({
        kind: "opinion",
        text: `${prefix} bot opinion: ${envelope.botOpinion.band} ${envelope.botOpinion.score}% (${envelope.botOpinion.trend})`,
      });
    }
    if (envelope.autoRecovery) {
      const recovery = envelope.autoRecovery;
      lines.push({
        kind: "summary",
        text:
          `${prefix} Auto recovered with ${recovery.finalProvider}:${recovery.finalModel}. ` +
          recovery.attempts
            .map(
              (attempt) =>
                `${attempt.provider}:${attempt.model}=${attempt.outcome}${attempt.reason ? `(${attempt.reason})` : ""}`,
            )
            .join(" -> "),
      });
    }
    if (
      envelope.psychicDebug &&
      psychicTextEnabledForConversation(envelope.conversation, {
        productChatSurface: isChatSurfaceView(view),
      })
    ) {
      const debug = envelope.psychicDebug;
      lines.push({
        kind: "summary",
        text:
          `${prefix} psychic ${debug.simulated ? "simulated effort" : "summary"} ` +
          `(${debug.provider}${debug.model ? `:${debug.model}` : ""}, effort=${debug.effort}): ` +
          debug.summary,
      });
      if (
        typeof debug.passCount === "number" ||
        typeof debug.guidanceChars === "number"
      ) {
        lines.push({
          kind: "summary",
          text:
            `${prefix} psychic diagnostics: passes=${debug.passCount ?? 0}; ` +
            `guidance=${debug.guidanceChars ?? 0} chars`,
        });
      }
      for (const pass of debug.passes ?? []) {
        lines.push({
          kind: "summary",
          text:
            `${prefix} psychic pass ${pass.name}: ${pass.chars} chars` +
            (pass.warning ? `; warning=${pass.warning}` : ""),
        });
      }
      if (debug.scratchpad.trim().length > 0) {
        lines.push({
          kind: "summary",
          text: `${prefix} psychic scratchpad: ${debug.scratchpad}`,
        });
      }
    }
    const toolCallEvents = envelope.toolCalls ?? [];
    for (const event of toolCallEvents) {
      lines.push({
        kind: "tool",
        text: formatChatToolCallDebugLine(prefix, event),
      });
    }
    if (envelope.pendingImageJob) {
      lines.push({
        kind: "tool",
        text:
          `${prefix} tool sendGeneratedImage queued — pending image job ` +
          `${envelope.pendingImageJob.jobId} ` +
          `(conversation ${envelope.pendingImageJob.conversationId ?? "incognito"})`,
      });
    }
    return lines;
  }
  async function refreshBots(): Promise<Bot[]> {
    const d = await api<{ bots: Bot[] }>("/api/bots");
    botLibraryGroupsCanPruneRef.current = true;
    setBots(d.bots);
    return d.bots;
  }
  async function refreshImages(botFilter?: string | null) {
    const path =
      botFilter === "general"
        ? "/api/images?general=1"
        : typeof botFilter === "string" && botFilter.length > 0
          ? `/api/images?botId=${encodeURIComponent(botFilter)}`
          : "/api/images";
    const filtered =
      botFilter === "general" ||
      (typeof botFilter === "string" && botFilter.length > 0);
    const d = await api<{ images: ImageRecord[] }>(path);
    setImages(d.images);
    if (!filtered) {
      setImageBotDirectorySnapshot(d.images);
    }
  }

  /** Zen mode: never load the global multi-bot mix into the Images grid. */
  async function refreshImagesChatGallery(): Promise<void> {
    if (chatScopedGalleryBotId) {
      await refreshImages(chatScopedGalleryBotId);
      return;
    }
    await refreshImages("general");
  }

  /**
   * Chat startup uses one authenticated local read for both its scoped gallery
   * and group-canvas bubbles. This replaces the former filtered startup read;
   * it does not contact an image provider or load legacy remote image URLs.
   */
  async function refreshImagesChatCanvasDirectory(): Promise<void> {
    const d = await api<{ images: ImageRecord[] }>("/api/images?limit=200");
    setImageBotDirectorySnapshot(d.images);
    setImages(
      chatScopedGalleryBotId
        ? d.images.filter((img) =>
            imageLibraryOwnerBotIds(img).includes(chatScopedGalleryBotId),
          )
        : d.images.filter((img) => imageLibraryOwnerBotIds(img).length === 0),
    );
  }

  /** Refreshes bot tallies for the Images dropdown without changing the filtered grid. */
  async function refreshImageBotDirectorySnapshot(): Promise<void> {
    try {
      const d = await api<{ images: ImageRecord[] }>("/api/images?limit=200");
      setImageBotDirectorySnapshot(d.images);
    } catch {
      /* Errors surface via other panel flows; directory tallies are best-effort. */
    }
  }

  async function refreshImageCleanupRecoveries(): Promise<void> {
    const response = await api<{
      recoveries: ImageAssetCleanupRecoverySummary[];
    }>("/api/images/cleanup-recovery");
    setImageCleanupRecoveries(response.recoveries);
  }

  async function previewUnusedImageAssets(): Promise<void> {
    if (imageCleanupPreviewLoading) return;
    setImageCleanupPreviewOpen(true);
    setImageCleanupConfirmOpen(false);
    setImageCleanupPreviewLoading(true);
    setImageCleanupPreviewError(null);
    setImageCleanupSelectedIds(new Set());
    setImageCleanupResult(null);
    setImageCleanupPreview(null);
    try {
      const result = await api<{
        ok: boolean;
        preview: ImageAssetCleanupPreview;
      }>("/api/images/cleanup-preview");
      setImageCleanupPreview(result.preview);
      setImageCleanupSelectedIds(
        new Set(result.preview.candidates.map((candidate) => candidate.id)),
      );
      try {
        await refreshImageCleanupRecoveries();
      } catch {
        setImageCleanupRecoveries([]);
      }
    } catch (error) {
      setImageCleanupPreviewError(
        error instanceof Error
          ? error.message
          : "Could not audit generated assets.",
      );
    } finally {
      setImageCleanupPreviewLoading(false);
    }
  }

  async function cleanupSelectedImageAssets(): Promise<void> {
    const preview = imageCleanupPreview;
    const imageIds =
      preview?.candidates
        .map((candidate) => candidate.id)
        .filter((imageId) => imageCleanupSelectedIds.has(imageId)) ?? [];
    if (!preview || imageIds.length === 0 || imageCleanupBusy) return;
    setImageCleanupBusy(true);
    setImageCleanupPreviewError(null);
    try {
      const response = await api<{
        ok: boolean;
        result: ImageAssetCleanupResult;
      }>("/api/images/cleanup", {
        method: "POST",
        body: JSON.stringify({
          snapshot: preview.snapshot,
          imageIds,
          permanent: true,
        }),
      });
      setImageCleanupPreview(response.result.preview);
      setImageCleanupResult(response.result);
      setImageCleanupSelectedIds(
        new Set(
          response.result.preview.candidates.map((candidate) => candidate.id),
        ),
      );
      setImageCleanupConfirmOpen(false);
      try {
        await refreshImageCleanupRecoveries();
      } catch {
        setImageCleanupRecoveries([]);
      }
      try {
        if (imagePanelScope === "general") {
          await refreshImages("general");
        } else if (imagePanelScope === "bot" && imagePanelBotId) {
          await refreshImages(imagePanelBotId);
        } else if (view === "chat") {
          await refreshImagesChatGallery();
        } else {
          await refreshImages(null);
        }
        await refreshImageBotDirectorySnapshot();
      } catch {
        setPanelNotice(
          "Cleanup finished. The image grid will refresh the next time it opens.",
        );
      }
    } catch (error) {
      setImageCleanupConfirmOpen(false);
      setImageCleanupPreviewError(
        error instanceof Error
          ? error.message
          : "Could not permanently delete the selected assets.",
      );
    } finally {
      setImageCleanupBusy(false);
    }
  }

  async function restoreImageCleanupRecovery(
    recoveryId: string,
  ): Promise<void> {
    if (imageCleanupBusy) return;
    setImageCleanupBusy(true);
    setImageCleanupPreviewError(null);
    try {
      const response = await api<{
        result: { restoredCount: number };
      }>(
        `/api/images/cleanup-recovery/${encodeURIComponent(recoveryId)}/restore`,
        { method: "POST", body: "{}" },
      );
      setImageCleanupResult(null);
      setPanelNotice(
        `Restored ${response.result.restoredCount} asset${response.result.restoredCount === 1 ? "" : "s"} to the Image Library.`,
      );
      await refreshImageCleanupRecoveries();
      await previewUnusedImageAssets();
      await refreshImages(null);
    } catch (error) {
      setImageCleanupPreviewError(
        error instanceof Error
          ? error.message
          : "Could not restore recovery batch.",
      );
    } finally {
      setImageCleanupBusy(false);
    }
  }

  async function permanentlyDeleteImageCleanupRecovery(
    recoveryId: string,
  ): Promise<void> {
    if (imageCleanupBusy) return;
    if (
      !window.confirm(
        "Permanently delete this recovery batch? Its image files and metadata cannot be restored afterward.",
      )
    ) {
      return;
    }
    setImageCleanupBusy(true);
    setImageCleanupPreviewError(null);
    try {
      await api(
        `/api/images/cleanup-recovery/${encodeURIComponent(recoveryId)}`,
        {
          method: "DELETE",
          body: JSON.stringify({ confirm: "permanently-delete" }),
        },
      );
      await refreshImageCleanupRecoveries();
      setPanelNotice("Recovery batch permanently deleted.");
    } catch (error) {
      setImageCleanupPreviewError(
        error instanceof Error
          ? error.message
          : "Could not permanently delete recovery batch.",
      );
    } finally {
      setImageCleanupBusy(false);
    }
  }

  async function deleteGalleryImage(img: ImageRecord) {
    setPanelError(null);
    setPanelNotice(null);
    try {
      await api(`/api/images/${encodeURIComponent(img.id)}`, {
        method: "DELETE",
      });
      setImagePrivateGeneratedIds((current) =>
        current.filter((id) => id !== img.id),
      );
      setImagePrivateRevealedIds((current) => {
        if (!current.has(img.id)) return current;
        const next = new Set(current);
        next.delete(img.id);
        return next;
      });
      setImageLightbox((current) => (current?.id === img.id ? null : current));
      setBotGroupFailedWallpaperImageIds((current) => {
        if (current.has(img.id)) return current;
        const next = new Set(current);
        next.add(img.id);
        return next;
      });
      if (imagePanelScope === "general") {
        await refreshImages("general");
      } else if (imagePanelScope === "bot" && imagePanelBotId) {
        await refreshImages(imagePanelBotId);
      } else if (view === "chat") {
        await refreshImagesChatGallery();
      } else {
        await refreshImages(null);
      }
      await refreshImageBotDirectorySnapshot();
    } catch (err) {
      setPanelError(
        err instanceof Error ? err.message : "Could not delete image.",
      );
    }
  }

  async function deleteAllGalleryImages() {
    if (imagesDeleteAllBusy) return;
    setImagesDeleteAllBusy(true);
    setPanelError(null);
    setPanelNotice(null);
    try {
      const isBotScopedDelete =
        imagePanelScope === "bot" && imagePanelBotId != null;
      const endpoint = isBotScopedDelete
        ? `/api/images?botId=${encodeURIComponent(imagePanelBotId)}`
        : "/api/images";
      const deletedImageIds = imageBotDirectorySnapshot
        .filter(
          (image) =>
            !isBotScopedDelete ||
            (imagePanelBotId != null &&
              imageLibraryOwnerBotIds(image, botLibraryGroups).includes(
                imagePanelBotId,
              )),
        )
        .map((image) => image.id);
      const result = await api<{ ok: boolean; deleted?: number }>(endpoint, {
        method: "DELETE",
      });
      setImagePrivateGeneratedIds([]);
      setImagePrivateRevealedIds(new Set());
      setImageLightbox(null);
      setBotGroupFailedWallpaperImageIds((current) => {
        if (deletedImageIds.every((imageId) => current.has(imageId))) {
          return current;
        }
        const next = new Set(current);
        for (const imageId of deletedImageIds) next.add(imageId);
        return next;
      });
      if (imagePanelScope === "general") {
        await refreshImages("general");
      } else if (imagePanelScope === "bot" && imagePanelBotId) {
        await refreshImages(imagePanelBotId);
      } else if (view === "chat") {
        await refreshImagesChatGallery();
      } else {
        await refreshImages(null);
      }
      await refreshImageBotDirectorySnapshot();
      const deleted = typeof result.deleted === "number" ? result.deleted : 0;
      setPanelNotice(
        deleted === 0
          ? "No images to delete."
          : deleted === 1
            ? "Deleted 1 image."
            : `Deleted ${deleted} images.`,
      );
    } catch (err) {
      setPanelError(
        err instanceof Error ? err.message : "Could not delete images.",
      );
    } finally {
      setImagesDeleteAllBusy(false);
      setImagesDeleteAllConfirmOpen(false);
    }
  }

  async function downloadGalleryImage(img: ImageRecord) {
    setPanelError(null);
    try {
      const ownerNames = imageLibraryOwnerBotIds(img, botLibraryGroups)
        .map((botId) => bots.find((bot) => bot.id === botId)?.name)
        .filter((name): name is string => Boolean(name));
      const botLabel =
        (ownerNames.length > 0 ? ownerNames.join("-") : null) ??
        (imagePanelScope === "bot" ? imagePanelBot?.name : null) ??
        "PRISM";
      await downloadBotImageFile(img, botLabel);
    } catch (err) {
      setPanelError(
        err instanceof Error ? err.message : "Could not download image.",
      );
    }
  }

