  async function completeAuth(
    normalizedUsername: string,
    isRegistering: boolean,
  ): Promise<boolean> {
    setBusy(true);
    setError(null);
    try {
      if (isRegistering) {
        await api("/api/auth/register", {
          method: "POST",
          body: JSON.stringify({
            username: normalizedUsername,
            password,
            theme: preAuthTheme,
            eulaAccepted: true,
            eulaVersion: PRISM_EULA_VERSION,
            minimumAgeConfirmed: true,
          }),
        });
      } else {
        await api("/api/auth/login", {
          method: "POST",
          body: JSON.stringify({ username: normalizedUsername, password }),
        });
      }
      clearNativeSessionToken();
      const bootstrappedUser = await bootstrap();
      if (isRegistering && bootstrappedUser?.id) {
        starterPackFreshAccountEligibleUserRef.current = bootstrappedUser.id;
      }
      setUsername(normalizedUsername);
      setPassword("");
      setConfirmPassword("");
      return true;
    } catch (err) {
      setError(err instanceof Error ? err.message : "Auth failed.");
      return false;
    } finally {
      setBusy(false);
    }
  }

  async function submitAuth(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    const normalizedUsername = normalizeAuthUsername(username);
    if (!normalizedUsername) {
      setError("Username is required.");
      return;
    }
    if (authMode === "register") {
      if (password !== confirmPassword) {
        setError("Passwords do not match.");
        return;
      }
      setEulaReviewOpen(true);
      return;
    }
    await completeAuth(normalizedUsername, false);
  }

  async function acceptEulaAndRegister(): Promise<void> {
    const normalizedUsername = normalizeAuthUsername(username);
    if (!normalizedUsername || password !== confirmPassword) {
      setEulaReviewOpen(false);
      setError(
        normalizedUsername
          ? "Passwords do not match."
          : "Username is required.",
      );
      return;
    }
    const registered = await completeAuth(normalizedUsername, true);
    if (registered) setEulaReviewOpen(false);
  }

  async function logout() {
    await api("/api/auth/logout", { method: "POST", body: "{}" });
    clearAuthenticatedSessionState();
  }

  function advanceLivingTutorialToStep(mode: TutorialMode, step: number): void {
    const safeStep = Math.max(
      0,
      Math.min(MODE_TUTORIALS[mode].steps.length - 1, Math.floor(step)),
    );
    const nextProgress: PrismTutorialProgress = {
      ...tutorialProgress,
      [mode]: { status: "pending", step: safeStep, remindAfter: null },
    };
    setTutorialProgress(nextProgress);
    setActiveTutorialStepIndex(safeStep);
    void persistLivingShellProgress({ tutorialProgress: nextProgress }, false);
  }

  function markTutorialComplete(
    mode: TutorialMode,
    status: "completed" | "skipped" = "completed",
  ): void {
    const nextProgress: PrismTutorialProgress = {
      ...tutorialProgress,
      [mode]: { status, step: 0, remindAfter: null },
    };
    setTutorialProgress(nextProgress);
    setActiveTutorialMode(null);
    setActiveTutorialStepIndex(0);
    void persistLivingShellProgress({ tutorialProgress: nextProgress }, false);
  }

  function remindAboutTutorialLater(mode: TutorialMode): void {
    const nextProgress: PrismTutorialProgress = {
      ...tutorialProgress,
      [mode]: {
        status: "remind",
        step: activeTutorialStepIndex,
        remindAfter: new Date(
          Date.now() + TUTORIAL_REMIND_LATER_MS,
        ).toISOString(),
      },
    };
    setTutorialProgress(nextProgress);
    setActiveTutorialMode(null);
    void persistLivingShellProgress({ tutorialProgress: nextProgress }, false);
  }

  function resetSingleModeTutorial(mode: TutorialMode): void {
    const nextProgress: PrismTutorialProgress = {
      ...tutorialProgress,
      [mode]: { status: "pending", step: 0, remindAfter: null },
      ...(mode === "botcast"
        ? {
            prismWield: {
              status: "pending" as const,
              step: 0,
              remindAfter: null,
            },
            signalRefract: {
              status: "pending" as const,
              step: 0,
              remindAfter: null,
            },
          }
        : {}),
    };
    setTutorialProgress(nextProgress);
    const currentMode: TutorialMode | null = botAvatarCustomizerOpen
      ? "avatar"
      : view === "chat"
        ? "zen"
        : view === "sandbox"
          ? "chat"
          : view === "coffee"
            ? "coffee"
            : view === "debate"
              ? "debate"
              : view === "botcast"
                ? "botcast"
                : view === "slate"
                  ? "slate"
                  : null;
    if (currentMode === mode) {
      setActiveTutorialMode(mode);
      setActiveTutorialStepIndex(0);
    }
    void persistLivingShellProgress({ tutorialProgress: nextProgress }, false);
    setPanelNotice(`${mode[0].toUpperCase()}${mode.slice(1)} tutorial reset.`);
  }

  async function saveSlateHemisphereSettings(
    config: SlateDeliberationConfig,
  ): Promise<void> {
    const snapshot = slateHemisphereSettingsSnapshot;
    if (!snapshot || slateHemisphereSettingsSaving) return;
    setSlateHemisphereSettingsSaving(true);
    setSlateHemisphereSettingsError(null);
    try {
      const response = await api<SlateProjectResponse>(
        `/api/slate/projects/${encodeURIComponent(snapshot.projectId)}`,
        {
          method: "PATCH",
          body: JSON.stringify({ deliberationConfig: config }),
        },
      );
      const nextConfig = response.project.deliberationConfig;
      setSlateHemisphereSettingsSnapshot((current) =>
        current?.projectId === response.project.id
          ? {
              ...current,
              projectTitle: response.project.title,
              proseMode: response.project.proseMode,
              config: nextConfig,
            }
          : current,
      );
      setSlateHemisphereSettingsUpdate({
        projectId: response.project.id,
        config: nextConfig,
        revision: Date.now(),
      });
    } catch (cause) {
      setSlateHemisphereSettingsError(
        cause instanceof Error
          ? cause.message
          : "Slate could not save those hemisphere settings.",
      );
    } finally {
      setSlateHemisphereSettingsSaving(false);
    }
  }

