  async function importAccountFromPrismFile(file: File): Promise<void> {
    if (file.size === 0 || file.size > ACCOUNT_BACKUP_ARCHIVE_MAX_BYTES) {
      throw new Error(".prism account backup archive is too large.");
    }
    const archiveBytes = new Uint8Array(await file.arrayBuffer());
    const entries = unzipAccountBackupEntries(archiveBytes);
    const preferredEntry = Object.entries(entries).find(
      ([name]) => name.trim().toLowerCase() === "backup.json",
    );
    const fallbackEntry = Object.entries(entries).find(([name]) =>
      name.trim().toLowerCase().endsWith(".json"),
    );
    const jsonEntry = preferredEntry ?? fallbackEntry;
    if (!jsonEntry) {
      throw new Error(".prism file does not contain a JSON backup payload.");
    }
    const backup = parseAccountBackupFromJson(strFromU8(jsonEntry[1]));
    await api("/api/backup/import", {
      method: "POST",
      headers: {
        ...authHeadersForFetch(),
        "content-type": ACCOUNT_BACKUP_ARCHIVE_CONTENT_TYPE,
      },
      body: bytesToArrayBuffer(archiveBytes),
    });
    await refreshAll({ includeModels: false });
    const failedAtmosphereAssetCount = await restoreAccountBotLibraryGroups(
      backup.botLibraryGroups,
      backup.botGroupRoomAtmosphereAssets,
    );
    restoreAccountCommandCenter(backup.commandCenter);
    restoreAccountAvatarInkTemplates(backup.avatarInkTemplates);
    const restoredLocalState = [
      backup.botLibraryGroups ? "bot groups" : null,
      backup.commandCenter ? "Prompt Center" : null,
      backup.avatarInkTemplates ? "saved avatar ink" : null,
    ].filter((label): label is string => Boolean(label));
    const roomAtmosphereWarning =
      failedAtmosphereAssetCount > 0
        ? ` ${failedAtmosphereAssetCount} room atmosphere image${failedAtmosphereAssetCount === 1 ? " was" : "s were"} unavailable; those rooms will use their member gradients.`
        : "";
    setPanelNotice(
      `${
        restoredLocalState.length > 0
          ? `Account backup imported, including ${restoredLocalState.join(" and ")}.`
          : "Account backup imported."
      }${roomAtmosphereWarning}`,
    );
  }

