  async function importBotFromArchiveBytes(
    archiveBytes: Uint8Array,
    options?: ImportBotOptions,
  ): Promise<ImportBotResult> {
    if (!options?.suppressPanelReset) {
      setPanelError(null);
      setPanelNotice(null);
    }
    const parsed = parsePrismBotArchive(archiveBytes);
    const preparedArchive = prepareBotArchivePayload(parsed);
    let createBody = await compileStaleArchivePowers(preparedArchive.body);
    if (options?.generateThinkingSfx) {
      try {
        const generatedProfile = await generateBotThinkingSfxProfile(
          normalizeBotAudioVoiceProfileV1(createBody.authoredAudioVoiceProfile),
          window.location.origin,
        );
        const importedOverride = normalizeOptionalBotAudioVoiceProfileV1(
          createBody.audioVoiceProfileOverride,
        );
        createBody = {
          ...createBody,
          authoredAudioVoiceProfile: generatedProfile,
          ...(importedOverride
            ? {
                audioVoiceProfileOverride: normalizeBotAudioVoiceProfileV1({
                  ...importedOverride,
                  avatarSfx: generatedProfile.avatarSfx,
                }),
              }
            : {}),
        };
      } catch (error) {
        const normalizedError =
          error instanceof Error
            ? error
            : new Error("ElevenLabs could not create the thinking loop.");
        if (!options.onThinkingSfxError) throw normalizedError;
        options.onThinkingSfxError(normalizedError);
      }
    }
    const importedBotHash = preparedArchive.importedBotHash;
    if (
      importedBotHash &&
      !options?.allowDuplicateHash &&
      bots.some(
        (candidate) =>
          normalizeImportedBotHash(candidate.export_hash) === importedBotHash,
      )
    ) {
      throw new Error("This bot is already in your library!");
    }
    const created = await api<{ bot?: { id?: string } }>("/api/bots", {
      method: "POST",
      body: JSON.stringify(createBody),
    });
    const createdBotId = created.bot?.id;
    if (!createdBotId) {
      throw new Error("Imported bot was created without an id.");
    }

    const importedName = preparedArchive.importedName;
    const memories = preparedArchive.memories;
    options?.onProgress?.({
      kind: "bot-created",
      importedName,
      restoredMemories: 0,
      totalMemories: memories.length,
    });
    let restored = 0;
    for (const memory of memories) {
      const text = memory.trim();
      if (!text) continue;
      await api("/api/memories/restore", {
        method: "POST",
        body: JSON.stringify({
          text,
          botId: createdBotId,
          source: "compiled",
          category: "general",
          sourceMessageIds: [],
        }),
      });
      restored += 1;
      options?.onProgress?.({
        kind: "memory-restored",
        importedName,
        restoredMemories: restored,
        totalMemories: memories.length,
      });
    }

    let refreshedBots: Bot[] | null = null;
    if (!options?.deferRefresh) {
      refreshedBots = await refreshBots();
      await refreshMemories();
      await refreshBotMemories(createdBotId);
    }
    if (options?.selectInChat !== false) {
      selectImportedBotInChatMode(createdBotId);
    }
    if (options?.openImportedBotInEditor) {
      const importedBot =
        refreshedBots?.find((bot) => bot.id === createdBotId) ?? null;
      if (importedBot) {
        openBotCustomizer(importedBot);
      }
    }
    if (!options?.suppressNotice) {
      setPanelNotice(
        restored > 0
          ? `${importedName} imported with ${restored} memories.`
          : `${importedName} imported.`,
      );
    }
    if (panelRef.current === "bots" && !options?.keepBotsPanelOpen) {
      closePanel();
    }
    return {
      botId: createdBotId,
      importedName,
      importedBotHash,
      restoredMemories: restored,
    };
  }

  async function compileStaleArchivePowers(
    body: Record<string, unknown>,
  ): Promise<Record<string, unknown>> {
    const powers = normalizeBotPowersV1(body.powers);
    if (
      !powers.some(
        (power) =>
          power.compileStatus === "draft" && power.name && power.intent,
      )
    ) {
      return body;
    }
    try {
      const result = await api<{ ok: true; powers: BotPowerV1[] }>(
        "/api/bot-powers/compile",
        {
          method: "POST",
          body: JSON.stringify({
            botName: typeof body.name === "string" ? body.name : "",
            systemPrompt:
              typeof body.systemPrompt === "string" ? body.systemPrompt : "",
            powers,
          }),
        },
      );
      return { ...body, powers: normalizeBotPowersV1(result.powers) };
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : "Local power compilation failed.";
      return {
        ...body,
        powers: powers.map((power) =>
          power.compileStatus === "draft"
            ? {
                ...power,
                compileStatus: "error" as const,
                compileError: message,
                compiled: null,
              }
            : power,
        ),
      };
    }
  }

  function parseBotGroupManifest(raw: string): BotGroupManifestV1 | null {
    try {
      const parsedUnknown = JSON.parse(raw) as unknown;
      if (
        !parsedUnknown ||
        typeof parsedUnknown !== "object" ||
        Array.isArray(parsedUnknown)
      ) {
        return null;
      }
      const manifest = parsedUnknown as Partial<BotGroupManifestV1>;
      if (manifest.schema !== "prism-bot-group-manifest-v1") return null;
      return manifest as BotGroupManifestV1;
    } catch {
      return null;
    }
  }

  async function importBotCollectionBundle(file: File): Promise<void> {
    setPanelError(null);
    setPanelNotice(null);
    updateBotTransferOverlay((current) => ({
      ...current,
      title: "Importing bot collection",
      subject: file.name,
      detail: "Reading collection file.",
      currentStepLabel: "Opening .bots file",
      totalSteps: null,
    }));
    const archiveBytes = new Uint8Array(await file.arrayBuffer());
    let entries: Record<string, Uint8Array>;
    try {
      updateBotTransferOverlay((current) => ({
        ...current,
        detail: "Unpacking bot collection.",
        currentStepLabel: "Reading bundled bots",
      }));
      await waitForBotTransferPaint();
      entries = unzipSync(archiveBytes);
    } catch {
      throw new Error("Could not read bot collection file.");
    }
    const allEntries = Object.entries(entries);
    const unsupportedEntries = allEntries.filter(([name]) => {
      const normalized = name.trim().toLowerCase();
      return !normalized.endsWith(".bot") && normalized !== "manifest.json";
    });
    if (unsupportedEntries.length > 0) {
      throw new Error("Bot collection contains unsupported files.");
    }
    const botEntries = allEntries.filter(([name]) =>
      name.trim().toLowerCase().endsWith(".bot"),
    );
    if (botEntries.length === 0) {
      throw new Error("Bot collection contains no .bot files.");
    }
    const manifestEntry = allEntries.find(([name]) =>
      name.trim().toLowerCase().endsWith("manifest.json"),
    );
    const manifest = manifestEntry
      ? parseBotGroupManifest(strFromU8(manifestEntry[1]))
      : null;
    const preparedEntries: PreparedBotCollectionImportEntry[] = [];
    let failedCount = 0;
    let totalMemoryEntries = 0;
    for (const [entryName, bytes] of botEntries) {
      try {
        const parsed = parsePrismBotArchive(bytes);
        // Validate the complete create payload before any duplicate can be
        // deleted during the later overwrite phase.
        prepareBotArchivePayload(parsed);
        const importedName = parsed.botJson.bot.name.trim() || entryName;
        const memoryCount = parsed.memories.length;
        totalMemoryEntries += memoryCount;
        preparedEntries.push({
          entryName,
          archiveBytes: bytes,
          parsed,
          importedName,
          memoryCount,
        });
      } catch (error) {
        const message =
          error instanceof Error ? error.message : "Invalid bot archive.";
        if (
          /(?:avatarDetails|avatar|accessory|unsupported files)/iu.test(message)
        ) {
          throw new Error(
            `Bot collection entry ${entryName} was rejected before import: ${message}`,
          );
        }
        failedCount += 1;
      }
    }
    if (preparedEntries.length === 0 && failedCount > 0) {
      throw new Error(
        "Bot collection import failed. None of the .bot files could be imported.",
      );
    }
    const totalWorkSteps =
      preparedEntries.reduce((sum, entry) => sum + 1 + entry.memoryCount, 0) +
      failedCount +
      1;
    let completedWorkSteps = failedCount;
    let completedMemorySteps = 0;
    updateBotTransferOverlay((current) => ({
      ...current,
      detail:
        totalMemoryEntries > 0
          ? `Found ${preparedEntries.length} bots and ${totalMemoryEntries} memories.`
          : `Found ${preparedEntries.length} bots.`,
      currentStepLabel: "Preparing import",
      completedSteps: completedWorkSteps,
      totalSteps: Math.max(1, totalWorkSteps),
      stats: {
        ...current.stats,
        totalBots: botEntries.length,
        completedBots: failedCount,
        totalMemories: totalMemoryEntries,
        completedMemories: 0,
        failed: failedCount,
      },
    }));
    await waitForBotTransferPaint();
    const botIdByHash = new Map<string, string>();
    for (const bot of bots) {
      const hash = normalizeImportedBotHash(bot.export_hash);
      if (hash) botIdByHash.set(hash, bot.id);
    }
    const importedBotIds: string[] = [];
    const importedBotIdByEntryName = new Map<string, string>();
    let importedCount = 0;
    let overwrittenCount = 0;
    let skippedCount = 0;
    let restoredTotal = 0;

    for (const entry of preparedEntries) {
      const identityHint = parseImportBotLoadingHint(entry.archiveBytes);
      const entryTotalSteps = 1 + entry.memoryCount;
      let entryCompletedSteps = 0;
      let entryRestoredMemories = 0;
      const completeRemainingEntrySteps = () => {
        const remaining = Math.max(0, entryTotalSteps - entryCompletedSteps);
        if (remaining === 0) return;
        completedWorkSteps += remaining;
        entryCompletedSteps += remaining;
      };
      try {
        updateBotTransferOverlay((current) => ({
          ...current,
          subject: entry.importedName,
          detail:
            entry.memoryCount > 0
              ? `Restoring ${entry.memoryCount} memories for ${entry.importedName}.`
              : `Importing ${entry.importedName}.`,
          currentStepLabel: `Importing ${entry.importedName}`,
          accentColor: identityHint.color,
          glyph: identityHint.glyph,
          stats: {
            ...current.stats,
            imported: importedCount,
            overwritten: overwrittenCount,
            skipped: skippedCount,
            failed: failedCount,
          },
        }));
        const importedHash = normalizeImportedBotHash(
          entry.parsed.botJson.botHash,
        );
        let allowDuplicateHash = false;
        if (importedHash && botIdByHash.has(importedHash)) {
          const shouldOverwrite = window.confirm(
            `${entry.importedName} already exists. Click OK to overwrite, or Cancel to skip it.`,
          );
          if (!shouldOverwrite) {
            skippedCount += 1;
            completeRemainingEntrySteps();
            updateBotTransferOverlay((current) => ({
              ...current,
              detail: `${entry.importedName} skipped.`,
              currentStepLabel: `${skippedCount} skipped`,
              completedSteps: Math.min(
                completedWorkSteps,
                current.totalSteps ?? completedWorkSteps,
              ),
              stats: {
                ...current.stats,
                completedBots: importedCount + skippedCount + failedCount,
                imported: importedCount,
                overwritten: overwrittenCount,
                skipped: skippedCount,
                failed: failedCount,
                completedMemories: completedMemorySteps,
              },
            }));
            continue;
          }
          const existingId = botIdByHash.get(importedHash);
          if (existingId) {
            updateBotTransferOverlay((current) => ({
              ...current,
              detail: `Replacing existing ${entry.importedName}.`,
              currentStepLabel: "Overwriting duplicate",
            }));
            await api(`/api/bots/${encodeURIComponent(existingId)}`, {
              method: "DELETE",
            });
          }
          botIdByHash.delete(importedHash);
          allowDuplicateHash = true;
          overwrittenCount += 1;
        }
        const result = await importBotFromArchiveBytes(entry.archiveBytes, {
          allowDuplicateHash,
          suppressNotice: true,
          suppressPanelReset: true,
          selectInChat: false,
          deferRefresh: true,
          onProgress: (event) => {
            if (event.kind === "bot-created" && entryCompletedSteps === 0) {
              entryCompletedSteps += 1;
              completedWorkSteps += 1;
            }
            if (event.kind === "memory-restored") {
              const memoryDelta = Math.max(
                0,
                event.restoredMemories - entryRestoredMemories,
              );
              entryRestoredMemories = event.restoredMemories;
              entryCompletedSteps += memoryDelta;
              completedWorkSteps += memoryDelta;
              completedMemorySteps += memoryDelta;
            }
            updateBotTransferOverlay((current) => ({
              ...current,
              subject: event.importedName,
              detail:
                event.totalMemories > 0
                  ? `${event.restoredMemories} of ${event.totalMemories} memories restored.`
                  : "Profile restored.",
              currentStepLabel:
                event.kind === "memory-restored"
                  ? `Restoring memories for ${event.importedName}`
                  : `Created ${event.importedName}`,
              completedSteps: Math.min(
                completedWorkSteps,
                current.totalSteps ?? completedWorkSteps,
              ),
              stats: {
                ...current.stats,
                completedMemories: completedMemorySteps,
                imported: importedCount,
                overwritten: overwrittenCount,
                skipped: skippedCount,
                failed: failedCount,
              },
            }));
          },
        });
        completeRemainingEntrySteps();
        importedCount += 1;
        restoredTotal += result.restoredMemories;
        importedBotIds.push(result.botId);
        importedBotIdByEntryName.set(
          entry.entryName.trim().toLowerCase(),
          result.botId,
        );
        if (result.importedBotHash) {
          botIdByHash.set(result.importedBotHash, result.botId);
        }
        updateBotTransferOverlay((current) => ({
          ...current,
          subject: result.importedName,
          detail:
            result.restoredMemories > 0
              ? `${result.importedName} imported with ${result.restoredMemories} memories.`
              : `${result.importedName} imported.`,
          currentStepLabel: `${importedCount} of ${preparedEntries.length} bots imported`,
          completedSteps: Math.min(
            completedWorkSteps,
            current.totalSteps ?? completedWorkSteps,
          ),
          stats: {
            ...current.stats,
            completedBots: importedCount + skippedCount + failedCount,
            completedMemories: completedMemorySteps,
            imported: importedCount,
            overwritten: overwrittenCount,
            skipped: skippedCount,
            failed: failedCount,
          },
        }));
      } catch {
        failedCount += 1;
        completeRemainingEntrySteps();
        updateBotTransferOverlay((current) => ({
          ...current,
          detail: `${entry.importedName} could not be imported.`,
          currentStepLabel: `${failedCount} failed`,
          completedSteps: Math.min(
            completedWorkSteps,
            current.totalSteps ?? completedWorkSteps,
          ),
          stats: {
            ...current.stats,
            completedBots: importedCount + skippedCount + failedCount,
            completedMemories: completedMemorySteps,
            imported: importedCount,
            overwritten: overwrittenCount,
            skipped: skippedCount,
            failed: failedCount,
          },
        }));
      }
    }

    if (manifest?.group?.name && importedBotIds.length > 0) {
      const manifestName = manifest.group.name.trim();
      const manifestDescription =
        typeof manifest.group.description === "string"
          ? manifest.group.description.trim()
          : "";
      const manifestBotIds =
        Array.isArray(manifest.group.botFileNames) &&
        manifest.group.botFileNames.length > 0
          ? manifest.group.botFileNames
              .map(
                (name) =>
                  importedBotIdByEntryName.get(
                    String(name).trim().toLowerCase(),
                  ) ?? null,
              )
              .filter((id): id is string => Boolean(id))
          : [];
      const targetBotIds =
        manifestBotIds.length > 0 ? manifestBotIds : importedBotIds;
      setBotLibraryGroups((current) => {
        const normalized = normalizeBotLibraryGroups(current);
        const existingIndex = normalized.findIndex(
          (group) =>
            group.name.trim().toLowerCase() === manifestName.toLowerCase(),
        );
        if (existingIndex >= 0) {
          const existing = normalized[existingIndex];
          const next = [...normalized];
          next[existingIndex] = {
            ...existing,
            description: manifestDescription || existing.description,
            botIds: Array.from(new Set([...existing.botIds, ...targetBotIds])),
            updatedAt: new Date().toISOString(),
          };
          return normalizeBotLibraryGroups(next);
        }
        return normalizeBotLibraryGroups([
          ...normalized,
          {
            id:
              typeof crypto !== "undefined" &&
              typeof crypto.randomUUID === "function"
                ? `group:${crypto.randomUUID()}`
                : `group:${Date.now().toString(36)}`,
            name: manifestName,
            description: manifestDescription,
            botIds: Array.from(new Set(targetBotIds)),
            deleteProtected: false,
            builtIn: false,
            createdAt: new Date().toISOString(),
            updatedAt: new Date().toISOString(),
          },
        ]);
      });
    }

    if (importedCount === 0 && failedCount > 0) {
      throw new Error(
        "Bot collection import failed. None of the .bot files could be imported.",
      );
    }
    if (importedBotIds.length > 0) {
      updateBotTransferOverlay((current) => ({
        ...current,
        subject: `${importedBotIds.length} imported`,
        detail: "Refreshing bot library and memories.",
        currentStepLabel: "Refreshing Prism",
        completedSteps: Math.min(
          completedWorkSteps,
          Math.max(0, (current.totalSteps ?? 1) - 1),
        ),
      }));
      await refreshBots();
      await refreshMemories();
      if (importedBotIds.length === 1) {
        await refreshBotMemories(importedBotIds[0]!);
      }
    }
    completedWorkSteps = Math.max(completedWorkSteps, totalWorkSteps);
    updateBotTransferOverlay((current) => ({
      ...current,
      detail: "Import complete.",
      currentStepLabel: "Complete",
      completedSteps: current.totalSteps ?? completedWorkSteps,
      stats: {
        ...current.stats,
        completedBots: importedCount + skippedCount + failedCount,
        completedMemories: completedMemorySteps,
        imported: importedCount,
        overwritten: overwrittenCount,
        skipped: skippedCount,
        failed: failedCount,
      },
    }));
    const summaryParts = [
      `${importedCount} imported`,
      `${overwrittenCount} overwritten`,
      `${skippedCount} skipped`,
      `${failedCount} failed`,
    ];
    if (restoredTotal > 0) {
      summaryParts.push(`${restoredTotal} memories restored`);
    }
    setPanelNotice(
      `Bot collection import complete: ${summaryParts.join(" · ")}.`,
    );
    if (importedBotIds.length === 1) {
      selectImportedBotInChatMode(importedBotIds[0]!);
    }
  }

  async function fetchMarketplaceBotBundle(
    entry: BotMarketplaceEntry,
    signal?: AbortSignal,
  ): Promise<Uint8Array> {
    const response = await fetch(entry.bundlePath, {
      cache: "no-store",
      signal,
    });
    if (!response.ok) {
      throw new Error(
        `Marketplace bundle unavailable for ${entry.name} (${response.status}).`,
      );
    }
    return new Uint8Array(await response.arrayBuffer());
  }

  function validateMarketplacePreparedBundle(
    prepared: BotMarketplacePreparedBundle,
  ): void {
    const parsed = parsePrismBotArchive(prepared.bytes);
    const parsedHash = normalizeImportedBotHash(parsed.botJson.botHash);
    if (parsedHash !== prepared.entry.botHash) {
      throw new Error(
        `${prepared.entry.name} marketplace bundle has the wrong bot hash.`,
      );
    }
    const parsedName = parsed.botJson.bot.name.trim();
    if (!parsedName) {
      throw new Error(
        `${prepared.entry.name} marketplace bundle is missing a bot name.`,
      );
    }
    if (!normalizeBotFaceFontId(parsed.botJson.bot.faceEyesFont)) {
      throw new Error(
        `${prepared.entry.name} marketplace bundle is missing a valid eye face font.`,
      );
    }
    if (!normalizeBotFaceFontId(parsed.botJson.bot.faceMouthFont)) {
      throw new Error(
        `${prepared.entry.name} marketplace bundle is missing a valid mouth face font.`,
      );
    }
    for (const [label, animation] of [
      ["eye", parsed.botJson.bot.faceEyeAnimation],
      ["mouth", parsed.botJson.bot.faceMouthAnimation],
    ] as const) {
      if (
        animation !== undefined &&
        animation !== null &&
        normalizeBotFaceGlyphAnimation(animation) === null
      ) {
        throw new Error(
          `${prepared.entry.name} marketplace bundle has an invalid ${label} animation.`,
        );
      }
    }
    if (
      parsed.botJson.bot.faceMouthCharacter !== undefined &&
      parsed.botJson.bot.faceMouthCharacter !== null &&
      normalizeBotFaceMouthCharacter(parsed.botJson.bot.faceMouthCharacter) ===
        null
    ) {
      throw new Error(
        `${prepared.entry.name} marketplace bundle has an invalid mouth character.`,
      );
    }
    if (
      parsed.botJson.bot.faceMouthCoffeePucker !== undefined &&
      typeof parsed.botJson.bot.faceMouthCoffeePucker !== "boolean"
    ) {
      throw new Error(
        `${prepared.entry.name} marketplace bundle has an invalid Coffee sip pucker preference.`,
      );
    }
    if (
      normalizeBotFaceFontWeight(parsed.botJson.bot.faceFontWeight) === null
    ) {
      throw new Error(
        `${prepared.entry.name} marketplace bundle is missing a valid face weight.`,
      );
    }
    if (
      parsed.botJson.bot.faceEyeScale !== undefined &&
      parsed.botJson.bot.faceEyeScale !== null &&
      normalizeBotFaceEyeScale(parsed.botJson.bot.faceEyeScale) === null
    ) {
      throw new Error(
        `${prepared.entry.name} marketplace bundle has an invalid eye scale.`,
      );
    }
    if (
      parsed.botJson.bot.faceEyeOffsetX !== undefined &&
      parsed.botJson.bot.faceEyeOffsetX !== null &&
      normalizeBotFaceEyeOffsetX(parsed.botJson.bot.faceEyeOffsetX) === null
    ) {
      throw new Error(
        `${prepared.entry.name} marketplace bundle has an invalid eye horizontal position.`,
      );
    }
    if (
      parsed.botJson.bot.faceEyeOffsetY !== undefined &&
      parsed.botJson.bot.faceEyeOffsetY !== null &&
      normalizeBotFaceEyeOffsetY(parsed.botJson.bot.faceEyeOffsetY) === null
    ) {
      throw new Error(
        `${prepared.entry.name} marketplace bundle has an invalid eye height.`,
      );
    }
    if (
      parsed.botJson.bot.faceEyeRotationDeg !== undefined &&
      parsed.botJson.bot.faceEyeRotationDeg !== null &&
      normalizeBotFaceEyeRotationDeg(parsed.botJson.bot.faceEyeRotationDeg) ===
        null
    ) {
      throw new Error(
        `${prepared.entry.name} marketplace bundle has an invalid eye rotation.`,
      );
    }
    if (
      parsed.botJson.bot.faceEyeCount !== undefined &&
      parsed.botJson.bot.faceEyeCount !== null &&
      normalizeBotFaceEyeCount(parsed.botJson.bot.faceEyeCount) === null
    ) {
      throw new Error(
        `${prepared.entry.name} marketplace bundle has an invalid custom eye count.`,
      );
    }
    if (
      parsed.botJson.bot.faceMouthScale !== undefined &&
      parsed.botJson.bot.faceMouthScale !== null &&
      normalizeBotFaceMouthScale(parsed.botJson.bot.faceMouthScale) === null
    ) {
      throw new Error(
        `${prepared.entry.name} marketplace bundle has an invalid mouth size.`,
      );
    }
    if (
      parsed.botJson.bot.faceMouthOffsetX !== undefined &&
      parsed.botJson.bot.faceMouthOffsetX !== null &&
      normalizeBotFaceMouthOffsetX(parsed.botJson.bot.faceMouthOffsetX) === null
    ) {
      throw new Error(
        `${prepared.entry.name} marketplace bundle has an invalid mouth horizontal position.`,
      );
    }
    if (
      parsed.botJson.bot.faceMouthOffsetY !== undefined &&
      parsed.botJson.bot.faceMouthOffsetY !== null &&
      normalizeBotFaceMouthOffsetY(parsed.botJson.bot.faceMouthOffsetY) === null
    ) {
      throw new Error(
        `${prepared.entry.name} marketplace bundle has an invalid mouth height.`,
      );
    }
    if (
      parsed.botJson.bot.faceMouthRotationDeg !== undefined &&
      parsed.botJson.bot.faceMouthRotationDeg !== null &&
      normalizeBotFaceMouthRotationDeg(
        parsed.botJson.bot.faceMouthRotationDeg,
      ) === null
    ) {
      throw new Error(
        `${prepared.entry.name} marketplace bundle has an invalid mouth rotation.`,
      );
    }
    if (
      parsed.botJson.bot.faceBlinkBar !== undefined &&
      parsed.botJson.bot.faceBlinkBar !== null &&
      normalizeBotFaceBlinkBar(parsed.botJson.bot.faceBlinkBar) === null
    ) {
      throw new Error(
        `${prepared.entry.name} marketplace bundle has an invalid blink bar.`,
      );
    }
    if (
      parsed.botJson.bot.faceBlinkScale !== undefined &&
      parsed.botJson.bot.faceBlinkScale !== null &&
      normalizeBotFaceBlinkScale(parsed.botJson.bot.faceBlinkScale) === null
    ) {
      throw new Error(
        `${prepared.entry.name} marketplace bundle has an invalid blink size.`,
      );
    }
    if (
      parsed.botJson.bot.faceBlinkOffsetX !== undefined &&
      parsed.botJson.bot.faceBlinkOffsetX !== null &&
      normalizeBotFaceBlinkOffsetX(parsed.botJson.bot.faceBlinkOffsetX) === null
    ) {
      throw new Error(
        `${prepared.entry.name} marketplace bundle has an invalid blink horizontal position.`,
      );
    }
    if (
      parsed.botJson.bot.faceBlinkOffsetY !== undefined &&
      parsed.botJson.bot.faceBlinkOffsetY !== null &&
      normalizeBotFaceBlinkOffsetY(parsed.botJson.bot.faceBlinkOffsetY) === null
    ) {
      throw new Error(
        `${prepared.entry.name} marketplace bundle has an invalid blink height.`,
      );
    }
    if (
      parsed.botJson.bot.faceBlinkRotationDeg !== undefined &&
      parsed.botJson.bot.faceBlinkRotationDeg !== null &&
      normalizeBotFaceBlinkRotationDeg(
        parsed.botJson.bot.faceBlinkRotationDeg,
      ) === null
    ) {
      throw new Error(
        `${prepared.entry.name} marketplace bundle has an invalid blink rotation.`,
      );
    }
    if (
      parsed.botJson.bot.faceThinkingFrames !== undefined &&
      parsed.botJson.bot.faceThinkingFrames !== null &&
      normalizeBotFaceThinkingFrames(parsed.botJson.bot.faceThinkingFrames) ===
        null
    ) {
      throw new Error(
        `${prepared.entry.name} marketplace bundle has invalid thinking frames.`,
      );
    }
  }

  async function updateMarketplaceBotFromArchiveBytes(
    botId: string,
    prepared: BotMarketplacePreparedBundle,
  ): Promise<{ importedName: string; thinkingSfxError: string | null }> {
    const parsed = parsePrismBotArchive(prepared.bytes);
    const archive = prepareBotArchivePayload(parsed);
    if (archive.importedBotHash !== prepared.entry.botHash) {
      throw new Error(
        `${prepared.entry.name} marketplace update has the wrong bot hash.`,
      );
    }
    // Marketplace bundles may author a new portable voice profile, but the
    // installed bot's account-local override is a user's choice and must win.
    let compiledArchiveBody = await compileStaleArchivePowers(archive.body);
    const installedOverride = normalizeOptionalBotAudioVoiceProfileV1(
      bots.find((bot) => bot.id === botId)?.audio_voice_profile_override,
    );
    let generatedThinkingSfx: BotAvatarSfxV1 | null = null;
    let thinkingSfxError: string | null = null;
    try {
      const generatedProfile = await generateBotThinkingSfxProfile(
        normalizeBotAudioVoiceProfileV1(
          compiledArchiveBody.authoredAudioVoiceProfile,
        ),
        window.location.origin,
      );
      generatedThinkingSfx = generatedProfile.avatarSfx ?? null;
      compiledArchiveBody = {
        ...compiledArchiveBody,
        authoredAudioVoiceProfile: generatedProfile,
      };
    } catch (error) {
      thinkingSfxError =
        error instanceof Error
          ? error.message
          : "ElevenLabs could not create the thinking loop.";
    }
    const {
      audioVoiceProfileOverride: _preservedUserOverride,
      ...marketplacePatch
    } = compiledArchiveBody;
    if (
      installedOverride &&
      !installedOverride.avatarSfx &&
      generatedThinkingSfx
    ) {
      marketplacePatch.audioVoiceProfileOverride =
        normalizeBotAudioVoiceProfileV1({
          ...installedOverride,
          avatarSfx: generatedThinkingSfx,
        });
    }
    const updated = await api<{ bot?: { id?: string } }>(
      `/api/bots/${encodeURIComponent(botId)}`,
      {
        method: "PATCH",
        // Marketplace profile/config is authoritative. Keep the existing bot
        // row so conversations, library groups, and user memories survive.
        body: JSON.stringify(marketplacePatch),
      },
    );
    if (!updated.bot?.id) {
      throw new Error(
        `${prepared.entry.name} marketplace update returned no bot.`,
      );
    }
    return { importedName: archive.importedName, thinkingSfxError };
  }

  async function prepareMarketplaceBundles(
    entries: readonly BotMarketplaceEntry[],
  ): Promise<BotMarketplacePreparedBundle[]> {
    const bundleBytesByPath = new Map<string, Uint8Array>();
    await Promise.all(
      entries.map(async (entry) => {
        bundleBytesByPath.set(
          entry.bundlePath,
          await fetchMarketplaceBotBundle(entry),
        );
      }),
    );
    const prepared = validateMarketplaceSelectionBundles(
      entries,
      bundleBytesByPath,
    );
    for (const bundle of prepared) {
      validateMarketplacePreparedBundle(bundle);
    }
    return prepared;
  }

  function startMarketplaceInstallOverlay(options: {
    title: string;
    subject: string;
    detail: string;
    currentStepLabel: string;
    totalBots?: number;
    accentColor?: string | null;
    glyph?: BotGlyphName;
  }): void {
    startBotTransferOverlay({
      mode: "import",
      title: options.title,
      subject: options.subject,
      detail: options.detail,
      currentStepLabel: options.currentStepLabel,
      completedSteps: 0,
      totalSteps: null,
      accentColor: options.accentColor ?? null,
      glyph: options.glyph ?? DEFAULT_BOT_GLYPH,
      stats: {
        totalBots: options.totalBots,
        completedBots: typeof options.totalBots === "number" ? 0 : undefined,
      },
    });
  }

  async function importMarketplacePreparedBundlesWithOverlay(
    prepared: readonly BotMarketplacePreparedBundle[],
    options: {
      title: string;
      subject: string;
    },
  ): Promise<MarketplaceBundleImportResult> {
    if (prepared.length === 0) {
      updateBotTransferOverlay((current) => ({
        ...current,
        title: options.title,
        subject: options.subject,
        detail:
          "Everything in this marketplace selection is already installed.",
        currentStepLabel: "Already installed",
        completedSteps: 1,
        totalSteps: 1,
        stats: { ...current.stats, completedBots: 0, totalBots: 0 },
      }));
      await waitForBotTransferPaint();
      return {
        importedBotIds: [],
        importedBotReferences: [],
        restoredTotal: 0,
        thinkingSfxGenerated: 0,
        thinkingSfxFailed: 0,
        thinkingSfxFailureMessage: null,
      };
    }

    const bundleHints = prepared.map((bundle) => ({
      bundle,
      hint: parseImportBotLoadingHint(bundle.bytes),
    }));
    const totalMemories = bundleHints.reduce(
      (sum, { hint }) => sum + hint.memoryCount,
      0,
    );
    const totalSteps = Math.max(
      2,
      1 + bundleHints.reduce((sum, { hint }) => sum + 1 + hint.memoryCount, 0),
    );
    let completedSteps = 1;
    let completedMemorySteps = 0;
    let importedCount = 0;
    let restoredTotal = 0;
    let thinkingSfxGenerated = 0;
    let thinkingSfxFailed = 0;
    let thinkingSfxFailureMessage: string | null = null;
    const importedBotIds: string[] = [];
    const importedBotReferences: MarketplaceInstalledBotReference[] = [];

    updateBotTransferOverlay((current) => ({
      ...current,
      title: options.title,
      subject: options.subject,
      detail:
        totalMemories > 0
          ? `Installing ${prepared.length} bot${prepared.length === 1 ? "" : "s"} and restoring ${totalMemories} memories.`
          : `Installing ${prepared.length} bot${prepared.length === 1 ? "" : "s"}.`,
      currentStepLabel: "Preparing marketplace install",
      completedSteps,
      totalSteps,
      stats: {
        ...current.stats,
        totalBots: prepared.length,
        completedBots: 0,
        totalMemories,
        completedMemories: 0,
      },
    }));
    await waitForBotTransferPaint();

    for (const { bundle, hint } of bundleHints) {
      let botCreated = false;
      let entryRestoredMemories = 0;
      let thinkingSfxFailedForBot = false;
      const subject = hint.name ?? bundle.entry.name;
      updateBotTransferOverlay((current) => ({
        ...current,
        subject,
        detail:
          hint.memoryCount > 0
            ? `Creating ${subject}'s thinking loop, then restoring ${hint.memoryCount} memories.`
            : `Creating ${subject}'s thinking loop and installing the bot.`,
        currentStepLabel: `Creating ${subject}'s thinking loop`,
        accentColor: hint.color ?? bundle.entry.color ?? current.accentColor,
        glyph: hint.glyph,
      }));
      await waitForBotTransferPaint();
      const result = await importBotFromArchiveBytes(bundle.bytes, {
        suppressNotice: true,
        suppressPanelReset: true,
        selectInChat: false,
        deferRefresh: true,
        keepBotsPanelOpen: true,
        generateThinkingSfx: true,
        onThinkingSfxError: (error) => {
          thinkingSfxFailedForBot = true;
          thinkingSfxFailed += 1;
          thinkingSfxFailureMessage ??= error.message;
        },
        onProgress: (event) => {
          if (event.kind === "bot-created" && !botCreated) {
            botCreated = true;
            completedSteps += 1;
          }
          if (event.kind === "memory-restored") {
            const memoryDelta = Math.max(
              0,
              event.restoredMemories - entryRestoredMemories,
            );
            entryRestoredMemories = event.restoredMemories;
            completedSteps += memoryDelta;
            completedMemorySteps += memoryDelta;
          }
          updateBotTransferOverlay((current) => ({
            ...current,
            subject: event.importedName,
            detail:
              event.totalMemories > 0
                ? `${event.restoredMemories} of ${event.totalMemories} memories restored.`
                : "Profile restored.",
            currentStepLabel:
              event.kind === "memory-restored"
                ? `Restoring memories for ${event.importedName}`
                : `Created ${event.importedName}`,
            completedSteps: Math.min(
              completedSteps,
              current.totalSteps ?? completedSteps,
            ),
            stats: {
              ...current.stats,
              completedBots: importedCount + (botCreated ? 1 : 0),
              completedMemories: completedMemorySteps,
              imported: importedCount,
            },
          }));
        },
      });
      if (!botCreated) {
        completedSteps += 1;
      }
      if (!thinkingSfxFailedForBot) {
        thinkingSfxGenerated += 1;
      }
      importedCount += 1;
      restoredTotal += result.restoredMemories;
      importedBotIds.push(result.botId);
      importedBotReferences.push({
        botHash: result.importedBotHash ?? bundle.entry.botHash,
        botId: result.botId,
      });
      updateBotTransferOverlay((current) => ({
        ...current,
        subject: result.importedName,
        detail:
          result.restoredMemories > 0
            ? `${result.importedName} installed with ${result.restoredMemories} memories.`
            : `${result.importedName} installed.`,
        currentStepLabel: `${importedCount} of ${prepared.length} bots installed`,
        completedSteps: Math.min(
          completedSteps,
          current.totalSteps ?? completedSteps,
        ),
        stats: {
          ...current.stats,
          completedBots: importedCount,
          completedMemories: completedMemorySteps,
          imported: importedCount,
        },
      }));
    }

    return {
      importedBotIds,
      importedBotReferences,
      restoredTotal,
      thinkingSfxGenerated,
      thinkingSfxFailed,
      thinkingSfxFailureMessage,
    };
  }

  function markMarketplaceEntriesCurrent(
    entryIds: readonly string[],
    manifest: BotMarketplaceManifest | null,
  ): void {
    if (!user?.id || !manifest || entryIds.length === 0) return;
    const revision = marketplaceCatalogRevision(manifest);
    setBotMarketplaceUpdateRevisions((current) => {
      let changed = false;
      const next = { ...current };
      for (const entryId of entryIds) {
        if (next[entryId] === revision) continue;
        next[entryId] = revision;
        changed = true;
      }
      return changed ? next : current;
    });
  }

  async function installPrismStarterPackFromMarketplace(): Promise<{
    installedCount: number;
    starterBotCount: number;
  }> {
    const currentBots = await refreshBots();
    const installedHashes = marketplaceInstalledHashSet(
      currentBots.map((bot) => bot.export_hash),
    );
    const manifest =
      botMarketplaceManifest ?? (await fetchBotMarketplaceManifest());
    setBotMarketplaceManifest(manifest);
    const visibleThemes = marketplaceVisibleThemes(manifest, {
      branchName: botMarketplaceBranchName,
    });
    setBotMarketplaceSelectedThemeId((current) =>
      current && visibleThemes.some((theme) => theme.id === current)
        ? current
        : (visibleThemes[0]?.id ?? null),
    );
    const entries = marketplaceEntriesForTheme(
      manifest,
      BOT_MARKETPLACE_STARTER_THEME_ID,
      { branchName: botMarketplaceBranchName },
    );
    if (entries.length === 0) {
      throw new Error(
        "Prism starter pack is missing from the marketplace catalog.",
      );
    }

    startMarketplaceInstallOverlay({
      title: "Installing starter bots",
      subject: "Prism Originals",
      detail: "Fetching marketplace bundles.",
      currentStepLabel: "Downloading starter pack",
      totalBots: entries.length,
    });
    await waitForBotTransferPaint();
    const missingEntries = marketplaceMissingEntries(entries, installedHashes);
    const prepared = await prepareMarketplaceBundles(missingEntries);
    const importResult = await importMarketplacePreparedBundlesWithOverlay(
      prepared,
      {
        title: "Installing starter bots",
        subject: "Prism Originals",
      },
    );
    markMarketplaceEntriesCurrent(
      missingEntries.map((entry) => entry.id),
      manifest,
    );

    if (prepared.length > 0) {
      updateBotTransferOverlay((current) => ({
        ...current,
        subject: "Prism Originals",
        detail: "Refreshing bot library and memories.",
        currentStepLabel: "Refreshing Prism",
        completedSteps: Math.min(
          current.completedSteps,
          Math.max(0, (current.totalSteps ?? 1) - 1),
        ),
      }));
    }
    const refreshedBots =
      prepared.length > 0 ? await refreshBots() : currentBots;
    if (prepared.length > 0) {
      await refreshMemories();
    }
    const refreshedIdByHash = new Map<string, string>();
    for (const bot of refreshedBots) {
      const hash = normalizeImportedBotHash(bot.export_hash);
      if (hash) refreshedIdByHash.set(hash, bot.id);
    }
    const starterBotIds = entries
      .map((entry) => refreshedIdByHash.get(entry.botHash) ?? null)
      .filter((botId): botId is string => Boolean(botId));
    const factoryGroups = createFactoryResetBotLibraryGroups(starterBotIds);
    setBotLibraryGroups(factoryGroups);
    if (user?.id && typeof window !== "undefined") {
      try {
        markStarterPackInstalled(user.id);
        window.localStorage.setItem(
          botLibraryGroupsStorageKey(user.id),
          JSON.stringify(factoryGroups),
        );
      } catch {
        // Non-fatal: the in-memory group state is already set for this page session.
      }
    }
    updateBotTransferOverlay((current) => ({
      ...current,
      subject: "Prism Originals",
      detail:
        importResult.importedBotIds.length > 0
          ? `${importResult.importedBotIds.length} starter bots installed.`
          : "Prism Originals are already installed.",
      currentStepLabel: "Complete",
      completedSteps: current.totalSteps ?? current.completedSteps,
      stats: {
        ...current.stats,
        completedBots: importResult.importedBotIds.length,
        completedMemories: importResult.restoredTotal,
        imported: importResult.importedBotIds.length,
      },
    }));
    return {
      installedCount: prepared.length,
      starterBotCount: starterBotIds.length,
    };
  }

  async function installMarketplaceBot(
    entry: BotMarketplaceEntry,
  ): Promise<void> {
    if (blockCoffeeConfigurationMutation()) return;
    if (botMarketplaceInstallingKey || botTransferBusy) return;
    const installedBotId = botMarketplaceInstalledBotIdByHash.get(
      entry.botHash,
    );
    const installedBot = installedBotId
      ? (bots.find((bot) => bot.id === installedBotId) ?? null)
      : null;
    if (installedBot) {
      openBotCustomizer(installedBot);
      return;
    }
    setBotMarketplaceInstallingKey(`bot:${entry.id}`);
    setPanelError(null);
    setPanelNotice(null);
    try {
      const entryGlyph = isBotGlyphName(entry.glyph)
        ? entry.glyph
        : DEFAULT_BOT_GLYPH;
      startMarketplaceInstallOverlay({
        title: "Installing marketplace bot",
        subject: entry.name,
        detail: "Fetching marketplace bundle.",
        currentStepLabel: "Downloading bot",
        totalBots: 1,
        accentColor: entry.color ?? null,
        glyph: entryGlyph,
      });
      await waitForBotTransferPaint();
      const [prepared] = await prepareMarketplaceBundles([entry]);
      if (!prepared)
        throw new Error(
          `${entry.name} marketplace bundle could not be prepared.`,
        );
      const importResult = await importMarketplacePreparedBundlesWithOverlay(
        [prepared],
        {
          title: "Installing marketplace bot",
          subject: entry.name,
        },
      );
      markMarketplaceEntriesCurrent([entry.id], botMarketplaceManifest);
      updateBotTransferOverlay((current) => ({
        ...current,
        subject: entry.name,
        detail: "Refreshing bot library and memories.",
        currentStepLabel: "Refreshing Prism",
        completedSteps: Math.min(
          current.completedSteps,
          Math.max(0, (current.totalSteps ?? 1) - 1),
        ),
      }));
      const refreshedBots = await refreshBots();
      await refreshMemories();
      const importedBotId = importResult.importedBotIds[0] ?? null;
      if (importedBotId) {
        await refreshBotMemories(importedBotId);
      }
      if (botMarketplaceManifest) {
        setBotLibraryGroups((current) =>
          upsertMarketplaceBotLibraryThemeGroups(
            current,
            botMarketplaceManifest,
            [entry],
            refreshedBots,
            importResult.importedBotReferences,
            botMarketplaceBranchName,
          ),
        );
      }
      setBotPanelView("marketplace");
      const installedMessage = `${
        importResult.restoredTotal > 0
          ? `${entry.name} installed with ${importResult.restoredTotal} memories.`
          : `${entry.name} installed.`
      }${marketplaceThinkingSfxNotice(importResult)}`;
      updateBotTransferOverlay((current) => ({
        ...current,
        subject: entry.name,
        detail: installedMessage,
        currentStepLabel: "Complete",
        completedSteps: current.totalSteps ?? current.completedSteps,
        stats: {
          ...current.stats,
          completedBots: 1,
          completedMemories: importResult.restoredTotal,
          imported: 1,
        },
      }));
      setPanelNotice(installedMessage);
    } catch (err) {
      setPanelError(
        err instanceof Error ? err.message : "Marketplace install failed.",
      );
    } finally {
      setBotTransferOverlay(null);
      setBotMarketplaceInstallingKey(null);
    }
  }

