  async function installMarketplaceTheme(
    theme: BotMarketplaceTheme,
  ): Promise<void> {
    if (blockCoffeeConfigurationMutation()) return;
    if (
      !botMarketplaceManifest ||
      botMarketplaceInstallingKey ||
      botTransferBusy
    )
      return;
    const entries = marketplaceEntriesForTheme(
      botMarketplaceManifest,
      theme.id,
      { branchName: botMarketplaceBranchName },
    );
    if (entries.length === 0) return;
    setBotMarketplaceInstallingKey(`theme:${theme.id}`);
    setPanelError(null);
    setPanelNotice(null);
    try {
      startMarketplaceInstallOverlay({
        title: "Installing marketplace pack",
        subject: theme.name,
        detail: "Fetching marketplace bundles.",
        currentStepLabel: "Downloading pack",
        totalBots: entries.length,
      });
      await waitForBotTransferPaint();
      const prepared = await prepareMarketplaceBundles(entries);
      const missingPrepared = prepared.filter(
        ({ entry }) => !botMarketplaceInstalledHashes.has(entry.botHash),
      );
      const importResult = await importMarketplacePreparedBundlesWithOverlay(
        missingPrepared,
        {
          title: "Installing marketplace pack",
          subject: theme.name,
        },
      );
      markMarketplaceEntriesCurrent(
        missingPrepared.map(({ entry }) => entry.id),
        botMarketplaceManifest,
      );
      updateBotTransferOverlay((current) => ({
        ...current,
        subject: theme.name,
        detail: "Refreshing bot library and memories.",
        currentStepLabel: "Refreshing Prism",
        completedSteps: Math.min(
          current.completedSteps,
          Math.max(0, (current.totalSteps ?? 1) - 1),
        ),
      }));
      const refreshedBots = await refreshBots();
      await refreshMemories();
      setBotLibraryGroups((current) =>
        upsertMarketplaceBotLibraryThemeGroups(
          current,
          botMarketplaceManifest,
          entries,
          refreshedBots,
          importResult.importedBotReferences,
          botMarketplaceBranchName,
        ),
      );
      setBotPanelView("marketplace");
      if (missingPrepared.length === 0) {
        updateBotTransferOverlay((current) => ({
          ...current,
          subject: theme.name,
          detail: `${theme.name} is already installed.`,
          currentStepLabel: "Complete",
          completedSteps: current.totalSteps ?? current.completedSteps,
        }));
        setPanelNotice(`${theme.name} is already installed.`);
      } else {
        const installedMessage = `${
          importResult.restoredTotal > 0
            ? `${theme.name} installed: ${importResult.importedBotIds.length} bots and ${importResult.restoredTotal} memories.`
            : `${theme.name} installed: ${importResult.importedBotIds.length} bots.`
        }${marketplaceThinkingSfxNotice(importResult)}`;
        updateBotTransferOverlay((current) => ({
          ...current,
          subject: theme.name,
          detail: installedMessage,
          currentStepLabel: "Complete",
          completedSteps: current.totalSteps ?? current.completedSteps,
          stats: {
            ...current.stats,
            completedBots: importResult.importedBotIds.length,
            completedMemories: importResult.restoredTotal,
            imported: importResult.importedBotIds.length,
          },
        }));
        setPanelNotice(installedMessage);
      }
    } catch (err) {
      setPanelError(
        err instanceof Error
          ? err.message
          : "Marketplace theme install failed.",
      );
    } finally {
      setBotTransferOverlay(null);
      setBotMarketplaceInstallingKey(null);
    }
  }

  async function updateMarketplaceTheme(
    theme: BotMarketplaceTheme,
  ): Promise<void> {
    if (blockCoffeeConfigurationMutation()) return;
    if (
      !botMarketplaceManifest ||
      botMarketplaceInstallingKey ||
      botTransferBusy
    )
      return;
    const entries = marketplaceEntriesForTheme(
      botMarketplaceManifest,
      theme.id,
      { branchName: botMarketplaceBranchName },
    );
    if (entries.length === 0) return;
    const currentBots = bots;
    const currentInstalledHashes = marketplaceInstalledHashSet(
      currentBots.map((bot) => bot.export_hash),
    );
    const installedBotIdByHash = botIdByMarketplaceHash(currentBots);
    const catalogRevision = marketplaceCatalogRevision(botMarketplaceManifest);
    const installedEntries = entries.filter(
      (entry) =>
        installedBotIdByHash.has(entry.botHash) &&
        marketplaceEntryNeedsUpdate(
          entry,
          currentInstalledHashes,
          botMarketplaceUpdateRevisions,
          catalogRevision,
        ),
    );
    if (installedEntries.length === 0) return;

    setBotMarketplaceInstallingKey(`update:theme:${theme.id}`);
    setPanelError(null);
    setPanelNotice(null);
    try {
      startMarketplaceInstallOverlay({
        title: "Updating marketplace pack",
        subject: theme.name,
        detail: "Fetching the latest marketplace sources.",
        currentStepLabel: "Downloading updates",
        totalBots: installedEntries.length,
      });
      await waitForBotTransferPaint();
      const prepared = await prepareMarketplaceBundles(installedEntries);
      let updatedCount = 0;
      let thinkingSfxGenerated = 0;
      let thinkingSfxFailed = 0;
      let thinkingSfxFailureMessage: string | null = null;
      for (const bundle of prepared) {
        const installedBotId = installedBotIdByHash.get(bundle.entry.botHash);
        if (!installedBotId) continue;
        updateBotTransferOverlay((current) => ({
          ...current,
          subject: bundle.entry.name,
          detail: `Updating ${bundle.entry.name} from the marketplace.`,
          currentStepLabel: `${updatedCount + 1} of ${prepared.length} bots updating`,
        }));
        await waitForBotTransferPaint();
        const result = await updateMarketplaceBotFromArchiveBytes(
          installedBotId,
          bundle,
        );
        if (result.thinkingSfxError) {
          thinkingSfxFailed += 1;
          thinkingSfxFailureMessage ??= result.thinkingSfxError;
        } else {
          thinkingSfxGenerated += 1;
        }
        markMarketplaceEntriesCurrent(
          [bundle.entry.id],
          botMarketplaceManifest,
        );
        updatedCount += 1;
        updateBotTransferOverlay((current) => ({
          ...current,
          completedSteps: Math.min(
            updatedCount,
            current.totalSteps ?? updatedCount,
          ),
          stats: {
            ...current.stats,
            completedBots: updatedCount,
            updated: updatedCount,
          },
        }));
      }

      const refreshedBots = await refreshBots();
      setBotLibraryGroups((current) =>
        upsertMarketplaceBotLibraryThemeGroups(
          current,
          botMarketplaceManifest,
          installedEntries,
          refreshedBots,
          [],
          botMarketplaceBranchName,
        ),
      );
      setBotPanelView("marketplace");
      const updateMessage = `${theme.name}: ${updatedCount} bot${
        updatedCount === 1 ? "" : "s"
      } updated from the marketplace. Your memories were kept.${marketplaceThinkingSfxNotice(
        {
          thinkingSfxGenerated,
          thinkingSfxFailed,
          thinkingSfxFailureMessage,
        },
      )}`;
      updateBotTransferOverlay((current) => ({
        ...current,
        subject: theme.name,
        detail: updateMessage,
        currentStepLabel: "Complete",
        completedSteps: current.totalSteps ?? current.completedSteps,
        stats: {
          ...current.stats,
          completedBots: updatedCount,
          updated: updatedCount,
        },
      }));
      setPanelNotice(updateMessage);
    } catch (err) {
      setPanelError(
        err instanceof Error ? err.message : "Marketplace pack update failed.",
      );
    } finally {
      setBotTransferOverlay(null);
      setBotMarketplaceInstallingKey(null);
    }
  }

  async function installStarterBotsFromEmptyState(
    source: "coffee" | "story",
  ): Promise<void> {
    if (botMarketplaceInstallingKey || botTransferBusy) return;
    setBotMarketplaceInstallingKey(`theme:${BOT_MARKETPLACE_STARTER_THEME_ID}`);
    setPanelError(null);
    setPanelNotice(null);
    setCoffeeError(null);
    setStoryError(null);
    try {
      const result = await installPrismStarterPackFromMarketplace();
      const message =
        result.installedCount > 0
          ? `Installed ${result.installedCount} Prism Originals starter bots.`
          : `Prism Originals are already installed.`;
      setPanelNotice(message);
      if (source === "coffee") {
        setCoffeeSearch("");
      } else {
        setStorySearch("");
      }
    } catch (err) {
      const message =
        err instanceof Error
          ? err.message
          : "Prism Originals could not be installed.";
      if (source === "coffee") {
        setCoffeeError(message);
      } else {
        setStoryError(message);
      }
    } finally {
      setBotTransferOverlay(null);
      setBotMarketplaceInstallingKey(null);
    }
  }

  useEffect(() => {
    if (!user?.id) return;
    const freshAccountEligible =
      !hasAnyAccounts ||
      starterPackFreshAccountEligibleUserRef.current === user.id;
    if (!freshAccountEligible) return;
    if (starterPackInstallMarked(user.id)) return;
    if (starterPackAutoInstallAttemptedUserRef.current === user.id) return;
    let cancelled = false;
    starterPackAutoInstallAttemptedUserRef.current = user.id;
    if (starterPackFreshAccountEligibleUserRef.current === user.id) {
      starterPackFreshAccountEligibleUserRef.current = null;
    }
    setBotMarketplaceInstallingKey(`theme:${BOT_MARKETPLACE_STARTER_THEME_ID}`);
    setPanelError(null);
    setPanelNotice("Installing Prism Originals starter bots...");
    void (async () => {
      try {
        const result = await installPrismStarterPackFromMarketplace();
        if (cancelled) return;
        setPanelNotice(
          result.installedCount > 0
            ? `Installed ${result.installedCount} Prism Originals starter bots.`
            : "Prism Originals are ready.",
        );
      } catch (err) {
        if (!cancelled) {
          setPanelError(
            err instanceof Error
              ? `Starter bots could not be installed: ${err.message}`
              : "Starter bots could not be installed.",
          );
        }
      } finally {
        if (!cancelled) {
          setBotTransferOverlay(null);
          setBotMarketplaceInstallingKey(null);
        }
      }
    })();
    return () => {
      cancelled = true;
    };
    // The installer is a local workflow function; this effect is intentionally keyed to auth/install state.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user?.id, hasAnyAccounts]);

  async function handleBotImportFileSelection(
    event: React.ChangeEvent<HTMLInputElement>,
  ): Promise<void> {
    const file = event.currentTarget.files?.[0];
    event.currentTarget.value = "";
    if (botTransferBusy) return;
    if (!file) return;
    const lower = file.name.trim().toLowerCase();
    const isBotFile = lower.endsWith(".bot");
    const isBotCollectionFile = lower.endsWith(BOT_COLLECTION_FILE_EXTENSION);
    if (!isBotFile && !isBotCollectionFile) {
      setPanelError("Only .bot or .bots files can be imported from disk.");
      return;
    }
    startBotTransferOverlay({
      mode: "import",
      title: isBotCollectionFile ? "Importing bot collection" : "Importing bot",
      subject: file.name,
      detail: isBotCollectionFile
        ? "Reading collection file."
        : "Reading bot export.",
      currentStepLabel: "Opening file",
      completedSteps: 0,
      totalSteps: null,
      accentColor: null,
      glyph: DEFAULT_BOT_GLYPH,
      stats: {},
    });
    try {
      if (isBotCollectionFile) {
        await importBotCollectionBundle(file);
      } else {
        const archiveBytes = new Uint8Array(await file.arrayBuffer());
        const hint = parseImportBotLoadingHint(archiveBytes);
        const totalSteps = Math.max(2, hint.memoryCount + 2);
        let completedSteps = 0;
        let restoredMemories = 0;
        updateBotTransferOverlay((current) => ({
          ...current,
          subject: hint.name ?? file.name,
          detail:
            hint.memoryCount > 0
              ? `Restoring profile and ${hint.memoryCount} memories.`
              : "Restoring profile.",
          currentStepLabel: "Preparing import",
          totalSteps,
          accentColor: hint.color,
          glyph: hint.glyph,
          stats: {
            totalBots: 1,
            completedBots: 0,
            totalMemories: hint.memoryCount,
          },
        }));
        await waitForBotTransferPaint();
        const result = await importBotFromArchiveBytes(archiveBytes, {
          onProgress: (event) => {
            if (event.kind === "bot-created" && completedSteps === 0) {
              completedSteps = 1;
            }
            if (event.kind === "memory-restored") {
              const memoryDelta = Math.max(
                0,
                event.restoredMemories - restoredMemories,
              );
              restoredMemories = event.restoredMemories;
              completedSteps += memoryDelta;
            }
            updateBotTransferOverlay((current) => ({
              ...current,
              subject: event.importedName,
              detail:
                event.totalMemories > 0
                  ? `${event.restoredMemories} of ${event.totalMemories} memories restored.`
                  : "Profile restored.",
              currentStepLabel:
                event.kind === "memory-restored"
                  ? `Restoring memories for ${event.importedName}`
                  : `Created ${event.importedName}`,
              completedSteps: Math.min(
                completedSteps,
                current.totalSteps ?? completedSteps,
              ),
              stats: {
                ...current.stats,
                completedBots:
                  event.kind === "bot-created"
                    ? 1
                    : current.stats.completedBots,
                completedMemories: restoredMemories,
              },
            }));
          },
        });
        updateBotTransferOverlay((current) => ({
          ...current,
          subject: result.importedName,
          detail:
            result.restoredMemories > 0
              ? `${result.importedName} imported with ${result.restoredMemories} memories.`
              : `${result.importedName} imported.`,
          currentStepLabel: "Complete",
          completedSteps: current.totalSteps ?? totalSteps,
          stats: {
            ...current.stats,
            completedBots: 1,
            completedMemories: result.restoredMemories,
            imported: 1,
          },
        }));
      }
    } catch (err) {
      setPanelError(err instanceof Error ? err.message : "Bot import failed.");
    } finally {
      setBotTransferOverlay(null);
    }
  }

