  function applyBotLibraryHeaderFilter(nextValue: string): void {
    if (nextValue === BOT_LIBRARY_GROUP_FILTER_ALL) {
      performShowAllBotsView(null);
      return;
    }
    if (nextValue === BOT_LIBRARY_GROUP_FILTER_UNGROUPED) {
      applyBotLibraryGroupFilter(BOT_LIBRARY_GROUP_FILTER_UNGROUPED);
      return;
    }
    if (nextValue.startsWith(BOT_LIBRARY_HEADER_SAVED_GROUP_PREFIX)) {
      const groupId = nextValue.slice(
        BOT_LIBRARY_HEADER_SAVED_GROUP_PREFIX.length,
      );
      applyBotLibraryGroupFilter(groupId);
      return;
    }
  }

  function handleEmptyStateBackgroundClick(
    event: React.MouseEvent<HTMLDivElement>,
  ): void {
    if (canvasBotMarqueeSuppressClickRef.current) {
      canvasBotMarqueeSuppressClickRef.current = false;
      event.preventDefault();
      event.stopPropagation();
      return;
    }
    const target = event.target;
    if (!(target instanceof Element)) return;
    const interactiveTarget = target.closest(
      BOT_CANVAS_BACKGROUND_INTERACTIVE_SELECTOR,
    );
    if (interactiveTarget) return;
    if (event.shiftKey) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }
    const shouldZoomOutFocusedBot = canvasBackgroundShouldZoomOutFocusedBot({
      view:
        view === "chat" || view === "sandbox" || view === "coffee"
          ? view
          : "other",
      conversationMessageCount: detail ? detail.messages.length : null,
      focusedBotId: zenPersonaBotId,
      pendingIncognito,
      canZoomOutToAllBots: zenCanZoomOutToAllBots,
    });
    // Empty canvas always collapses to All Bots Home — never one-step history
    // back (Back/Escape still walk the relationship stack one level at a time).
    if (
      shouldZoomOutFocusedBot ||
      (view === "chat" && relationshipDepthReturnDepth > 0)
    ) {
      event.preventDefault();
      event.stopPropagation();
      jumpCanvasToAllBotsHome();
      return;
    }
    if (detail || pendingIncognito) return;
    const shouldReturnToBotDirectory =
      bots.length > 0 &&
      !pendingReplyVisible &&
      (selectedBotId !== null ||
        zenPersonaBotId !== null ||
        composerPrimed ||
        hueFilterCenter !== null ||
        botLibraryGroupFilterId !== BOT_LIBRARY_GROUP_FILTER_ALL ||
        botPanelGroup !== BOT_LIBRARY_FILTER_ALL);
    if (shouldReturnToBotDirectory) {
      event.preventDefault();
      event.stopPropagation();
      jumpCanvasToAllBotsHome();
      return;
    }
    setCanvasSelectedBotIds((current) =>
      current.size === 0 ? current : new Set(),
    );
  }

