  function captureHomeRelationshipDepthCheckpoint(
    botId: string | null,
    sourceElement: HTMLElement | null,
  ): ZenRelationshipDepthRuntimeCheckpoint {
    const identityKey = relationshipDepthIdentity(botId);
    const conversationId =
      detail?.id && detail.id !== "pending" ? detail.id : selectedId;
    const sourceEndpoint: RelationshipDepthEndpoint = {
      key: `home:${identityKey}:${conversationId ?? "pending"}`,
      surface: "home",
      contextKey: identityKey,
      identityKey,
      activityKey: conversationId
        ? `conversation:${conversationId}`
        : "pending",
    };
    return {
      controller: {
        key: `checkpoint:${sourceEndpoint.key}:${Date.now()}`,
        endpoint: sourceEndpoint,
        focusKey: `home:${identityKey}`,
      },
      transitionState: null,
      surface: "home",
      returnLabel:
        botId === null
          ? "Prism Home"
          : `${bots.find((bot) => bot.id === botId)?.name ?? "Persona"}'s Home`,
      identityKey,
      botId,
      conversationId,
      library: null,
      draft: draftLiveRef.current,
      scrollTop: messagesScrollRef.current?.scrollTop ?? 0,
      focusElement: sourceElement,
    };
  }

  function restoreRelationshipDepthFocus(
    checkpoint: ZenRelationshipDepthRuntimeCheckpoint,
  ): void {
    window.requestAnimationFrame(() => {
      const retainedFocus = checkpoint.focusElement;
      const fallback = visibleRelationshipDepthAnchor(
        checkpoint.surface,
        checkpoint.identityKey,
      );
      const candidate =
        retainedFocus?.isConnected && retainedFocus.getClientRects().length > 0
          ? retainedFocus
          : fallback;
      const focusTarget = candidate
        ? candidate.matches("button, a, input, select, textarea, [tabindex]")
          ? candidate
          : (candidate.closest<HTMLElement>(
              "button, a, input, select, textarea, [tabindex]",
            ) ??
            candidate.querySelector<HTMLElement>(
              "button, a, input, select, textarea, [tabindex]",
            ))
        : null;
      if (focusTarget) {
        focusTarget.focus({ preventScroll: true });
      } else {
        focusDraftInput();
      }
    });
  }

  async function restoreRelationshipDepthCheckpoint(
    checkpoint: ZenRelationshipDepthRuntimeCheckpoint,
  ): Promise<void> {
    setError(null);
    setSessionOpinion(null);
    setBotOpinion(null);
    setConversationStarterPrompts(null);
    if (checkpoint.surface === "home") {
      setChatAutoRestoreSuppressed(false);
      setForceNewConversationOnNextSend(false);
      setSelectedBotId(checkpoint.botId);
      setSandboxGridSelectedBotId(checkpoint.botId);
      setZenPersonaBotId(checkpoint.botId);
      if (checkpoint.conversationId) {
        await refreshConversation(checkpoint.conversationId);
      } else {
        setSelectedId(null);
        setDetail(null);
      }
      rememberZenHomeDraft(checkpoint.identityKey, checkpoint.draft);
      setComposerDraftNow(checkpoint.draft);
      window.requestAnimationFrame(() => {
        messagesScrollRef.current?.scrollTo({
          top: checkpoint.scrollTop,
          behavior: "auto",
        });
      });
      return;
    }

    const library = checkpoint.library;
    if (!library) return;
    setChatAutoRestoreSuppressed(true);
    setForceNewConversationOnNextSend(true);
    setSelectedId(null);
    setDetail(null);
    setSelectedBotId(library.selectedBotId);
    setSandboxGridSelectedBotId(library.sandboxGridSelectedBotId);
    setZenPersonaBotId(library.zenPersonaBotId);
    setChatBotOverride(undefined);
    setBotLibraryGroupFilterId(library.groupFilterId);
    setBotPanelGroup(library.panelGroup);
    setHueFilterCenter(library.hueFilterCenter);
    setEmptyStateSearchOpen(library.searchOpen);
    setEmptyStateBotNameFilter(library.searchQuery);
    spotlightTypingArmedRef.current = library.searchOpen;
    setComposerDraftNow(checkpoint.draft);
    setZenZoomedOutConversationId(null);
    window.requestAnimationFrame(() => {
      messagesScrollRef.current?.scrollTo({
        top: library.scrollTop,
        behavior: "auto",
      });
    });
  }

  async function runRelationshipDepthTransition({
    checkpoint,
    destination,
    destinationLabel,
    sourceElement,
    commitDestination,
    nativeCommitSafe = true,
  }: {
    checkpoint: ZenRelationshipDepthRuntimeCheckpoint;
    destination: RelationshipDepthEndpoint;
    destinationLabel: string;
    sourceElement: HTMLElement | null;
    commitDestination: () => void | Promise<void>;
    nativeCommitSafe?: boolean;
  }): Promise<void> {
    if (
      relationshipDepthTransitionRef.current &&
      relationshipDepthTransitionInteractionLock(
        relationshipDepthTransitionRef.current,
      ) !== "none"
    ) {
      return;
    }
    const runId = ++relationshipDepthRunRef.current;
    const reducedMotion = window.matchMedia(
      "(prefers-reduced-motion: reduce)",
    ).matches;
    const destinationBeforeCommit = visibleRelationshipDepthAnchor(
      destination.surface === "home" ? "home" : checkpoint.surface,
      destination.identityKey ?? checkpoint.identityKey,
    );
    const created = createRelationshipDepthTransition({
      id: `relationship-depth-${runId}`,
      source: checkpoint.controller.endpoint,
      destination,
      checkpoint: checkpoint.controller,
      geometry: relationshipDepthAnchorGeometry(
        checkpoint.identityKey,
        sourceElement,
        destinationBeforeCommit ?? sourceElement,
      ),
      reducedMotion,
      activeTurnRunning: false,
    });
    if (!created) {
      await commitDestination();
      return;
    }

    let controllerState = created.state;
    setRelationshipDepthControllerState(controllerState);
    const root = document.documentElement;
    root.dataset.relationshipDepthMotion = controllerState.plan.motion;
    root.dataset.relationshipDepthAtmosphere = controllerState.plan.atmosphere;
    root.dataset.relationshipDepthDirection = "forward";
    const transitionDocument = document as PrismViewTransitionDocument;
    const useNativeTransition = relationshipDepthNativeViewTransitionEligible({
      supported: Boolean(transitionDocument.startViewTransition),
      reducedMotion,
      asyncHandoffSafe: nativeCommitSafe,
    });
    root.dataset.relationshipDepthRenderer = useNativeTransition
      ? "native"
      : "manual";
    const manualBeatTiming = relationshipDepthManualBeatTiming({
      crossfade:
        controllerState.plan.motion === "crossfade" ||
        controllerState.plan.atmosphere === "crossfade",
      reducedMotion,
    });
    const useSharedAnchor =
      controllerState.plan.motion === "shared-anchor" ||
      controllerState.plan.motion === "pullback-swap";
    if (useSharedAnchor && sourceElement) {
      sourceElement.style.setProperty(
        "view-transition-name",
        RELATIONSHIP_DEPTH_ANCHOR_NAME,
      );
    }
    let destinationElement: HTMLElement | null = null;

    let handoffPromise: Promise<void> | null = null;
    const commitAtHandoff = (insideNativeTransition = false): Promise<void> => {
      if (handoffPromise) return handoffPromise;
      handoffPromise = (async (): Promise<void> => {
        const handoff = reduceRelationshipDepthTransition(controllerState, {
          type: "beat-complete",
          transitionId: controllerState.id,
        });
        controllerState = handoff.state;
        setRelationshipDepthControllerState(controllerState);
        sourceElement?.style.removeProperty("view-transition-name");
        let pendingCommit: void | Promise<void>;
        if (insideNativeTransition) {
          flushSync(() => {
            pendingCommit = commitDestination();
          });
        } else {
          pendingCommit = commitDestination();
        }
        await pendingCommit!;
        if (relationshipDepthRunRef.current !== runId) return;
        if (!insideNativeTransition) {
          await new Promise<void>((resolve) =>
            window.requestAnimationFrame(() => resolve()),
          );
        }
        destinationElement = visibleRelationshipDepthAnchor(
          destination.surface === "home" ? "home" : checkpoint.surface,
          destination.identityKey ?? checkpoint.identityKey,
        );
        if (useSharedAnchor && destinationElement) {
          destinationElement.style.setProperty(
            "view-transition-name",
            RELATIONSHIP_DEPTH_ANCHOR_NAME,
          );
        }
        const ready = reduceRelationshipDepthTransition(controllerState, {
          type: "endpoint-ready",
          transitionId: controllerState.id,
        });
        controllerState = ready.state;
        setRelationshipDepthControllerState(controllerState);
      })();
      return handoffPromise;
    };

    try {
      if (useNativeTransition) {
        await runRelationshipDepthViewTransition({
          startViewTransition: (update) =>
            transitionDocument.startViewTransition!(update),
          handoff: commitAtHandoff,
          wait: waitForRelationshipDepthBeat,
          timeoutMs: RELATIONSHIP_DEPTH_NATIVE_TIMEOUT_MS,
          updateCallbackGraceMs: 120,
          fallbackSettleMs: manualBeatTiming.destinationMs,
        });
      } else {
        await waitForRelationshipDepthBeat(manualBeatTiming.sourceMs);
        await commitAtHandoff(false);
        await waitForRelationshipDepthBeat(manualBeatTiming.destinationMs);
      }
      if (relationshipDepthRunRef.current !== runId) return;
      const settled = reduceRelationshipDepthTransition(controllerState, {
        type: "beat-complete",
        transitionId: controllerState.id,
      });
      controllerState = settled.state;
      checkpoint.transitionState = controllerState;
      relationshipDepthCheckpointStackRef.current.push(checkpoint);
      setRelationshipDepthReturnDepth(
        relationshipDepthCheckpointStackRef.current.length,
      );
      setRelationshipDepthReturnLabel(checkpoint.returnLabel);
      flushSync(() => setRelationshipDepthControllerState(controllerState));
      setRelationshipDepthAnnouncement(`Entered ${destinationLabel}.`);
      focusDraftInput();
    } catch (err) {
      setRelationshipDepthControllerState(null);
      throw err;
    } finally {
      sourceElement?.style.removeProperty("view-transition-name");
      (destinationElement as HTMLElement | null)?.style.removeProperty(
        "view-transition-name",
      );
      delete root.dataset.relationshipDepthMotion;
      delete root.dataset.relationshipDepthAtmosphere;
      delete root.dataset.relationshipDepthDirection;
      delete root.dataset.relationshipDepthRenderer;
    }
  }

  async function returnFromRelationshipDepth(
    reason: "back" | "escape",
  ): Promise<void> {
    const stack = relationshipDepthCheckpointStackRef.current;
    const checkpoint = stack.at(-1);
    const settledTransition = checkpoint?.transitionState;
    if (!checkpoint || !settledTransition) return;
    const activeTurnRunning =
      pendingReplyVisible || chatAssistantRevealInProgress;
    const interruptedHomeDraft =
      activeTurnRunning && settledTransition.destination.surface === "home"
        ? pendingReplySubmittedDraftRef.current
        : null;
    if (activeTurnRunning && checkpoint.surface !== "group-room") return;
    if (
      relationshipDepthTransitionRef.current &&
      relationshipDepthTransitionInteractionLock(
        relationshipDepthTransitionRef.current,
      ) !== "none"
    ) {
      return;
    }

    if (activeTurnRunning) {
      const interruptingState: RelationshipDepthTransitionState = {
        ...settledTransition,
        phase: "interrupting",
        direction: "reverse",
        settledAt: null,
        returnReason: reason,
      };
      setRelationshipDepthControllerState(interruptingState);
      try {
        const currentInterruption =
          relationshipDepthReturnInterruptionRef.current;
        if (currentInterruption) {
          await currentInterruption;
        } else {
          const pendingSettlement = pendingReplySettlementRef.current;
          const interruption = interruptRelationshipDepthReturn({
            cancelQueuedAndFollowupWork: () => {
              queuedPromptDrainGenerationRef.current += 1;
              setQueuedChatPrompts([]);
              setDispatchingQueuedPrompt(null);
              clearZenFollowupCooldownTimer();
              zenFollowupBufferRef.current = null;
              setZenFollowupBuffer(null);
              zenFollowupDispatchingRef.current = false;
            },
            cancelStarterWork: () => {
              const starterRequest = zenInitialStarterRequestRef.current;
              if (!starterRequest) return;
              starterRequest.cancelled = true;
              starterRequest.replayWhenReady = false;
              starterRequest.controller.abort();
            },
            clearStarterReplyCache: clearZenInitialStarterReplyCache,
            pendingReplyVisible,
            stopPendingReply,
            pendingReplySettled: pendingSettlement?.settled,
            waitForPendingReplyRender: () =>
              new Promise<void>((resolve) =>
                window.requestAnimationFrame(() => resolve()),
              ),
            stopResponseAudio: stopVoicePlaybackForAssistantInterruption,
            finishResponseReveal: () =>
              finishRelationshipDepthAssistantRevealRef.current(),
          });
          relationshipDepthReturnInterruptionRef.current = interruption;
          try {
            await interruption;
          } finally {
            if (
              relationshipDepthReturnInterruptionRef.current === interruption
            ) {
              relationshipDepthReturnInterruptionRef.current = null;
            }
          }
        }
      } catch (err) {
        setRelationshipDepthControllerState(settledTransition);
        setError(
          err instanceof Error
            ? err.message
            : "Could not finish the active Zen reply before returning.",
        );
        return;
      }
      setRelationshipDepthControllerState(settledTransition);
    }

    if (checkpoint.surface === "group-room") {
      stopVoicePlaybackForAssistantInterruption();
    }

    if (
      settledTransition.destination.surface === "home" &&
      settledTransition.destination.identityKey
    ) {
      rememberZenHomeDraft(
        settledTransition.destination.identityKey,
        interruptedHomeDraft ?? draftLiveRef.current,
      );
    }

    const runId = ++relationshipDepthRunRef.current;
    let controllerState = reduceRelationshipDepthTransition(settledTransition, {
      type: "return",
      transitionId: settledTransition.id,
      reason,
    }).state;
    setRelationshipDepthControllerState(controllerState);
    const reducedMotion = window.matchMedia(
      "(prefers-reduced-motion: reduce)",
    ).matches;
    const root = document.documentElement;
    root.dataset.relationshipDepthMotion = controllerState.plan.motion;
    root.dataset.relationshipDepthAtmosphere = controllerState.plan.atmosphere;
    root.dataset.relationshipDepthDirection = "reverse";
    const transitionDocument = document as PrismViewTransitionDocument;
    const nativeRestoreSafe =
      checkpoint.surface !== "home" || checkpoint.conversationId === null;
    const useNativeTransition = relationshipDepthNativeViewTransitionEligible({
      supported: Boolean(transitionDocument.startViewTransition),
      reducedMotion,
      asyncHandoffSafe: nativeRestoreSafe,
    });
    root.dataset.relationshipDepthRenderer = useNativeTransition
      ? "native"
      : "manual";
    const manualBeatTiming = relationshipDepthManualBeatTiming({
      crossfade:
        controllerState.plan.motion === "crossfade" ||
        controllerState.plan.atmosphere === "crossfade",
      reducedMotion,
    });
    const currentIdentity = controllerState.destination.identityKey;
    const currentSurface =
      controllerState.destination.surface === "home"
        ? "home"
        : checkpoint.surface;
    const sourceElement = currentIdentity
      ? visibleRelationshipDepthAnchor(currentSurface, currentIdentity)
      : null;
    const useSharedAnchor =
      controllerState.plan.motion === "shared-anchor" ||
      controllerState.plan.motion === "pullback-swap";
    if (useSharedAnchor && sourceElement) {
      sourceElement.style.setProperty(
        "view-transition-name",
        RELATIONSHIP_DEPTH_ANCHOR_NAME,
      );
    }
    let destinationElement: HTMLElement | null = null;

    let restorePromise: Promise<void> | null = null;
    const restoreAtHandoff = (
      insideNativeTransition = false,
    ): Promise<void> => {
      if (restorePromise) return restorePromise;
      restorePromise = (async (): Promise<void> => {
        const handoff = reduceRelationshipDepthTransition(controllerState, {
          type: "beat-complete",
          transitionId: controllerState.id,
        });
        controllerState = handoff.state;
        setRelationshipDepthControllerState(controllerState);
        sourceElement?.style.removeProperty("view-transition-name");
        let pendingRestore: Promise<void>;
        if (insideNativeTransition) {
          flushSync(() => {
            pendingRestore = restoreRelationshipDepthCheckpoint(checkpoint);
          });
        } else {
          pendingRestore = restoreRelationshipDepthCheckpoint(checkpoint);
        }
        await pendingRestore!;
        if (relationshipDepthRunRef.current !== runId) return;
        if (!insideNativeTransition) {
          await new Promise<void>((resolve) =>
            window.requestAnimationFrame(() => resolve()),
          );
        }
        destinationElement = visibleRelationshipDepthAnchor(
          checkpoint.surface,
          checkpoint.identityKey,
        );
        if (useSharedAnchor && destinationElement) {
          destinationElement.style.setProperty(
            "view-transition-name",
            RELATIONSHIP_DEPTH_ANCHOR_NAME,
          );
        }
        const ready = reduceRelationshipDepthTransition(controllerState, {
          type: "endpoint-ready",
          transitionId: controllerState.id,
        });
        controllerState = ready.state;
        setRelationshipDepthControllerState(controllerState);
      })();
      return restorePromise;
    };

    try {
      if (useNativeTransition) {
        await runRelationshipDepthViewTransition({
          startViewTransition: (update) =>
            transitionDocument.startViewTransition!(update),
          handoff: restoreAtHandoff,
          wait: waitForRelationshipDepthBeat,
          timeoutMs: RELATIONSHIP_DEPTH_NATIVE_TIMEOUT_MS,
          updateCallbackGraceMs: 120,
          fallbackSettleMs: manualBeatTiming.destinationMs,
        });
      } else {
        await waitForRelationshipDepthBeat(manualBeatTiming.sourceMs);
        await restoreAtHandoff(false);
        await waitForRelationshipDepthBeat(manualBeatTiming.destinationMs);
      }
      if (relationshipDepthRunRef.current !== runId) return;
      const settled = reduceRelationshipDepthTransition(controllerState, {
        type: "beat-complete",
        transitionId: controllerState.id,
      });
      controllerState = settled.state;
      stack.pop();
      setRelationshipDepthReturnDepth(stack.length);
      setRelationshipDepthReturnLabel(stack.at(-1)?.returnLabel ?? null);
      flushSync(() => setRelationshipDepthControllerState(controllerState));
      setRelationshipDepthAnnouncement(
        `Returned to ${checkpoint.returnLabel}.`,
      );
      restoreRelationshipDepthFocus(checkpoint);
    } catch (err) {
      setError(
        err instanceof Error
          ? err.message
          : "Could not return to the previous Zen space.",
      );
      setRelationshipDepthControllerState(settledTransition);
    } finally {
      sourceElement?.style.removeProperty("view-transition-name");
      (destinationElement as HTMLElement | null)?.style.removeProperty(
        "view-transition-name",
      );
      delete root.dataset.relationshipDepthMotion;
      delete root.dataset.relationshipDepthAtmosphere;
      delete root.dataset.relationshipDepthDirection;
      delete root.dataset.relationshipDepthRenderer;
    }
  }

  async function visitZenHome(
    nextBotId: string | null,
    options: ZenHomeVisitOptions = {},
  ): Promise<void> {
    if (pendingReplyVisible || chatAssistantRevealInProgress) return;
    const sessionNotStarted = zenSessionHasNotStarted();
    const currentBotId = zenPersonaBotIdRef.current ?? detail?.botId ?? null;
    const selectedConversationIsZen = Boolean(
      selectedId &&
      conversations.some(
        (conversation) =>
          conversation.id === selectedId && conversation.mode === "zen",
      ),
    );
    const sourceIsHome = Boolean(
      options.sourceSurface === "home" ||
      (options.sourceSurface !== "library" &&
        !botGroupWaitingRoomRenderActive &&
        (detail?.mode === "zen" ||
          (!sessionNotStarted && detail?.mode !== "chat") ||
          selectedConversationIsZen ||
          relationshipDepthCheckpointStackRef.current.length > 0)),
    );
    if (currentBotId === nextBotId && sourceIsHome) {
      focusDraftInput();
      return;
    }
    const destinationIdentity = relationshipDepthIdentity(nextBotId);
    if (sourceIsHome) {
      rememberZenHomeDraft(
        relationshipDepthIdentity(currentBotId),
        draftLiveRef.current,
      );
    }
    const requestedDestination = options.destination ?? { kind: "infer" };
    const explicitConversationId =
      requestedDestination.kind === "conversation"
        ? requestedDestination.conversationId
        : null;
    const shouldKeepPendingHome = requestedDestination.kind === "pending";
    const shouldResolvePersistedHome =
      !shouldKeepPendingHome &&
      (requestedDestination.kind === "resolve" ||
        requestedDestination.kind === "infer");
    const resolvedPersonaHome =
      shouldResolvePersistedHome && nextBotId
        ? resolveExistingPersonaHome(nextBotId, conversations)
        : null;
    const existingConversationId =
      explicitConversationId ?? resolvedPersonaHome?.conversationId ?? null;
    // Every ordinary Home visit resumes the latest continuation that History
    // can prove belongs to that relationship. Only explicit `pending` visits
    // and the New chat affordances are allowed to arm a fresh conversation.
    // Missing or contradictory History still fails closed to an unsaved
    // surface instead of guessing from presentation-era bot fields.
    const shouldOpenPrismHome =
      shouldResolvePersistedHome && nextBotId === null;
    const shouldOpenPersistedHome = Boolean(
      existingConversationId || shouldOpenPrismHome,
    );
    const destinationDraft =
      zenHomeDraftsRef.current.get(destinationIdentity) ?? "";
    const resolvedSourceElement =
      options.sourceElement ??
      visibleRelationshipDepthAnchor(
        sourceIsHome ? "home" : "library",
        sourceIsHome
          ? relationshipDepthIdentity(currentBotId)
          : destinationIdentity,
      );
    const homeNavigationFocus = document.querySelector<HTMLElement>(
      'button[aria-label="Zen Home"]',
    );
    const checkpoint = sourceIsHome
      ? captureHomeRelationshipDepthCheckpoint(
          currentBotId,
          homeNavigationFocus ??
            (document.activeElement instanceof HTMLElement
              ? document.activeElement
              : resolvedSourceElement),
        )
      : captureLibraryRelationshipDepthCheckpoint(
          destinationIdentity,
          resolvedSourceElement,
          options.focusElement ?? resolvedSourceElement,
        );
    const destinationActivityKey = existingConversationId
      ? `conversation:${existingConversationId}`
      : shouldOpenPrismHome
        ? `open:${destinationIdentity}`
        : "pending";
    const destination: RelationshipDepthEndpoint = {
      key: `home:${destinationIdentity}:${destinationActivityKey}`,
      surface: "home",
      contextKey: destinationIdentity,
      identityKey: destinationIdentity,
      activityKey: destinationActivityKey,
    };
    const destinationName =
      nextBotId === null
        ? "Prism Home"
        : `${bots.find((bot) => bot.id === nextBotId)?.name ?? "persona"}'s Home`;

    setError(null);
    try {
      await runRelationshipDepthTransition({
        checkpoint,
        destination,
        destinationLabel: destinationName,
        sourceElement: resolvedSourceElement,
        nativeCommitSafe: !shouldOpenPersistedHome,
        commitDestination: shouldOpenPersistedHome
          ? async () => {
              const conversationId = existingConversationId
                ? existingConversationId
                : (
                    await api<{ conversationId: string }>(
                      "/api/conversations/zen/open",
                      {
                        method: "POST",
                        body: JSON.stringify({ botId: nextBotId }),
                      },
                    )
                  ).conversationId;
              clearConversationUnread(conversationId);
              if (!existingConversationId) await refreshConversations();
              await refreshConversation(conversationId);
              options.commitSourceVisit?.();
              setSelectedBotId(nextBotId);
              setSandboxGridSelectedBotId(nextBotId);
              setZenPersonaBotId(nextBotId);
              setChatBotOverride(undefined);
              setChatAutoRestoreSuppressed(false);
              setForceNewConversationOnNextSend(false);
              setComposerDraftNow(destinationDraft);
            }
          : () => {
              options.commitSourceVisit?.();
              relationshipDepthTitleRefreshSuppressionRef.current =
                selectedIdRef.current;
              armFreshZenPersona(nextBotId);
              setComposerDraftNow(destinationDraft);
            },
      });
    } catch (err) {
      await restoreRelationshipDepthCheckpoint(checkpoint).catch(
        () => undefined,
      );
      restoreRelationshipDepthFocus(checkpoint);
      setError(
        err instanceof Error ? err.message : "Could not open this Zen Home.",
      );
    }
  }

  useEffect(() => {
    if (view !== "chat" || relationshipDepthReturnDepth <= 0) return;
    const handleRelationshipDepthEscape = (event: KeyboardEvent): void => {
      if (event.key !== "Escape" || event.defaultPrevented) return;
      if (emptyStateSearchActive || panel !== null) return;
      if (
        (pendingReplyVisible || chatAssistantRevealInProgress) &&
        !relationshipDepthCanInterruptActiveTurn
      ) {
        return;
      }
      event.preventDefault();
      void returnFromRelationshipDepth("escape");
    };
    window.addEventListener("keydown", handleRelationshipDepthEscape);
    return () =>
      window.removeEventListener("keydown", handleRelationshipDepthEscape);
  }, [
    emptyStateSearchActive,
    panel,
    pendingReplyVisible,
    chatAssistantRevealInProgress,
    relationshipDepthCanInterruptActiveTurn,
    relationshipDepthReturnDepth,
    returnFromRelationshipDepth,
    view,
  ]);

  const commitEmptyStateBotSelection = useCallback(
    (botId: string, sourceElement: HTMLElement | null = null) => {
      if (view === "chat") {
        void visitZenHome(botId, {
          sourceElement,
          sourceSurface: "library",
        });
        return;
      }
      cancelCanvasBotMarqueeGesture();
      setCanvasSelectedBotIds((current) =>
        current.size === 0 ? current : new Set(),
      );
      if (selectedBotId === botId) {
        setSandboxGridSelectedBotId(botId);
        focusDraftInput();
        return;
      }
      cancelPendingEmptyStateSearchOpen();
      setCanvasBotSwitchOverlayPhase("enter");
      canvasBotSwitchTransitionStartedAtRef.current = Date.now();
      pendingCanvasBotUnfoldRef.current = true;
      setCanvasBotSwitchTransitioning(true);
      // Committing a bot exits visible lens mode, but keeps the current
      // filtered/zoomed bot view intact. `emptyStateLensVisible` hides the
      // slider while `shellStyle` lets the selected bot own the interface
      // color, so the hue lens no longer competes with the bot accent.
      setSelectedBotId(botId);
      setSandboxGridSelectedBotId(botId);
      setEmptyStateSearchOpen(false);
      setEmptyStateBotNameFilter("");
      spotlightTypingArmedRef.current = false;
      focusDraftInput();
    },
    [
      cancelCanvasBotMarqueeGesture,
      cancelPendingEmptyStateSearchOpen,
      focusDraftInput,
      selectedBotId,
      visitZenHome,
      view,
    ],
  );

  useEffect(() => {
    if (view !== "chat") return;
    const botId = pendingImportedChatBotSelectionRef.current;
    if (!botId) return;
    pendingImportedChatBotSelectionRef.current = null;
    commitEmptyStateBotSelection(botId);
  }, [commitEmptyStateBotSelection, view]);

  function selectImportedBotInChatMode(botId: string): void {
    pendingImportedChatBotSelectionRef.current = null;
    if (view !== "chat") {
      pendingImportedChatBotSelectionRef.current = botId;
      navigateToView("chat");
      return;
    }
    setConversationStarterPrompts(null);
    setSelectedId(null);
    setDetail(null);
    setChatBotOverride(undefined);
    setSidebarOpen(false);
    commitEmptyStateBotSelection(botId);
  }

  const openEmptyStateBotSearchFromTyping = useCallback(
    (typedCharacter: string) => {
      cancelPendingEmptyStateSearchOpen();
      setSelectedBotId(null);
      setSandboxGridSelectedBotId(null);
      setEmptyStateBotNameFilter((current) =>
        current.length > 0 ? `${current}${typedCharacter}` : typedCharacter,
      );
      if (hueFilterCenter !== null) {
        setEmptyStateSearchOpen(false);
        startBotPickerReturnToAll();
        showEmptyStateSearchAfterReturn();
        return;
      }
      setHueFilterCenter(null);
      showEmptyStateSearchAfterReturn();
    },
    [
      cancelPendingEmptyStateSearchOpen,
      hueFilterCenter,
      showEmptyStateSearchAfterReturn,
      startBotPickerReturnToAll,
    ],
  );

  const handleComposerBotSelectionChange = useCallback(
    (next: string) => {
      const nextBotId = next || null;
      setSelectedBotId(nextBotId);
      // Empty-canvas picker controls need to keep their highlighted tile and
      // immersive Hub persona in sync when selection comes from the dropdown.
      if (view === "chat") {
        setZenPersonaBotId(nextBotId);
        setSandboxGridSelectedBotId(nextBotId);
      } else if (view === "sandbox") {
        setSandboxGridSelectedBotId(nextBotId);
      }
    },
    [view],
  );

  function zenSessionHasNotStarted(): boolean {
    return view === "chat" && (!detail || detail.messages.length === 0);
  }

  function armFreshZenPersona(nextBotId: string | null): void {
    if (zenSessionHasNotStarted() && zenPersonaBotIdRef.current !== nextBotId) {
      rotateZenFallbackWallpaperSeed();
    }
    if (view === "chat") {
      selectedIdRef.current = null;
      detailIdRef.current = null;
      conversationSurfaceLoadingTokenRef.current += 1;
      setSelectedId(null);
      setDetail(null);
      setChatAutoRestoreSuppressed(true);
      setForceNewConversationOnNextSend(true);
    }
    setZenPersonaBotId(nextBotId);
    setSelectedBotId(nextBotId);
    setSandboxGridSelectedBotId(nextBotId);
    setChatBotOverride(undefined);
    closeEmptyStateBotSearch();
    focusDraftInput();
  }

  function commitZenPersonaTransition(nextBotId: string | null): void {
    if (pendingReplyVisible) return;
    const fromBotId = zenPersonaBotIdRef.current;
    if (fromBotId === nextBotId) return;

    const style = resolveZenPersonaTransitionStyle(zenPersonaTransitionChoice, {
      fromBotId,
      toBotId: nextBotId,
    });

    if (style === "off") {
      settleZenPersonaPresence(nextBotId);
      setZenPersonaBotId(nextBotId);
      setSelectedBotId(nextBotId);
      setChatBotOverride(undefined);
      closeEmptyStateBotSearch();
      focusDraftInput();
      return;
    }

    beginZenPersonaPresenceTransition({
      fromBotId,
      toBotId: nextBotId,
      style,
    });
    setZenPersonaBotId(nextBotId);
    const syntheticSubmit = {
      preventDefault() {
        // no-op; used so Persona transitions share the normal submit path
      },
    } as React.FormEvent<HTMLFormElement>;
    void sendMessage(syntheticSubmit, {
      draftOverride: "",
      skipComposerHistory: true,
      personaTransition: {
        fromBotId,
        toBotId: nextBotId,
        source: "picker",
        style,
      },
    });
  }

  function handleZenPersonaSelectionChange(next: string): void {
    const nextBotId = next || null;
    void visitZenHome(nextBotId);
  }

  function handleZenMentionPersonaSelection(botId: string): void {
    if (zenSessionHasNotStarted()) {
      armFreshZenPersona(botId);
      return;
    }
    commitZenPersonaTransition(botId);
  }

  async function persistZenPersonaTransitionChoice(
    next: ZenPersonaTransitionChoice,
  ): Promise<void> {
    const normalized = normalizeZenPersonaTransitionChoice(next);
    if (zenPersonaTransitionChoice === normalized) return;
    const previousChoice = zenPersonaTransitionChoice;
    setZenPersonaTransitionChoice(normalized);
    setSettings((previous) =>
      previous
        ? { ...previous, zenPersonaTransitionChoice: normalized }
        : previous,
    );
    if (!settings) return;
    setError(null);
    setPanelError(null);
    try {
      await api("/api/settings", {
        method: "PATCH",
        body: JSON.stringify({ zenPersonaTransitionChoice: normalized }),
      });
      await refreshSettings();
    } catch (err) {
      setZenPersonaTransitionChoice(previousChoice);
      setSettings((previous) =>
        previous
          ? { ...previous, zenPersonaTransitionChoice: previousChoice }
          : previous,
      );
      setError(
        err instanceof Error
          ? err.message
          : "Guest handoff setting failed to save.",
      );
    }
  }

  function renderZenPersonaTransitionChoiceControl(
    compact = false,
  ): React.ReactNode {
    return (
      <ZenPersonaTransitionChoiceControl
        value={zenPersonaTransitionChoice}
        onChange={(next) => {
          void persistZenPersonaTransitionChoice(next);
        }}
        compact={compact}
      />
    );
  }

  useEffect(() => {
    if (!emptyStateTypingSearchAvailable) return;
    function handlePageTyping(event: KeyboardEvent) {
      if (
        event.defaultPrevented ||
        event.metaKey ||
        event.ctrlKey ||
        event.altKey
      )
        return;
      const activeElement = document.activeElement;
      if (event.key === "Tab") {
        if (!emptyStateSearchActive && !spotlightTypingArmedRef.current) return;
        if (
          activeElement instanceof Element &&
          activeElement.closest(
            "[data-starter-compose-surface='true'],[data-prism-compose-field='true']",
          )
        ) {
          return;
        }
        const spotlightInput = emptyStateSearchActive
          ? emptyStateSpotlightInputRef.current
          : emptyStateSearchInputRef.current;
        const focusSpotlight = () => {
          if (hueFilterCenter !== null) {
            setEmptyStateSearchOpen(false);
            startBotPickerReturnToAll();
            focusEmptyStateSearchAfterReturn();
            return;
          }
          setHueFilterCenter(null);
          setEmptyStateSearchOpen(true);
          window.setTimeout(() => {
            spotlightInput?.focus({ preventScroll: true });
          }, 0);
        };

        event.preventDefault();
        if (!emptyStateSearchActive) {
          focusSpotlight();
          return;
        }
        if (activeElement === spotlightInput) {
          closeEmptyStateBotSearchAndFocusDraft();
          return;
        }
        spotlightInput?.focus({ preventScroll: true });
        return;
      }
      const activeElementIsEditable =
        activeElement instanceof HTMLElement &&
        (activeElement.isContentEditable ||
          activeElement instanceof HTMLInputElement ||
          activeElement instanceof HTMLTextAreaElement ||
          activeElement instanceof HTMLSelectElement);
      if (activeElementIsEditable) return;
      const pageHasFocus =
        !activeElement ||
        activeElement === document.body ||
        activeElement === document.documentElement;
      const spotlightHasFocusFallback = emptyStateSearchActive || pageHasFocus;
      if (!spotlightHasFocusFallback) return;

      if (event.key === "Backspace" && emptyStateSearchActive) {
        event.preventDefault();
        setEmptyStateBotNameFilter((current) => {
          if (current.length <= 1) {
            window.setTimeout(closeEmptyStateBotSearchAndFocusDraft, 0);
            return "";
          }
          return current.slice(0, -1);
        });
        return;
      }
      if (event.key === "Escape" && emptyStateSearchActive) {
        event.preventDefault();
        closeEmptyStateBotSearch();
        return;
      }
      if (event.key.length !== 1 || event.key.trim().length === 0) return;
      if (!emptyStateSearchActive && !spotlightTypingArmedRef.current) return;
      if (!emptyStateSearchActive && !pageHasFocus) return;
      event.preventDefault();
      openEmptyStateBotSearchFromTyping(event.key);
    }
    window.addEventListener("keydown", handlePageTyping);
    return () => window.removeEventListener("keydown", handlePageTyping);
  }, [
    closeEmptyStateBotSearchAndFocusDraft,
    closeEmptyStateBotSearch,
    emptyStateSearchActive,
    emptyStateTypingSearchAvailable,
    focusEmptyStateSearchAfterReturn,
    hueFilterCenter,
    openEmptyStateBotSearchFromTyping,
    startBotPickerReturnToAll,
  ]);

  useEffect(() => {
    if (!emptyStateSearchActive) return;
    function isEmptyStateSearchKeepAliveTarget(
      target: EventTarget | null,
    ): boolean {
      if (!(target instanceof Element)) return false;
      if (emptyStateSpotlightRef.current?.contains(target)) return true;
      if (emptyStateSearchRef.current?.contains(target)) return true;
      // Bot tiles live outside the Spotlight field; keep the filter alive while
      // picking, right-clicking, or using the bot action menu.
      if (target.closest('[data-bot-picker-frame="true"]')) return true;
      if (target.closest("[data-prism-menu-owner]")) return true;
      if (
        botContextMenuRef.current instanceof Node &&
        botContextMenuRef.current.contains(target)
      ) {
        return true;
      }
      return false;
    }
    function handleDocumentClick(event: MouseEvent) {
      if (isEmptyStateSearchKeepAliveTarget(event.target)) return;
      closeEmptyStateBotSearch();
    }
    document.addEventListener("click", handleDocumentClick);
    return () => document.removeEventListener("click", handleDocumentClick);
  }, [closeEmptyStateBotSearch, emptyStateSearchActive]);

  const toggleCanvasBotSelection = useCallback((botId: string) => {
    setCanvasSelectedBotIds((current) => {
      const next = new Set(current);
      if (next.has(botId)) {
        next.delete(botId);
      } else {
        next.add(botId);
      }
      return stringSetsEqual(current, next) ? current : next;
    });
  }, []);

  const selectCanvasBot = useCallback((botId: string) => {
    setCanvasSelectedBotIds((current) => {
      if (current.has(botId)) return current;
      const next = new Set(current);
      next.add(botId);
      return next;
    });
  }, []);

  const focusHueLensOnBot = useCallback(
    (bot: Bot) => {
      if (emptyStateSearchActive || !botHasFilterableColor(bot)) return;
      const { h } = hexToHsl(bot.color!.trim());
      setHueFilterCenter(hueLensPositionForHue(h));
    },
    [emptyStateSearchActive],
  );

  // Touch keyboard-balloon handlers. Shared by both the Chat-mode and
  // Sandbox-mode empty-state picker frames. Active only when the gesture
  // is genuine touch input AND the picker is in hue-navigation territory:
  // Stage 3+ on mobile, Stage 4+ elsewhere. Completed taps select the bot
  // directly; capture keeps long-press/context handling stable as fingers move.
  const handleTouchPickerDown = useCallback(
    (event: React.PointerEvent<HTMLDivElement>, geom: PickerGeometry) => {
      if (event.pointerType !== "touch") return;
      if (!pickerUsesHueNavigation(geom, viewportWidth)) return;
      // Capture so subsequent move/up events route here even if the
      // finger drifts off this element. Without capture, the user's
      // finger crossing into a child tile would lose the gesture.
      event.currentTarget.setPointerCapture(event.pointerId);
      touchPreviewPointerIdRef.current = event.pointerId;
    },
    [viewportWidth],
  );

  const handleTouchPickerMove = useCallback(
    (event: React.PointerEvent<HTMLDivElement>) => {
      if (event.pointerId !== touchPreviewPointerIdRef.current) return;
      cancelBotContextLongPress(event.pointerId);
    },
    [cancelBotContextLongPress],
  );

  const handleTouchPickerUp = useCallback(
    (event: React.PointerEvent<HTMLDivElement>, _geom: PickerGeometry) => {
      if (event.pointerId !== touchPreviewPointerIdRef.current) return;
      cancelBotContextLongPress(event.pointerId);
      if (botContextSuppressClickRef.current) {
        event.preventDefault();
        setTouchPreview(null);
        touchPreviewPointerIdRef.current = null;
        if (event.currentTarget.hasPointerCapture(event.pointerId)) {
          event.currentTarget.releasePointerCapture(event.pointerId);
        }
        window.setTimeout(() => {
          botContextSuppressClickRef.current = false;
        }, 150);
        return;
      }
      const botId = findBotIdAtPoint(event.clientX, event.clientY);
      if (botId) {
        commitEmptyStateBotSelection(botId);
      }
      setTouchPreview(null);
      touchPreviewPointerIdRef.current = null;
      if (event.currentTarget.hasPointerCapture(event.pointerId)) {
        event.currentTarget.releasePointerCapture(event.pointerId);
      }
    },
    [cancelBotContextLongPress, commitEmptyStateBotSelection],
  );

  const handleTouchPickerCancel = useCallback(
    (event: React.PointerEvent<HTMLDivElement>) => {
      if (event.pointerId !== touchPreviewPointerIdRef.current) return;
      cancelBotContextLongPress(event.pointerId);
      setTouchPreview(null);
      touchPreviewPointerIdRef.current = null;
      if (event.currentTarget.hasPointerCapture(event.pointerId)) {
        event.currentTarget.releasePointerCapture(event.pointerId);
      }
    },
    [cancelBotContextLongPress],
  );

  const renderEmptyStateBotSearch = (): React.JSX.Element | null => {
    const persistentEmptyCanvasSpotlight =
      (view === "chat" || view === "sandbox") &&
      (!detail || detail.messages.length === 0);
    if (
      (!emptyStateSearchActive && !persistentEmptyCanvasSpotlight) ||
      pickerSourceBots.length === 0
    )
      return null;
    const resultLabel =
      normalizedEmptyStateBotNameFilter.length === 0
        ? "Start typing to filter bots by name."
        : filteredBots.length === 1
          ? "1 bot found"
          : `${filteredBots.length} bots found`;
    return (
      <div
        ref={emptyStateSpotlightRef}
        className={styles.emptyStateSearch}
        role="search"
      >
        <div className={styles.emptyStateSearchRow}>
          <div className={styles.emptyStateSearchField}>
            <span className={styles.emptyStateSearchGlyph} aria-hidden="true">
              ⌕
            </span>
            <input
              ref={emptyStateSpotlightInputRef}
              type="search"
              value={emptyStateBotNameFilter}
              onChange={(event) =>
                setEmptyStateBotNameFilter(event.currentTarget.value)
              }
              onKeyDown={(event) => {
                if (event.key === "Escape") {
                  event.preventDefault();
                  closeEmptyStateBotSearch();
                  return;
                }
                if (
                  event.key === "Backspace" &&
                  emptyStateBotNameFilter.length <= 1
                ) {
                  event.preventDefault();
                  closeEmptyStateBotSearchAndFocusDraft();
                }
              }}
              className={styles.emptyStateSearchInput}
              placeholder="Search bots"
              aria-label="Search bots by name"
            />
          </div>
          {persistentEmptyCanvasSpotlight ? (
            <div className={styles.emptyStateSearchGroupPicker}>
              <BotLibraryGroupPicker
                value={botLibraryGroupPickerValue}
                options={botLibraryGroupFilterOptions}
                onChange={applyBotLibraryHeaderFilter}
                onCreateGroup={() => openCreateBotLibraryGroupDialog([])}
                resolvedTheme={resolvedTheme}
                showCounts={false}
                dismissPopoversSignal={composerPopoverDismissSignal}
              />
            </div>
          ) : null}
        </div>
        <div className={styles.emptyStateSearchMeta} aria-live="polite">
          {resultLabel}
        </div>
      </div>
    );
  };

  const renderCanvasBotBrowserRail = ({
    variant,
    style,
    railRef,
    searchInputRef,
    searchValue,
    onSearchChange,
    onSearchKeyDown,
    searchPlaceholder,
    searchAriaLabel,
    botPicker,
    groupPicker,
    resultLabel,
  }: {
    variant: "chat" | "coffee";
    style?: React.CSSProperties;
    railRef?: React.Ref<HTMLDivElement>;
    searchInputRef?: React.Ref<HTMLInputElement>;
    searchValue: string;
    onSearchChange: (nextValue: string) => void;
    onSearchKeyDown?: (event: React.KeyboardEvent<HTMLInputElement>) => void;
    searchPlaceholder: string;
    searchAriaLabel: string;
    botPicker?: React.ReactNode;
    groupPicker: React.ReactNode;
    resultLabel?: string;
  }): React.JSX.Element => {
    const railClassName = [
      styles.canvasBotBrowserRail,
      variant === "chat"
        ? styles.chatCanvasPickerControls
        : styles.coffeeCanvasPickerControls,
    ].join(" ");
    return (
      <div
        ref={railRef}
        className={railClassName}
        style={style}
        role="search"
        data-bot-browser-variant={variant}
        data-starter-bot-affordance={variant === "chat" ? "true" : undefined}
        data-zen-live-bot-chrome-avoid={variant === "chat" ? "true" : undefined}
        onClick={(event) => event.stopPropagation()}
      >
        <label
          className={`${styles.coffeeSearchBar} ${styles.canvasBotBrowserSearch}`}
        >
          <span aria-hidden="true">⌕</span>
          <input
            ref={searchInputRef}
            type="search"
            value={searchValue}
            onChange={(event) => onSearchChange(event.currentTarget.value)}
            onKeyDown={onSearchKeyDown}
            placeholder={searchPlaceholder}
            aria-label={searchAriaLabel}
          />
        </label>
        {botPicker}
        {groupPicker}
        {resultLabel ? (
          <span className={styles.srOnly} aria-live="polite">
            {resultLabel}
          </span>
        ) : null}
      </div>
    );
  };

  const renderBotGroupImageBubbles = (
    variant: BotGroupImageBubbleVariant,
  ): React.JSX.Element | null => {
    const placements =
      variant === "waiting"
        ? botGroupWaitingImageBubbles
        : botGroupCompactImageBubbles;
    const focusedGroup = activeBotLibraryGroupFilter;
    if (!focusedGroup || placements.length === 0) return null;
    const receded = botGroupWaitingRoomTyping || zenPersonaBot !== null;
    return (
      <ul
        className={styles.botGroupImageBubbleLayer}
        data-group-image-bubbles={variant}
        data-group-image-bubble-count={placements.length}
        data-receded={receded ? "true" : undefined}
        aria-label={`Generated images from ${focusedGroup.name}`}
        aria-hidden={receded ? true : undefined}
      >
        {placements.map((placement) => {
          const image = botGroupImageRecordsById.get(placement.imageId);
          const bot = bots.find(
            (candidate) => candidate.id === placement.botId,
          );
          if (!image || image.hasLocalFile !== true || !bot) return null;
          const prompt = image.prompt?.trim() || "Untitled generated image";
          const glyph = isBotGlyphName(bot.glyph)
            ? bot.glyph
            : DEFAULT_PRISM_BOT_GLYPH;
          const label = `View image made with ${bot.name}: ${prompt}`;
          const bubbleStyle = {
            "--bot-group-image-x": `${placement.xPercent}%`,
            "--bot-group-image-y": `${placement.yPercent}%`,
            "--bot-group-image-size": `${placement.sizePx}px`,
            "--bot-group-image-tilt": `${placement.tiltDeg}deg`,
            "--bot-group-image-float-delay": `${placement.floatDelayMs}ms`,
            "--bot-group-image-float-duration": `${placement.floatDurationMs}ms`,
            "--bot-group-image-accent": normalizeAccentForTheme(
              bot.color ?? PRISM_DEFAULT_ACCENT,
              resolvedTheme,
            ),
          } as React.CSSProperties;
          return (
            <li
              key={placement.imageId}
              className={styles.botGroupImageBubble}
              data-group-image-bubble-id={placement.imageId}
              data-group-image-bubble-bot-id={placement.botId}
              style={bubbleStyle}
            >
              <button
                type="button"
                className={styles.botGroupImageBubbleButton}
                aria-label={label}
                title={label}
                disabled={receded}
                onClick={(event) => {
                  event.stopPropagation();
                  if (!receded) openImageLightbox(image);
                }}
              >
                <span
                  className={styles.botGroupImageBubbleVisual}
                  aria-hidden="true"
                >
                  {/* eslint-disable-next-line @next/next/no-img-element */}
                  <img
                    src={apiGeneratedImageThumbUrl(image.id)}
                    alt=""
                    loading="lazy"
                    decoding="async"
                    draggable={false}
                    onError={() => {
                      setBotGroupFailedImageIds((current) => {
                        if (current.has(image.id)) return current;
                        const next = new Set(current);
                        next.add(image.id);
                        return next;
                      });
                    }}
                  />
                  <span className={styles.botGroupImageBubbleOwner}>
                    <BotGlyph name={glyph} size={12} strokeWidth={2.2} />
                  </span>
                </span>
              </button>
            </li>
          );
        })}
      </ul>
    );
  };

  const handleBotGroupWaitingRoomPresenceClick = (
    placement: BotGroupWaitingRoomPlacement,
    sourceElement: HTMLElement,
    focusElement: HTMLElement,
  ): void => {
    if (botGroupWaitingRoomHandoff) return;
    const current = botGroupWaitingRoomVisitRef.current;
    if (!current) return;
    let next = current;
    let announcement = "";
    if (placement.role === "anchor") {
      next = engageBotGroupWaitingRoomAnchor(current, placement.botId);
      const engagedBot = botGroupWaitingRoomBotsById.get(placement.botId);
      announcement = engagedBot
        ? `${engagedBot.name} will stay in the conversation circle longer.`
        : "The conversation circle order changed.";
    } else {
      next = promoteBotGroupWaitingRoomRoamer(current, placement.botId);
      if (next === current) return;
      const demotedBotId = current.anchorBotIds.find(
        (botId) => !next.anchorBotIds.includes(botId),
      );
      const promotedBot = botGroupWaitingRoomBotsById.get(placement.botId);
      const demotedBot = demotedBotId
        ? botGroupWaitingRoomBotsById.get(demotedBotId)
        : null;
      announcement =
        promotedBot && demotedBot
          ? `${promotedBot.name} joined the conversation circle; ${demotedBot.name} is roaming nearby.`
          : "The conversation circle changed.";
    }
    const existingHome = resolveExistingPersonaHome(
      placement.botId,
      conversations,
    );
    void visitZenHome(placement.botId, {
      sourceElement,
      focusElement,
      destination: existingHome
        ? {
            kind: "conversation",
            conversationId: existingHome.conversationId,
          }
        : { kind: "pending" },
      commitSourceVisit: () => {
        botGroupWaitingRoomVisitRef.current = next;
        setBotGroupWaitingRoomVisit(next);
        setBotGroupWaitingRoomAnnouncement(announcement);
      },
    });
  };

  const renderFocusedBotLibraryGroupWaitingRoom = ({
    heroBot,
  }: {
    heroBot: Bot | null;
  }): React.JSX.Element | null => {
    const focusedGroup = activeBotLibraryGroupFilter;
    const visit = botGroupWaitingRoomVisit;
    if (
      !focusedGroup ||
      !visit ||
      heroBot ||
      !botGroupWaitingRoomRenderActive
    ) {
      return null;
    }
    const renderedPresences = botGroupWaitingRoomRenderedPresences.filter(
      ({ placement }) => botGroupWaitingRoomBotsById.has(placement.botId),
    );
    if (renderedPresences.length === 0) return null;
    const staticRosterNames = botGroupWaitingRoomVisiblePlacements(visit, {
      width: viewportWidth,
      height: viewportHeight,
    })
      .map(({ botId }) => botGroupWaitingRoomBotsById.get(botId)?.name)
      .filter((name): name is string => Boolean(name));
    const ambientPresentation = botGroupWaitingRoomAmbientPresentation;
    const ambientPair = ambientPresentation?.pair ?? null;
    const renderedPlacementsByBotId = new Map(
      renderedPresences.map(({ placement }) => [placement.botId, placement]),
    );
    const coffeeStaging =
      botGroupCoffeeStaging?.sourceGroupId === focusedGroup.id
        ? botGroupCoffeeStaging
        : null;
    const coffeeStagingRoster = coffeeStaging
      ? botGroupCoffeeStagingReplacementRoster({
          prompt: coffeeStaging.model.submittedPrompt,
          fullRosterBots: coffeeStaging.model.fullRosterBots,
          selectedBotIds: coffeeStaging.selectedBotIds,
        })
      : [];
    const coffeeStagingSelection = coffeeStaging
      ? summarizeBotGroupCoffeeStagingSelection(coffeeStaging.selectedBotIds)
      : null;
    const coffeeStagingSwapBot = coffeeStaging?.swapOutgoingBotId
      ? (botGroupWaitingRoomBotsById.get(coffeeStaging.swapOutgoingBotId) ??
        null)
      : null;
    const coffeeStagingTopicLength =
      coffeeStaging?.model.submittedPrompt.trim().length ?? 0;
    const coffeeStagingTopicTooLong =
      coffeeStagingTopicLength > COFFEE_TOPIC_MAX_LENGTH;

    return (
      <section
        ref={botGroupWaitingRoomRosterRef}
        className={styles.botGroupWaitingRoom}
        style={botLibraryGroupVisualStyle(
          focusedGroup,
          baseFilteredPanelBots,
          resolvedTheme,
        )}
        data-bot-group-waiting-room="true"
        data-room-visit-id={visit.visitSeed}
        data-room-viewport={`${viewportWidth}x${viewportHeight}`}
        data-room-presence-count={botGroupWaitingRoomVisiblePresenceCount}
        data-room-next-rotation-ms={visit.nextRotationDelayMs}
        data-room-rotation-paused={botGroupWaitingRoomPaused ? "true" : "false"}
        data-room-ambient-phase={
          botGroupWaitingRoomAmbient?.visitSeed === visit.visitSeed
            ? botGroupWaitingRoomAmbient.phase
            : "idle"
        }
        data-room-ambient-cycle={
          botGroupWaitingRoomAmbient?.visitSeed === visit.visitSeed
            ? botGroupWaitingRoomAmbient.cycle
            : 0
        }
        data-room-ambient-next-ms={
          botGroupWaitingRoomAmbient?.visitSeed === visit.visitSeed
            ? botGroupWaitingRoomAmbient.phaseDurationMs
            : undefined
        }
        data-room-ambient-paused={
          botGroupWaitingRoomAmbientIsPaused ? "true" : "false"
        }
        data-room-ambient-speaker={ambientPair?.speakerBotId}
        data-room-ambient-listener={ambientPair?.listenerBotId}
        data-room-handoff-order={botGroupWaitingRoomHandoff?.order}
        data-room-handoff-phase={botGroupWaitingRoomHandoff?.phase}
        data-reduced-motion={
          botGroupWaitingRoomReducedMotion ? "true" : undefined
        }
        data-starter-bot-affordance="true"
        data-zen-live-bot-chrome-avoid="true"
        aria-labelledby="bot-group-waiting-room-title"
        onClick={(event) => event.stopPropagation()}
        onPointerDownCapture={() =>
          setBotGroupWaitingRoomRosterInteracting(true)
        }
        onPointerUpCapture={() => {
          if (
            !botGroupWaitingRoomRosterRef.current?.contains(
              document.activeElement,
            )
          ) {
            setBotGroupWaitingRoomRosterInteracting(false);
          }
        }}
        onPointerCancelCapture={() =>
          setBotGroupWaitingRoomRosterInteracting(false)
        }
        onFocusCapture={() => setBotGroupWaitingRoomRosterInteracting(true)}
        onBlurCapture={(event) => {
          const nextFocus = event.relatedTarget;
          if (
            nextFocus instanceof Node &&
            event.currentTarget.contains(nextFocus)
          ) {
            return;
          }
          setBotGroupWaitingRoomRosterInteracting(false);
        }}
      >
        <p id="bot-group-waiting-room-title" className={styles.srOnly}>
          {focusedGroup.name} waiting room. Present now:{" "}
          {staticRosterNames.join(", ")}.
        </p>
        {coffeeStaging ? (
          <div
            ref={botGroupCoffeeStagingRef}
            className={styles.botGroupCoffeeStaging}
            role="region"
            aria-labelledby="bot-group-coffee-staging-title"
            tabIndex={-1}
            data-room-coffee-staging="true"
            data-ranking-strategy={coffeeStaging.model.rankingStrategy}
            data-staged-bot-count={coffeeStagingSelection?.count ?? 0}
          >
            <header className={styles.botGroupCoffeeStagingHeader}>
              <div>
                <span className={styles.botGroupCoffeeStagingEyebrow}>
                  Listen up
                </span>
                <h3 id="bot-group-coffee-staging-title">
                  Set the Coffee table
                </h3>
                <p>
                  PRISM ranked the bots already in view on this device. Choose
                  2-5, or swap in anyone else from {focusedGroup.name}.
                </p>
              </div>
              <span className={styles.botGroupCoffeeStagingPrivacy}>
                Local room read · no model call
              </span>
            </header>
            <blockquote className={styles.botGroupCoffeeStagingPrompt}>
              {coffeeStaging.model.submittedPrompt}
            </blockquote>
            <div className={styles.botGroupCoffeeStagingSummary} role="status">
              <strong>{coffeeStagingSelection?.count ?? 0} at the table</strong>
              <span>Choose 2-5 bots</span>
              {coffeeStagingTopicTooLong ? (
                <span data-kind="error">
                  Prompt is {coffeeStagingTopicLength} characters; Coffee allows{" "}
                  {COFFEE_TOPIC_MAX_LENGTH}.
                </span>
              ) : null}
            </div>
            <ul
              className={styles.botGroupCoffeeStagingRoster}
              aria-label={`${focusedGroup.name} Coffee staging roster`}
            >
              {coffeeStagingRoster.map((stagedBot, stagedIndex) => {
                const bot = botGroupWaitingRoomBotsById.get(stagedBot.id);
                if (!bot) return null;
                const glyph = isBotGlyphName(bot.glyph)
                  ? bot.glyph
                  : DEFAULT_PRISM_BOT_GLYPH;
                return (
                  <li
                    key={bot.id}
                    className={styles.botGroupCoffeeStagingBot}
                    data-selected={stagedBot.selected ? "true" : undefined}
                    data-reaction={stagedBot.reactionBand}
                    style={botAccentStyle(bot.color, resolvedTheme)}
                  >
                    <button
                      type="button"
                      className={styles.botGroupCoffeeStagingBotToggle}
                      data-room-coffee-staging-primary-focus={
                        stagedIndex === 0 ? "true" : undefined
                      }
                      aria-pressed={stagedBot.selected}
                      aria-label={
                        stagedBot.selected
                          ? `Remove ${bot.name} from the Coffee table`
                          : `Invite ${bot.name} to the Coffee table`
                      }
                      disabled={coffeeStaging.launching}
                      onClick={() =>
                        toggleBotGroupCoffeeStagingBot(stagedBot.id)
                      }
                    >
                      <span
                        className={styles.botGroupCoffeeStagingBotGlyph}
                        aria-hidden="true"
                      >
                        <BotGlyph name={glyph} size={21} strokeWidth={1.8} />
                      </span>
                      <span className={styles.botGroupCoffeeStagingBotCopy}>
                        <strong>{bot.name}</strong>
                        <span aria-label={stagedBot.reaction.accessibleLabel}>
                          {stagedBot.reaction.label}
                        </span>
                      </span>
                      <span
                        className={styles.botGroupCoffeeStagingBotState}
                        aria-hidden="true"
                      >
                        {stagedBot.selected ? "Seated" : "Invite"}
                      </span>
                    </button>
                    {stagedBot.selected ? (
                      <button
                        type="button"
                        className={styles.botGroupCoffeeStagingSwapButton}
                        aria-pressed={
                          coffeeStaging.swapOutgoingBotId === stagedBot.id
                        }
                        disabled={coffeeStaging.launching}
                        onClick={() =>
                          beginBotGroupCoffeeStagingSwap(stagedBot.id)
                        }
                      >
                        Swap
                      </button>
                    ) : null}
                  </li>
                );
              })}
            </ul>
            {coffeeStagingSwapBot ? (
              <div
                className={styles.botGroupCoffeeStagingSwapTray}
                role="group"
                aria-label={`Choose a replacement for ${coffeeStagingSwapBot.name}`}
              >
                <span>Replace {coffeeStagingSwapBot.name} with</span>
                <div>
                  {coffeeStagingRoster
                    .filter((bot) => !bot.selected)
                    .map((replacement) => (
                      <button
                        key={replacement.id}
                        type="button"
                        disabled={coffeeStaging.launching}
                        onClick={() =>
                          replaceBotGroupCoffeeStagingBot(replacement.id)
                        }
                      >
                        {replacement.name}
                      </button>
                    ))}
                </div>
              </div>
            ) : null}
            <footer className={styles.botGroupCoffeeStagingActions}>
              <button
                type="button"
                className={styles.botGroupCoffeeStagingCancel}
                disabled={coffeeStaging.launching}
                onClick={cancelBotGroupCoffeeStaging}
              >
                Cancel and edit prompt
              </button>
              <button
                type="button"
                className={styles.botGroupCoffeeStagingStart}
                disabled={
                  coffeeStaging.launching ||
                  coffeeStagingTopicTooLong ||
                  !coffeeStagingSelection?.canStart
                }
                onClick={startBotGroupCoffeeStaging}
              >
                {coffeeStaging.launching
                  ? "Opening Coffee..."
                  : `Start Coffee with ${coffeeStagingSelection?.count ?? 0}`}
              </button>
            </footer>
          </div>
        ) : (
          <>
            <ul
              className={styles.botGroupWaitingRoomRoster}
              aria-label={`${focusedGroup.name} waiting room roster`}
            >
              {renderedPresences.map(({ placement, phase }, placementIndex) => {
                const bot = botGroupWaitingRoomBotsById.get(placement.botId);
                if (!bot) return null;
                const glyph = isBotGlyphName(bot.glyph)
                  ? bot.glyph
                  : DEFAULT_PRISM_BOT_GLYPH;
                const accentStyle = botAccentStyle(bot.color, resolvedTheme);
                const ambientRole =
                  ambientPair?.speakerBotId === bot.id
                    ? "speaker"
                    : ambientPair?.listenerBotId === bot.id
                      ? "listener"
                      : null;
                const ambientPartnerId =
                  ambientRole === "speaker"
                    ? ambientPair?.listenerBotId
                    : ambientRole === "listener"
                      ? ambientPair?.speakerBotId
                      : null;
                const ambientPartnerPlacement = ambientPartnerId
                  ? renderedPlacementsByBotId.get(ambientPartnerId)
                  : null;
                const ambientFacing = ambientPartnerPlacement
                  ? ambientPartnerPlacement.xPercent >= placement.xPercent
                    ? "right"
                    : "left"
                  : null;
                const faceScaleY =
                  ambientFacing === "left"
                    ? 1
                    : BOT_AVATAR_CANONICAL_FACE_SCALE_Y;
                const ambientTalking =
                  ambientRole === "speaker" &&
                  ambientPresentation?.phase === "speaking" &&
                  !botPowerIsMutedV1(bot.powers);
                const placementStyle = {
                  ...accentStyle,
                  "--bot-group-room-x": `${placement.xPercent}%`,
                  "--bot-group-room-y": `${placement.yPercent}%`,
                  "--bot-group-room-scale": String(placement.scale),
                  "--bot-group-room-depth": String(placement.depth),
                  "--coffee-plate-emoji-face-scale-y": faceScaleY,
                  "--avatar-details-facing-scale-x":
                    botAvatarDetailsFacingScaleX(faceScaleY),
                  "--avatar-details-facing-offset-y":
                    botAvatarDetailsFacingOffsetY(faceScaleY),
                } as React.CSSProperties;
                return (
                  <li
                    key={bot.id}
                    className={styles.botGroupWaitingRoomPresence}
                    style={placementStyle}
                    data-room-presence-role={placement.role}
                    data-room-presence-bot-id={bot.id}
                    data-room-presence-state={phase}
                    data-room-presence-slot={placement.slot}
                    data-room-render-detail={
                      placement.role === "roamer" ? "reduced" : "full"
                    }
                    data-room-ambient-role={ambientRole ?? undefined}
                    data-room-ambient-facing={ambientFacing ?? undefined}
                    data-room-ambient-phase={
                      ambientRole ? ambientPresentation?.phase : undefined
                    }
                  >
                    <button
                      type="button"
                      className={styles.botGroupWaitingRoomPresenceButton}
                      data-tutorial-target="chat-bot-picker"
                      aria-label={`Visit ${bot.name}'s Zen Home`}
                      title={`Visit ${bot.name}'s Zen Home`}
                      disabled={phase !== "stable"}
                      onClick={(event) => {
                        const focusElement = event.currentTarget;
                        const sourceElement =
                          focusElement.querySelector<HTMLElement>(
                            '[data-relationship-depth-anchor="group-room"]',
                          ) ?? focusElement;
                        handleBotGroupWaitingRoomPresenceClick(
                          placement,
                          sourceElement,
                          focusElement,
                        );
                      }}
                    >
                      <span
                        className={styles.botGroupWaitingRoomPresenceBody}
                        data-room-transition-anchor={bot.id}
                        data-relationship-depth-anchor="group-room"
                        data-relationship-depth-identity={`bot:${bot.id}`}
                        aria-hidden="true"
                      >
                        <BotAmbientPresenceRig
                          theme={resolvedTheme}
                          isTalking={ambientTalking}
                          motionActive={
                            phase === "stable" && ambientRole === null
                          }
                          phaseOffsetSeconds={placementIndex * 1.8}
                        >
                          <ZenLiveBotMannequin
                            glyph={glyph}
                            faceStyle={resolveBotFaceStyleForBot(bot)}
                            faceScaleY={faceScaleY}
                            voicePreset={coffeeSeatVoicePreset(bot)}
                            isTalking={ambientTalking}
                            avatarSfx={
                              coffeeReplayActive && coffeeReplayUsesAudioMaster
                                ? null
                                : botAvatarSfxForBot(bot)
                            }
                            avatarSfxState={ambientTalking ? "talking" : "idle"}
                            mouthShape={
                              ambientTalking ? "open-small" : "closed"
                            }
                            moodHint={
                              placement.role === "anchor"
                                ? "attentive"
                                : "waiting"
                            }
                            scheduleKey={`waiting-room-${visit.visitSeed}-${bot.id}`}
                            forceBlinkPhase={
                              botGroupWaitingRoomReducedMotion ||
                              placement.role === "roamer"
                                ? "open"
                                : null
                            }
                            detailLevel={
                              placement.role === "roamer" ? "reduced" : "full"
                            }
                            screenMaterialSeed={botScreenMaterialSeedForBot(
                              bot,
                              bot.id,
                            )}
                            frameMaterialSeed={botFrameMaterialSeedForBot(
                              bot,
                              bot.id,
                            )}
                            avatarDetails={resolveBotAvatarDetails(bot)}
                            avatarDetailsColor={normalizeAccentForTheme(
                              bot.color ?? PRISM_DEFAULT_ACCENT,
                              resolvedTheme,
                            )}
                          />
                        </BotAmbientPresenceRig>
                      </span>
                      {ambientTalking && ambientPair ? (
                        <span
                          className={styles.botGroupWaitingRoomAmbientCue}
                          data-room-ambient-cue="true"
                          data-room-ambient-cue-id={ambientPair.cue.id}
                          aria-hidden="true"
                        >
                          <span
                            className={styles.botGroupWaitingRoomAmbientAction}
                          >
                            {ambientPair.cue.visualCue}
                          </span>
                          <span
                            className={styles.botGroupWaitingRoomAmbientBark}
                          >
                            {ambientPair.cue.microBark}
                          </span>
                        </span>
                      ) : null}
                      <span className={styles.botGroupWaitingRoomPresenceName}>
                        {bot.name}
                      </span>
                      <span className={styles.botGroupWaitingRoomPresenceRole}>
                        {placement.role === "anchor"
                          ? "In the circle"
                          : "Roaming"}
                      </span>
                    </button>
                  </li>
                );
              })}
            </ul>
          </>
        )}
        <span className={styles.srOnly} role="status" aria-live="polite">
          {botGroupWaitingRoomAnnouncement}
        </span>
      </section>
    );
  };

  const renderFocusedBotLibraryGroupHero = ({
    heroBot,
  }: {
    heroBot: Bot | null;
  }): React.JSX.Element | null => {
    const focusedBotLibraryGroup = activeBotLibraryGroupFilter;
    if (
      !focusedBotLibraryGroup ||
      pendingIncognito ||
      emptyStateSearchActive ||
      heroBot
    ) {
      return null;
    }

    const groupHeroBots = baseFilteredPanelBots;
    const groupDescription = focusedBotLibraryGroup.description.trim();
    const groupProtectedBotCount = groupHeroBots.filter((bot) =>
      isBotDeleteProtected(bot.id),
    ).length;
    const groupEyebrowLabel = botLibraryGroupDashboardEyebrowLabel(
      groupHeroBots.length,
      focusedBotLibraryGroup.builtIn ? undefined : BOT_LIBRARY_GROUP_BOT_CAP,
      groupProtectedBotCount,
    );
    const groupDeleteProtected = focusedBotLibraryGroup.deleteProtected;
    const nextGroupDeleteProtected = !groupDeleteProtected;
    const groupProtectionLabel = groupDeleteProtected
      ? "Allow deletion"
      : "Protect group";
    const groupProtectionTitle = groupDeleteProtected
      ? `Allow deletion for bots in ${focusedBotLibraryGroup.name}`
      : `Protect bots in ${focusedBotLibraryGroup.name} from deletion`;
    const groupExportTitle =
      groupHeroBots.length > 0
        ? `Export ${focusedBotLibraryGroup.name} as a bot collection`
        : `${focusedBotLibraryGroup.name} has no bots to export`;
    const groupMemberIds = new Set(groupHeroBots.map((bot) => bot.id));
    const groupAddableBotCount = sortedPanelBots.filter(
      (bot) => !groupMemberIds.has(bot.id),
    ).length;
    const groupIsFull = groupHeroBots.length >= BOT_LIBRARY_GROUP_BOT_CAP;
    const groupAddBotsTitle = groupIsFull
      ? `${focusedBotLibraryGroup.name} is full`
      : groupAddableBotCount === 0
        ? `Every Library bot is already in ${focusedBotLibraryGroup.name}`
        : `Add Library bots to ${focusedBotLibraryGroup.name}`;
    const groupAtmosphereAvailable =
      !focusedBotLibraryGroup.builtIn &&
      groupHeroBots.length >= BOT_LIBRARY_CUSTOM_GROUP_MIN_BOTS &&
      groupHeroBots.length <= BOT_LIBRARY_GROUP_BOT_CAP;
    const groupMarketplaceAtmosphere = resolveBotMarketplaceGroupAtmosphere(
      focusedBotLibraryGroup.marketplaceThemeId,
    );
    const groupAtmosphereTitle = focusedBotLibraryGroup.roomAtmosphere
      ? `Replace or clear ${focusedBotLibraryGroup.name}'s room atmosphere`
      : groupMarketplaceAtmosphere
        ? `Customize ${focusedBotLibraryGroup.name}'s marketplace atmosphere`
        : `Choose or generate ${focusedBotLibraryGroup.name}'s room atmosphere`;
    const openGroupActionsMenu = (anchor: PrismMenuAnchor) => {
      const entries: PrismMenuEntry[] = [
        {
          id: "protect-group",
          kind: "toggle",
          icon: <BotGlyph name={groupDeleteProtected ? "key" : "lock"} />,
          label: groupProtectionLabel,
          description: groupProtectionTitle,
          checked: groupDeleteProtected,
          onSelect: () =>
            setBotLibraryGroupDeleteProtection(
              focusedBotLibraryGroup.id,
              nextGroupDeleteProtected,
            ),
        },
        {
          id: "export-group",
          icon: <Download />,
          label: "Export group",
          description: groupExportTitle,
          disabled: groupHeroBots.length === 0 || botTransferBusy,
          disabledReason:
            groupHeroBots.length === 0
              ? "This group has no bots to export."
              : botTransferBusy
                ? "Finish the current transfer first."
                : undefined,
          onSelect: () =>
            exportBotsAsCollection(groupHeroBots, {
              group: {
                name: focusedBotLibraryGroup.name,
                description: focusedBotLibraryGroup.description,
              },
            }),
        },
      ];
      if (!focusedBotLibraryGroup.builtIn) {
        entries.push(
          {
            id: "edit-group",
            icon: <PencilLine />,
            label: "Edit details",
            onSelect: () => editBotLibraryGroup(focusedBotLibraryGroup.id),
          },
          { id: "delete-group-separator", kind: "separator" },
          {
            id: "delete-group",
            icon: <Trash2 />,
            label: "Delete group",
            tone: "danger",
            onSelect: () =>
              requestDeleteBotLibraryGroup(focusedBotLibraryGroup.id),
          },
        );
      }
      openMenu({
        id: `group-actions-${focusedBotLibraryGroup.id}`,
        label: `${focusedBotLibraryGroup.name} group actions`,
        anchor,
        accent: normalizeAccentForTheme(
          groupHeroBots[0]?.color ?? PRISM_DEFAULT_ACCENT,
          resolvedTheme,
        ),
        theme: resolvedTheme,
        minWidth: 224,
        entries,
      });
    };

    return (
      <div
        className={styles.botGroupHeroStage}
        data-room-variant={
          botGroupWaitingRoomRenderActive ? "waiting" : undefined
        }
      >
        <section
          className={styles.botGroupHero}
          style={botLibraryGroupVisualStyle(
            focusedBotLibraryGroup,
            groupHeroBots,
            resolvedTheme,
          )}
          data-starter-bot-affordance="true"
          data-zen-live-bot-chrome-avoid="true"
          data-room-variant={
            botGroupWaitingRoomRenderActive ? "waiting" : undefined
          }
          aria-labelledby="bot-library-group-hero-title"
          onClick={(event) => event.stopPropagation()}
          onContextMenu={(event) => {
            event.preventDefault();
            event.stopPropagation();
            openGroupActionsMenu({
              kind: "pointer",
              x: event.clientX,
              y: event.clientY,
            });
          }}
        >
          <header className={styles.botGroupHeroHeader}>
            <div className={styles.botGroupHeroCopy}>
              <span className={styles.botGroupHeroEyebrow}>
                {groupEyebrowLabel}
              </span>
              <h2 id="bot-library-group-hero-title">
                Explore {focusedBotLibraryGroup.name}
              </h2>
              {groupDescription ? <p>{groupDescription}</p> : null}
            </div>
            <div className={styles.botGroupHeroActions}>
              {!focusedBotLibraryGroup.builtIn ? (
                <button
                  type="button"
                  className={styles.botGroupHeroAction}
                  data-active={
                    focusedBotLibraryGroup.roomAtmosphere ||
                    groupMarketplaceAtmosphere
                      ? "true"
                      : undefined
                  }
                  data-tutorial-target="chat-group-atmosphere"
                  disabled={!groupAtmosphereAvailable}
                  onClick={() =>
                    void openBotGroupRoomAtmosphereDialog(
                      focusedBotLibraryGroup.id,
                    )
                  }
                  aria-label={groupAtmosphereTitle}
                  title={groupAtmosphereTitle}
                >
                  <ImageGlyph size={14} strokeWidth={2.05} aria-hidden="true" />
                  <span>Atmosphere</span>
                </button>
              ) : null}
              {!focusedBotLibraryGroup.builtIn ? (
                <button
                  type="button"
                  className={styles.botGroupHeroAction}
                  disabled={groupIsFull || groupAddableBotCount === 0}
                  onClick={() =>
                    openAddBotFromLibraryGroupDialog(focusedBotLibraryGroup.id)
                  }
                  aria-label={groupAddBotsTitle}
                  title={groupAddBotsTitle}
                >
                  <Plus size={14} strokeWidth={2.2} aria-hidden="true" />
                  <span>Add bots</span>
                </button>
              ) : null}
              <button
                type="button"
                className={styles.botGroupHeroAction}
                aria-label={`Open ${focusedBotLibraryGroup.name} group actions`}
                title="Group actions"
                onClick={(event) =>
                  openGroupActionsMenu({
                    kind: "element",
                    element: event.currentTarget,
                    preferredPlacement: "bottom-end",
                  })
                }
              >
                <MenuIcon size={14} strokeWidth={2.05} aria-hidden="true" />
                <span>Group actions</span>
              </button>
            </div>
          </header>
        </section>
      </div>
    );
  };

  const renderChatCanvasPickerControls = (
    style?: React.CSSProperties,
  ): React.JSX.Element | null => {
    const standaloneSpotlightOwnsSearch =
      (view === "chat" || view === "sandbox") &&
      (!detail || detail.messages.length === 0);
    if (
      (view !== "chat" && view !== "sandbox") ||
      sortedPanelBots.length === 0 ||
      standaloneSpotlightOwnsSearch
    )
      return null;
    const resultLabel =
      normalizedEmptyStateBotNameFilter.length === 0
        ? "Type to filter bots by name."
        : filteredBots.length === 1
          ? "1 bot found"
          : `${filteredBots.length} bots found`;
    const botHasCommenced = !!detail && detail.messages.length > 0;
    const botPickerBots = botHasCommenced ? bots : filteredBots;
    const showRailBotPicker = view === "sandbox" || botHasCommenced;
    const botPicker =
      showRailBotPicker && botPickerBots.length > 0 ? (
        <ComposerBotPicker
          value={selectedBotId ?? ""}
          onChange={handleComposerBotSelectionChange}
          bots={botPickerBots}
          resolvedTheme={resolvedTheme}
          placement="down"
          title={
            !detail
              ? "Choose a starter bot for this chat. You can also pick directly from the grid below."
              : undefined
          }
          ariaLabel="Bot for the next message"
          showName={botHasCommenced}
          enableFilters
          hueFilterCenter={hueFilterCenter}
          onHueChange={setHueFilterCenter}
          hueLensAvailable={hueLensAvailable}
          hueLensTrackGradient={hueLensTrackGradient}
          hueLensTrackSegments={hueLensTrackSegments}
          dismissPopoversSignal={composerPopoverDismissSignal}
          privateTone={appWidePrivateMode}
        />
      ) : null;
    return renderCanvasBotBrowserRail({
      variant: "chat",
      style,
      railRef: emptyStateSearchRef,
      searchInputRef: emptyStateSearchInputRef,
      searchValue: emptyStateBotNameFilter,
      onSearchChange: setEmptyStateBotNameFilter,
      onSearchKeyDown: (event) => {
        if (event.key === "Escape") {
          event.preventDefault();
          closeEmptyStateBotSearchAndFocusDraft();
        }
      },
      searchPlaceholder: "Search or add bots...",
      searchAriaLabel: "Search bots for Chat",
      botPicker,
      groupPicker: (
        <BotLibraryGroupPicker
          value={botLibraryGroupPickerValue}
          options={botLibraryGroupFilterOptions}
          onChange={applyBotLibraryHeaderFilter}
          onCreateGroup={() => openCreateBotLibraryGroupDialog([])}
          resolvedTheme={resolvedTheme}
          showCounts={false}
          dismissPopoversSignal={composerPopoverDismissSignal}
        />
      ),
      resultLabel,
    });
  };

  const renderChatBotPickerGrid = (
    pickerGeom: PickerGeometry | null = null,
  ): React.JSX.Element | null => {
    if (pickerBots.length === 0) return null;
    const geom =
      pickerGeom ??
      pickerGeometry(
        pickerBots.length,
        viewportWidth,
        viewportHeight,
        activeHueLensGridOptions,
      );
    const rowWidth =
      geom.gridCols * geom.tileSize + (geom.gridCols - 1) * geom.tileGap;
    const frameStyle: React.CSSProperties = {
      "--picker-width": `${geom.pickerWidth}px`,
      "--picker-height": `${geom.pickerHeight}px`,
      "--picker-parallax-x": "0px",
      "--picker-parallax-y": "0px",
      "--picker-return-duration": `${BOT_PICKER_RETURN_ANIMATION_MS}ms`,
    } as React.CSSProperties;
    const pickerStyle: React.CSSProperties = {
      "--tile-size": `${geom.tileSize}px`,
      "--tile-gap": `${geom.tileGap}px`,
      "--tile-hover-scale": String(geom.hoverScale),
      "--grid-cols": geom.gridCols,
      width: `${rowWidth}px`,
    } as React.CSSProperties;
    const pickerClassName = [
      styles.chatBotPicker,
      geom.singleBot ? styles.chatBotPickerSingle : null,
      geom.threeBotStack ? styles.chatBotPickerThreeStack : null,
      geom.mobileColumnStack ? styles.chatBotPickerMobileColumnStack : null,
      geom.crosshairCursor ? styles.chatBotPickerCrosshair : null,
      geom.dotCursor ? styles.chatBotPickerDotCursor : null,
      geom.solidSwatch ? styles.chatBotPickerSolidSwatch : null,
      geom.compactPixelGrid ? styles.chatBotPickerPixelGrid : null,
      geom.radialRainbowGradient ? styles.chatBotPickerRainbowGradient : null,
    ]
      .filter(Boolean)
      .join(" ");
    const pickerCells = pickerFormationCells(pickerBots, geom);
    const compactBotLibraryGroupView =
      activeBotLibraryGroupFilter !== null &&
      pickerBots.length >= BOT_LIBRARY_CUSTOM_GROUP_MIN_BOTS &&
      pickerBots.length <= BOT_LIBRARY_GROUP_BOT_CAP;
    const focusedBotId = focusedCanvasBotId({
      view:
        view === "chat" || view === "sandbox" || view === "coffee"
          ? view
          : "other",
      sandboxGridSelectedBotId,
      zenPersonaBotId,
    });

    return (
      <div
        className={styles.chatBotPickerFrame}
        data-tutorial-target="chat-bot-picker"
        data-starter-bot-affordance="true"
        data-bot-picker-frame="true"
        data-single-bot={geom.singleBot ? "true" : undefined}
        data-returning-all={botPickerReturnAnimating ? "true" : undefined}
        data-search-active={emptyStateSearchActive ? "true" : undefined}
        data-touch-active={touchPreview ? "true" : undefined}
        style={frameStyle}
        onPointerLeave={(e) => {
          if (e.pointerType === "mouse" && !geom.compactPixelGrid) {
            resetPickerParallax(e.currentTarget);
          }
        }}
        onPointerDown={(e) => {
          handleTouchPickerDown(e, geom);
        }}
        onPointerMove={handleTouchPickerMove}
        onPointerUp={(e) => {
          handleTouchPickerUp(e, geom);
        }}
        onPointerCancel={handleTouchPickerCancel}
      >
        <BotPickerGrid
          className={pickerClassName}
          role="radiogroup"
          ariaLabel="Bot for this chat"
          style={pickerStyle}
        >
          {pickerCells.map((b, cellIndex) => {
            if (!b) {
              if (
                hueFilterActive ||
                pickerBots.length < pickerSourceBots.length ||
                compactBotLibraryGroupView ||
                geom.threeBotStack ||
                geom.mobileColumnStack
              )
                return null;
              return (
                <span
                  key={`blank-${cellIndex}`}
                  className={styles.chatBotTilePlaceholder}
                  aria-hidden="true"
                />
              );
            }
            const isSelected = focusedBotId === b.id;
            const isMarqueeSelected = canvasSelectedBotIds.has(b.id);
            const isProtected = isBotDeleteProtected(b.id);
            const isFavorite = favoriteBotIdSet.has(b.id);
            const tileTraits = [
              isFavorite ? "favorite" : null,
              isProtected ? "protected" : null,
            ].filter(Boolean);
            const rawColor = b.color?.trim();
            const accent = rawColor
              ? displayAccentForMode(
                  rawColor,
                  resolvedTheme,
                  appWidePrivateMode,
                )
              : null;
            const tileStyle = accent
              ? ({ "--bot-color": accent } as React.CSSProperties)
              : undefined;
            const showPixelGridGlyph = geom.compactPixelGrid;
            const showFeaturedName =
              !geom.compactPixelGrid &&
              geom.tileSize >= PICKER_TILE_NAME_MIN_SIZE;
            const tileGlyphSize = showPixelGridGlyph
              ? Math.max(
                  PICKER_PIXEL_GLYPH_MIN_SIZE,
                  Math.round(geom.tileSize * PICKER_PIXEL_GLYPH_RATIO),
                )
              : geom.glyphSize;
            const tileGlyphStroke = showPixelGridGlyph
              ? PICKER_PIXEL_GLYPH_STROKE
              : geom.glyphStroke;

            return (
              <BotPickerTile
                key={b.id}
                item={{
                  id: b.id,
                  name: b.name,
                  color: b.color,
                  glyph: b.glyph,
                }}
                selected={isSelected}
                marqueeSelected={isMarqueeSelected}
                favorite={isFavorite}
                protected={isProtected}
                accentColor={accent}
                forceName={showFeaturedName}
                geometry={{
                  ...geom,
                  glyphSize: tileGlyphSize,
                  glyphStroke: tileGlyphStroke,
                }}
                renderGlyph={(glyph, options) => (
                  <BotGlyph
                    name={glyph}
                    size={options.size}
                    strokeWidth={options.strokeWidth}
                    className={options.className}
                  />
                )}
                style={tileStyle}
                buttonProps={{
                  role: "radio",
                  "aria-checked": isSelected,
                  "aria-label":
                    tileTraits.length > 0
                      ? `${b.name}, ${tileTraits.join(", ")}`
                      : b.name,
                  "data-living-shell-focus-id": `bot:${b.id}`,
                  "data-relationship-depth-anchor": "library",
                  "data-relationship-depth-identity": `bot:${b.id}`,
                  "data-canvas-bot-marquee-item": "true",
                  "data-marquee-selected": isMarqueeSelected
                    ? "true"
                    : undefined,
                  "data-zen-live-bot-chrome-avoid": "true",
                  onPointerDown: (e) => {
                    lastBotPickerPointerTypeRef.current = e.pointerType;
                    startBotContextLongPress(e, b);
                  },
                  onPointerUp: handleBotContextPointerEnd,
                  onPointerCancel: handleBotContextPointerEnd,
                  onPointerEnter: (e) => {
                    if (canvasBotMarqueeDragRef.current?.active) return;
                    if (e.pointerType !== "mouse" || geom.compactPixelGrid)
                      return;
                    updatePickerParallax(e);
                  },
                  onPointerMove: (e) => {
                    handleBotContextPointerMove(e);
                    if (canvasBotMarqueeDragRef.current?.active) return;
                    if (geom.compactPixelGrid) return;
                    updatePickerParallax(e);
                  },
                  onContextMenu: (event) => {
                    event.preventDefault();
                    event.stopPropagation();
                    if (event.ctrlKey) {
                      toggleCanvasBotSelection(b.id);
                      return;
                    }
                    const multiSelectionIds =
                      canvasSelectedBotIds.size > 1 &&
                      canvasSelectedBotIds.has(b.id)
                        ? Array.from(canvasSelectedBotIds)
                        : [];
                    openCanvasBotContextMenu(
                      b,
                      event.clientX,
                      event.clientY,
                      multiSelectionIds,
                    );
                  },
                  onClick: (e) => {
                    if (canvasBotMarqueeSuppressClickRef.current) {
                      canvasBotMarqueeSuppressClickRef.current = false;
                      e.preventDefault();
                      e.stopPropagation();
                      return;
                    }
                    if (botContextSuppressClickRef.current) {
                      botContextSuppressClickRef.current = false;
                      e.preventDefault();
                      e.stopPropagation();
                      return;
                    }
                    if (e.shiftKey || e.ctrlKey || e.metaKey) {
                      e.preventDefault();
                      e.stopPropagation();
                      toggleCanvasBotSelection(b.id);
                      return;
                    }
                    const isDesktopMousePixelClick =
                      geom.compactPixelGrid &&
                      e.detail > 0 &&
                      lastBotPickerPointerTypeRef.current === "mouse";
                    if (isDesktopMousePixelClick) {
                      focusHueLensOnBot(b);
                    }
                    commitEmptyStateBotSelection(b.id, e.currentTarget);
                  },
                }}
              />
            );
          })}
        </BotPickerGrid>
      </div>
    );
  };

  const disarmDelete = useCallback(() => {
    if (pendingDeleteTimerRef.current) {
      clearTimeout(pendingDeleteTimerRef.current);
      pendingDeleteTimerRef.current = null;
    }
    setPendingDeleteKey(null);
  }, []);

  const beginConversationGroupPointerDrag = useCallback(
    (event: React.PointerEvent<HTMLElement>, groupKey: string) => {
      if (event.button !== 0) return;
      if (
        conversationGroupPointerDragRef.current ||
        draggingConversationGroupKey
      )
        return;
      conversationGroupPointerDragRef.current = {
        key: groupKey,
        pointerId: event.pointerId,
        startY: event.clientY,
        active: false,
      };
      try {
        event.currentTarget.setPointerCapture(event.pointerId);
      } catch {
        // Pointer capture is unavailable in some browser/test environments.
      }
    },
    [draggingConversationGroupKey],
  );

  const updateConversationGroupPointerDrag = useCallback(
    (event: React.PointerEvent<HTMLElement>) => {
      const drag = conversationGroupPointerDragRef.current;
      if (!drag || drag.pointerId !== event.pointerId) return;
      const deltaY = event.clientY - drag.startY;
      if (!drag.active) {
        if (Math.abs(deltaY) < 6) return;
        drag.active = true;
        disarmDelete();
        setExpandedConversationGroupKey((previous) =>
          previous === drag.key ? null : previous,
        );
        setDraggingConversationGroupKey(drag.key);
        suppressConversationGroupClickRef.current = true;
      }

      event.preventDefault();
      const hoveredGroup = document
        .elementsFromPoint(event.clientX, event.clientY)
        .map((element) =>
          element instanceof HTMLElement
            ? element.closest<HTMLElement>("[data-conversation-group-key]")
            : null,
        )
        .find(
          (element) =>
            element && element.dataset.conversationGroupKey !== drag.key,
        );
      const targetKey = hoveredGroup?.dataset.conversationGroupKey;
      if (!hoveredGroup || !targetKey) return;
      const rect = hoveredGroup.getBoundingClientRect();
      const position: ConversationGroupDropPosition =
        event.clientY > rect.top + rect.height / 2 ? "after" : "before";
      moveConversationGroup(drag.key, targetKey, position);
    },
    [disarmDelete, moveConversationGroup],
  );

  const endConversationGroupPointerDrag = useCallback(
    (event: React.PointerEvent<HTMLElement>) => {
      const drag = conversationGroupPointerDragRef.current;
      if (!drag || drag.pointerId !== event.pointerId) return;
      const wasActive = drag.active;
      try {
        event.currentTarget.releasePointerCapture(event.pointerId);
      } catch {
        // Non-fatal: capture may already be released.
      }
      clearConversationGroupDragState();
      if (wasActive) {
        event.preventDefault();
        window.setTimeout(() => {
          suppressConversationGroupClickRef.current = false;
        }, 0);
      }
    },
    [clearConversationGroupDragState],
  );

  useEffect(() => {
    if (!draggingConversationGroupKey) return;
    const handleViewportLeave = (event: MouseEvent) => {
      if (event.relatedTarget !== null) return;
      abortConversationGroupPointerDrag();
    };
    const handleWindowBlur = () => {
      abortConversationGroupPointerDrag();
    };
    document.documentElement.addEventListener(
      "mouseleave",
      handleViewportLeave,
    );
    window.addEventListener("blur", handleWindowBlur);
    return () => {
      document.documentElement.removeEventListener(
        "mouseleave",
        handleViewportLeave,
      );
      window.removeEventListener("blur", handleWindowBlur);
    };
  }, [abortConversationGroupPointerDrag, draggingConversationGroupKey]);

  const armDelete = useCallback((key: string) => {
    if (pendingDeleteTimerRef.current) {
      clearTimeout(pendingDeleteTimerRef.current);
      pendingDeleteTimerRef.current = null;
    }
    setPendingDeleteKey(key);
    // DELETE_ALL_KEY / DELETE_ALL_BOTS_KEY are special: their confirm
    // surface is a centered modal, and the 3.5 s window that makes the
    // inline "Are you sure?" pill feel snappy would instead pull the
    // modal out from under the user mid-read. We skip auto-disarm for
    // them and rely on Cancel / backdrop / Esc to dismiss explicitly.
    if (
      key === DELETE_ALL_KEY ||
      key === DELETE_ALL_COFFEE_SESSIONS_KEY ||
      key === DELETE_ALL_BOTS_KEY ||
      key.startsWith(DELETE_COFFEE_GROUP_KEY_PREFIX)
    )
      return;
    pendingDeleteTimerRef.current = setTimeout(() => {
      setPendingDeleteKey(null);
      pendingDeleteTimerRef.current = null;
    }, DELETE_CONFIRM_WINDOW_MS);
  }, []);

  // Clean up the pending-delete timer on unmount so an in-flight auto-disarm
  // doesn't call setState on a torn-down component.
  useEffect(
    () => () => {
      if (pendingDeleteTimerRef.current) {
        clearTimeout(pendingDeleteTimerRef.current);
      }
    },
    [],
  );

  // Right-click is suppressed app-wide for custom surfaces, but text-entry
  // controls should keep native OS context menus (copy/paste/spellcheck).
  // This preserves expected platform behavior in all textarea/input fields.
  const shouldAllowNativeContextMenu = useCallback(
    (target: EventTarget | null): boolean => {
      if (!(target instanceof HTMLElement)) return false;
      return (
        target.closest(
          [
            "textarea",
            "input:not([type='button']):not([type='submit']):not([type='reset'])",
            "[contenteditable='true']",
            "[contenteditable='']",
            "[role='textbox']",
          ].join(", "),
        ) !== null
      );
    },
    [],
  );

  const openAppWideBotContextMenu = useCallback(
    (event: React.MouseEvent<HTMLElement>): boolean => {
      if (shouldAllowNativeContextMenu(event.target)) return false;
      const botId = appWideBotContextTargetId(event.target);
      if (!botId) return false;
      const bot = bots.find((candidate) => candidate.id === botId);
      if (!bot) return false;
      event.preventDefault();
      event.stopPropagation();
      openBotContextMenu(bot, event.clientX, event.clientY);
      return true;
    },
    [bots, openBotContextMenu, shouldAllowNativeContextMenu],
  );

  const handleAppContextMenu = useCallback(
    (event: React.MouseEvent<HTMLElement>) => {
      if (openAppWideBotContextMenu(event)) return;
      if (shouldAllowNativeContextMenu(event.target)) return;
      event.preventDefault();
      setZenLiveBotContextMenu(null);
      closeCanvasToolsContextMenu();
    },
    [
      closeCanvasToolsContextMenu,
      openAppWideBotContextMenu,
      shouldAllowNativeContextMenu,
    ],
  );

  /**
   * Right-click anywhere in the Coffee shell that isn't a seat / a button / a
   * field surfaces the same actions the Coffee header icons offer, in their
   * text-equivalent form. Mirrors `renderCanvasToolsContextMenu` for Chat.
   */
  const handleCoffeeShellContextMenu = useCallback(
    (event: React.MouseEvent<HTMLElement>) => {
      if (openAppWideBotContextMenu(event)) return;
      if (shouldAllowNativeContextMenu(event.target)) return;
      event.preventDefault();
      if (event.target instanceof HTMLElement) {
        // Bot Library showcase previews own their context menu even while Coffee is active.
        if (event.target.closest('[data-bot-showcase-context="true"]')) return;
        // Defer to the seat-specific handler if the click landed on a Coffee seat.
        if (event.target.closest('[data-coffee-seat-context="true"]')) return;
      }
      setCoffeeShellContextMenu({ x: event.clientX, y: event.clientY });
      setCoffeeBotContextMenu(null);
      setCanvasToolsContextMenu(null);
      setBotContextMenu(null);
      setZenLiveBotContextMenu(null);
      setConversationGroupContextMenu(null);
    },
    [openAppWideBotContextMenu, shouldAllowNativeContextMenu],
  );

  /**
   * Right-click on a seated bot — text shortcuts to that bot's customizer + memories.
   */
  const openCoffeeBotContextMenu = useCallback(
    (botId: string, x: number, y: number) => {
      setCoffeeBotContextMenu({ botId, x, y });
      setCoffeeShellContextMenu(null);
      setBotContextMenu(null);
      setZenLiveBotContextMenu(null);
      setCanvasToolsContextMenu(null);
      setConversationGroupContextMenu(null);
    },
    [],
  );

  const handleStoryShellContextMenu = useCallback(
    (event: React.MouseEvent<HTMLElement>) => {
      if (openAppWideBotContextMenu(event)) return;
      event.preventDefault();
      setStoryShellContextMenu({ x: event.clientX, y: event.clientY });
      setCoffeeShellContextMenu(null);
      setCoffeeBotContextMenu(null);
      setCanvasToolsContextMenu(null);
      setBotContextMenu(null);
      setZenLiveBotContextMenu(null);
      setConversationGroupContextMenu(null);
    },
    [openAppWideBotContextMenu],
  );

  const handleMessagesFrameContextMenu = useCallback(
    (event: React.MouseEvent<HTMLElement>) => {
      if (openAppWideBotContextMenu(event)) return;
      if (shouldAllowNativeContextMenu(event.target)) return;
      event.preventDefault();
      event.stopPropagation();
      if (canvasToolsContextMenu) {
        closeCanvasToolsContextMenu();
        return;
      }
      setCanvasToolsContextMenu({ x: event.clientX, y: event.clientY });
      closeMessageContextOverlay();
      setBotContextMenu(null);
      setZenLiveBotContextMenu(null);
      setConversationGroupContextMenu(null);
      setChatOverflowMenuOpen(false);
    },
    [
      canvasToolsContextMenu,
      closeCanvasToolsContextMenu,
      closeMessageContextOverlay,
      openAppWideBotContextMenu,
      shouldAllowNativeContextMenu,
    ],
  );

  // ── Hold-to-delete-all gesture ────────────────────────────────────────
  // `startHoldDelete` / `cancelHoldDelete` are called from pointer events
  // on every chat-clear affordance (sidebar × rows + header Delete). The
  // discrete React state change (holdingKey set/cleared) drives the CSS
  // `[data-holding="true"]` attribute, which owns the actual 900 ms morph
  // animation — we never re-render on intermediate progress, so even a
  // long hold doesn't thrash React's reconciler.
  const cancelHoldDelete = useCallback(() => {
    if (holdTimerRef.current) {
      clearTimeout(holdTimerRef.current);
      holdTimerRef.current = null;
    }
    setHoldingKey(null);
  }, []);

  const startHoldDelete = useCallback(
    (key: string) => {
      // Refuse to start a new hold while anything is already armed: the
      // active confirm pill / modal deserves the user's attention first,
      // and a second gesture layering on top would be disorienting.
      if (pendingDeleteKey) return;
      if (holdTimerRef.current) {
        clearTimeout(holdTimerRef.current);
      }
      holdCompletedRef.current = false;
      setHoldingKey(key);
      // Route to the bots sentinel when the holding key is a bot × so the
      // confirmation modal asks the right question and the bulk action
      // wipes the right dataset. Any non-bot key (sidebar chat ×, header
      // Delete) stays on the original DELETE_ALL_KEY path.
      const allKey = key.startsWith(BOT_DELETE_KEY_PREFIX)
        ? DELETE_ALL_BOTS_KEY
        : DELETE_ALL_KEY;
      holdTimerRef.current = setTimeout(() => {
        // Threshold crossed — snap out of "holding" visuals and into the
        // armed-all state. The list-level data attribute flip takes the
        // ×'s from tilted-and-glowing straight into iOS jiggle, and
        // `armDelete` renders the confirmation modal.
        holdCompletedRef.current = true;
        setHoldingKey(null);
        holdTimerRef.current = null;
        armDelete(allKey);
      }, DELETE_ALL_HOLD_MS);
    },
    [armDelete, pendingDeleteKey],
  );

  // Clean up the hold timer on unmount.
  useEffect(
    () => () => {
      if (holdTimerRef.current) {
        clearTimeout(holdTimerRef.current);
      }
    },
    [],
  );

  // Armed-all modal a11y: when the modal mounts, capture whatever had
  // focus (usually the × / header Delete the user was holding) so we can
  // restore focus to it on dismiss. While the modal is open, Escape
  // cancels — keeping the keyboard escape hatch consistent with every
  // other confirm surface in the app. Both the chat-scoped and bot-scoped
  // armed-all states share this contract so the two modals behave
  // identically from the keyboard / screen-reader side.
  const pendingCoffeeGroupDeleteIdForModal =
    parseCoffeeGroupDeleteKey(pendingDeleteKey);
  const isDeleteAllActive =
    pendingDeleteKey === DELETE_ALL_KEY ||
    pendingDeleteKey === DELETE_ALL_COFFEE_SESSIONS_KEY ||
    pendingDeleteKey === DELETE_ALL_BOTS_KEY ||
    pendingCoffeeGroupDeleteIdForModal !== null;
  useEffect(() => {
    if (!isDeleteAllActive) {
      // On close, return focus to the element that opened the modal
      // (if it still exists in the DOM and is focusable).
      const prev = preModalFocusRef.current;
      preModalFocusRef.current = null;
      if (prev && typeof prev.focus === "function" && document.contains(prev)) {
        // Use a microtask so React has flushed the modal-removal render
        // before we refocus — otherwise the browser may steal focus
        // back to <body> between our call and the reconciliation tick.
        queueMicrotask(() => {
          try {
            prev.focus({ preventScroll: true });
          } catch {
            /* focus can fail on detached nodes */
          }
        });
      }
      return;
    }
    // Modal is opening — remember where focus came from.
    const active = document.activeElement;
    preModalFocusRef.current = active instanceof HTMLElement ? active : null;

    function handleKey(event: KeyboardEvent) {
      if (event.key === "Escape") {
        event.stopPropagation();
        disarmDelete();
      }
    }
    document.addEventListener("keydown", handleKey);
    return () => document.removeEventListener("keydown", handleKey);
  }, [isDeleteAllActive, disarmDelete]);

  useEffect(() => {
    const id = parseCoffeeGroupDeleteKey(pendingDeleteKey);
    if (!id) return;
    if (!coffeeGroups.some((group) => group.id === id)) {
      disarmDelete();
    }
  }, [pendingDeleteKey, coffeeGroups, disarmDelete]);

  // Single-bot delete from the Bots panel header uses its own modal; if any
  // sidebar/header delete affordance arms, drop the header modal so only one
  // confirm surface is active.
  useEffect(() => {
    if (!pendingDeleteKey) return;
    setPanelBotDeleteConfirm(null);
    setSelectedBotDeleteConfirm(null);
  }, [pendingDeleteKey]);

  const isPanelBotDeleteModalOpen = panelBotDeleteConfirm !== null;
  useEffect(() => {
    if (!isPanelBotDeleteModalOpen) {
      const prev = prePanelBotDeleteModalFocusRef.current;
      prePanelBotDeleteModalFocusRef.current = null;
      if (prev && typeof prev.focus === "function" && document.contains(prev)) {
        queueMicrotask(() => {
          try {
            prev.focus({ preventScroll: true });
          } catch {
            /* ignore */
          }
        });
      }
      return;
    }
    const active = document.activeElement;
    prePanelBotDeleteModalFocusRef.current =
      active instanceof HTMLElement ? active : null;

    function handleKey(event: KeyboardEvent) {
      if (event.key === "Escape") {
        event.stopPropagation();
        setPanelBotDeleteConfirm(null);
      }
    }
    document.addEventListener("keydown", handleKey);
    return () => document.removeEventListener("keydown", handleKey);
  }, [isPanelBotDeleteModalOpen]);

  const isSweepConfirmModalOpen = sweepConfirmOpen;
  useEffect(() => {
    if (!isSweepConfirmModalOpen) {
      const prev = preSweepConfirmModalFocusRef.current;
      preSweepConfirmModalFocusRef.current = null;
      if (prev && typeof prev.focus === "function" && document.contains(prev)) {
        queueMicrotask(() => {
          try {
            prev.focus({ preventScroll: true });
          } catch {
            /* ignore */
          }
        });
      }
      return;
    }
    const active = document.activeElement;
    preSweepConfirmModalFocusRef.current =
      active instanceof HTMLElement ? active : null;

    function handleKey(event: KeyboardEvent) {
      if (event.key === "Escape") {
        event.stopPropagation();
        setSweepConfirmOpen(false);
      }
    }
    document.addEventListener("keydown", handleKey);
    return () => document.removeEventListener("keydown", handleKey);
  }, [isSweepConfirmModalOpen]);

  useEffect(() => {
    if (!sweepUndoToast) return;
    const remainingMs = Math.max(0, sweepUndoToast.expiresAt - Date.now());
    if (remainingMs <= 0) {
      setSweepUndoToast(null);
      return;
    }
    const timer = window.setTimeout(() => {
      setSweepUndoToast((current) =>
        current?.batchId === sweepUndoToast.batchId ? null : current,
      );
    }, remainingMs);
    return () => window.clearTimeout(timer);
  }, [sweepUndoToast]);

  useEffect(() => {
    if (!devToolsOpen && !devToolsMinimized) return;
    function handleKey(event: KeyboardEvent) {
      if (event.key === "Escape") {
        event.stopPropagation();
        closeDevTools();
      }
    }
    document.addEventListener("keydown", handleKey);
    return () => document.removeEventListener("keydown", handleKey);
  }, [devToolsMinimized, devToolsOpen, closeDevTools]);

  // Clicking anywhere outside the delete / confirm affordance should disarm it.
  // This prevents the confirm pill from lingering in an awkward in-between
  // state after focus moves elsewhere in the sidebar.
  useEffect(() => {
    if (!pendingDeleteKey) {
      return;
    }

    function handlePointerDown(event: PointerEvent) {
      if (!isPrimaryPointerDismissal(event)) return;
      const target = event.target;
      // `Element` (not HTMLElement) is deliberate: clicks on inline SVG
      // glyphs have an SVGElement target, which is NOT an HTMLElement but
      // IS an Element (and has .closest). Narrowing to HTMLElement here
      // would treat glyph-icon taps as "outside" and collapse the
      // affordance the user just tried to act on.
      if (
        target instanceof Element &&
        target.closest("[data-delete-affordance='true']")
      ) {
        return;
      }
      disarmDelete();
    }

    document.addEventListener("pointerdown", handlePointerDown);
    return () => {
      document.removeEventListener("pointerdown", handlePointerDown);
    };
  }, [pendingDeleteKey, disarmDelete]);

  // Inline delete confirms (long-term rows + short-term card): disarm when leaving Memories.
  useEffect(() => {
    if (pendingDeleteKey === null) return;
    const memoryScoped =
      pendingDeleteKey.startsWith(LONG_TERM_MEMORY_ACTION_PREFIX) ||
      pendingDeleteKey.startsWith(MEMORY_CARD_DELETE_PREFIX) ||
      pendingDeleteKey.startsWith(ZEN_SESSION_MEMORY_DELETE_PREFIX);
    if (!memoryScoped) return;
    if (panel === "memories") return;
    disarmDelete();
  }, [panel, pendingDeleteKey, disarmDelete]);

  useEffect(() => {
    if (botProfileBuilderOpen && !editingBotId && !newBotName.trim()) {
      setBotProfileBuilderOpen(false);
    }
  }, [botProfileBuilderOpen, editingBotId, newBotName]);

  useEffect(() => {
    if (botAiParametersModalOpen && panel !== "bots") {
      setBotAiParametersModalOpen(false);
    }
  }, [botAiParametersModalOpen, panel]);

  useEffect(() => {
    if (botAvatarCustomizerOpen && panel !== "bots") {
      closeBotAvatarCustomizer();
    }
  }, [botAvatarCustomizerOpen, closeBotAvatarCustomizer, panel]);

  // Close the color/glyph popover on any outside click or Escape. Only
  // one picker ever lives on screen (the top form in the Bots panel), so
  // a single `colorWheelOpen` flag is enough — no per-bot variant needed.
  useEffect(() => {
    if (!colorWheelOpen) return;
    function handlePointerDown(event: PointerEvent) {
      if (!isPrimaryPointerDismissal(event)) return;
      const target = event.target;
      // `Element` (not HTMLElement) is deliberate: a click inside the
      // glyph grid typically lands on an SVG <path>/<circle>, which is
      // an SVGElement — an Element subtype but NOT an HTMLElement. The
      // previous HTMLElement narrowing silently collapsed the popover
      // whenever the user hit an actual glyph icon (the whole point of
      // the grid), while clicks on gaps/padding worked fine.
      if (
        target instanceof Element &&
        target.closest("[data-color-affordance='true']")
      ) {
        return;
      }
      setColorWheelOpen(false);
    }
    function handleKey(event: KeyboardEvent) {
      if (event.key === "Escape") setColorWheelOpen(false);
    }
    document.addEventListener("pointerdown", handlePointerDown);
    document.addEventListener("keydown", handleKey);
    return () => {
      document.removeEventListener("pointerdown", handlePointerDown);
      document.removeEventListener("keydown", handleKey);
    };
  }, [colorWheelOpen]);

  async function deleteConversation(id: string) {
    setError(null);
    disarmDelete();
    // Optimistic update: drop the chat from the sidebar immediately and, if
    // it was open, clear the main pane. Roll everything back on failure.
    const previousConversations = conversations;
    const previousSelectedId = selectedId;
    const previousDetail = detail;
    const previousSessionOpinion = sessionOpinion;
    const previousBotOpinion = botOpinion;
    setConversations((list) => list.filter((c) => c.id !== id));
    if (selectedId === id) {
      setSelectedId(null);
      setDetail(null);
      setSessionOpinion(null);
      setBotOpinion(null);
    }
    try {
      await api(`/api/conversations/${id}`, { method: "DELETE" });
      // Resync from the server so updatedAt order / any server-side fixups
      // (e.g. race with another tab) are reflected.
      await refreshConversations();
    } catch (err) {
      setConversations(previousConversations);
      setSelectedId(previousSelectedId);
      setDetail(previousDetail);
      setSessionOpinion(previousSessionOpinion);
      setBotOpinion(previousBotOpinion);
      setError(err instanceof Error ? err.message : "Delete failed.");
    }
  }

  async function deleteConversationGroup(group: ConversationGroupSummary) {
    setError(null);
    disarmDelete();
    const previousConversations = conversations;
    const previousSelectedId = selectedId;
    const previousDetail = detail;
    const previousSessionOpinion = sessionOpinion;
    const previousBotOpinion = botOpinion;
    const previousUnreadIds = unreadConversationIds;
    const previousUnreadOrder = unreadConversationOrder;
    const previousExpandedGroupKey = expandedConversationGroupKey;
    const groupConversationIds = new Set(
      previousConversations
        .filter(
          (conversation) => conversationGroupKey(conversation) === group.key,
        )
        .map((conversation) => conversation.id),
    );
    const selectedGroupKey = previousDetail?.incognito
      ? null
      : previousDetail
        ? conversationGroupKey(previousDetail)
        : null;

    setConversations((list) =>
      list.filter(
        (conversation) => conversationGroupKey(conversation) !== group.key,
      ),
    );
    setUnreadConversationIds((previous) => {
      const next = new Set(previous);
      for (const id of groupConversationIds) next.delete(id);
      return next;
    });
    setUnreadConversationOrder((previous) =>
      previous.filter((id) => !groupConversationIds.has(id)),
    );
    setExpandedConversationGroupKey(null);
    if (selectedGroupKey === group.key) {
      setSelectedId(null);
      setDetail(null);
      setSessionOpinion(null);
      setBotOpinion(null);
    }

    const deleteConversationIds = group.conversations
      .filter(
        (conversation) =>
          !conversation.parentHubId ||
          !groupConversationIds.has(conversation.parentHubId),
      )
      .map((conversation) => conversation.id);

    try {
      await Promise.all(
        deleteConversationIds.map((conversationId) =>
          api(`/api/conversations/${encodeURIComponent(conversationId)}`, {
            method: "DELETE",
          }),
        ),
      );
      await refreshConversations();
      await refreshOpenMemoryViews();
    } catch (err) {
      setConversations(previousConversations);
      setSelectedId(previousSelectedId);
      setDetail(previousDetail);
      setSessionOpinion(previousSessionOpinion);
      setBotOpinion(previousBotOpinion);
      setUnreadConversationIds(previousUnreadIds);
      setUnreadConversationOrder(previousUnreadOrder);
      setExpandedConversationGroupKey(previousExpandedGroupKey);
      setError(
        err instanceof Error
          ? err.message
          : "Delete conversation group failed.",
      );
    }
  }

  // Bulk-clear every chat, triggered by the hold-to-delete-all gesture.
  // Optimistically wipes the sidebar + open pane so the UI matches the
  // user's intent instantly; on failure we roll back to the previous
  // snapshot and surface the error rather than silently recovering.
  async function deleteAllConversations() {
    setError(null);
    disarmDelete();
    const previousConversations = conversations;
    const previousSelectedId = selectedId;
    const previousDetail = detail;
    const previousSessionOpinion = sessionOpinion;
    const previousBotOpinion = botOpinion;
    // Nothing to clear — short-circuit rather than fire a no-op request.
    if (previousConversations.length === 0) return;
    setConversations([]);
    setSelectedId(null);
    setDetail(null);
    setSessionOpinion(null);
    setBotOpinion(null);
    try {
      await api("/api/conversations", { method: "DELETE" });
      await refreshConversations();
    } catch (err) {
      setConversations(previousConversations);
      setSelectedId(previousSelectedId);
      setDetail(previousDetail);
      setSessionOpinion(previousSessionOpinion);
      setBotOpinion(previousBotOpinion);
      setError(err instanceof Error ? err.message : "Delete all failed.");
    }
  }

  async function deleteAllCoffeeSessions() {
    setCoffeeError(null);
    setError(null);
    disarmDelete();
    const coffeeSessionIds = coffeeSessions.map((session) => session.id);
    if (coffeeSessionIds.length === 0) return;
    const coffeeSessionIdSet = new Set(coffeeSessionIds);
    try {
      await Promise.all(
        coffeeSessionIds.map((sessionId) =>
          api(`/api/conversations/${encodeURIComponent(sessionId)}`, {
            method: "DELETE",
          }),
        ),
      );
      if (
        (coffeeConversation && coffeeSessionIdSet.has(coffeeConversation.id)) ||
        (coffeeSelectedSessionId &&
          coffeeSessionIdSet.has(coffeeSelectedSessionId))
      ) {
        resetCoffeeToPicker();
      }
      if (selectedId && coffeeSessionIdSet.has(selectedId)) {
        setSelectedId(null);
        setDetail(null);
        setSessionOpinion(null);
        setBotOpinion(null);
      }
      await refreshConversations();
    } catch (err) {
      setCoffeeError(
        err instanceof Error ? err.message : "Delete Coffee Sessions failed.",
      );
      await refreshConversations().catch(() => undefined);
    }
  }

  async function deleteCoffeeGroupConfirmed(groupId: string) {
    setCoffeeError(null);
    setError(null);
    disarmDelete();
    try {
      await api(`/api/coffee/groups/${encodeURIComponent(groupId)}`, {
        method: "DELETE",
      });
      if (
        coffeeSelectedGroupId === groupId ||
        coffeeConversation?.coffeeGroupId === groupId
      ) {
        resetCoffeeToPicker();
      }
      await refreshCoffeeGroups();
      await refreshConversations();
    } catch (err) {
      setCoffeeError(
        err instanceof Error ? err.message : "Failed to delete Coffee Group.",
      );
      await refreshCoffeeGroups().catch(() => undefined);
      await refreshConversations().catch(() => undefined);
    }
  }

  async function runConversationSweepActionConfirmed(): Promise<void> {
    if (sweepBusy) return;
    setError(null);
    setSweepBusy(true);
    try {
      const sweepResult = await api<ConversationSweepResponse>(
        "/api/conversations/sweep",
        {
          method: "POST",
          body: JSON.stringify({
            mode: "sandbox",
          }),
        },
      );
      const expiresAtMs = sweepResult.undoExpiresAt
        ? Date.parse(sweepResult.undoExpiresAt)
        : NaN;
      if (sweepResult.batchId && Number.isFinite(expiresAtMs)) {
        setSweepUndoToast({
          batchId: sweepResult.batchId,
          expiresAt: expiresAtMs,
        });
      } else {
        setSweepUndoToast(null);
      }
      const nextConversations = await refreshConversations();
      if (
        detailIdRef.current &&
        !nextConversations.some(
          (conversation) => conversation.id === detailIdRef.current,
        )
      ) {
        setSelectedId(null);
        setDetail(null);
        setSessionOpinion(null);
        setBotOpinion(null);
      }
      await refreshOpenMemoryViews();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Sweep action failed.");
    } finally {
      setSweepBusy(false);
    }
  }

  async function undoConversationSweepFromToast(
    batchId: string,
  ): Promise<void> {
    if (sweepBusy) return;
    setError(null);
    setSweepBusy(true);
    try {
      await api("/api/conversations/sweep/undo", {
        method: "POST",
        body: JSON.stringify({ batchId }),
      });
      setSweepUndoToast((current) =>
        current?.batchId === batchId ? null : current,
      );
      const nextConversations = await refreshConversations();
      if (
        detailIdRef.current &&
        !nextConversations.some(
          (conversation) => conversation.id === detailIdRef.current,
        )
      ) {
        setSelectedId(null);
        setDetail(null);
        setSessionOpinion(null);
        setBotOpinion(null);
      }
      await refreshOpenMemoryViews();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Undo sweep failed.");
    } finally {
      setSweepBusy(false);
    }
  }

  function requestConversationSweepAction(): void {
    if (sweepBusy) return;
    if (!hasSweepEligibleConversations) return;
    setSweepConfirmOpen(true);
  }

