  async function openManualBotDraft(): Promise<void> {
    if (botGeneratorBusy) return;
    const runId = botFoundryRunRef.current + 1;
    botFoundryRunRef.current = runId;
    const reducedMotion = window.matchMedia(
      "(prefers-reduced-motion: reduce)",
    ).matches;
    setBotGeneratorBusy(true);
    setBotGeneratorError(null);
    setBotGeneratorCompletedDraft(null);
    setBotFoundryPhase("handoff");
    await new Promise<void>((resolve) =>
      window.setTimeout(
        resolve,
        reducedMotion
          ? BOT_AVATAR_FOUNDRY_TIMING.reducedHandoffMs
          : BOT_AVATAR_FOUNDRY_TIMING.handoffMs,
      ),
    );
    if (botFoundryRunRef.current !== runId) return;
    setBotFoundryPhase("awakening");
    await new Promise<void>((resolve) =>
      window.setTimeout(
        resolve,
        reducedMotion
          ? BOT_AVATAR_FOUNDRY_TIMING.reducedAwakeningMs
          : BOT_AVATAR_FOUNDRY_TIMING.awakeningMs,
      ),
    );
    if (botFoundryRunRef.current !== runId) return;
    setBotGeneratorOpen(false);
    setBotGeneratorBusy(false);
    setBotFoundryPhase("editing");
    setBotAvatarCustomizerInitialTab("face");
    setBotAvatarCustomizerOpen(true);
  }

  async function randomizeSemanticBotField(
    fieldKey: BotGenerationFieldKeyV1,
    currentValue: unknown,
    applyValue: (value: unknown) => void,
  ): Promise<void> {
    const runId = (botFieldGenerationRunRef.current.get(fieldKey) ?? 0) + 1;
    botFieldGenerationRunRef.current.set(fieldKey, runId);
    const responseMode = responseModeForProvider(
      settings?.preferredProvider ?? "local",
    );
    try {
      const result = await api<{
        ok: true;
        fieldKey: BotGenerationFieldKeyV1;
        value: string | number | boolean | string[];
      }>("/api/bots/generate-field", {
        method: "POST",
        body: JSON.stringify({
          fieldKey,
          currentValue,
          preferredProvider: settings?.preferredProvider ?? "local",
          responseMode,
          context: {
            name: newBotName,
            namePronunciation: newBotNamePronunciation,
            selfReferral: newBotSelfReferral,
            profile: botProfile,
            color: newBotColor,
            glyph: newBotGlyph,
            face: {
              eyesFont: newBotFaceEyesFont,
              eyeCharacter: newBotFaceEyeCharacter,
              eyeAnimation: newBotFaceEyeAnimation,
              mouthFont: newBotFaceMouthFont,
              mouthCharacter: newBotFaceMouthCharacter,
              mouthAnimation: newBotFaceMouthAnimation,
            },
            voice: (() => {
              const voice = normalizeBotAudioVoiceProfileV1(
                newBotAudioVoiceProfile,
              );
              return {
                effect: voice.elevenLabsEffect,
                direction: voice.elevenLabsDirection,
                pitch: voice.pitch,
                warmth: voice.warmth,
                pace: voice.pace,
                lilt: voice.lilt,
              };
            })(),
            settings: {
              flirtEnabled: newBotFlirtEnabled,
              temperature: newBotTemperature,
              maxTokens: newBotMaxTokens,
              topP: newBotTopP,
              topK: newBotTopK,
              repetitionPenalty: newBotRepetitionPenalty,
            },
            powers: newBotPowers.map(({ name, intent }) => ({ name, intent })),
          },
        }),
      });
      if (botFieldGenerationRunRef.current.get(fieldKey) !== runId) return;
      pushBotAvatarUndoSnapshot();
      applyValue(result.value);
    } catch (error) {
      if (botFieldGenerationRunRef.current.get(fieldKey) !== runId) return;
      setPanelNotice(
        error instanceof Error ? error.message : "That field stayed unchanged.",
      );
    }
  }

