  async function createBot(): Promise<boolean> {
    if (blockCoffeeConfigurationMutation()) return false;
    if (!newBotName.trim()) return false;
    setBusy(true);
    setPanelError(null);
    setPanelNotice(null);
    const createdBotName = newBotName.trim();
    const localModel = visibleConcreteModelChoiceForProvider(
      modelCatalog,
      settings,
      "local",
      newBotLocalModel,
    );
    const onlineModel = visibleConcreteOnlineModelChoice(
      modelCatalog,
      settings,
      newBotOnlineModel,
    );
    const localImageStored =
      newBotLocalImageModel === AUTO_MODEL_CHOICE
        ? ""
        : newBotLocalImageModel.trim();
    const openaiImageStored =
      newBotOpenAiImageModel === AUTO_MODEL_CHOICE
        ? ""
        : normalizeOnlineImageModelPreference(newBotOpenAiImageModel);
    const storedSystemPrompt = botEditorAdvancedMode
      ? newBotSystemPrompt
      : botProfileCompletionCount(botProfile) === 0
        ? ""
        : serializeStoredBotPrompt(botProfile, createdBotName);
    let createdAudioVoiceProfile = normalizeBotAudioVoiceProfileV1(
      newBotAudioVoiceProfile,
    );
    let thinkingSfxNotice = createdAudioVoiceProfile.avatarSfxMuted
      ? " Its avatar thinking sound is muted."
      : createdAudioVoiceProfile.avatarSfx
        ? ""
        : " A built-in PRISM thinking sound is ready.";
    const shouldGenerateThinkingSfx =
      !createdAudioVoiceProfile.avatarSfx &&
      !createdAudioVoiceProfile.avatarSfxMuted &&
      Boolean(
        settings &&
        settings.preferredProvider !== "local" &&
        settings.elevenLabsApiKeySource !== "none",
      );
    try {
      if (shouldGenerateThinkingSfx) {
        try {
          createdAudioVoiceProfile = await generateBotThinkingSfxProfile(
            createdAudioVoiceProfile,
            window.location.origin,
          );
          thinkingSfxNotice = " Its unique ElevenLabs thinking loop is ready.";
        } catch (error) {
          const message =
            error instanceof Error
              ? error.message
              : "ElevenLabs could not create the thinking loop.";
          thinkingSfxNotice = ` Its unique thinking loop could not be created (${message}); a PRISM fallback is active.`;
        }
      }
      await api("/api/bots", {
        method: "POST",
        body: JSON.stringify({
          name: newBotName,
          namePronunciation: normalizeBotNamePronunciation(
            newBotNamePronunciation,
          ),
          selfReferral: "",
          systemPrompt: storedSystemPrompt,
          localModel: localModel === AUTO_MODEL_CHOICE ? "" : localModel,
          onlineModel: onlineModel === AUTO_MODEL_CHOICE ? "" : onlineModel,
          localImageModel: localImageStored,
          openaiImageModel: openaiImageStored,
          onlineEnabled: newBotOnlineEnabled,
          flirtEnabled: newBotFlirtEnabled,
          temperature: newBotTemperature,
          maxTokens: newBotMaxTokens,
          topP: newBotTopP,
          topK: newBotTopK,
          repetitionPenalty: newBotRepetitionPenalty,
          color: newBotColor,
          glyph: newBotGlyph,
          faceEyesFont: newBotFaceEyesFont,
          faceEyeCharacter: newBotFaceEyeCharacter,
          faceEyeAnimation: newBotFaceEyeAnimation,
          faceMouthFont: newBotFaceMouthFont,
          faceMouthCharacter: newBotFaceMouthCharacter,
          faceMouthAnimation: newBotFaceMouthAnimation,
          faceMouthCoffeePucker: newBotFaceMouthCoffeePucker,
          faceFontWeight: newBotFaceFontWeight,
          faceEyeScale: newBotFaceEyeScale,
          faceEyeOffsetX: newBotFaceEyeOffsetX,
          faceEyeOffsetY: newBotFaceEyeOffsetY,
          faceEyeRotationDeg: newBotFaceEyeRotationDeg,
          faceEyeCount: newBotFaceEyeCount,
          faceMouthScale: newBotFaceMouthScale,
          faceMouthOffsetX: newBotFaceMouthOffsetX,
          faceMouthOffsetY: newBotFaceMouthOffsetY,
          faceMouthRotationDeg: newBotFaceMouthRotationDeg,
          faceBlinkBar: newBotFaceBlinkBar,
          faceBlinkScale: newBotFaceBlinkScale,
          faceBlinkOffsetX: newBotFaceBlinkOffsetX,
          faceBlinkOffsetY: newBotFaceBlinkOffsetY,
          faceBlinkRotationDeg: newBotFaceBlinkRotationDeg,
          faceThinkingFrames: newBotFaceThinkingFrames,
          faceThinkingScale: newBotFaceThinkingScale,
          faceThinkingOffsetX: newBotFaceThinkingOffsetX,
          faceThinkingOffsetY: newBotFaceThinkingOffsetY,
          avatarDetails: newBotAvatarDetails,
          voicePreviewLine: newBotVoicePreviewLine || null,
          authoredAudioVoiceProfile: createdAudioVoiceProfile,
          powers: newBotPowers,
        }),
      });
      resetBotForm();
      setPanelNotice(`${createdBotName} created.${thinkingSfxNotice}`);
      await refreshBots();
      if (elevenLabsVoiceCatalog.length > 0) {
        await initializePremiumVoiceDefaultsForAccount(true);
      }
      return true;
    } catch (err) {
      setPanelError(err instanceof Error ? err.message : "Create bot failed.");
      return false;
    } finally {
      setBusy(false);
    }
  }

  async function allowBotDeletionForIds(ids: readonly string[]): Promise<void> {
    const uniqueIds = Array.from(
      new Set(ids.filter((id) => typeof id === "string")),
    );
    if (uniqueIds.length === 0) return;
    await api<{ updated?: number }>("/api/bots/selected/delete-protection", {
      method: "PATCH",
      body: JSON.stringify({ ids: uniqueIds, deleteProtected: false }),
    });
  }

  async function deleteBot(
    id: string,
    options?: { keepBotPanelOpen?: boolean },
  ) {
    if (blockCoffeeConfigurationMutation()) return;
    setPanelError(null);
    setPanelNotice(null);
    disarmDelete();
    if (isBotDeleteProtected(id)) {
      setPanelBotDeleteConfirm(null);
      setPanelError(
        "This bot is protected. Allow deletion from its group dashboard first.",
      );
      return;
    }
    // If the deleted bot was the one loaded into the top form, collapse
    // back to create mode so the editor doesn't keep pointing at a row
    // that no longer exists.
    if (editingBotId === id) {
      setEditingBotId(null);
      resetBotForm();
    }
    if (selectedBotPanelBotId === id) {
      setSelectedBotPanelBotId(null);
      setBotPanelView("library");
    }
    // Optimistic update: drop the bot from the panel immediately, and if the
    // user had it selected in the sidebar clear that too so subsequent chats
    // don't try to reference a bot that's already gone. Roll back on failure.
    const previousBots = bots;
    const previousSelectedBotId = selectedBotId;
    setBots((list) => list.filter((b) => b.id !== id));
    if (selectedBotId === id) {
      setSelectedBotId(null);
    }
    try {
      await allowBotDeletionForIds([id]);
      await api(`/api/bots/${id}`, { method: "DELETE" });
      await refreshBots();
      if (panelRef.current === "bots" && !options?.keepBotPanelOpen) {
        closePanel();
      }
    } catch (err) {
      setBots(previousBots);
      setSelectedBotId(previousSelectedBotId);
      setPanelError(err instanceof Error ? err.message : "Delete failed.");
    }
  }

