  function toggleBotLibraryGroupDialogMember(botId: string): void {
    setBotLibraryGroupDetailsDialog((current) => {
      if (!current || current.mode !== "create") return current;
      const selected = current.botIds.includes(botId);
      const botIds = selected
        ? current.botIds.filter((candidateId) => candidateId !== botId)
        : [...current.botIds, botId];
      return {
        ...current,
        botIds,
        error: null,
      };
    });
  }

  function saveBotLibraryGroupDetailsDialog(): void {
    const dialog = botLibraryGroupDetailsDialog;
    if (!dialog) return;
    const name = dialog.name.trim();
    const description = dialog.description.trim();
    const exceptGroupId = dialog.mode === "edit" ? dialog.groupId : undefined;
    const creatingNewGroup =
      dialog.mode === "create" &&
      dialog.targetGroupId === BOT_LIBRARY_GROUP_CREATE_NEW;
    const capValidationError =
      dialog.mode === "create" && creatingNewGroup
        ? botLibraryGroupSizeError(dialog.botIds.length)
        : null;
    const validationError =
      capValidationError ??
      (dialog.mode === "edit" || creatingNewGroup
        ? botLibraryGroupNameError(name, exceptGroupId)
        : null);
    if (validationError) {
      setBotLibraryGroupDetailsDialog({
        ...dialog,
        error: validationError,
      });
      return;
    }
    const now = new Date().toISOString();
    setPanelError(null);
    setPanelNotice(null);
    if (dialog.mode === "create") {
      const uniqueSelected = Array.from(new Set(dialog.botIds));
      if (!creatingNewGroup) {
        const target = botLibraryGroups.find(
          (group) => group.id === dialog.targetGroupId && !group.builtIn,
        );
        if (!target) {
          setBotLibraryGroupDetailsDialog({
            ...dialog,
            error: "Choose a group that still exists, or create a new one.",
          });
          return;
        }
        const targetBotIds = target.botIds.filter((botId) =>
          existingBotIds.has(botId),
        );
        const mergedBotIds = Array.from(
          new Set([...targetBotIds, ...uniqueSelected]),
        );
        if (mergedBotIds.length > BOT_LIBRARY_GROUP_BOT_CAP) {
          setBotLibraryGroupDetailsDialog({
            ...dialog,
            error: `Adding these bots would put "${target.name}" at ${botLibraryGroupCapacityLabel(
              mergedBotIds.length,
              BOT_LIBRARY_GROUP_BOT_CAP,
            )}.`,
          });
          return;
        }
        const addedCount = mergedBotIds.length - targetBotIds.length;
        setBotLibraryGroups((current) =>
          normalizeBotLibraryGroups(
            current.map((group) =>
              group.id === target.id
                ? {
                    ...group,
                    botIds: mergedBotIds,
                    updatedAt: now,
                  }
                : group,
            ),
          ),
        );
        setBotLibraryGroupFilterId(target.id);
        setBotPanelGroup(BOT_LIBRARY_FILTER_ALL);
        if (
          (view === "chat" || view === "sandbox") &&
          !detail &&
          !pendingReplyVisible
        ) {
          resetEmptyStateBotSelection();
          setHueFilterCenter(null);
        }
        setPanelNotice(
          addedCount > 0
            ? `Added ${addedCount === 1 ? "1 bot" : `${addedCount} bots`} to "${target.name}".`
            : `"${target.name}" already has those bots.`,
        );
        setBotLibraryGroupDetailsDialog(null);
        return;
      }

      const groupId = createBotLibraryGroupId();
      setBotLibraryGroups((current) =>
        normalizeBotLibraryGroups([
          ...current,
          {
            id: groupId,
            name,
            description,
            botIds: uniqueSelected,
            deleteProtected: false,
            builtIn: false,
            createdAt: now,
            updatedAt: now,
          },
        ]),
      );
      setBotLibraryGroupFilterId(groupId);
      setBotPanelGroup(BOT_LIBRARY_FILTER_ALL);
      if (
        (view === "chat" || view === "sandbox") &&
        !detail &&
        !pendingReplyVisible
      ) {
        resetEmptyStateBotSelection();
        setHueFilterCenter(null);
      }
      setPanelNotice(
        uniqueSelected.length === 2
          ? `Created "${name}" with 2 bots.`
          : `Created "${name}" with ${uniqueSelected.length} bots.`,
      );
    } else {
      const target = botLibraryGroups.find(
        (group) => group.id === dialog.groupId,
      );
      if (!target || target.builtIn) {
        setBotLibraryGroupDetailsDialog({
          ...dialog,
          error: "This group can no longer be edited.",
        });
        return;
      }
      setBotLibraryGroups((current) =>
        normalizeBotLibraryGroups(
          current.map((group) =>
            group.id === dialog.groupId
              ? {
                  ...group,
                  name,
                  description,
                  updatedAt: now,
                }
              : group,
          ),
        ),
      );
      setPanelNotice(`Updated "${name}".`);
    }
    setBotLibraryGroupDetailsDialog(null);
  }

  function toggleBotFavorite(botId: string): void {
    setBotLibraryGroups((current) => {
      const normalized = normalizeBotLibraryGroups(current);
      const now = new Date().toISOString();
      let found = false;
      const next = normalized.map((group) => {
        if (group.id !== BOT_LIBRARY_FAVORITES_GROUP_ID) return group;
        found = true;
        const hasBot = group.botIds.includes(botId);
        return {
          ...group,
          botIds: hasBot
            ? group.botIds.filter((id) => id !== botId)
            : [...group.botIds, botId],
          updatedAt: now,
        };
      });
      if (!found) {
        const favorites = createFavoritesBotGroup();
        next.push({
          ...favorites,
          botIds: [botId],
          updatedAt: now,
        });
      }
      return normalizeBotLibraryGroups(next);
    });
  }

  function botLibraryAddToGroupOptionsForBot(
    botId: string,
  ): Array<{ group: BotLibraryGroup; count: number; botIds: string[] }> {
    return customBotLibraryGroups
      .map((group) => {
        const existingGroupBotIds = group.botIds.filter((candidateBotId) =>
          existingBotIds.has(candidateBotId),
        );
        return {
          group,
          count: existingGroupBotIds.length,
          botIds: existingGroupBotIds,
        };
      })
      .filter(
        ({ count, botIds }) =>
          !botIds.includes(botId) && count < BOT_LIBRARY_GROUP_BOT_CAP,
      );
  }

  function openAddBotToGroupDialog(botId: string): void {
    const options = botLibraryAddToGroupOptionsForBot(botId);
    const firstGroupId = options[0]?.group.id;
    if (!firstGroupId) return;
    botLibraryAddToGroupDialogOpenerRef.current =
      document.activeElement instanceof HTMLElement
        ? document.activeElement
        : null;
    setPanelError(null);
    setBotLibraryAddToGroupDialog({
      mode: "pick-group",
      botId,
      groupId: firstGroupId,
    });
  }

  function openAddBotFromLibraryGroupDialog(groupId: string): void {
    const target = botLibraryGroups.find((group) => group.id === groupId);
    if (!target || target.builtIn) return;
    const targetBotIds = new Set(
      target.botIds.filter((botId) => existingBotIds.has(botId)),
    );
    if (targetBotIds.size >= BOT_LIBRARY_GROUP_BOT_CAP) {
      setPanelError(null);
      setPanelNotice(`"${target.name}" is full.`);
      return;
    }
    const firstEligibleBot = sortedPanelBots.find(
      (bot) => !targetBotIds.has(bot.id),
    );
    if (!firstEligibleBot) {
      setPanelError(null);
      setPanelNotice(`Every Library bot is already in "${target.name}".`);
      return;
    }
    botLibraryAddToGroupDialogOpenerRef.current =
      document.activeElement instanceof HTMLElement
        ? document.activeElement
        : null;
    setPanelError(null);
    setPanelNotice(null);
    setBotLibraryAddToGroupDialog({
      mode: "pick-bot",
      botId: firstEligibleBot.id,
      groupId: target.id,
    });
  }

  function addBotToExistingLibraryGroup(botId: string, groupId: string): void {
    const bot = bots.find((candidate) => candidate.id === botId);
    const target = botLibraryGroups.find((group) => group.id === groupId);
    if (!bot || !target || target.builtIn) return;

    const result = addBotToLibraryGroup(botLibraryGroups, {
      groupId,
      botId,
      existingBotIds,
      maxBots: BOT_LIBRARY_GROUP_BOT_CAP,
      now: new Date().toISOString(),
    });
    if (result.status !== "added") {
      setPanelError(null);
      setPanelNotice(
        result.status === "already-in-group"
          ? `"${target.name}" already has ${bot.name}.`
          : result.status === "group-full"
            ? `"${target.name}" is full.`
            : "Could not add bot to that group.",
      );
      return;
    }

    setPanelError(null);
    setPanelNotice(`Added ${bot.name} to "${target.name}".`);
    setBotLibraryGroups(normalizeBotLibraryGroups(result.groups));
    setBotLibraryGroupFilterId(groupId);
    setBotPanelGroup(BOT_LIBRARY_FILTER_ALL);
    if (
      (view === "chat" || view === "sandbox") &&
      !detail &&
      !pendingReplyVisible
    ) {
      resetEmptyStateBotSelection();
      setHueFilterCenter(null);
    }
  }

