  async function uploadBotGroupRoomAtmosphere(
    groupId: string,
    file: File,
  ): Promise<void> {
    const target = botLibraryGroups.find((group) => group.id === groupId);
    if (!target || target.builtIn || appWidePrivateMode) return;
    if (
      !BOT_GROUP_ROOM_ATMOSPHERE_UPLOAD_ACCEPT.split(",").includes(file.type)
    ) {
      setBotGroupRoomAtmosphereDialog((current) =>
        current?.groupId === groupId
          ? { ...current, error: "Upload a PNG, JPEG, or WebP image." }
          : current,
      );
      return;
    }
    if (
      file.size === 0 ||
      file.size > BOT_GROUP_ROOM_ATMOSPHERE_UPLOAD_MAX_BYTES
    ) {
      setBotGroupRoomAtmosphereDialog((current) =>
        current?.groupId === groupId
          ? { ...current, error: "Upload an image up to 16 MB." }
          : current,
      );
      return;
    }
    setBotGroupRoomAtmosphereDialog((current) =>
      current?.groupId === groupId
        ? { ...current, busy: "upload", error: null }
        : current,
    );
    try {
      const dataUrl = await readImageBlobAsDataUrl(file);
      const data = await api<{ image?: ImageRecord }>(
        "/api/images/group-room-wallpaper/upload",
        {
          method: "POST",
          body: JSON.stringify({
            dataUrl,
            prompt: `${target.name} uploaded room atmosphere`,
          }),
        },
      );
      const imageId = data.image?.id?.trim() ?? "";
      if (!imageId) {
        throw new Error("The uploaded room did not return an image.");
      }
      chooseBotGroupRoomAtmosphere(
        groupId,
        imageId,
        data.image?.prompt ?? `${target.name} uploaded room atmosphere`,
      );
      setPanelNotice(`Uploaded ${target.name}'s room atmosphere.`);
      void refreshImageBotDirectorySnapshot();
    } catch (error) {
      setBotGroupRoomAtmosphereDialog((current) =>
        current?.groupId === groupId
          ? {
              ...current,
              error:
                error instanceof Error
                  ? error.message
                  : "Room atmosphere upload failed.",
            }
          : current,
      );
    } finally {
      setBotGroupRoomAtmosphereDialog((current) =>
        current?.groupId === groupId ? { ...current, busy: null } : current,
      );
    }
  }

  async function generateBotGroupRoomAtmosphere(
    groupId: string,
    direction = "",
  ): Promise<void> {
    const target = botLibraryGroups.find((group) => group.id === groupId);
    const memberBotIds = target?.botIds.filter((botId) =>
      existingBotIds.has(botId),
    );
    if (
      !target ||
      target.builtIn ||
      !memberBotIds ||
      memberBotIds.length < BOT_LIBRARY_CUSTOM_GROUP_MIN_BOTS ||
      memberBotIds.length > BOT_LIBRARY_GROUP_BOT_CAP
    ) {
      setBotGroupRoomAtmosphereDialog((current) =>
        current?.groupId === groupId
          ? { ...current, error: "This saved group is no longer eligible." }
          : current,
      );
      return;
    }
    const groupImageProvider = resolveImageProviderName({
      savedProvider: settings?.preferredImageProvider,
      offlineOnly: memberBotIds.some(
        (botId) =>
          bots.find((candidate) => candidate.id === botId)?.online_enabled ===
          0,
      ),
    });
    if (!zenWallpaperImageGenerationAvailable(groupImageProvider)) {
      setBotGroupRoomAtmosphereDialog((current) =>
        current?.groupId === groupId
          ? {
              ...current,
              error:
                "Configure a Zen wallpaper image model before generating an atmosphere.",
            }
          : current,
      );
      return;
    }
    setBotGroupRoomAtmosphereDialog((current) =>
      current?.groupId === groupId
        ? { ...current, busy: "generate", error: null }
        : current,
    );
    try {
      const { localModelId, openAiModelId } = resolveZenWallpaperImageModels();
      const body: Record<string, unknown> = {
        purpose: "group-room-wallpaper",
        groupName: target.name,
        groupDescription: target.description,
        memberBotIds,
        variationSeed:
          typeof crypto !== "undefined" &&
          typeof crypto.randomUUID === "function"
            ? crypto.randomUUID()
            : `${Date.now().toString(36)}:${Math.random().toString(36).slice(2)}`,
        size: "1536x1024",
      };
      if (direction.trim()) body.direction = direction.trim();
      if (groupImageProvider !== "local") {
        if (zenWallpaperImageLaneDisabled("openai")) {
          if (zenWallpaperImageLaneDisabled("local") || !localModelId) {
            throw new Error(
              "Online image generation is disabled. Choose a local Zen wallpaper model before generating.",
            );
          }
          body.preferredProvider = "local";
          body.model = localModelId;
        } else {
          if (!openAiModelId) {
            throw new Error(
              "Add an OpenAI key in Settings to enable online image models.",
            );
          }
          body.preferredProvider = "openai";
          body.model = openAiModelId;
        }
      } else {
        if (zenWallpaperImageLaneDisabled("local") || !localModelId) {
          throw new Error(
            "Choose a local Zen wallpaper model before generating.",
          );
        }
        body.preferredProvider = "local";
        body.model = localModelId;
      }
      const data = await api<BotGroupRoomAtmosphereGenerateApiResponse>(
        "/api/images/generate",
        {
          method: "POST",
          body: JSON.stringify(body),
        },
      );
      const imageId = data.image?.id?.trim() ?? "";
      if (!imageId) {
        throw new Error("Atmosphere generation did not return an image.");
      }
      chooseBotGroupRoomAtmosphere(
        groupId,
        imageId,
        data.composedPrompt ?? data.image?.prompt,
      );
      void refreshImageBotDirectorySnapshot();
    } catch (error) {
      setBotGroupRoomAtmosphereDialog((current) =>
        current?.groupId === groupId
          ? {
              ...current,
              error:
                error instanceof Error
                  ? error.message
                  : "Atmosphere generation failed.",
            }
          : current,
      );
    } finally {
      setBotGroupRoomAtmosphereDialog((current) =>
        current?.groupId === groupId ? { ...current, busy: null } : current,
      );
    }
  }

  async function applyBotGroupRoomAtmosphereAsset(
    groupId: string,
    asset: ImageAssetSet,
  ): Promise<void> {
    const member = asset.members.find((candidate) => candidate.role === "primary");
    if (!member) {
      setBotGroupRoomAtmosphereDialog((current) =>
        current?.groupId === groupId
          ? { ...current, error: "That Atmosphere has no reusable image." }
          : current,
      );
      return;
    }
    chooseBotGroupRoomAtmosphere(groupId, member.imageId, member.prompt);
  }

