                                botName={profileReferenceName}
                                studioLayer
                                renderPickAwareComposer={
                                  renderPickAwareComposer
                                }
                                onRandomizePersonality={
                                  applyRandomBotPersonalityDraft
                                }
                                onRandomizeField={randomizeSemanticBotField}
