    setCoffeeAutoBusy(false);
    setCoffeeAutoplayPausedValue(false);
    setCoffeeError(null);
    setCoffeeConversation(null);
    setCoffeeSelectedSessionId(null);
    setCoffeeSelectedGroupId(coffeeConversation.coffeeGroupId ?? null);
